/****** Object:  UserDefinedFunction [dbo].[fn_split]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create FUNCTION [dbo].[fn_split](  
@delimited NVARCHAR(MAX),  
@delimiter NVARCHAR(100)  
) RETURNS @table TABLE (id INT IDENTITY(1,1), [value] NVARCHAR(MAX))  
AS  
BEGIN  
DECLARE @xml XML  
SET @xml = N'<t>' + REPLACE(@delimited,@delimiter,'</t><t>') + '</t>'  
INSERT INTO @table([value])  
SELECT r.value('.','Nvarchar(MAX)') as item  
FROM @xml.nodes('/t') as records(r)  
RETURN  
END
GO
/****** Object:  UserDefinedFunction [dbo].[GetCurrentWeek]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE function [dbo].[GetCurrentWeek]()
returns varchar(10)
as
begin
DECLARE @RetValue as varchar(10)='202529'

Select @RetValue=Max(CALENDAR_WEEK) From APPS_BSR(NOLOCK)

return @RetValue
end

GO
/****** Object:  UserDefinedFunction [dbo].[GetDateTimeFormat]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE function [dbo].[GetDateTimeFormat](@myDate as datetime,@format as VARCHAR(25))
returns varchar(25)
as
begin
DECLARE @RetDate as varchar(25)
DECLARE @SetDate as DateTime
SET @RetDate=''
IF @myDate IS NOT NULL AND @myDate<>'' AND ISDATE(@myDate)=1
SET @SetDate=@myDate
BEGIN
  IF @format='dd-MMM-yyyy HH:mm:ss'
    BEGIN
	  SELECT @RetDate=REPLACE(CONVERT(VARCHAR,@SetDate,106),' ','-') + ' ' + CONVERT(VARCHAR(8),@SetDate,108)
     END
  ELSE IF @format='dd-MMM-yyyy HH:mm:ss:fff'
    BEGIN
	  SELECT @RetDate=REPLACE(CONVERT(VARCHAR,@SetDate,106),' ','-') + ' ' + CONVERT(VARCHAR(20),@SetDate,114)
     END
 ELSE IF @format='yyyymmddHHmmssfff'
    BEGIN
	  SELECT @RetDate=REPLACE(CONVERT(VARCHAR,@SetDate,102),'.','') + REPLACE(CONVERT(VARCHAR(20),@SetDate,114),':','')
     END
 ELSE IF @format='dd-MMM-yyyy HH:mm'
    BEGIN
	  SELECT @RetDate=REPLACE(CONVERT(VARCHAR,@SetDate,106),' ','-') + ' ' + CONVERT(VARCHAR(5),@SetDate,108)
     END 
 ELSE IF @format='yyyy-MM-dd HH:mm:ss'
    BEGIN
	  SELECT @RetDate=REPLACE(CONVERT(VARCHAR,@SetDate,102),'.','-') + ' ' + CONVERT(VARCHAR(8),@SetDate,108)
     END 
 ELSE IF @format='yyyy-MM-dd HH:mm'
    BEGIN
	  SELECT @RetDate=REPLACE(CONVERT(VARCHAR,@SetDate,102),'.','-') + ' ' + CONVERT(VARCHAR(5),@SetDate,108)
     END 	 	  
 ELSE IF @format='ddmmyy'
    BEGIN
	  SELECT @RetDate=REPLACE(CONVERT(VARCHAR,@SetDate,4),'.','')
     END  
 ELSE IF @format='ddmmyyyy'
    BEGIN
	  SELECT @RetDate=REPLACE(CONVERT(VARCHAR,@SetDate,104),'.','')
     END   
 ELSE IF @format='yyyymmdd'
    BEGIN
	  SELECT @RetDate=REPLACE(CONVERT(VARCHAR,@SetDate,102),'.','')
     END       
 ELSE IF @format='dd-mm-yyyy'
    BEGIN
	  SELECT @RetDate=CONVERT(VARCHAR,@SetDate,105)
     END
 ELSE IF @format='dd-MMM-yy'
    BEGIN
	  SELECT @RetDate=REPLACE(CONVERT(VARCHAR,@SetDate,6),' ','-')
     END     
 ELSE IF @format='dd-MMM'
    BEGIN
	  SELECT @RetDate=LEFT(REPLACE(CONVERT(VARCHAR,@SetDate,106),' ','-'),6)
     END 
 ELSE IF @format='MMM-yyyy'
    BEGIN
	  SELECT @RetDate=RIGHT(REPLACE(CONVERT(VARCHAR,@SetDate,106),' ','-'),8)
     END     
 ELSE IF @format='HH:mm:ss'
    BEGIN
	  SELECT @RetDate=CONVERT(VARCHAR(8),@SetDate,108)
     END       
 ELSE IF @format='HH:mm'
    BEGIN
	  SELECT @RetDate=CONVERT(VARCHAR(5),@SetDate,108)
     END            
 ELSE
   BEGIN
	  SELECT @RetDate=REPLACE(CONVERT(VARCHAR,@SetDate,106),' ','-')
   END        
END
return @RetDate
end
GO
