/****** Object:  View [dbo].[VW_ACTIVECHECK_POINTS]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- ============================================================
-- VIEWS
-- ============================================================

-- ACTIVE CHECK_POINTS PER ELEMENT (RESPECTS IS_ACTIVE ON BOTH)
CREATE   VIEW [dbo].[VW_ACTIVECHECK_POINTS] AS
SELECT
    CP.CHECK_POINT_ID,
    CP.ELEMENT_ID,
    KE.ELEMENT_NO,
    KE.ELEMENT_NAME,
    CP.CHECK_POINT_NO,
    CP.QUESTION,
    CP.HAVE_DROPDOWN,
    CP.IS_CRITICAL,
    CP.DISPLAY_ORDER
FROM MASTER_AUDIT_CHECK_POINT CP
INNER JOIN MASTER_AUDIT_KEY_ELEMENT KE ON KE.ELEMENT_ID = CP.ELEMENT_ID
WHERE CP.IS_ACTIVE = 1
  AND KE.IS_ACTIVE = 1;

GO
