/****** Object:  View [dbo].[QPS_PPS_STATUS]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[QPS_PPS_STATUS]
AS
SELECT        dbo.QPS_PPS_REQUEST.GENERIC_ARTICLE,dbo.QPS_PPS_REQUEST.PP_TYPE, dbo.QPS_PPS_REQUEST.ARTICLE_DESCRIPTION, dbo.QPS_PPS_REQUEST.BUYER_ID, 
              dbo.QPS_PPS_LOGS.STATUS_ID, dbo.QPS_STATUS.STATUS, dbo.QPS_PPS_REQUEST.CREATED_AT
FROM            dbo.QPS_PPS_REQUEST LEFT JOIN
                dbo.QPS_PPS_LOGS ON dbo.QPS_PPS_REQUEST.REQUEST_ID = dbo.QPS_PPS_LOGS.REQUEST_ID and QPS_PPS_LOGS.LAST_LOG='Y'  LEFT JOIN
                dbo.QPS_STATUS ON dbo.QPS_PPS_LOGS.STATUS_ID = dbo.QPS_STATUS.STATUS_ID 
				
GO
