/****** Object:  View [auth].[vw_AuthUser]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE       VIEW [auth].[vw_AuthUser]
AS
	Select A.VENDOR_ID AS ID, VENDOR_CODE AS USERCODE, VENDOR_NAME AS USERNAME,ISNULL(B.EMAIL_IDS,'') AS EMAIL,'' AS MOBILENUMBER, VENDOR_NAME AS DISPLAYNAME, 
	IS_ACTIVE AS ISACTIVE, 'Vendor' AS ACCOUNTTYPE, '' AS ROLEID,'' AS REGION_IDS, GST_NO  
	from VENDORS_MASTER A left join VENDOR_ADDRESS B on A.VENDOR_ID=B.VENDOR_ID AND B.IS_DEFAULT=1
	UNION ALL
	Select ID , EMP_CODE AS USERCODE, EMP_NAME AS USERNAME,EMP_MAIL_ID AS EMAIL,EMP_CONTACT_NO AS MOBILENUMBER, EMP_NAME AS DISPLAYNAME, 
	EMP_STATUS AS ISACTIVE, 'Employee' AS ACCOUNTTYPE, ROLE_ID AS ROLEID , REGION_IDS,'' AS GST_NO  
	from USER_MASTER
GO
