/****** Object:  View [dbo].[VW_AUDITSUMMARY]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO






-- AUDIT SUMMARY VIEW (FOR DASHBOARD LIST)
CREATE     VIEW [dbo].[VW_AUDITSUMMARY] AS
SELECT
    AR.AUDIT_ID,
    AR.AUDIT_CODE,
    AR.CURRENT_STEP,
    AR.AUDITOR_EMP_CODE,
	U.EMP_NAME AS AUDITOR_NAME,
	AR.FACTORY_OWNER_EMAIL,
	AR.OVER_ALL_COMMENTS,
	AR.STATUS_ID,
	AR.GRADE_ID,
    AR.AUDIT_DATE,
    AR.AUDIT_REQ_ID,
    ISNULL(AR.AUDIT_SCORE_PERCENT,0)       AS AUDIT_SCORE_PERCENT,
    AR.VALIDITY_TILL,
    AR.CREATED_ON,
    AR.SUBMITTED_AT,
    AR.CREATED_BY,
    AR.UPDATED_BY,
    AR.UPDATED_ON,
    S.STATUS_NAME,
    ISNULL(G.GRADE_CODE,'')		 AS GRADE_CODE,
    ISNULL(G.COLOR_HEX,'')       AS GRADECOLOR_HEX,
    G.VALIDATION_PERIOD,
    ISNULL(G.VALIDITY_IN_MONTHS,0) AS VALIDITY_IN_MONTHS,
	G.DESCRIPTION
FROM AUDIT_REPORT AR
INNER JOIN MASTER_AUDIT_STATUS S ON S.STATUS_ID = AR.STATUS_ID
LEFT  JOIN MASTER_AUDIT_GRADE  G ON G.GRADE_ID  = AR.GRADE_ID
LEFT  JOIN USER_MASTER  U ON AR.AUDITOR_EMP_CODE  = U.EMP_CODE
WHERE AR.IS_DELETED = 0;

GO
