SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [dbo].[VW_BSR_WITHIMAGEURL]
AS
SELECT a.*, 
CASE WHEN ISNULL(LTRIM(RTRIM(IMAGE_URL)), '') = '' THEN 'resources/media/images/noimage.jpg' ELSE IMAGE_URL END AS IMAGE_URL
FROM APPS_BSR a
INNER JOIN MATERIAL_IMAGE_URL b ON a.MATERIAL = b.MATERIAL;
GO
