/****** Object:  StoredProcedure [asn].[POIR_ASN_Request_CRUD]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [asn].[POIR_ASN_Request_CRUD]
    @CMD                VARCHAR(20),
    @ASN_REQ_ID          BIGINT        = NULL,
    @INSP_ID             BIGINT        = NULL,   -- FK -> INSPECTION_REQUESTS.INSP_ID
    @INSPECT_ID          BIGINT        = NULL,   -- FK -> INSPECTIONS.INSPECT_ID (set once inspection completes)
    @PO_NUMBER           VARCHAR(30)   = NULL,   -- used by GET_SUMMARY_BY_PO
    @SHIP_QTY            INT           = NULL,
    @REQUESTED_QTY       INT           = NULL,
    @ASN_NUMBER          VARCHAR(20)   = NULL,
    @ASN_ATTACHMENT      VARCHAR(1000) = NULL,
    @REMARKS             VARCHAR(500)  = NULL,
    @PO_NET_VALUE        DECIMAL(18,2) = NULL,
    @GRC_QTY             INT           = NULL,
    @GRC_VALUE           DECIMAL(18,2) = NULL,
    @GRC_DATE            DATETIME      = NULL,
    @CREATED_BY          INT           = NULL,
    @UPDATED_BY          INT           = NULL, --
	@USER_TYPE           VARCHAR(20)   = NULL, --
	@USER_CODE           VARCHAR(10)   = NULL, --
	
	@ERROR_CODE INT = 0 OUTPUT,             
    @ERROR_MESSAGE VARCHAR(500) = 'Success' OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
	   BEGIN TRY
		SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Success';

    IF @CMD = 'CREATE'
    BEGIN
		
		INSERT INTO [asn].[ASN_CRUD_TestCases] ( CMD,ASN_REQ_ID,INSP_ID,INSPECT_ID ,PO_NUMBER ,SHIP_QTY ,REQUESTED_QTY ,ASN_NUMBER ,ASN_ATTACHMENT ,REMARKS ,PO_NET_VALUE ,GRC_QTY ,GRC_VALUE ,GRC_DATE ,CREATED_BY ,UPDATED_BY)
		VALUES ( @CMD ,@ASN_REQ_ID ,@INSP_ID ,@INSPECT_ID ,@PO_NUMBER ,@SHIP_QTY ,@REQUESTED_QTY ,@ASN_NUMBER ,@ASN_ATTACHMENT ,@REMARKS ,@PO_NET_VALUE,@GRC_QTY ,@GRC_VALUE ,@GRC_DATE ,@CREATED_BY ,@UPDATED_BY );

        -- BFT submits a new ASN request against an inspection request.
        IF @INSP_ID IS NULL OR @SHIP_QTY IS NULL OR @REQUESTED_QTY IS NULL OR @CREATED_BY IS NULL
        BEGIN
            RAISERROR('CREATE requires INSPECION NUMBER, SHIP QTY, REQUESTED QTY, CREATED BY.', 16, 1);
            RETURN;
        END

        IF @REQUESTED_QTY <= 0
        BEGIN
            RAISERROR('ASN REQUESTED QTY must be greater than zero.', 16, 1);
            RETURN;
        END

        IF NOT EXISTS (SELECT 1 FROM [dbo].[INSPECTION_REQUESTS] WHERE INSP_ID = @INSP_ID)
        BEGIN
            RAISERROR('INSP_ID %I64d does not exist in INSPECTION REQUESTS.', 16, 1, @INSP_ID);
            RETURN;
        END

        DECLARE @NextSeq BIGINT, @AlreadyRequested INT, @Balance INT;

        SELECT @NextSeq = ISNULL(MAX(ASN_SEQ_NO), 0) + 1,
               @AlreadyRequested = ISNULL(SUM(REQUESTED_QTY), 0)
        FROM [asn].[POIR_ASN_REQUEST]
        WHERE INSP_ID = @INSP_ID;

        SET @Balance = @SHIP_QTY - (@AlreadyRequested + @REQUESTED_QTY);

        IF @Balance < 0
        BEGIN
            RAISERROR('REQUESTED_QTY (%d) exceeds remaining Ship Qty balance for this inspection request.', 16, 1, @REQUESTED_QTY);
            RETURN;
        END
		
        INSERT INTO [asn].[POIR_ASN_REQUEST]
            (INSP_ID, INSPECT_ID, ASN_SEQ_NO, SHIP_QTY, REQUESTED_QTY, BALANCE_QTY,
             STATUS, REMARKS,  CREATED_BY)
        VALUES
            (@INSP_ID, @INSPECT_ID, @NextSeq, @SHIP_QTY, @REQUESTED_QTY, @Balance,
             'Pending', @REMARKS, @CREATED_BY);

        SELECT SCOPE_IDENTITY() AS ASN_REQ_ID;
		
    END

    ELSE IF @CMD = 'COMPLETE'
    BEGIN
        -- ASN team assigns ASN_NUMBER and closes the request out.
        IF @ASN_REQ_ID IS NULL OR @ASN_NUMBER IS NULL OR @UPDATED_BY IS NULL
        BEGIN
            RAISERROR('COMPLETE requires ASN REQUEST ID, ASN NUMBER, UPDATED BY.', 16, 1);
            RETURN;
        END

        UPDATE [asn].[POIR_ASN_REQUEST]
        SET ASN_NUMBER      = @ASN_NUMBER,
            ASN_ATTACHMENT  = @ASN_ATTACHMENT,
			ASN_GENERATED_ON = SYSDATETIME(),
            STATUS          = 'Completed',
            ASN_UPDATE_DATE = SYSDATETIME(),
            UPDATED_BY      = @UPDATED_BY
        WHERE ASN_REQ_ID = @ASN_REQ_ID
          AND STATUS = 'Pending';

        IF @@ROWCOUNT = 0
            RAISERROR('No pending ASN request found for ASN_REQ_ID %I64d, or it is already completed.', 16, 1, @ASN_REQ_ID);
    END

    ELSE IF @CMD = 'UPDATE_GRC'
    BEGIN
        -- Backend service posts GRC details after ASN is completed.
        IF @ASN_REQ_ID IS NULL
        BEGIN
            RAISERROR('UPDATE_GRC requires ASN_REQ_ID.', 16, 1);
            RETURN;
        END

        UPDATE [asn].[POIR_ASN_REQUEST]
        SET GRC_QTY    = @GRC_QTY,
			PO_NET_VALUE  = @PO_NET_VALUE,
            GRC_VALUE  = @GRC_VALUE,
            GRC_DATE   = @GRC_DATE
        WHERE ASN_REQ_ID = @ASN_REQ_ID
          AND STATUS = 'Completed';

        IF @@ROWCOUNT = 0
            RAISERROR('ASN request %I64d not found or not yet Completed — cannot post GRC.', 16, 1, @ASN_REQ_ID);
    END

    ELSE IF @CMD = 'GET_SUMMARY_BY_PO'
    BEGIN
        IF @PO_NUMBER IS NULL
        BEGIN
            RAISERROR('SUMMARY BY PO requires PO NUMBER.', 16, 1);
            RETURN;
        END

       SELECT
            po.PO_NUMBER		   As PoNumber,
            ir.INSPECTION_NO       AS InspectionNumber,   -- InspectionAsnGroup.InspectionNumber
            r.SHIP_QTY			   AS ShipQty,                                    -- InspectionAsnGroup.ShipQty
            r.ASN_SEQ_NO           AS Sno,                 -- AsnDetailRow.Sno
            r.REQUESTED_QTY		   AS RequestedQty,                               -- AsnDetailRow.RequestedQty
            r.ASN_NUMBER           AS AsnNumber,                                  -- AsnDetailRow.AsnNumber (NULL -> "-" in UI)
			r.ASN_ATTACHMENT          , 
            r.REQ_CREATE_DATE      AS DateOfCreation,      -- AsnDetailRow.DateOfCreation
            r.BALANCE_QTY          AS BalanceQty,                                 -- AsnDetailRow.BalanceQty
            r.STATUS ,                                      -- AsnDetailRow.Status
            r.REMARKS,
			CONCAT
            (
                po.PO_NUMBER,
                CASE WHEN ISNULL(po.LINK_PO_NUMBER,'') <> '' THEN ' ~ ' + po.LINK_PO_NUMBER ELSE '' END
            ) AS PoNumberWithLinkPo
        FROM [asn].[POIR_ASN_REQUEST] r
        INNER JOIN [dbo].[INSPECTION_REQUESTS] ir ON ir.INSP_ID = r.INSP_ID
        INNER JOIN [dbo].[POHEADER]            po ON po.POID   = ir.POID
        WHERE po.PO_NUMBER = @PO_NUMBER
        ORDER BY ir.INSPECTION_NO, r.ASN_SEQ_NO;
    END

    ELSE IF @CMD = 'GET_BY_INSPECTION'
    BEGIN
        SELECT * FROM [asn].[POIR_ASN_REQUEST]
        WHERE INSP_ID = @INSP_ID
        ORDER BY ASN_SEQ_NO;
    END

    ELSE IF @CMD = 'GET_PENDING'
    BEGIN
        
		 SELECT
			r.ASN_REQ_ID,
            po.PO_NUMBER as PoNumber,
            ir.INSPECTION_NO       AS InspectionNumber,   -- InspectionAsnGroup.InspectionNumber
            r.SHIP_QTY as ShipQty,                                    -- InspectionAsnGroup.ShipQty
            r.ASN_SEQ_NO           AS Sno,                 -- AsnDetailRow.Sno
            r.REQUESTED_QTY as RequestedQty,                               -- AsnDetailRow.RequestedQty
            r.ASN_NUMBER as AsnNumber,                                  -- AsnDetailRow.AsnNumber (NULL -> "-" in UI)
            r.REQ_CREATE_DATE      AS DateOfCreation,      -- AsnDetailRow.DateOfCreation
            r.BALANCE_QTY as BalanceQty,                                 -- AsnDetailRow.BalanceQty
            r.STATUS ,                                      -- AsnDetailRow.Status
            r.REMARKS,
			r.INSPECT_ID,
			r.INSP_ID,
			CONCAT
            (
                po.PO_NUMBER,
                CASE WHEN ISNULL(po.LINK_PO_NUMBER,'') <> '' THEN ' ~ ' + po.LINK_PO_NUMBER ELSE '' END
            ) AS PoNumberWithLinkPo,
			po.VENDOR_CODE,
			po.VENDOR_NAME,
			po.BUYER_NAME,
			po.BUYER_ID,
			po.CATEGORY,
			po.MC_TEXT AS PRODUCT,
			po.COLOR,
			po.MRP

        FROM [asn].[POIR_ASN_REQUEST] r
        INNER JOIN [dbo].[INSPECTION_REQUESTS] ir ON ir.INSP_ID = r.INSP_ID
        INNER JOIN [dbo].[POHEADER]            po ON po.POID   = ir.POID
        WHERE r.STATUS = 'Pending'-- po.PO_NUMBER = @PO_NUMBER
        ORDER BY ir.INSPECTION_NO, r.ASN_SEQ_NO;
   

    END

	ELSE IF @CMD = 'GET_COMPLETED'
    BEGIN
		IF @USER_TYPE = 'VENDOR'
			BEGIN
			    SELECT
			        r.ASN_REQ_ID,
			        po.PO_NUMBER        AS PoNumber,
			        ir.INSPECTION_NO    AS InspectionNumber,
			        r.SHIP_QTY          AS ShipQty,
			        r.ASN_SEQ_NO        AS Sno,
			        r.REQUESTED_QTY     AS RequestedQty,
			        r.ASN_NUMBER        AS AsnNumber,
			        r.REQ_CREATE_DATE   AS DateOfCreation,
			        r.BALANCE_QTY       AS BalanceQty,
			        r.STATUS,
			        r.REMARKS,
			        r.ASN_ATTACHMENT,
			        r.INSPECT_ID,
			        r.INSP_ID,
					po.VENDOR_CODE,
					po.VENDOR_NAME,
					po.BUYER_NAME,
					po.BUYER_ID,
					po.CATEGORY,
					po.MC_TEXT AS PRODUCT,
					po.COLOR,
					po.MRP,
					r.ASN_UPDATE_DATE,
					CONCAT
                    (
                        po.PO_NUMBER,
                        CASE WHEN ISNULL(po.LINK_PO_NUMBER,'') <> '' THEN ' ~ ' + po.LINK_PO_NUMBER ELSE '' END
                    ) AS PoNumberWithLinkPo
			    FROM [asn].[POIR_ASN_REQUEST] r
			    INNER JOIN [dbo].[INSPECTION_REQUESTS] ir ON ir.INSP_ID = r.INSP_ID
			    INNER JOIN [dbo].[POHEADER]            po ON po.POID   = ir.POID
			    WHERE r.STATUS = 'Completed' AND po.VENDOR_CODE = @USER_CODE
			    ORDER BY ir.INSPECTION_NO, r.ASN_SEQ_NO;
			END
		ELSE IF @USER_TYPE = 'BUYER'
			BEGIN
			    SELECT
			        r.ASN_REQ_ID,
			        po.PO_NUMBER        AS PoNumber,
			        ir.INSPECTION_NO    AS InspectionNumber,
			        r.SHIP_QTY          AS ShipQty,
			        r.ASN_SEQ_NO        AS Sno,
			        r.REQUESTED_QTY     AS RequestedQty,
			        r.ASN_NUMBER        AS AsnNumber,
			        r.REQ_CREATE_DATE   AS DateOfCreation,
			        r.BALANCE_QTY       AS BalanceQty,
			        r.STATUS,
			        r.REMARKS,
			        r.ASN_ATTACHMENT,
			        r.INSPECT_ID,
			        r.INSP_ID,
					r.ASN_UPDATE_DATE,
					PO.*,
					CONCAT
                    (
                        po.PO_NUMBER,
                        CASE WHEN ISNULL(po.LINK_PO_NUMBER,'') <> '' THEN ' ~ ' + po.LINK_PO_NUMBER ELSE '' END
                    ) AS PoNumberWithLinkPo
			    FROM [asn].[POIR_ASN_REQUEST] r
			    INNER JOIN [dbo].[INSPECTION_REQUESTS] ir ON ir.INSP_ID = r.INSP_ID
			    INNER JOIN [dbo].[POHEADER]            po ON po.POID   = ir.POID
			    WHERE r.STATUS = 'Completed' AND po.BUYER_ID LIKE '%'+@USER_CODE
			    ORDER BY ir.INSPECTION_NO, r.ASN_SEQ_NO;
			END
		ELSE -- 'ASN' or any other role with no restriction
			BEGIN
			    SELECT
			        r.ASN_REQ_ID,
			        po.PO_NUMBER        AS PoNumber,
			        ir.INSPECTION_NO    AS InspectionNumber,
			        r.SHIP_QTY          AS ShipQty,
			        r.ASN_SEQ_NO        AS Sno,
			        r.REQUESTED_QTY     AS RequestedQty,
			        r.ASN_NUMBER        AS AsnNumber,
			        r.REQ_CREATE_DATE   AS DateOfCreation,
			        r.BALANCE_QTY       AS BalanceQty,
			        r.STATUS,
			        r.REMARKS,
			        r.ASN_ATTACHMENT,
			        r.INSPECT_ID,
			        r.INSP_ID,
					po.VENDOR_CODE,
					po.VENDOR_NAME,
					po.BUYER_NAME,
					po.BUYER_ID,
					po.CATEGORY,
					po.MC_TEXT AS PRODUCT,
					po.COLOR,
					po.MRP,
					r.ASN_UPDATE_DATE,
					CONCAT
                    (
                        po.PO_NUMBER,
                        CASE WHEN ISNULL(po.LINK_PO_NUMBER,'') <> '' THEN ' ~ ' + po.LINK_PO_NUMBER ELSE '' END
                    ) AS PoNumberWithLinkPo
			    FROM [asn].[POIR_ASN_REQUEST] r
			    INNER JOIN [dbo].[INSPECTION_REQUESTS] ir ON ir.INSP_ID = r.INSP_ID
			    INNER JOIN [dbo].[POHEADER]            po ON po.POID   = ir.POID
			    WHERE r.STATUS = 'Completed'
			    ORDER BY ir.INSPECTION_NO, r.ASN_SEQ_NO;
			END

    END

    ELSE IF @CMD = 'GET_BY_ID'
    BEGIN
        SELECT * FROM [asn].[POIR_ASN_REQUEST]
        WHERE ASN_REQ_ID = @ASN_REQ_ID;
    END

	ELSE IF @CMD = 'GET_PO_WISE_ASN_LIST'
    BEGIN
        SELECT r.ASN_NUMBER
        FROM [asn].[POIR_ASN_REQUEST] r
        INNER JOIN [dbo].[INSPECTION_REQUESTS] ir ON ir.INSP_ID = r.INSP_ID
        INNER JOIN [dbo].[POHEADER]            po ON po.POID   = ir.POID
        WHERE po.PO_NUMBER = @PO_NUMBER AND r.STATUS='Completed'
        ORDER BY ir.INSPECTION_NO, r.ASN_SEQ_NO;
    END

    ELSE
    BEGIN
        RAISERROR('Unknown @CMD value: %s', 16, 1, @CMD);
    END
	END TRY

    BEGIN CATCH
		IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH
END
GO
/****** Object:  StoredProcedure [auth].[PRO_LOGIN_CLEAR_LOCKOUT]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [auth].[PRO_LOGIN_CLEAR_LOCKOUT]
    @ACCOUNT_TYPE  VARCHAR(20),
    @USER_CODE     VARCHAR(10),
    @NOW_UTC       DATETIMEOFFSET
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE auth.UserSecurity
       SET FailedLoginCount = 0,
           LockoutEndUtc    = NULL,
           UpdatedUtc       = @NOW_UTC
     WHERE UserId      = @USER_CODE
       AND AccountType = @ACCOUNT_TYPE
       AND (FailedLoginCount <> 0 OR LockoutEndUtc IS NOT NULL);   -- skip the write when already clear
END
GO
/****** Object:  StoredProcedure [auth].[PRO_LOGIN_LOCKOUT]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [auth].[PRO_LOGIN_LOCKOUT]
    @ACCOUNT_TYPE     VARCHAR(20),
    @USER_CODE        VARCHAR(10),
    @LOCKOUT_END_UTC  DATETIMEOFFSET,
    @NOW_UTC          DATETIMEOFFSET
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- Lock the row (or the key range if it doesn't exist yet) so a concurrent
        -- failed-login call can't insert a duplicate between the UPDATE and INSERT.
        UPDATE s WITH (UPDLOCK, HOLDLOCK)
           SET s.FailedLoginCount = 0,          -- fresh attempts once the lockout expires
               s.LockoutEndUtc    = @LOCKOUT_END_UTC,
               s.UpdatedUtc       = @NOW_UTC
          FROM auth.UserSecurity AS s
         WHERE s.UserId      = @USER_CODE
           AND s.AccountType = @ACCOUNT_TYPE;

        -- Replaces EnsureSecurityRow: create the row already locked out.
        IF @@ROWCOUNT = 0
        BEGIN
            INSERT INTO auth.UserSecurity (UserId, AccountType, FailedLoginCount, LockoutEndUtc, UpdatedUtc)
            VALUES (@USER_CODE, @ACCOUNT_TYPE, 0, @LOCKOUT_END_UTC, @NOW_UTC);
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [auth].[PRO_LOGIN_LOOKUP]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [auth].[PRO_LOGIN_LOOKUP]
	@ACCOUNT_TYPE           VARCHAR(20), 
	@USER_CODE           VARCHAR(10)  
AS
BEGIN
    SET NOCOUNT ON;

		--insert into ProcParaTest values('AccountType: '+@ACCOUNT_TYPE +' | UserCode: '+@USER_CODE+' | InsertedAt: '+ Convert(varchar, GETDATE(),9));
		--INSERT INTO auth.UserSecurity (UserId, AccountType, PasswordHash, SecurityStamp, FailedLoginCount, LockoutEndUtc)
  --      SELECT um.EMP_CODE, 'Employee','', CONVERT(NVARCHAR(64), NEWID()), 0, NULL
  --      FROM USER_MASTER um
  --      WHERE NOT EXISTS (SELECT 1 FROM auth.UserSecurity s
  --                        WHERE s.UserId = um.EMP_CODE AND s.AccountType = 'Employee');
        
  --      INSERT INTO auth.UserSecurity (UserId, AccountType, PasswordHash, SecurityStamp, FailedLoginCount, LockoutEndUtc)
  --      SELECT um.VENDOR_CODE, 'Vendor', PASSWORD, CONVERT(NVARCHAR(64), NEWID()), 0, NULL
  --      FROM VENDORS_MASTER um
  --      WHERE NOT EXISTS (SELECT 1 FROM auth.UserSecurity s
  --                WHERE s.UserId = um.VENDOR_CODE AND s.AccountType = 'Vendor');  REGION_IDS, GST_NO 



			
		SELECT u.ID,u.USERCODE, u.USERNAME,u.MOBILENUMBER, u.EMAIL, u.DISPLAYNAME, 
			   s.PasswordHash AS PASSWORDHASH, s.SecurityStamp AS SECURITYSTAMP, u.ISACTIVE, s.FailedLoginCount AS FAILEDLOGINCOUNT, 
			   s.LockoutEndUtc AS LOCKOUTENDUTC, u.ROLEID, ISNULL( REGION_IDS,'') REGION_IDS , ISNULL( GST_NO,'') GST_NO , s.MustChangePassword AS MUSTCHANGEPASSWORD,  
			   u.ACCOUNTTYPE
		FROM  auth.vw_AuthUser u
					LEFT JOIN auth.UserSecurity s ON s.UserId = u.USERCODE AND s.AccountType=u.AccountType
		WHERE u.USERCODE = @USER_CODE AND u.AccountType=@ACCOUNT_TYPE;

		SELECT MENU,CMS,MEDIA,USER_MANAGEMENT FROM USER_MASTER A INNER JOIN ROLE_MASTER B ON A.ROLE_ID=B.ID WHERE EMP_CODE=@USER_CODE AND EMP_STATUS=1 AND ACTIVE_STATUS=1
		SELECT C.ID,C.LABEL, C.URL,PARENT_ID,PAGE_TITLE,PAGE_DESCRIPTION,PAGE_KEYWORDS,PERMISSION FROM USER_ROLE_DETAILS A INNER JOIN USER_MASTER B ON A.USER_ID=B.ID INNER JOIN MENU_MASTER C ON A.MENU_ID=C.ID WHERE B.EMP_CODE=@USER_CODE AND C.ACTIVE_STATUS=1  ORDER BY C.[ORDER]

END






GO
/****** Object:  StoredProcedure [auth].[PRO_LOGIN_RECORD_FAILED_COUNT]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [auth].[PRO_LOGIN_RECORD_FAILED_COUNT]
    @ACCOUNT_TYPE  VARCHAR(20),
    @USER_CODE     VARCHAR(10),
    @NOW_UTC       DATETIMEOFFSET
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Result TABLE (FAILED_LOGIN_COUNT INT);

    BEGIN TRY
        BEGIN TRANSACTION;

        -- UPDLOCK + HOLDLOCK: two simultaneous wrong-password attempts can't both
        -- miss the row and insert twice, and increments are never lost.
        UPDATE s WITH (UPDLOCK, HOLDLOCK)
           SET s.FailedLoginCount = ISNULL(s.FailedLoginCount, 0) + 1,
               s.UpdatedUtc       = @NOW_UTC
        OUTPUT inserted.FailedLoginCount INTO @Result (FAILED_LOGIN_COUNT)
          FROM auth.UserSecurity AS s
         WHERE s.UserId      = @USER_CODE
           AND s.AccountType = @ACCOUNT_TYPE;

        IF @@ROWCOUNT = 0
        BEGIN
            INSERT INTO auth.UserSecurity (UserId, AccountType, FailedLoginCount, UpdatedUtc)
            OUTPUT inserted.FailedLoginCount INTO @Result (FAILED_LOGIN_COUNT)
            VALUES (@USER_CODE, @ACCOUNT_TYPE, 1, @NOW_UTC);
        END

        COMMIT TRANSACTION;

        SELECT FAILED_LOGIN_COUNT FROM @Result;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END



GO
/****** Object:  StoredProcedure [auth].[PRO_LOGIN_SET_PASSWORD]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [auth].[PRO_LOGIN_SET_PASSWORD]
    @ACCOUNT_TYPE         VARCHAR(20),
    @USER_CODE            VARCHAR(10),
    @PASSWORD_HASH        NVARCHAR(500),
    @ROTATE_STAMP         BIT,
    @NEW_SECURITY_STAMP   NVARCHAR(100),
    @NOW_UTC              DATETIMEOFFSET
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE s WITH (UPDLOCK, HOLDLOCK)
           SET s.PasswordHash       = @PASSWORD_HASH,
               s.SecurityStamp      = CASE WHEN @ROTATE_STAMP = 1 THEN @NEW_SECURITY_STAMP ELSE s.SecurityStamp END,
               s.MustChangePassword = 0,
               s.PasswordChangedUtc = @NOW_UTC,
               s.UpdatedUtc         = @NOW_UTC
          FROM auth.UserSecurity AS s
         WHERE s.UserId      = @USER_CODE
           AND s.AccountType = @ACCOUNT_TYPE;

        -- Replaces EnsureSecurityRow: first password for this user.
        IF @@ROWCOUNT = 0
        BEGIN
            INSERT INTO auth.UserSecurity
                (UserId, AccountType, PasswordHash, SecurityStamp, MustChangePassword,
                 FailedLoginCount, LockoutEndUtc, PasswordChangedUtc, UpdatedUtc)
            VALUES
                (@USER_CODE, @ACCOUNT_TYPE, @PASSWORD_HASH, @NEW_SECURITY_STAMP, 0,
                 0, NULL, @NOW_UTC, @NOW_UTC);
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [auth].[PRO_PASSWORD_RESET_TOKEN_FIND]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [auth].[PRO_PASSWORD_RESET_TOKEN_FIND]
    @TOKEN_HASH  VARCHAR(128),        -- same type as in PRO_PASSWORD_RESET_TOKEN_ISSUE
    @NOW_UTC     DATETIMEOFFSET
AS
BEGIN
    SET NOCOUNT ON;
	insert into ProcParaTest values('AccountType: Token : '+@TOKEN_HASH +' | InsertedAt: '+ Convert(varchar, GETDATE(),9));
    SELECT TOP (1)
           t.UserId      AS USER_CODE,
           t.AccountType AS ACCOUNT_TYPE
      FROM auth.PasswordResetToken AS t
     WHERE t.TokenHash  = @TOKEN_HASH
       AND t.ExpiresUtc > @NOW_UTC;
END
GO
/****** Object:  StoredProcedure [auth].[PRO_PASSWORD_RESET_TOKEN_ISSUE]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [auth].[PRO_PASSWORD_RESET_TOKEN_ISSUE]
    @ACCOUNT_TYPE  VARCHAR(20),
    @USER_CODE     VARCHAR(10),
    @TOKEN_HASH    VARCHAR(128),        -- match your column: e.g. NVARCHAR(128) if you store hex/Base64
    @EXPIRES_UTC   DATETIMEOFFSET,
    @NOW_UTC       DATETIMEOFFSET
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;
		insert into ProcParaTest values('AccountType: '+@ACCOUNT_TYPE +' | UserCode: '+@USER_CODE+' | Token : '+@TOKEN_HASH +' | InsertedAt: '+ Convert(varchar, GETDATE(),9));
        -- Only one live token per user: issuing a new one invalidates the previous link.
        -- UPDLOCK + HOLDLOCK keeps two simultaneous "forgot password" clicks from
        -- both inserting and leaving two valid links.
        DELETE t
          FROM auth.PasswordResetToken AS t WITH (UPDLOCK, HOLDLOCK)
         WHERE t.UserId      = @USER_CODE
           AND t.AccountType = @ACCOUNT_TYPE;

        INSERT INTO auth.PasswordResetToken (TokenHash, UserId, AccountType, ExpiresUtc, CreatedUtc)
        VALUES (@TOKEN_HASH, @USER_CODE, @ACCOUNT_TYPE, @EXPIRES_UTC, @NOW_UTC);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH

    -- Housekeeping outside the transaction: expired tokens of ALL users.
    -- Kept separate so it never holds locks on other users' rows during the issue.
    DELETE FROM auth.PasswordResetToken
     WHERE ExpiresUtc <= @NOW_UTC;
END
GO
/****** Object:  StoredProcedure [auth].[PRO_PASSWORD_RESET_TOKEN_REDEEM]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [auth].[PRO_PASSWORD_RESET_TOKEN_REDEEM]
    @TOKEN_HASH  VARCHAR(128),        -- same type as ISSUE / FIND
    @NOW_UTC     DATETIMEOFFSET
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Deleted TABLE
    (
        USER_CODE     VARCHAR(10),
        ACCOUNT_TYPE  VARCHAR(20),
        EXPIRES_UTC   DATETIMEOFFSET
    );
	insert into ProcParaTest values('Redeem : Token : '+@TOKEN_HASH +' | InsertedAt: '+ Convert(varchar, GETDATE(),9));
    -- Atomic: two requests racing with the same link can't both get a row back.
    -- Expired tokens are deleted too, but return no user.
    DELETE FROM auth.PasswordResetToken
    OUTPUT deleted.UserId, deleted.AccountType, deleted.ExpiresUtc
      INTO @Deleted (USER_CODE, ACCOUNT_TYPE, EXPIRES_UTC)
     WHERE TokenHash = @TOKEN_HASH;

    SELECT TOP (1) USER_CODE, ACCOUNT_TYPE
      FROM @Deleted
     WHERE EXPIRES_UTC > @NOW_UTC;
END
GO
