CREATE PROCEDURE [dbo].[CREATEDAILYEMAIL]
AS
BEGIN
    DECLARE @TODAY DATE = CAST(GETDATE() AS DATE);
    DECLARE @EMAILKEY NVARCHAR(150) = 'Schedule_' + CONVERT(VARCHAR, @TODAY, 23);
	DECLARE @EMAILIDS VARCHAR(MAX);
	DECLARE @TODAYTIME TIME = CAST(GETDATE() AS TIME), @IS_UNDER_TIME_FRAME BIT;

	Select @IS_UNDER_TIME_FRAME= CASE WHEN START_TIME<= @TODAYTIME AND END_TIME>= @TODAYTIME THEN 1 else 0 END from EMAIL_SEND_SETTING	

	--IF(@IS_UNDER_TIME_FRAME=1)
	--	BEGIN
			IF NOT EXISTS (SELECT 1 FROM EMAILMASTER WHERE EMAILKEY = @EMAILKEY)
				BEGIN
					INSERT INTO EMAILMASTER (EMAILKEY, SUBJECT, BODY, SCHEDULEDATE, SCHEDULETIME)
					VALUES (@EMAILKEY,'DAILY REPORT','YOUR REPORT CONTENT HERE',@TODAY,@TODAYTIME);

					DECLARE @EMAILID INT = SCOPE_IDENTITY();

					SELECT @EMAILIDS = STRING_AGG(ISNULL(EMAIL_ID,''), '; ') FROM EMAIL_LIST  WHERE IS_ACTIVE = 1 AND EMAIL_ID IS NOT NULL AND EMAIL_ID!='';

					INSERT INTO EMAILRECIPIENTS (EMAILID, RECIPIENT) VALUES (@EMAILID, @EMAILIDS);
				END
		--END
END;
