CREATE PROCEDURE [dbo].[GETPENDINGEMAILS]
AS
BEGIN
    SELECT 
        R.ID,
        R.RECIPIENT,
        M.SUBJECT,
        M.BODY
    FROM EMAILRECIPIENTS R
    INNER JOIN EMAILMASTER M ON R.EMAILID = M.ID
    WHERE R.ISSENT = 0
      AND R.ATTEMPTCOUNT < R.MAXATTEMPTS
      AND (R.NEXTATTEMPTTIME IS NULL OR R.NEXTATTEMPTTIME <= GETDATE())


END;
