/****** Object:  StoredProcedure [dbo].[MARK_STATUS]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[MARK_STATUS]
(
    @ID INT, 
	@CMD VARCHAR(30),
	@ERROR NVARCHAR(MAX),
	@ERROR_CODE INT = 0 OUTPUT,             
    @ERROR_MESSAGE VARCHAR(500) = 'Success' OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
		SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Success';
		DECLARE @POID INT
        BEGIN TRANSACTION;

		

        IF EXISTS (SELECT TOP 1 * FROM EMAILRECIPIENTS WHERE ID = @ID)
			BEGIN
				IF(@CMD='MARKATTEMPT')
					BEGIN
						UPDATE EMAILRECIPIENTS
						SET 
							ATTEMPTCOUNT = ATTEMPTCOUNT + 1,
							LASTATTEMPTTIME = GETDATE()
						WHERE ID = @ID;
					END

				IF(@CMD='MARKSUCCESS')
					BEGIN
						UPDATE EMAILRECIPIENTS
						SET 
							ISSENT = 1,
							SENTTIME = GETDATE(),
							LASTERROR = NULL
						WHERE ID = @ID;
					END

				IF(@CMD='MARKFAILURE')
					BEGIN
						UPDATE EMAILRECIPIENTS
						SET 
							LASTERROR = @ERROR,
							NEXTATTEMPTTIME = DATEADD(MINUTE, 5 * ATTEMPTCOUNT, GETDATE())
						WHERE ID = @ID;
					END

			END
        ELSE
			BEGIN
				RAISERROR (
					'Email id not found.',
					16,
					1,
					 ''
				);
			END
	
        COMMIT TRANSACTION;
		
    END TRY

    BEGIN CATCH
		IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH
END
GO
