	--REPLACE([API_BASE_URL],'<apimodule>',REPLACE(ISNULL(API_MODULE_NAME,''),'<parm>',ISNULL(@PARM,''))) + ISNULL([API_END_POINT],'') AS API_URL,
	[API_USERNAME],[API_PWD],[API_PROXY],[API_PORT],[API_HTTP_METHOD],[API_CONTENT_TYPE],[API_AUTHORIZATION_TYPE],[API_AUTHORIZATION],
