/****** Object:  StoredProcedure [dbo].[PRO_GET_BSR_FILTER_VALUES]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[PRO_GET_BSR_FILTER_VALUES]
    @USERID   INT = 0,
	@SEASON VARCHAR(10)='ALL',
	@WHERECLAUSE NVARCHAR(MAX) = '',
	@REQUIREDCOLNAMES VARCHAR(500) = 'ALL'

AS
BEGIN
    SET NOCOUNT ON;

    DECLARE 
        @BRAND_TYPE VARCHAR(MAX) = 'ALL',
        @DIV        VARCHAR(MAX) = 'ALL',
        @MC         VARCHAR(MAX) = 'ALL';

    -- GET USER-SPECIFIC FILTER VALUES
    SELECT 
        @BRAND_TYPE = ISNULL(BRAND_TYPE, 'ALL'),
        @DIV        = ISNULL(DIV, 'ALL'),
        @MC         = ISNULL(MC, 'ALL')
    FROM USER_MASTER
    WHERE ID = @USERID;

    DECLARE @SQL NVARCHAR(MAX) = '';

	 -- ADD SEASONS JSON FIELD
    SET @SQL += '
        (SELECT SEASON AS VALUE FROM ( SELECT DISTINCT SEASON  
         FROM BSR_SEASON_CALENDAR_WEEK WITH (NOLOCK)) A
         ORDER BY RIGHT(SEASON, 2) DESC,LEFT(SEASON, 2) DESC
         FOR JSON PATH) AS [SEASON|SEASON|1],';

    -- ADD WEEKS JSON FIELD
    SET @SQL += '
        (SELECT WEEK_DESC AS VALUE FROM ( SELECT DISTINCT 
            CALENDAR_WEEK,
            CALENDAR_WEEK + '' ~ '' + RIGHT(CALENDAR_WEEK, 2) + 
            '' ('' + CONVERT(VARCHAR, WOS, 3) + '' To '' + CONVERT(VARCHAR, WOE, 3) + '')'' AS WEEK_DESC
         FROM BSR_SEASON_CALENDAR_WEEK WITH (NOLOCK) WHERE CASE WHEN ''' + @SEASON + '''=''ALL'' THEN ''ALL'' ELSE SEASON END IN (SELECT VALUE FROM DBO.FN_SPLIT(''' + @SEASON + ''', '',''))) A
         ORDER BY CALENDAR_WEEK DESC
         FOR JSON PATH) AS [CALENDAR_WEEK|WEEK|1],';

    -- BUILD DYNAMIC FILTER JSON FIELDS
    SELECT 
        @SQL += '
        (SELECT DISTINCT ' + COLUMN_VALUE + ' AS VALUE
         FROM BSR_FILTER_DATA WITH (NOLOCK)
         WHERE 
             CASE WHEN @BRAND_TYPE = ''ALL'' THEN ''ALL'' ELSE BRAND_TYPE END IN (SELECT VALUE FROM DBO.FN_SPLIT(@BRAND_TYPE, '',''))
             AND CASE WHEN @DIV        = ''ALL'' THEN ''ALL'' ELSE DIV        END IN (SELECT VALUE FROM DBO.FN_SPLIT(@DIV, '',''))
             AND CASE WHEN @MC         = ''ALL'' THEN ''ALL'' ELSE MC         END IN (SELECT VALUE FROM DBO.FN_SPLIT(@MC, '',''))
             AND [' + COLUMN_NAME + '] IS NOT NULL
             AND LTRIM(RTRIM([' + COLUMN_NAME + '])) <> ''''' +
			 CASE WHEN LEN(@WHERECLAUSE) > 0 THEN ' AND ' + @WHERECLAUSE ELSE '' END + '
         FOR JSON PATH
        ) AS [' + COLUMN_NAME + '|' + COLUMN_TEXT + '|' + CAST(ISNULL(COL_SM_PER_ROW,1) AS VARCHAR) + '],'
    FROM BSR_FILTER_CONFIG  
    WHERE ACTIVE_STATUS = 1 AND CASE WHEN ISNULL(@REQUIREDCOLNAMES,'ALL')='ALL' THEN 'ALL' ELSE COLUMN_NAME END IN (SELECT VALUE FROM DBO.FN_SPLIT(@REQUIREDCOLNAMES, ','))
    ORDER BY SORTING_ORDER;

   

    -- REMOVE LAST COMMA
    SET @SQL = 'SELECT ' + LEFT(@SQL, LEN(@SQL) - 1) + ';';

    -- DEBUG PRINT
    PRINT @SQL;

    -- EXECUTE DYNAMIC SQL
    EXEC SP_EXECUTESQL 
        @SQL, 
        N'@BRAND_TYPE VARCHAR(MAX), @DIV VARCHAR(MAX), @MC VARCHAR(MAX)',
        @BRAND_TYPE = @BRAND_TYPE,
        @DIV        = @DIV,
        @MC         = @MC;
END

-- PRO_GET_BSR_FILTER_VALUES 3,'SS25','MRP IN (199.0000)','DIV,MC,PRICE_BAND_CATEGORY,BRAND_TYPE,COLOR,VENDOR'



GO
/****** Object:  StoredProcedure [dbo].[PRO_GET_DATA_BY_TABLE]    Script Date: 23-11-2026 14:30:58 ******/
