CREATE PROC [dbo].[PRO_GET_DATA_BY_TABLE]
@TABLE_NAME VARCHAR(50),
@DATA_STATUS VARCHAR(1)=''
AS 
BEGIN
IF  @TABLE_NAME='APPS_BSR_API'
	BEGIN
		SET DATEFIRST 1 
		DECLARE @CALENDER_WEEK AS VARCHAR(10)=CAST(DATEPART(YEAR,GETDATE()) AS  VARCHAR)+RIGHT('00'+CAST(DATEPART(WEEK,GETDATE())-1 AS VARCHAR),2)
		SELECT @TABLE_NAME AS TASK_NAME,COL_ID, COL_VALUE   FROM (SELECT CASE WHEN MAX(TASK_VALUE)=@CALENDER_WEEK THEN NULL ELSE @CALENDER_WEEK END AS COL_ID,'APPS_BSR_TEMP' AS COL_VALUE FROM BSR_API_SERVICE_LOG(NOLOCK) WHERE TASK_NAME=@TABLE_NAME AND STATUS='SUCCESS')A WHERE COL_ID IS NOT NULL ORDER BY COL_ID
	END
END
GO
/****** Object:  StoredProcedure [dbo].[PRO_GET_LIST_BASED_ON_CMD]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[PRO_GET_LIST_BASED_ON_CMD]
	@CMD VARCHAR(100),
	@STRING_VAR1 varchar(MAX) = 'ALL',
	@STRING_VAR2 varchar(MAX) = 'ALL'
AS
BEGIN
    SET NOCOUNT ON;

	If(@CMD='GET_DIV')
	 BEGIN
	   SELECT DISTINCT DIV As LIST_VALUE,DIV + '~' + DIV_DESC AS LIST_TEXT FROM BSR_FILTER_DATA WITH (NOLOCK)
	 END
	ELSE IF(@CMD='GET_MC')
	 BEGIN
	   SELECT DISTINCT MC As LIST_VALUE,MC + '~' + MC_DESC AS LIST_TEXT FROM BSR_FILTER_DATA WITH (NOLOCK) WHERE CASE WHEN @STRING_VAR1 = 'ALL' Then 'ALL' ELSE DIV END IN (SELECT VALUE FROM DBO.FN_SPLIT(@STRING_VAR1,','))
	 END
	ELSE IF(@CMD='GET_BRAND')
	 BEGIN
	   SELECT DISTINCT BRAND_TYPE As LIST_VALUE,BRAND_TYPE AS LIST_TEXT FROM BSR_FILTER_DATA WITH (NOLOCK) WHERE CASE WHEN @STRING_VAR1 = 'ALL' Then 'ALL' ELSE DIV END IN (SELECT VALUE FROM DBO.FN_SPLIT(@STRING_VAR1,',')) AND CASE WHEN @STRING_VAR2 = 'ALL' Then 'ALL' ELSE MC END IN (SELECT VALUE FROM DBO.FN_SPLIT(@STRING_VAR2,','))
	 END
END





GO
