/****** Object:  StoredProcedure [dbo].[PRO_INSERT_NEW_VENDOR_ADDRESS]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Dinesh Baghel
-- Create date: 11 Dec 2025
-- Description:	Insert New Vendor Address
-- =============================================
CREATE PROCEDURE [dbo].[PRO_INSERT_NEW_VENDOR_ADDRESS]
    @VENDOR_CODE VARCHAR(30),
	@ADDRESSES AddressDetails READONLY, -- TABLE-TYPE PARAMETER
	@INSERTED_UPDATED_BY INT,
	@RECORD_ID INT OUTPUT,  
    @ERROR_CODE INT OUTPUT,             -- OUTPUT PARAMETER FOR ERROR CODE
    @ERROR_MESSAGE VARCHAR(500) OUTPUT -- OUTPUT PARAMETER FOR ERROR MESSAGE
AS
BEGIN
	BEGIN TRY
		BEGIN TRANSACTION;
		-- SET OUTPUT PARAMETERS FOR SUCCESS
		SET @ERROR_CODE = 0;
		SET @ERROR_MESSAGE = 'SUCCESS';
		SET @RECORD_ID = 0;
		-- CHECK IF EMP_CODE EXISTS
		IF @VENDOR_CODE is not null
			BEGIN
			Declare @ID int;
			select @ID=VENDOR_ID from VENDORS_MASTER WHERE VENDOR_CODE=@VENDOR_CODE;
				
				IF EXISTS (SELECT TOP 1 * FROM @ADDRESSES)
					BEGIN
						MERGE VENDOR_ADDRESS AS TARGET
						USING @ADDRESSES AS SOURCE
						ON TARGET.ADDRESS_ID = SOURCE.ADDRESS_ID and TARGET.VENDOR_ID=@ID

						WHEN MATCHED THEN
							UPDATE SET TARGET.ADDRESS_LINE1 = SOURCE.Address,
									   TARGET.CITY = SOURCE.City,
									   TARGET.PINCODE = SOURCE.PinCode,
									   TARGET.REGION_CODE = SOURCE.Region,
									   TARGET.REGION_DESCRIPTION = SOURCE.Region_Description,
									   TARGET.MOBILE_NUMBERS = SOURCE.Mobile_Numbers,
									   TARGET.EMAIL_IDS = SOURCE.Email_Ids,
									   TARGET.CONTACT_PERSON = SOURCE.Contact_Person,
									   TARGET.IS_DEFAULT = SOURCE.Is_Default,
									   TARGET.MODIFIED_DATE = GetDate(),
									   TARGET.MODIFIED_BY = @INSERTED_UPDATED_BY,
									   TARGET.IS_INSPECTION_LOCATION=1
									 
						WHEN NOT MATCHED BY TARGET THEN
							INSERT (VENDOR_ID, ADDRESS_LINE1, CITY, PINCODE, EMAIL_IDS, MOBILE_NUMBERS, CONTACT_PERSON,  REGION_CODE, REGION_DESCRIPTION, IS_DEFAULT, CREATED_DATE, CREATED_BY,IS_INSPECTION_LOCATION)
							VALUES (@ID, SOURCE.Address, SOURCE.City,SOURCE.PinCode,SOURCE.Email_Ids,SOURCE.Mobile_Numbers, SOURCE.Contact_Person, SOURCE.Region,SOURCE.Region_Description,SOURCE.Is_Default,GetDate(),@INSERTED_UPDATED_BY,1)
							;
					END
			END
		-- COMMIT TRANSACTION IF EVERYTHING SUCCEEDS
		COMMIT TRANSACTION;
		SET @RECORD_ID = SCOPE_IDENTITY();
    END TRY
    BEGIN CATCH
        -- ROLLBACK TRANSACTION IN CASE OF AN ERROR
        ROLLBACK TRANSACTION;
		-- SET ERROR CODE AND ERROR MESSAGE FOR OUTPUT
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH;
END;


GO
/****** Object:  StoredProcedure [dbo].[PRO_INSERT_TBL_FROM_TEMP]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[PRO_INSERT_TBL_FROM_TEMP] 
@TBLNAME AS VARCHAR(50),
@TASK_VALUE VARCHAR(100),
@PRO_STATUS INT OUTPUT,
@MESSAGE VARCHAR(1000) OUTPUT 
AS  
BEGIN   
 
BEGIN TRY
SET @PRO_STATUS=1  
IF @TBLNAME='APPS_BSR_TEMP'
BEGIN	
	
	IF NOT EXISTS (SELECT TOP 1 MATERIAL,CALENDAR_WEEK,SEASON,COUNT(MATERIAL) FROM APPS_BSR_TEMP (NOLOCK) GROUP BY MATERIAL,CALENDAR_WEEK,SEASON HAVING COUNT(MATERIAL)>1)
	BEGIN
		DELETE APPS_BSR  WHERE CALENDAR_WEEK IN (SELECT CALENDAR_WEEK FROM APPS_BSR_TEMP (NOLOCK))
		INSERT INTO APPS_BSR SELECT *,GETDATE() FROM APPS_BSR_TEMP (NOLOCK)
		INSERT INTO MATERIAL_IMAGE_URL(MATERIAL) SELECT MATERIAL FROM APPS_BSR_TEMP (NOLOCK)  WHERE MATERIAL NOT IN (SELECT MATERIAL FROM MATERIAL_IMAGE_URL (NOLOCK)) GROUP BY MATERIAL
		
		SET DATEFIRST 1
		INSERT INTO BSR_SEASON_CALENDAR_WEEK 
		SELECT DISTINCT A.SEASON,A.CALENDAR_WEEK,WSED.WOS,WSED.WOE,GETDATE() FROM APPS_BSR_TEMP A CROSS APPLY dbo.GetWeekStartEndDate(LEFT(CALENDAR_WEEK,4),RIGHT(CALENDAR_WEEK,2)) AS WSED 
		LEFT JOIN BSR_SEASON_CALENDAR_WEEK (NOLOCK) B ON B.SEASON=A.SEASON AND B.CALENDAR_WEEK=A.CALENDAR_WEEK WHERE B.SEASON IS NULL


		INSERT INTO BSR_FILTER_DATA 
		SELECT DISTINCT ISNULL(A.DIV,''),ISNULL(A.DIV_DESC,''),ISNULL(A.MC,''),ISNULL(A.MC_DESC,''),ISNULL(A.BRAND_TYPE,''),ISNULL(A.MRP,0),ISNULL(A.COLOR,''),ISNULL(A.VENDOR,''),ISNULL(A.VENDOR_NAME,''),GETDATE() FROM APPS_BSR_TEMP (NOLOCK) A
		LEFT JOIN BSR_FILTER_DATA B (NOLOCK) ON B.DIV=A.DIV AND B.MC=A.MC AND B.BRAND_TYPE=A.BRAND_TYPE AND B.MRP=A.MRP AND B.COLOR=A.COLOR AND B.VENDOR=A.VENDOR  WHERE B.DIV IS NULL
	
		
		SET @PRO_STATUS=0
		SET @MESSAGE='Success'
	END
	ELSE
	BEGIN
		SET @PRO_STATUS=1
		SET @MESSAGE='DUPLICATE RECORD FOUND'
	END	
END
END TRY  

BEGIN CATCH 
SET @PRO_STATUS =1
SET @MESSAGE=ERROR_MESSAGE() 
END CATCH;  
END 
GO
/****** Object:  StoredProcedure [dbo].[PRO_INSERT_UPDATE_MATERIAL_IMAGE_URL]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
