CREATE PROC [dbo].[PRO_INSERT_UPDATE_MATERIAL_IMAGE_URL]
AS
BEGIN

IF EXISTS(SELECT  * FROM TEMPDB.DBO.SYSOBJECTS O WHERE O.XTYPE IN ('U') AND O.ID = OBJECT_ID(N'TEMPDB..#TEMP_MATERIAL_IMAGE_URL'))  
BEGIN
	DROP TABLE #TEMP_MATERIAL_IMAGE_URL;  
END

SELECT SKU_CODE,IMAGE_URL,LAST_UPDATED_DATE INTO #TEMP_MATERIAL_IMAGE_URL FROM [192.168.0.43].OMS.DBO.TBL_ARTICLE_MST WITH (NOLOCK) WHERE LAST_UPDATED_DATE<=DATEADD(SECOND,-30,GETDATE()) AND LAST_UPDATED_DATE > (SELECT ISNULL(MAX(LAST_UPDATED_DATE),'01-Jan-2001') FROm MATERIAL_IMAGE_URL (NOLOCK))

DELETE MATERIAL_IMAGE_URL WHERE MATERIAL IN (SELECT SKU_CODE FROM #TEMP_MATERIAL_IMAGE_URL)

INSERT INTO MATERIAL_IMAGE_URL SELECT * FROM #TEMP_MATERIAL_IMAGE_URL

PRINT '(' + CAST(@@ROWCOUNT AS VARCHAR)  + ' Rows Inserted)'

END
