/****** Object:  StoredProcedure [dbo].[PRO_INSERT_UPDATE_MENU_MASTER]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Chandra Bhan Singh
-- Create date: 14 Nov 2024
-- Description:	Insert/Update MENU_MASTER
-- =============================================
CREATE PROCEDURE [dbo].[PRO_INSERT_UPDATE_MENU_MASTER]
    @ID INT,
	@LABEL NVARCHAR(100),
    @URL NVARCHAR(250),
    @ORDER INT,
    @PARENT_ID INT,
    @WEBSITE_VISIBILITY BIT,
    @ACTIVE_STATUS BIT,
	@PAGE_TITLE VARCHAR(200),
	@PAGE_DESCRIPTION VARCHAR(500),
	@PAGE_KEYWORDS VARCHAR(500),
    @INSERTED_UPDATED_BY INT,
	@DEFAULT_MENU_RIGHTS DEFAULT_MENU_RIGHTS READONLY,
	@ERROR_CODE INT OUTPUT,             -- OUTPUT PARAMETER FOR ERROR CODE
    @ERROR_MESSAGE NVARCHAR(500) OUTPUT -- OUTPUT PARAMETER FOR ERROR MESSAGE
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION
	 -- SET OUTPUT PARAMETERS FOR SUCCESS
        SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'SUCCESS';
		IF (@PARENT_ID=0)
		 BEGIN
		   SET @PARENT_ID = NULL;
		 END
		IF @ID=0
		  BEGIN
		    IF EXISTS(SELECT ID FROM MENU_MASTER WHERE LABEL=@LABEL AND ISNULL(PARENT_ID,0)=ISNULL(@PARENT_ID,0))
			 BEGIN
			     SET @ERROR_CODE = 1;
                 SET @ERROR_MESSAGE = 'ALREADY EXISTS.';
				 COMMIT TRANSACTION;
			     RETURN;
			 END

		      INSERT INTO MENU_MASTER 
			  ([LABEL], [URL], [ORDER], PARENT_ID, WEBSITE_VISIBILITY, ACTIVE_STATUS,PAGE_TITLE,PAGE_DESCRIPTION,PAGE_KEYWORDS, INSERTED_ON, INSERTED_BY)
              VALUES 
			  (@LABEL, @URL, @ORDER, @PARENT_ID, @WEBSITE_VISIBILITY, @ACTIVE_STATUS,@PAGE_TITLE,@PAGE_DESCRIPTION,@PAGE_KEYWORDS, GETDATE(), @INSERTED_UPDATED_BY);

			  -- GET THE GENERATED IDENTITY VALUE FOR ROLEID
				SET @ID = SCOPE_IDENTITY();
				 IF(@ORDER=0)
				  BEGIN
				    UPDATE MENU_MASTER SET [ORDER] = @ID WHERE ID=@ID
				  END
		        EXEC PRO_INSERT_LOG_MASTER @ID,'MENU_MASTER',@INSERTED_UPDATED_BY,'INSERT RECORD IN MENU_MASTER'
			  -- INSERT DEFAULT ROLES 
			  IF EXISTS(SELECT TOP 1 * FROM @DEFAULT_MENU_RIGHTS)
			   BEGIN
			     INSERT INTO USER_ROLE_DETAILS (USER_ID, MENU_ID, [PERMISSION])
				 SELECT U.ID, @ID, DMR.PERMISSION
					FROM USER_MASTER AS U INNER JOIN @DEFAULT_MENU_RIGHTS DMR ON U.ROLE_ID = DMR.ROLE_ID
			   END
		  END
		ELSE
		  BEGIN
		    -- CHECK FOR DUPLICATE RECORD ON UPDATE
		   IF EXISTS(SELECT ID FROM MENU_MASTER WHERE LABEL=@LABEL AND ISNULL(PARENT_ID,0)=ISNULL(@PARENT_ID,0) AND ID!=@ID)
			 BEGIN
			  SET @ERROR_CODE = 1;
			  SET @ERROR_MESSAGE = 'RECORD ALREADY EXISTS.';
			  COMMIT TRANSACTION;
			  RETURN;
			 END
			 -- UPDATE EXISTING RECORD
			 IF(@ACTIVE_STATUS=1)
				BEGIN
				  UPDATE MENU_MASTER SET [LABEL]=@LABEL, [URL]=@URL, [ORDER]=@ORDER, PARENT_ID=PARENT_ID, WEBSITE_VISIBILITY=@WEBSITE_VISIBILITY, ACTIVE_STATUS=@ACTIVE_STATUS,PAGE_TITLE=@PAGE_TITLE,PAGE_DESCRIPTION=@PAGE_DESCRIPTION,PAGE_KEYWORDS=@PAGE_KEYWORDS, UPDATED_ON= GETDATE(), UPDATED_BY= @INSERTED_UPDATED_BY WHERE ID=@ID
				END
			ELSE
			  BEGIN
				IF((SELECT ACTIVE_STATUS FROM MENU_MASTER WHERE ID = @ID)=0)
				  BEGIN
					UPDATE MENU_MASTER SET [LABEL]=@LABEL, [URL]=@URL, [ORDER]=@ORDER, PARENT_ID=PARENT_ID, WEBSITE_VISIBILITY=@WEBSITE_VISIBILITY, ACTIVE_STATUS=@ACTIVE_STATUS,PAGE_TITLE=@PAGE_TITLE,PAGE_DESCRIPTION=@PAGE_DESCRIPTION,PAGE_KEYWORDS=@PAGE_KEYWORDS, UPDATED_ON= GETDATE(), UPDATED_BY= @INSERTED_UPDATED_BY WHERE ID=@ID
				  END
				ELSE
				  BEGIN
					UPDATE MENU_MASTER SET [LABEL]=@LABEL, [URL]=@URL, [ORDER]=@ORDER, PARENT_ID=PARENT_ID, WEBSITE_VISIBILITY=@WEBSITE_VISIBILITY, ACTIVE_STATUS=@ACTIVE_STATUS,PAGE_TITLE=@PAGE_TITLE,PAGE_DESCRIPTION=@PAGE_DESCRIPTION,PAGE_KEYWORDS=@PAGE_KEYWORDS, DELETED_ON= GETDATE(), DELETED_BY= @INSERTED_UPDATED_BY WHERE ID=@ID
				  END
				  
		        EXEC PRO_INSERT_LOG_MASTER @ID,'MENU_MASTER',@INSERTED_UPDATED_BY,'UPDATE RECORD IN MENU_MASTER'
		   END
		  END
	-- COMMIT TRANSACTION IF EVERYTHING SUCCEEDS
        COMMIT TRANSACTION;
  END TRY
  BEGIN CATCH
  -- ROLLBACK TRANSACTION IN CASE OF AN ERROR
        ROLLBACK TRANSACTION;
		-- SET ERROR CODE AND ERROR MESSAGE FOR OUTPUT
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
  END CATCH
END
GO
