CREATE PROCEDURE [dbo].[PRO_INSERT_UPDATE_ROLE_MASTER]
    @ID INT,
    @ROLE_NAME NVARCHAR(50),
    @MENU BIT,
    @CMS BIT,
    @MEDIA BIT,
    @USER_MANAGEMENT BIT,
    @ACTIVE_STATUS BIT,
    @INSERTED_UPDATED_BY INT NULL,
    @ERROR_CODE INT OUTPUT,             -- OUTPUT PARAMETER FOR ERROR CODE
    @ERROR_MESSAGE NVARCHAR(500) OUTPUT -- OUTPUT PARAMETER FOR ERROR MESSAGE
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;
		-- SET OUTPUT PARAMETERS FOR SUCCESS
        SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'SUCCESS';

        IF @ID = 0
        BEGIN
		    IF EXISTS(SELECT TOP 1 ID FROM ROLE_MASTER WHERE ROLE_NAME=@ROLE_NAME)
			 BEGIN
			   SET @ERROR_CODE = 1;
               SET @ERROR_MESSAGE = 'THIS RECORD ALREADY EXISTS.';
			   COMMIT TRANSACTION;
			   RETURN;
			 END
            -- INSERT NEW ROLE INTO ROLE_MASTER
            INSERT INTO ROLE_MASTER (ROLE_NAME, MENU, CMS, MEDIA, USER_MANAGEMENT, ACTIVE_STATUS, INSERTED_ON, INSERTED_BY)
            VALUES (@ROLE_NAME, @MENU, @CMS, @MEDIA, @USER_MANAGEMENT, @ACTIVE_STATUS, GETDATE(), @INSERTED_UPDATED_BY);

            -- GET THE GENERATED IDENTITY VALUE FOR ROLEID
				SET @ID = SCOPE_IDENTITY();
		        EXEC PRO_INSERT_LOG_MASTER @ID,'ROLE_MASTER',@INSERTED_UPDATED_BY,'INSERT RECORD IN ROLE_MASTER'
        END
        ELSE
        BEGIN
		  -- CHECK FOR DUPLICATE RECORD ON UPDATE
		    IF EXISTS(SELECT TOP 1 ID FROM ROLE_MASTER WHERE ROLE_NAME=@ROLE_NAME AND ID!=@ID)
			 BEGIN
			   SET @ERROR_CODE = 1;
               SET @ERROR_MESSAGE = 'THIS RECORD ALREADY EXISTS.';
			   COMMIT TRANSACTION;
			   RETURN;
			 END
            -- UPDATE EXISTING ROLE IN ROLE_MASTER
			IF(@ACTIVE_STATUS=1)
			  BEGIN
				UPDATE ROLE_MASTER
				SET ROLE_NAME = @ROLE_NAME,MENU = @MENU,CMS = @CMS,MEDIA = @MEDIA,USER_MANAGEMENT = @USER_MANAGEMENT,ACTIVE_STATUS = @ACTIVE_STATUS,UPDATED_ON = GETDATE(),UPDATED_BY = @INSERTED_UPDATED_BY
				WHERE ID = @ID;
			  END
			ELSE
			  BEGIN
			    IF((SELECT ACTIVE_STATUS FROM ROLE_MASTER WHERE ID = @ID)=0)
				  BEGIN
					UPDATE ROLE_MASTER
					SET ROLE_NAME = @ROLE_NAME,MENU = @MENU,CMS = @CMS,MEDIA = @MEDIA,USER_MANAGEMENT = @USER_MANAGEMENT,ACTIVE_STATUS = @ACTIVE_STATUS,UPDATED_ON = GETDATE(),UPDATED_BY = @INSERTED_UPDATED_BY
					WHERE ID = @ID;
				  END
				ELSE
				  BEGIN
					UPDATE ROLE_MASTER
					SET ROLE_NAME = @ROLE_NAME,MENU = @MENU,CMS = @CMS,MEDIA = @MEDIA,USER_MANAGEMENT = @USER_MANAGEMENT,ACTIVE_STATUS = @ACTIVE_STATUS,DELETED_ON = GETDATE(),DELETED_BY = @INSERTED_UPDATED_BY
					WHERE ID = @ID;
				  END
			  END
			  
		        EXEC PRO_INSERT_LOG_MASTER @ID,'ROLE_MASTER',@INSERTED_UPDATED_BY,'INSERT RECORD IN ROLE_MASTER'
        END
        -- COMMIT TRANSACTION IF EVERYTHING SUCCEEDS
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        -- ROLLBACK TRANSACTION IN CASE OF AN ERROR
        ROLLBACK TRANSACTION;
		-- SET ERROR CODE AND ERROR MESSAGE FOR OUTPUT
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH;
END;
GO
