-- =============================================
-- Author:		Dinesh Baghel
-- Create date: 14 Nov 2025
-- Description:	Insert/Update User
-- =============================================
CREATE PROCEDURE [dbo].[PRO_INSERT_UPDATE_USER_MASTER]
    @ID INT,
    @EMP_CODE VARCHAR(50),
    @EMP_NAME VARCHAR(50),
    @EMP_LOCATION VARCHAR(50),
    @EMP_LOC_CODE VARCHAR(50),
    @EMP_DEPT_NAME VARCHAR(50),
    @EMP_DESIG VARCHAR(50),
    @EMP_CONTACT_NO VARCHAR(50),
    @EMP_MAIL_ID VARCHAR(50),
    @EMP_RPT_MNG VARCHAR(50),
    @IS_RESIGN BIT,
    @EMP_GRADE INT,
    @EMP_GRADE_DESC VARCHAR(50),
    @EMP_STATUS BIT,
    @IP_ADDRESS VARCHAR(50),
    @ROLE_ID INT,
	@DIV VARCHAR(MAX),
	@MC VARCHAR(MAX),
	@BRAND_TYPE VARCHAR(MAX),
	@REGION_ID INT=NULL,
	@REGION_IDS VARCHAR(10),
	@ROLEDETAILS ROLEDETAILS READONLY, -- TABLE-TYPE PARAMETER
	@INSERTED_UPDATED_BY INT,
	@STAMP_NO INT=NULL,
	@SIGN VARBINARY(MAX)=NULL,
    @ERROR_CODE INT OUTPUT,             -- OUTPUT PARAMETER FOR ERROR CODE
    @ERROR_MESSAGE VARCHAR(500) OUTPUT -- OUTPUT PARAMETER FOR ERROR MESSAGE
AS
BEGIN
BEGIN TRY
        BEGIN TRANSACTION;
		-- SET OUTPUT PARAMETERS FOR SUCCESS
        SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'SUCCESS';
		-- CHECK IF EMP_CODE EXISTS
        IF @ID > 0
		 BEGIN
				   -- CHECK FOR DUPLICATE RECORD ON UPDATE
				IF EXISTS(SELECT TOP 1 ID FROM USER_MASTER WHERE EMP_CODE=@EMP_CODE AND ID!=@ID)
				 BEGIN
				   SET @ERROR_CODE = 1;
				   SET @ERROR_MESSAGE = 'THIS RECORD ALREADY EXISTS.';
				   COMMIT TRANSACTION;
				   RETURN;
				 END
			   -- UPDATE EXISTING USER
				UPDATE USER_MASTER SET EMP_CODE=@EMP_CODE, EMP_NAME=@EMP_NAME, EMP_LOCATION=@EMP_LOCATION, EMP_LOC_CODE=@EMP_LOC_CODE,
				EMP_DEPT_NAME=@EMP_DEPT_NAME, EMP_DESIG=@EMP_DESIG, EMP_CONTACT_NO=@EMP_CONTACT_NO, EMP_MAIL_ID=@EMP_MAIL_ID, 
				EMP_RPT_MNG=@EMP_RPT_MNG, IS_RESIGN=@IS_RESIGN, EMP_GRADE=@EMP_GRADE, EMP_GRADE_DESC=@EMP_GRADE_DESC, 
				EMP_STATUS=@EMP_STATUS,ROLE_ID=@ROLE_ID,DIV=@DIV,MC=@MC,BRAND_TYPE=@BRAND_TYPE, REGION_ID = @REGION_ID,REGION_IDS=@REGION_IDS, 
				STAMP_NO=@STAMP_NO,SIGN=@SIGN ,UPDATED_ON=GETDATE(),UPDATED_BY=@INSERTED_UPDATED_BY WHERE ID=@ID
		
				 EXEC PRO_INSERT_LOG_MASTER @ID,'USER_MASTER',@INSERTED_UPDATED_BY,'UPDATE RECORD IN USER_MASTER'
				-- UPDATE ROLEDETAILS
				DELETE FROM USER_ROLE_DETAILS WHERE USER_ID=@ID;
		
					IF EXISTS (SELECT TOP 1 * FROM @ROLEDETAILS)
						BEGIN
							INSERT INTO USER_ROLE_DETAILS (USER_ID, MENU_ID, [PERMISSION])
							SELECT @ID, MENU_ID, [PERMISSION]
							FROM @ROLEDETAILS 
						END
		END
		  ELSE
		    BEGIN
			-- CHECK FOR DUPLICATE RECORD ON UPDATE
		    IF EXISTS(SELECT TOP 1 ID FROM USER_MASTER WHERE EMP_CODE=@EMP_CODE)
			 BEGIN
			   SET @ERROR_CODE = 1;
               SET @ERROR_MESSAGE = 'THIS RECORD ALREADY EXISTS.';
			   COMMIT TRANSACTION;
			   RETURN;
			 END
			-- INSERT NEW USER
			  INSERT INTO USER_MASTER 
			  (EMP_CODE, EMP_NAME, EMP_LOCATION, EMP_LOC_CODE, EMP_DEPT_NAME, EMP_DESIG, EMP_CONTACT_NO, EMP_MAIL_ID, 
			  EMP_RPT_MNG, IS_RESIGN, EMP_GRADE, EMP_GRADE_DESC, EMP_STATUS, IP_ADDRESS, ROLE_ID, DIV, MC, BRAND_TYPE, 
			  REGION_ID,REGION_IDS,STAMP_NO,SIGN , INSERTED_ON, INSERTED_BY,UPDATED_BY,UPDATED_ON)
			  VALUES 
			  ( @EMP_CODE, @EMP_NAME, @EMP_LOCATION, @EMP_LOC_CODE, @EMP_DEPT_NAME, @EMP_DESIG, @EMP_CONTACT_NO, @EMP_MAIL_ID, 
			  @EMP_RPT_MNG, @IS_RESIGN, @EMP_GRADE, @EMP_GRADE_DESC, @EMP_STATUS, @IP_ADDRESS, @ROLE_ID, @DIV, @MC, @BRAND_TYPE, 
			  @REGION_ID,@REGION_IDS,@STAMP_NO, @SIGN, GETDATE(), @INSERTED_UPDATED_BY,@INSERTED_UPDATED_BY,GETDATE());
			  -- GET THE GENERATED IDENTITY VALUE FOR ROLEID
				SET @ID = SCOPE_IDENTITY();
		        EXEC PRO_INSERT_LOG_MASTER @ID,'USER_MASTER',@INSERTED_UPDATED_BY,'INSERT RECORD IN USER_MASTER'
				-- INSERT ROLEDETAILS IF PROVIDED
				IF EXISTS (SELECT TOP 1 * FROM @ROLEDETAILS)
					BEGIN
						INSERT INTO USER_ROLE_DETAILS (USER_ID, MENU_ID, [PERMISSION])
						SELECT @ID, MENU_ID, [PERMISSION]
						FROM @ROLEDETAILS 
					END
			END
		
-- COMMIT TRANSACTION IF EVERYTHING SUCCEEDS
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        -- ROLLBACK TRANSACTION IN CASE OF AN ERROR
        ROLLBACK TRANSACTION;
		-- SET ERROR CODE AND ERROR MESSAGE FOR OUTPUT
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH;
END;


