-- =============================================
-- Author:		Dinesh Baghel
-- Create date: 11 Nov 2025
-- Description:	Insert/Update Vendor
-- =============================================
CREATE PROCEDURE [dbo].[PRO_INSERT_UPDATE_VENDOR_MASTER]
    @ID INT,
    @Vendor_Code VARCHAR(50),
    @Vendor_Name VARCHAR(100),
	@Password VARCHAR(100),
    @GSTNo VARCHAR(50),
	@DEFAULT_PASSWORD_CHANGED BIT,
	@IsActive BIT,
	@IsEmailSent BIT,
	@ADDRESSES AddressDetails READONLY, -- TABLE-TYPE PARAMETER
	@INSERTED_UPDATED_BY INT,
    @ERROR_CODE INT OUTPUT,             -- OUTPUT PARAMETER FOR ERROR CODE
    @ERROR_MESSAGE VARCHAR(500) OUTPUT -- OUTPUT PARAMETER FOR ERROR MESSAGE
AS
BEGIN
	BEGIN TRY
		BEGIN TRANSACTION;
		-- SET OUTPUT PARAMETERS FOR SUCCESS
		SET @ERROR_CODE = 0;
		SET @ERROR_MESSAGE = 'SUCCESS';
		-- CHECK IF EMP_CODE EXISTS
		IF @ID > 0
			BEGIN
				-- CHECK FOR DUPLICATE RECORD ON UPDATE
				IF EXISTS(SELECT TOP 1 VENDOR_ID FROM VENDORS_MASTER WHERE VENDOR_CODE=@Vendor_Code AND VENDOR_ID!=@ID)
					BEGIN
						SET @ERROR_CODE = 1;
						SET @ERROR_MESSAGE = 'THIS VENDOR CODE ALREADY EXISTS.';
						COMMIT TRANSACTION;
						RETURN;
					END
				Else
					BEGIN
						-- UPDATE EXISTING VENDOR
						UPDATE VENDORS_MASTER SET VENDOR_CODE=@Vendor_Code, VENDOR_NAME=@Vendor_Name,GST_NO=@GSTNo, PASSWORD=@Password, DEFAULT_PASSWORD_CHANGED=@DEFAULT_PASSWORD_CHANGED,
						IS_ACTIVE=@IsActive, IS_EMAIL_SENT=@IsEmailSent, MODIFIED_DATE=GETDATE(),MODIFIED_BY=@INSERTED_UPDATED_BY WHERE VENDOR_ID=@ID
					END
				
				--EXEC PRO_INSERT_LOG_MASTER @ID,'USER_MASTER',@INSERTED_UPDATED_BY,'UPDATE RECORD IN USER_MASTER'
				-- UPDATE ROLEDETAILS
				
				IF EXISTS (SELECT TOP 1 * FROM @ADDRESSES)
					BEGIN
						MERGE VENDOR_ADDRESS AS TARGET
						USING @ADDRESSES AS SOURCE
						ON TARGET.ADDRESS_ID = SOURCE.ADDRESS_ID and TARGET.VENDOR_ID=@ID

						WHEN MATCHED THEN
							UPDATE SET TARGET.ADDRESS_LINE1 = SOURCE.Address,
									   TARGET.CITY = SOURCE.City,
									   TARGET.PINCODE = SOURCE.PinCode,
									   TARGET.REGION_CODE = SOURCE.Region,
									   TARGET.REGION_DESCRIPTION = SOURCE.Region_Description,
									   TARGET.MOBILE_NUMBERS = SOURCE.Mobile_Numbers,
									   TARGET.EMAIL_IDS = SOURCE.Email_Ids,
									   TARGET.CONTACT_PERSON = SOURCE.Contact_Person,
									   TARGET.IS_DEFAULT = SOURCE.Is_Default,
									   TARGET.MODIFIED_DATE = GetDate(),
									   TARGET.MODIFIED_BY = @INSERTED_UPDATED_BY
									 
						WHEN NOT MATCHED BY TARGET THEN
							INSERT (VENDOR_ID, ADDRESS_LINE1, CITY, PINCODE, EMAIL_IDS, MOBILE_NUMBERS,CONTACT_PERSON, REGION_CODE, REGION_DESCRIPTION, IS_DEFAULT, CREATED_DATE, CREATED_BY)
							VALUES (@ID, SOURCE.Address, SOURCE.City,SOURCE.PinCode,SOURCE.Email_Ids,SOURCE.Mobile_Numbers,SOURCE.Contact_Person,SOURCE.Region,SOURCE.Region_Description,SOURCE.Is_Default,GetDate(),@INSERTED_UPDATED_BY)

						WHEN NOT MATCHED BY SOURCE AND TARGET.VENDOR_ID = @ID AND ISNULL(IS_INSPECTION_LOCATION,0) =0  THEN
							DELETE;
					END

				IF EXISTS (SELECT TOP 1 * FROM VENODR_EXCEL_DETAILS WHERE TRIM(VENDOR_CODE) = TRIM(@Vendor_Code))
					BEGIN
						UPDATE VENODR_EXCEL_DETAILS SET CM_STATUS = 1,CM_DATE = GETDATE(),CM_USER_ID =@INSERTED_UPDATED_BY,IS_CONFIRMED=@DEFAULT_PASSWORD_CHANGED WHERE TRIM(VENDOR_CODE) = TRIM(@Vendor_Code)
					END
			END
		ELSE
			BEGIN
				-- CHECK FOR DUPLICATE RECORD ON UPDATE
				IF EXISTS(SELECT TOP 1 VENDOR_ID FROM VENDORS_MASTER WHERE VENDOR_CODE=@Vendor_Code)
					BEGIN
						SET @ERROR_CODE = 1;
						SET @ERROR_MESSAGE = 'THIS VENDOR CODE ALREADY EXISTS.';
						COMMIT TRANSACTION;
						RETURN;
					END
				-- INSERT NEW USER

				INSERT INTO VENDORS_MASTER 
				(VENDOR_CODE, VENDOR_NAME, GST_NO, PASSWORD,DEFAULT_PASSWORD_CHANGED, IS_ACTIVE, IS_EMAIL_SENT, CREATED_DATE, CREATED_BY)
				VALUES 
				( @Vendor_Code, @Vendor_Name, @GSTNo, @Password,@DEFAULT_PASSWORD_CHANGED, @IsActive,@IsEmailSent,GETDATE(),@INSERTED_UPDATED_BY);
				-- GET THE GENERATED IDENTITY VALUE FOR VENDOR_ID
				SET @ID = SCOPE_IDENTITY();
				--EXEC PRO_INSERT_LOG_MASTER @ID,'USER_MASTER',@INSERTED_UPDATED_BY,'INSERT RECORD IN USER_MASTER'
				-- INSERT ROLEDETAILS IF PROVIDED
				IF EXISTS (SELECT TOP 1 * FROM @ADDRESSES)
					BEGIN
						INSERT INTO VENDOR_ADDRESS (VENDOR_ID, ADDRESS_LINE1, CITY, PINCODE, EMAIL_IDS, MOBILE_NUMBERS,CONTACT_PERSON, REGION_CODE, REGION_DESCRIPTION, IS_DEFAULT, CREATED_DATE, CREATED_BY)
						SELECT @ID, Address, City,PinCode,Email_Ids,Mobile_Numbers,Contact_Person,Region,Region_Description,Is_Default,GetDate(),@INSERTED_UPDATED_BY
						FROM @ADDRESSES 
					END

				IF EXISTS (SELECT TOP 1 * FROM VENODR_EXCEL_DETAILS WHERE TRIM(VENDOR_CODE) = TRIM(@Vendor_Code))
					BEGIN
						UPDATE VENODR_EXCEL_DETAILS SET CM_STATUS = 1,CM_DATE = GETDATE(),CM_USER_ID =@INSERTED_UPDATED_BY WHERE TRIM(VENDOR_CODE) = TRIM(@Vendor_Code)
					END
				

			END
		
		-- COMMIT TRANSACTION IF EVERYTHING SUCCEEDS
		COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        -- ROLLBACK TRANSACTION IN CASE OF AN ERROR
        ROLLBACK TRANSACTION;
		-- SET ERROR CODE AND ERROR MESSAGE FOR OUTPUT
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH;
END;


GO
/****** Object:  StoredProcedure [dbo].[PRO_INSPECTION_DETAIL]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author: Dinesh Baghel
-- Create date: 19 Aug 2026
-- Description:	[PRO_INSPECTION_DETAIL] 
-- =============================================

CREATE PROCEDURE [dbo].[PRO_INSPECTION_DETAIL]
	@ID INT,
	@STRFIELD VARCHAR(50),
	@CMD VARCHAR(100)
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @SDATE DATETIME=GETDATE();
	IF(@CMD='Get_InspRequest_By_Id')
		BEGIN
			SELECT A.INSP_ID, A.POID,B.PO_NUMBER,
			ISNULL(B.LINK_PO_NUMBER,'') as LINK_PO_NUMBER,B.VENDOR_CODE,B.VENDOR_NAME,B.FABRIC,B.COLOR,B.TOTAL_QTY , A.OFFERED_QTY,A.DATE_OF_INSPECTION, 
			E.ADDRESS_LINE1 + E.CITY + E.REGION_DESCRIPTION+ E.PINCODE as LOCATION,A.ADDRESS_ID,
			A.CREATED_ON, C.VENDOR_NAME as CREATED_BY, D.VENDOR_NAME as UPDATED_BY, A.LAST_UPDATED_ON,A.REGION_ID,A.QA_ASSIGNED_DOI,
			CONVERT(int, A.INSPECTOR_EMP_CODE) as INSPECTOR_EMP_CODE, A.IS_DATE_ASSIGNED_BY_QA, A.IS_INSPECTOR_ASSIGNED,
			ISNULL(S.INSP_STATUS,'Created') as INSP_REQ_STATUS,A.INSPECTION_TYPE_ID,B.APPARELS,B.CATEGORY,B.BUYER_NAME,B.BUYER_ID,
			A.INSPECTION_NO, U.EMP_NAME as INSPECTOR,B.MC,B.MC_TEXT, B.MRP, B.BRAND_ID, B.BRAND_ID2,B.FIT,A.STATUS_CODE, A.IS_QC_AT_DC
			FROM [dbo].[INSPECTION_REQUESTS] A 
			left join DBO.POHEADER B on A.POID=B.POID
			left join [dbo].[USER_MASTER] U on A.INSPECTOR_EMP_CODE=U.EMP_CODE
			left join [dbo].[VENDORS_MASTER] C on A.CREATED_BY=C.VENDOR_ID
			left join [dbo].[VENDORS_MASTER] D on A.UPDATED_BY=D.VENDOR_ID
			left join DBO.VENDOR_ADDRESS E on A.ADDRESS_ID=E.ADDRESS_ID
			left join DBO.INSPECTION_REQUEST_STATUS S on A.STATUS_CODE=S.INSP_STATUS_ID
			WHERE  A.INSP_ID =@ID

			SELECT PO_DETAILS_ID, POID,LINE_ITEM,ARTICLE,ARTICLE_DESC,PREPACK_QTY,PREPACK_QTY_EACHES,PURCHASE_TOT_QTY,EACHES,MRP,ATTYP,
			CREATED_ON,
			LAST_UPDATED_ON,
			CREATED_BY,	isnull(UPDATED_BY,0) UPDATED_BY 
			FROM   [DBO].[PODETAIL] A WHERE POID=(SELECT POID FROM  [DBO].[INSPECTION_REQUESTS] WHERE INSP_ID =@ID) 
			
			SELECT ADDRESS_ID, VENDOR_ID,ADDRESS_LINE1,CITY,PINCODE,EMAIL_IDS,MOBILE_NUMBERS,CONTACT_PERSON,REGION_CODE,REGION_DESCRIPTION,IS_DEFAULT,
			CREATED_DATE,
			MODIFIED_DATE,
			CREATED_BY,	isnull(MODIFIED_BY,0) MODIFIED_BY 
			FROM   [DBO].[VENDOR_ADDRESS] A WHERE VENDOR_ID=(SELECT VENDOR_ID FROM  [DBO].[VENDORS_MASTER] WHERE VENDOR_CODE=(SELECT VENDOR_CODE FROM  [DBO].[POHEADER] WHERE POID=(SELECT POID FROM  [DBO].[INSPECTION_REQUESTS] WHERE INSP_ID =@ID) ) ) ORDER BY A.MODIFIED_DATE DESC
	
	   
		
		END
	IF(@CMD='INSPECT_DETAILS_BY_INSPECTION_ID')
		BEGIN
			SELECT I.INSPECT_ID,I.INSPECTION_ID,I.INSPECTOR_CODE, I.OFFERED_QTY,I.GPT_NO,I.GPT_STATUS,I.GPT_APPROVED_BY,I.GPT_APPROVED_DATE,I.NO_OF_BAGS_CARTONS_QTY,I.NO_OF_BAGS_CARTONS_UNIT,
			I.PACKING_STATUS,I.INLINE_DONE,I.PACKING_LIST,I.PPS_RELEASE_DATE,I.PPS_EXPIRY_DATE,I.FIBER_CONTENT_ON_PO, I.FIBER_CONTENT_ON_TEST_REPORT, I.FIBER_CONTENT_ON_WC, I.GSM_ON_PO,I.GSM_ON_TEST_REPORT,
			I.GSM_ON_BULK,I.MEASUREMENT_SAMPLE_SIZE,I.MEASUREMENT_ATTACHMENT, I.NO_OF_CHECK,I.NO_OF_CHECK_UNIT,NO_OF_PREPACK_CHECK,I.WORKMANSHIP,I.DEFECTS_STATUS,
			I.INSPECTION_RESULT,I.REMARK_COMMENT, I.NOTE, I.NAME_OF_FACTORY_REPRESENTATIVE, I.TEST_REPORT_ATTACHMENT,I.GEN_ATTACHMENT_FIRST,I.GEN_ATTACHMENT_SECOND, I.IS_COMPLETE,I.CREATED_BY,I.CREATED_DATE,
			I.MODIFIED_BY, I.MODIFIED_DATE, A.SAMPLE_SIZE as AQL_SAMPLE_SIZE, A.AQL_2_5_MAJOR,A.AQL_2_5_MINOR,
			I.RESEAN_FOR_FAIL,	I.COLOR_CODE,	I.MFG_DATE,	I.GPT_COMM_APPROVAL_DATE,	I.SEASON,	I.AREA_OF_FAIL_GPTR,	I.GPT_COMM_APPROVED_BY,
			GPT_ELASTIC_NO,GPT_ELASTIC_STATUS,GPT_ELASTIC_APPROVED_BY,GPT_ELASTIC_APPROVED_DATE,CONFORMITY_SIZE,CONFORMITY_SIZE_STATUS,CONFORMITY_PREPACK,
			CONFORMITY_PREPACK_STATUS,EMBROIDERY_PF	,ACCESSORIES_PF,BARCODE_PF,NO_PLASTIC_PF,BOGO_PF,THREAD_YN,BUTTON_YN,ZIPPER_YN,INTERLINING_YN,ELASTIC_YN,MEASUREMENT_SAMPLE_QTY,
			I.DATE_OF_COMPLETION,
			ZIPPER_RPT_NO,ZIPPER_STATUS,ZIPPER_APPROVED_BY,ZIPPER_APPROVED_DATE,I.FIT,COMM_APPROVAL_DOC,DEBIT_AMOUNT,ADMIN_REMARK,
			I.ABORTIVE_REASON_IDS,I.OTHER_ABORTIVE_REASON ,I.AMT_TRAVELLING ,I.SELECTED_BAG_CARTONS_NO,I.LAST_UPDATE_DATE_BY_ADMIN 
			FROM INSPECTIONS I 
			LEFT JOIN MASTER_AQL A ON  I.AQL_ID=A.AQL_ID
			WHERE I.INSPECTION_ID=@ID

			SELECT  DEFECTS_ID, INSPECTION_ID, DEFECTS, DIMENSION, MAJOR, MINOR
			FROM INSPECTION_DEFECTS WHERE INSPECTION_ID=@ID

			SELECT BATCH_SIZE_MIN, BATCH_SIZE_MAX, SAMPLE_SIZE,AQL_2_5_MAJOR,AQL_2_5_MINOR  FROM MASTER_AQL ORDER BY AQL_ID
		END
	IF(@CMD='INSPECTION_REPORT_PDF')
		BEGIN
			
			SET NOCOUNT ON;

			;WITH PODETAIL_CTE AS
			(
				SELECT PD.POID, STRING_AGG(CONCAT(PD.Article, '~',CAST( ISNULL(PD.MRP,0) as INT), '/-'), ' | ')  WITHIN GROUP (ORDER BY PD.LINE_ITEM) AS ARTICLES
				FROM PODETAIL PD
				INNER JOIN INSPECTION_REQUESTS ir ON ir.POID = PD.POID
				INNER JOIN INSPECTIONS i ON i.INSPECTION_ID = ir.INSP_ID
				WHERE  PD.LINE_ITEM % 100 = 0 AND i.INSPECT_ID = @ID
				GROUP BY PD.POID
			)

			SELECT

			    I.DATE_OF_COMPLETION,
				ISNULL(A.INSPECTION_NO,'NA') AS INSPECTION_REPORT_NO,
				IT.INSPECTION_TYPE AS TYPE_OF_INSPECTION,
				P.PASSFAIL AS INSPECTION_RESULT,

				CASE WHEN ISNULL(B.BUYER_NAME,'') <> '' AND ISNULL(B.BUYER_ID,'') <> '' THEN B.BUYER_NAME + '[' + B.BUYER_ID + ']' ELSE '-' END AS BUYER_NAME,
				CONCAT (B.PO_NUMBER, CASE WHEN ISNULL(B.LINK_PO_NUMBER,'') <> '' THEN ' ~ ' + B.LINK_PO_NUMBER ELSE '' END ) AS PO_NUMBER,

				B.VENDOR_CODE,
				B.VENDOR_NAME,
				E.ADDRESS_LINE1 +', '+ E.CITY +', '+ E.REGION_DESCRIPTION +', '+ E.PINCODE+ ', '+RM.REGION AS LOCATION,
				E.ADDRESS_LINE1 +', '+ E.CITY +', '+ E.REGION_DESCRIPTION +', '+ E.PINCODE AS ADDRESS,
				CAST(B.TOTAL_QTY AS FLOAT) AS PO_QTY,
				
				B.MC_TEXT AS DESCRIPTION,
				B.FIT AS PO_FIT,
				B.MRP,

				CAST(A.OFFERED_QTY AS FLOAT) AS OFFERED_QTY,
				CAST(I.OFFERED_QTY AS FLOAT) AS SHIP_QTY,

				B.CATEGORY,
				CASE WHEN ISNULL(B.BRAND_ID2,'') <> '' AND ISNULL(B.BRAND_ID,'') <> '' THEN B.BRAND_ID2 + ' [ ' + B.BRAND_ID + ' ]' ELSE '-' END AS BRAND_LABEL,
				B.COLOR,
				PD.ARTICLES ,
			   
			    I.GPT_NO AS GPT_NO,
				CASE WHEN I.GPT_STATUS > 0 THEN GSPF.PASSFAIL ELSE '' END AS GPT_STATUS,
				I.GPT_APPROVED_BY AS APPROVED_BY_IF_GPT_FAILS,
				I.GPT_APPROVED_DATE AS APPROVED_DATE,
				I.AREA_OF_FAIL_GPTR AS AREA_OF_FAILURE_GPTR	,

				I.GPT_ELASTIC_NO,
				CASE WHEN I.GPT_ELASTIC_STATUS > 0 THEN ESPF.PASSFAIL ELSE '' END AS ELASTIC_STATUS,
				I.GPT_ELASTIC_APPROVED_BY,
				I.GPT_ELASTIC_APPROVED_DATE,

				I.ZIPPER_RPT_NO AS ZIPPER_REPORT_NO,
				CASE WHEN I.ZIPPER_STATUS > 0 THEN ZSPF.PASSFAIL ELSE '' END AS ZIPPER_REPORT_STATUS,
				I.ZIPPER_APPROVED_BY AS IF_FAIL_ZIPPER_APPROVED_BY,
				I.ZIPPER_APPROVED_DATE,
				
				CASE WHEN I.NO_OF_BAGS_CARTONS_QTY > 0 THEN CAST(I.NO_OF_BAGS_CARTONS_QTY AS VARCHAR) + ' ' + ISNULL(UNOB.UNIT,'') ELSE ''
				END AS NO_OF_BAGS_CARTON,
				CASE WHEN I.PACKING_STATUS > 0 THEN PSYN.YESNO ELSE '' END AS PACKING_STATUS,

				CASE WHEN I.INLINE_DONE > 0 THEN IDYN.YESNO ELSE '' END AS INLINE_DONE,
				CASE WHEN I.PACKING_LIST > 0 THEN PLYN.YESNO ELSE '' END AS PACKING_LIST,
				
				CONVERT(VARCHAR(11), I.PPS_RELEASE_DATE, 106) AS PPS_RELEASE_DATE,
				CONVERT(VARCHAR(11), I.PPS_EXPIRY_DATE, 106) AS PPS_EXPIRY_DATE,
				CONVERT(VARCHAR(11), I.MFG_DATE, 106) AS MFG_DATE,

				I.SEASON,
				CC.COLOR_CODE,

				I.FIBER_CONTENT_ON_PO,
				I.FIBER_CONTENT_ON_TEST_REPORT,
				I.FIBER_CONTENT_ON_WC AS FIBER_CONTENT_ON_LABEL,
				
				I.GSM_ON_PO,
				I.GSM_ON_TEST_REPORT,
				I.GSM_ON_BULK,

				I.FIT AS INSPECTION_FIT,
				ISNULL(I.SELECTED_BAG_CARTONS_NO,'') AS SELECTED_BAGS_CARTON_NO,

				ISNULL(MFR.FAIL_REASON,'') AS FAIL_REASON,
				MAQL.SAMPLE_SIZE,
				

				I.CONFORMITY_SIZE,
				CASE WHEN I.CONFORMITY_SIZE_STATUS > 0 THEN  SSPF.PASSFAIL ELSE '' END AS CONFORMITY_SIZE_STATUS,
				CASE WHEN I.EMBROIDERY_PF > 0 THEN EMPF.PASSFAIL ELSE '' END AS EMBRIODERY_PRINT_SHOULD_BE_AS_PER_PPS,
				CASE WHEN I.ACCESSORIES_PF > 0 THEN ACPF.PASSFAIL ELSE '' END AS ACCESSORIES_SHOULD_BE_AS_PER_PPS,
				CASE WHEN I.BARCODE_PF > 0 THEN BAPF.PASSFAIL ELSE '' END AS BARCODE_COMPLIANCES,
				CASE WHEN I.NO_PLASTIC_PF > 0 THEN NPPF.PASSFAIL ELSE '' END AS NO_PLASTIC_TAG_KIMBLE_TAG,
				CASE WHEN I.BOGO_PF > 0 THEN BOPF.PASSFAIL ELSE '' END AS BOGO_DISCOUNT_TAG,

				I.CONFORMITY_PREPACK ,
				CASE WHEN I.CONFORMITY_PREPACK_STATUS > 0 THEN PPRYN.YESNO ELSE '' END AS CONFORMITY_PREPACK_STATUS,
				CASE WHEN I.THREAD_YN > 0 THEN THYN.YESNO ELSE '' END AS THREAD_FROM_NOMINATED_Y_N,
				CASE WHEN I.BUTTON_YN > 0 THEN BUYN.YESNO ELSE '' END AS BUTTON_FROM_NOMINATED_Y_N,
				CASE WHEN I.ZIPPER_YN > 0 THEN ZIYN.YESNO ELSE '' END AS ZIPPER_FROM_NOMINATED_Y_N,
				CASE WHEN I.INTERLINING_YN > 0 THEN INYN.YESNO ELSE '' END AS INTERLINING_FROM_NOMINATED_VENDOR_Y_N,
				CASE WHEN I.ELASTIC_YN > 0 THEN ELYN.YESNO ELSE '' END AS ELASTIC_FROM_NOMINATED_Y_N,

				I.MEASUREMENT_SAMPLE_QTY AS MESUREMENT_SAMPLE_SIZE,
				CASE WHEN I.MEASUREMENT_SAMPLE_SIZE > 0 THEN MPF.PASSFAIL ELSE '' END AS MEASUREMENT_PASS_FAIL,

				MAQL.AQL_2_5_MAJOR AS ALLOWED_MAJOR,
				MAQL.AQL_2_5_MINOR AS ALLOWED_MINOR,

				CASE WHEN I.NO_OF_CHECK > 0 THEN CAST(I.NO_OF_CHECK AS VARCHAR) + ' ' + ISNULL(UCOB.UNIT,'') ELSE '0 BAG' END AS NO_OF_CHECK_CARTON_BAG,
				I.NO_OF_PREPACK_CHECK AS NO_OF_CHECK_PRE_PACK,
				
				CONVERT(VARCHAR(11), I.GPT_COMM_APPROVAL_DATE,106) AS FI_COMM_APPR_DATE,
				ISNULL(I.GPT_COMM_APPROVED_BY,'') AS FI_COMM_APPROVED_BY,
				ISNULL(I.COMM_APPROVAL_DOC,'') AS COMM_APPROVAL_DOCUMENTS,
				I.DEBIT_AMOUNT,
				I.AMT_TRAVELLING,
				ISNULL(I.ADMIN_REMARK,'') AS ADMIN_REMARK,

				ISNULL(I.REMARK_COMMENT,'') AS REMARKS_DETAILS,
				ISNULL(I.NOTE,'') AS NOTE ,

				CASE  WHEN ISNULL(A.INSPECTOR_EMP_CODE,'') <> '' AND ISNULL(INSP.EMP_NAME,'') <> '' THEN INSP.EMP_NAME + ' [ ' + A.INSPECTOR_EMP_CODE + ' ]' ELSE '-' END AS NAME_OF_THE_VMM_QA,
				INSP.STAMP_NO,
				INSP.SIGN,
				I.NAME_OF_FACTORY_REPRESENTATIVE,

				CASE  WHEN ISNULL(ADMN.EMP_NAME,'') <> '' THEN ADMN.EMP_NAME + ' [ ' + ADMN.EMP_CODE + ' ]' ELSE '---' END AS NAME_OF_QA_ADMIN,
				ADMN.STAMP_NO AS QAADMIN_STAMP_NO,
				ADMN.SIGN AS QAADMIN_SIGN,
				

				I.TEST_REPORT_ATTACHMENT,
				I.GEN_ATTACHMENT_FIRST,
				
				I.IS_COMPLETE,
				I.IS_EDIT_BY_ADMIN,

				I.ABORTIVE_REASON_IDS,
				I.OTHER_ABORTIVE_REASON,

				B.APPARELS AS APPS_NON_APPS,
				E.CONTACT_PERSON AS CONTACT_NAME,
				E.MOBILE_NUMBERS AS CONTACT_NUMBER,
				
				I.INSPECT_ID,
				A.INSP_ID,
				A.POID,
				CONVERT(VARCHAR(11), A.DATE_OF_INSPECTION, 106) AS INSPECTION_DATE,
				A.INSPECTION_TYPE_ID,
				I.LAST_UPDATE_DATE_BY_ADMIN

			FROM INSPECTIONS I

			INNER JOIN INSPECTION_REQUESTS A
				ON I.INSPECTION_ID= A.INSP_ID
			
			INNER JOIN PODETAIL_CTE PD ON A.POID = PD.POID 
				
			LEFT JOIN MASTER_REGION RM 
				ON A.REGION_ID = RM.REGION_ID

			LEFT JOIN POHEADER B 
				ON A.POID = B.POID

			LEFT JOIN VENDOR_ADDRESS E
				ON A.ADDRESS_ID = E.ADDRESS_ID

			LEFT JOIN MASTER_PASSFAIL P
				ON I.INSPECTION_RESULT = P.PASSFAIL_ID

			LEFT JOIN USER_MASTER INSP
				ON A.INSPECTOR_EMP_CODE = INSP.EMP_CODE

			LEFT JOIN USER_MASTER ADMN
				ON I.MODIFIED_BY = ADMN.ID AND I.IS_EDIT_BY_ADMIN=1  AND (ADMN.ROLE_ID=1008 OR ADMN.ROLE_ID=1007)

			LEFT JOIN MASTER_INSPECTION_TYPE IT
				ON A.INSPECTION_TYPE_ID = IT.INSPECTION_TYPE_ID

			LEFT JOIN MASTER_FAIL_REASON MFR
				ON I.RESEAN_FOR_FAIL = MFR.FAIL_REASON_ID

			LEFT JOIN MASTER_COLOR_CODE CC
				ON I.COLOR_CODE = CC.COLOR_CODE_ID

			LEFT JOIN MASTER_UNIT UNOB
				ON I.NO_OF_BAGS_CARTONS_UNIT = UNOB.UNIT_ID

			LEFT JOIN MASTER_UNIT UCOB
				ON I.NO_OF_CHECK_UNIT = UCOB.UNIT_ID

			LEFT JOIN MASTER_PASSFAIL MPF
				ON I.MEASUREMENT_SAMPLE_SIZE = MPF.PASSFAIL_ID

			LEFT JOIN MASTER_YESNO PSYN
				ON I.PACKING_STATUS = PSYN.YESNO_ID

			LEFT JOIN MASTER_YESNO PLYN
				ON I.PACKING_LIST = PLYN.YESNO_ID

			LEFT JOIN MASTER_YESNO IDYN
				ON I.INLINE_DONE = IDYN.YESNO_ID

			LEFT JOIN MASTER_PASSFAIL GSPF
				ON I.GPT_STATUS = GSPF.PASSFAIL_ID

			LEFT JOIN MASTER_PASSFAIL ESPF
				ON I.GPT_ELASTIC_STATUS = ESPF.PASSFAIL_ID

			LEFT JOIN MASTER_PASSFAIL ZSPF
				ON I.ZIPPER_STATUS = ZSPF.PASSFAIL_ID

			LEFT JOIN MASTER_PASSFAIL SSPF
				ON I.CONFORMITY_SIZE_STATUS = SSPF.PASSFAIL_ID

			LEFT JOIN MASTER_PASSFAIL EMPF
				ON I.EMBROIDERY_PF = EMPF.PASSFAIL_ID

			LEFT JOIN MASTER_PASSFAIL ACPF
				ON I.ACCESSORIES_PF = ACPF.PASSFAIL_ID

			LEFT JOIN MASTER_PASSFAIL BAPF
				ON I.BARCODE_PF = BAPF.PASSFAIL_ID

			LEFT JOIN MASTER_PASSFAIL NPPF
				ON I.NO_PLASTIC_PF = NPPF.PASSFAIL_ID

			LEFT JOIN MASTER_PASSFAIL BOPF
				ON I.BOGO_PF = BOPF.PASSFAIL_ID

			LEFT JOIN MASTER_YESNO PPRYN
				ON I.CONFORMITY_PREPACK_STATUS = PPRYN.YESNO_ID

			LEFT JOIN MASTER_YESNO THYN
				ON I.THREAD_YN = THYN.YESNO_ID

			LEFT JOIN MASTER_YESNO BUYN
				ON I.BUTTON_YN = BUYN.YESNO_ID

			LEFT JOIN MASTER_YESNO ZIYN
				ON I.ZIPPER_YN = ZIYN.YESNO_ID

			LEFT JOIN MASTER_YESNO INYN
				ON I.INTERLINING_YN = INYN.YESNO_ID

			LEFT JOIN MASTER_YESNO ELYN
				ON I.ELASTIC_YN = ELYN.YESNO_ID

			LEFT JOIN MASTER_AQL MAQL
				ON I.OFFERED_QTY BETWEEN MAQL.BATCH_SIZE_MIN AND MAQL.BATCH_SIZE_MAX

			WHERE I.INSPECT_ID = @ID


			--DEFECTS--
			SELECT D.DEFECTS_ID,  D.DEFECTS,MAJOR, MINOR 
			FROM INSPECTION_DEFECTS D
			INNER JOIN INSPECTION_REQUESTS IR on D.INSPECTION_ID=IR.INSP_ID
			INNER JOIN INSPECTIONS I ON IR.INSP_ID = I.INSPECTION_ID
			WHERE I.INSPECT_ID = @ID

			--ABORTIVE REASONS--
			SELECT AR_ID,REASON FROM MASTER_ABORTIVE_REASON MAR
			
		END

	--INSERT INTO [dbo].[TESTDESHBOARDLIST]([START_TIME],[INSP_IDS],[OUTPUT_TIME],[EXECUTION_TIME_IN_MS])
	--VALUES (@SDATE,'CMD : '+ @CMD +', STRFIELD : '+@STRFIELD+', | ID : '+ CAST(@ID as VARCHAR) ,GETDATE(),DATEDIFF(MILLISECOND, @SDATE, GETDATE()))
END
GO
/****** Object:  StoredProcedure [dbo].[PRO_MASTER_LOOKUPS]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author: Dinesh Baghel
-- Create date: 18 Aug 2026
-- Description:	Select Master Data 
-- =============================================

CREATE PROCEDURE [dbo].[PRO_MASTER_LOOKUPS]
	@ID INT,
	@STRFIELD VARCHAR(50),
	@CMD VARCHAR(100)
AS
BEGIN
	SET NOCOUNT ON;

	IF(@CMD='BULKINSPECITON')--1
		BEGIN
			  Select INSPECT_ID as Master_ID, R.INSPECTION_NO  as Master_Name  
			  from INSPECTIONS I
			  INNER JOIN INSPECTION_REQUESTS R ON I.INSPECTION_ID=R.INSP_ID
			  where   IS_COMPLETE=1 AND INSPECTION_RESULT in (1,2) --AND QA_ASSIGNED_DOI between '20 Jul 2026' and '30 Jul 2026'
			  ORDER BY INSPECT_ID
		END
	IF(@CMD='Buyer_Master_List')--2
		BEGIN
			SELECT distinct BUYER_ID  as String_ID, BUYER_NAME as Master_Name  FROM [dbo].[POHEADER] WHERE BUYER_ID IS NOT NULL
		END
	IF(@CMD='Category_Master_List')--3
		BEGIN
			SELECT distinct CATEGORY  as String_ID, CATEGORY as Master_Name  FROM [dbo].[POHEADER] WHERE CATEGORY IS NOT NULL
		END
	IF(@CMD='GET_ABORTIVE_REASONS')--4
		BEGIN
			SELECT AR_ID  as Master_ID, REASON as Master_Name  FROM [dbo].[MASTER_ABORTIVE_REASON] WHERE IS_ACTIVE=1
		END
	IF(@CMD='GET_BUSINESS_HEAD')--5
		BEGIN
			SELECT ID  as Master_ID, HEAD as Master_Name  FROM [dbo].[MASTER_BUSINESS_HEAD] WHERE ACTIVE=1
		END
	IF(@CMD='GET_CM_STATUS')--6
		BEGIN
			SELECT ID  as Master_ID, STATUS as Master_Name  FROM [dbo].[MASTER_APPROVE_REJECT] 
		END
	IF(@CMD='GET_COLOR_CODE')--7
		BEGIN
			SELECT COLOR_CODE_ID  as Master_ID, COLOR_CODE as Master_Name  FROM [dbo].[MASTER_COLOR_CODE] WHERE ACTIVE=1
		END
	IF(@CMD='GET_FAIL_REASON')--8
		BEGIN
			SELECT FAIL_REASON_ID  as Master_ID, FAIL_REASON as Master_Name  FROM [dbo].[MASTER_FAIL_REASON] WHERE ACTIVE=1
		END
	IF(@CMD='Get_Hierarchy_Roles_List')--9
		BEGIN
			SELECT 0  as Master_ID, '--Select Role--' as Master_Name  FROM [dbo].[ROLE_MASTER] 
			UNION
			SELECT ID  as Master_ID, ROLE_NAME as Master_Name  FROM [dbo].[ROLE_MASTER] WHERE ACTIVE_STATUS=1 AND ID IN(1010,1011,2)
		END
	IF(@CMD='GET_INSPECTION_MASTERS')--10
		BEGIN
			SELECT CONFORM_ID as ID ,CONFORM as NAME ,'CONFORM' as MTYPE FROM MASTER_CONFORM UNION ALL
			SELECT CLASSIFICATION_ID,CLASSIFICATION,'CLASSIFICATION' FROM MASTER_CLASSIFICATION UNION ALL
			SELECT RESULT_TYPE_ID,RESULT,'RESULT' FROM MASTER_RESULT UNION ALL
			SELECT INSPECTION_TYPE_ID,INSPECTION_TYPE,'INSPECTIONTYPE' FROM MASTER_INSPECTION_TYPE 
		END
	IF(@CMD='GET_INSPECTION_TYPE')--11
		BEGIN
			SELECT TOP 1 MIT.INSPECTION_TYPE_ID AS Master_ID,MIT.INSPECTION_TYPE AS Master_Name
			FROM MASTER_INSPECTION_TYPE MIT
			WHERE MIT.ACTIVE = 1 AND MIT.INSPECTION_TYPE_ID NOT IN(select INSPECTION_TYPE_ID from INSPECTION_REQUESTS where POID=(select TOP 1 POID from POHEADER where PO_NUMBER=@STRFIELD ORDER BY POID DESC) AND STATUS_CODE=7 )
			ORDER BY MIT.INSPECTION_TYPE_ID
		END
	IF(@CMD='GET_PASSFAIL')--12
		BEGIN
			SELECT PASSFAIL_ID  as Master_ID, PASSFAIL as Master_Name  FROM [dbo].[MASTER_PASSFAIL] WHERE ACTIVE=1
		END
	IF(@CMD='GET_REGION') --13
		BEGIN
			SELECT REGION_ID  as Master_ID, REGION as Master_Name  FROM [dbo].[MASTER_REGION] WHERE ACTIVE=1
		END
	IF(@CMD='GET_REGION_WITH_QAM') --14
		BEGIN
			SELECT A.REGION_ID  as Master_ID,  U.EMP_NAME+' ( '+A.REGION+' )' as Master_Name  
			FROM [dbo].[MASTER_REGION] A
			LEFT JOIN USER_MASTER U ON A.QAM_EMP_CODE=U.EMP_CODE
			WHERE ACTIVE=1
		END
	IF(@CMD='Get_ReportingManager_Master')--15
		BEGIN
			SELECT 0  as Master_ID, 'NA' as Master_Name  FROM [dbo].[MASTER_HIERARCHY] 
			UNION
			SELECT EMP_CODE  as Master_ID, EMP_NAME+'['+ EMP_CODE+']' as Master_Name  FROM [dbo].[MASTER_HIERARCHY] WHERE IS_ACTIVE=1 AND ROLE_ID IN(1010,1011)
		END
	IF(@CMD='GET_UNIT')--16
		BEGIN
			SELECT UNIT_ID  as Master_ID, UNIT as Master_Name  FROM [dbo].[MASTER_UNIT] WHERE ACTIVE=1
		END
	IF(@CMD='GET_YESNO')--17
		BEGIN
			SELECT YESNO_ID  as Master_ID, YESNO as Master_Name  FROM [dbo].[MASTER_YESNO] WHERE ACTIVE=1
		END
	 IF(@CMD='Inspector_Master_List')--18
		BEGIN
			SELECT distinct EMP_CODE  as String_ID, EMP_NAME as Master_Name  FROM [dbo].[USER_MASTER] WHERE ROLE_ID IN (1006,1007) 
		END
	IF(@CMD='Product_Master_List')--19
		BEGIN
			SELECT distinct MC  as String_ID, MC_TEXT as Master_Name  FROM [dbo].[POHEADER] WHERE MC IS NOT NULL
		END
	IF(@CMD='Vendor_Master_List')--20
		BEGIN
			SELECT VENDOR_CODE  as String_ID, VENDOR_NAME as Master_Name  FROM [dbo].[VENDORS_MASTER] WHERE IS_ACTIVE=1
		END
	
END
GO
/****** Object:  StoredProcedure [dbo].[PRO_PO_VENDOR_MASTER]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author: Dinesh Baghel
-- Create date: 18 Aug 2026
-- Description:	PRO_USER_ROLE_MENU — auth/menu/role, completely unrelated domain to inspections
-- =============================================

CREATE PROCEDURE [dbo].[PRO_PO_VENDOR_MASTER]
	@ID INT,
	@STRFIELD VARCHAR(50),
	@CMD VARCHAR(100)
AS
BEGIN
	SET NOCOUNT ON;
	If(@CMD='AQLDATA')--1
		BEGIN
			SELECT * FROM  [dbo].[MASTER_AQL] WHERE CAST(@STRFIELD AS INT)  BETWEEN BATCH_SIZE_MIN  AND BATCH_SIZE_MAX 
		END
	 IF(@CMD='Get_All_Excel_Vendors')--2
		BEGIN
			SELECT VENDOR_CODE  as Master_ID, EMAIL_IDS as Master_Name  FROM [dbo].[VENODR_EXCEL_DETAILS] WHERE ISNULL(IS_CONFIRMED,0)=1
		END
	If(@CMD='Get_GST_Details')--3
		BEGIN
			SELECT  GST_NUMBER,VENDOR_NAME,REGISTERED_ADDRESS,GST_API_RAW_RESPONSE FROM  [dbo].[FACTORY_AUDIT_REQUESTS] WHERE GST_NUMBER=@STRFIELD
		END
	IF(@CMD='Get_All_VENDORS')--4
		BEGIN
			SELECT VENDOR_ID,VENDOR_CODE,VENDOR_NAME,GST_NO,PASSWORD,DEFAULT_PASSWORD_CHANGED,IS_ACTIVE,IS_EMAIL_SENT,
		    ISNULL(	CONVERT(varchar(10),A.LAST_LOGIN_DATE, 103),'') as LAST_LOGIN_DATE,
			ISNULL(	CONVERT(varchar(10),A.CURRENT_LOGIN_DATE, 103),'') as CURRENT_LOGIN_DATE,isnull(A.IP_ADDRESS,'') as IP_ADDRESS,
			ISNULL(	CONVERT(varchar(10),CREATED_DATE, 103),'') as CREATED_DATE,
			ISNULL(	CONVERT(varchar(10),MODIFIED_DATE, 103),'') as MODIFIED_DATE,
			CREATED_BY,
			B.EMP_NAME as	CREATED_BY_NAME,	isnull(MODIFIED_BY,0) MODIFIED_BY ,
			C.EMP_NAME as	MODIFIED_BY_NAME
			FROM  [DBO].[VENDORS_MASTER] A  
			left join [DBO].USER_MASTER B on A.CREATED_BY=B.ID
			left join [DBO].USER_MASTER C on A.MODIFIED_BY=C.ID
			ORDER BY A.MODIFIED_DATE DESC
		
		END
	IF(@CMD='Get_PO_Details')--5
		BEGIN
			SELECT TOP 1 POID,PO_NUMBER,ISNULL(LINK_PO_NUMBER,'') as LINK_PO_NUMBER,VENDOR_CODE,VENDOR_NAME, FABRIC, COLOR,TOTAL_QTY,
			A.APPARELS,A.CATEGORY,A.BUYER_NAME,A.BUYER_ID,
			CREATED_ON,
			LAST_UPDATED_ON, GetDate() as DATE_OF_INSPECTION,
			CREATED_BY,	isnull(UPDATED_BY,0) MODIFIED_BY , 'Draft' as INSP_REQ_STATUS,A.MC,A.MC_TEXT, A.MRP, A.BRAND_ID, A.BRAND_ID2,A.FIT
			FROM  [DBO].[POHEADER] A WHERE PO_NUMBER=@STRFIELD  ORDER BY POID DESC

			SELECT PO_DETAILS_ID, POID,LINE_ITEM,ARTICLE,ARTICLE_DESC,PREPACK_QTY,PREPACK_QTY_EACHES,PURCHASE_TOT_QTY,EACHES,MRP,ATTYP,
			CREATED_ON,
			LAST_UPDATED_ON,
			CREATED_BY,	isnull(UPDATED_BY,0) UPDATED_BY 
			FROM   [DBO].[PODETAIL] A WHERE POID=(SELECT TOP 1 POID FROM  [DBO].[POHEADER] WHERE PO_NUMBER=@STRFIELD ORDER BY POID DESC)
		END
	IF(@CMD='Get_Vendor_Address')--6
		BEGIN
			SELECT ADDRESS_ID, VENDOR_ID,ADDRESS_LINE1,CITY,PINCODE,EMAIL_IDS,MOBILE_NUMBERS,CONTACT_PERSON,REGION_CODE,REGION_DESCRIPTION,IS_DEFAULT,
			ISNULL(	CONVERT(varchar(10),CREATED_DATE, 103),'') as CREATED_DATE,
			ISNULL(	CONVERT(varchar(10),MODIFIED_DATE, 103),'') as MODIFIED_DATE,
			CREATED_BY,	isnull(MODIFIED_BY,0) MODIFIED_BY 
			FROM   [DBO].[VENDOR_ADDRESS] A WHERE VENDOR_ID=@ID  ORDER BY A.MODIFIED_DATE DESC
		
		END
	IF(@CMD='Get_Vendor_By_Code')--7
		BEGIN
			SELECT VENDOR_ID,VENDOR_CODE,VENDOR_NAME,GST_NO,PASSWORD,DEFAULT_PASSWORD_CHANGED,IS_ACTIVE,IS_EMAIL_SENT,
		    ISNULL(	CONVERT(varchar(10),LAST_LOGIN_DATE, 103),'') as LAST_LOGIN_DATE,
			ISNULL(	CONVERT(varchar(10),CURRENT_LOGIN_DATE, 103),'') as CURRENT_LOGIN_DATE,isnull(IP_ADDRESS,'') as IP_ADDRESS,
			ISNULL(	CONVERT(varchar(10),CREATED_DATE, 103),'') as CREATED_DATE,
			ISNULL(	CONVERT(varchar(10),MODIFIED_DATE, 103),'') as MODIFIED_DATE,
			CREATED_BY,	isnull(MODIFIED_BY,0) MODIFIED_BY 
			FROM  [DBO].[VENDORS_MASTER] A WHERE VENDOR_CODE=@STRFIELD  


			SELECT ADDRESS_ID, VENDOR_ID,ADDRESS_LINE1,CITY,PINCODE,EMAIL_IDS,MOBILE_NUMBERS,CONTACT_PERSON,REGION_CODE,REGION_DESCRIPTION,IS_DEFAULT,
			ISNULL(	CONVERT(varchar(10),CREATED_DATE, 103),'') as CREATED_DATE,
			ISNULL(	CONVERT(varchar(10),MODIFIED_DATE, 103),'') as MODIFIED_DATE,
			CREATED_BY,	isnull(MODIFIED_BY,0) MODIFIED_BY 
			FROM   [DBO].[VENDOR_ADDRESS] A WHERE VENDOR_ID=(SELECT VENDOR_ID FROM  [DBO].[VENDORS_MASTER] WHERE VENDOR_CODE=@STRFIELD)  ORDER BY A.MODIFIED_DATE DESC
		
		END

	IF(@CMD='VENDOR_EXCEL_DATA')--8
		BEGIN
			SELECT EXCEL_ID,EXCEL_FILE,NO_OF_RECORDS,NO_INCORRECT_RECORDS,INCORRECT_DETAILS,DATE_OF_UPLOAD,
			U.EMP_CODE, U.EMP_NAME FROM VENDOR_EXCELS V
			INNER JOIN USER_MASTER U ON V.CREATED_BY=U.ID
			WHERE V.CREATED_BY=@ID
								
			if(@STRFIELD='ALL')
				BEGIN
					SELECT VENDOR_CODE,	EMAIL_IDS,	EXCEL_ID,	DATE_CREATED, V.CM_STATUS as CM_STATUS_ID, isnull(S.STATUS,'Approval Pending') as CM_STATUS,	ISNULL(CMU.EMP_CODE,'') as CMCODE,	
					ISNULL(CMU.EMP_NAME,'')+'~'+ISNULL(CMU.EMP_CODE,'') as CMNAME,	ISNULL(convert(varchar,CM_DATE,106),'') CM_DATE,	ISNULL(IS_CONFIRMED,0) IS_CONFIRMED,	CREATED_BY,	U.EMP_CODE, U.EMP_NAME 
					FROM VENODR_EXCEL_DETAILS V
					INNER JOIN USER_MASTER U ON V.CREATED_BY=U.ID
					LEFT JOIN [dbo].[MASTER_APPROVE_REJECT] S ON V.CM_STATUS=S.ID
					LEFT JOIN USER_MASTER CMU ON V.CM_USER_ID=CMU.ID
				END
			ELSE
				BEGIN
					SELECT VENDOR_CODE,	EMAIL_IDS,	EXCEL_ID,	DATE_CREATED,V.CM_STATUS as CM_STATUS_ID, isnull(S.STATUS,'Approval Pending') as CM_STATUS,	ISNULL(CMU.EMP_CODE,'') as CMCODE,	
					ISNULL(CMU.EMP_NAME,'')+'~'+ISNULL(CMU.EMP_CODE,'') as CMNAME,	ISNULL(convert(varchar,CM_DATE,106),'') CM_DATE,	ISNULL(IS_CONFIRMED,0) IS_CONFIRMED,	CREATED_BY,	U.EMP_CODE, U.EMP_NAME 
					FROM VENODR_EXCEL_DETAILS V
					INNER JOIN USER_MASTER U ON V.CREATED_BY=U.ID
					LEFT JOIN [dbo].[MASTER_APPROVE_REJECT] S ON V.CM_STATUS=S.ID
					LEFT JOIN USER_MASTER CMU ON V.CM_USER_ID=CMU.ID
					WHERE V.CREATED_BY=@ID
				END
			

		END

	
	
END
GO
/****** Object:  StoredProcedure [dbo].[PRO_QA_DASHBOARD]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author: Dinesh Baghel
-- Create date: 18 Aug 2026
-- Description:	PRO_QA_DASHBOARD — inspector/QA landing-page counts, all against INSPECTION_REQUESTS + INSPECTOR_ASSIGNMENTS
-- 1. QA_DASHBOARD, 2. QA_DASHBOARD_PENDING, 3. QA_DASHBOARD_ONGOING, 4. GET_REGION_WISE_INSPECTORS
-- =============================================

CREATE PROCEDURE [dbo].[PRO_QA_DASHBOARD]
	@ID INT,
	@STRFIELD VARCHAR(50),
	@CMD VARCHAR(100)
AS
BEGIN
	SET NOCOUNT ON;

	
	IF(@CMD='QA_DASHBOARD')--1
		BEGIN
			SELECT INSP_ID,POID,
			CAST(CASE WHEN IS_DATE_ASSIGNED_BY_QA is null THEN   DATE_OF_INSPECTION ELSE QA_ASSIGNED_DOI END AS DATE) AS  DOI,
			ISNULL(IS_DATE_ASSIGNED_BY_QA,0) IS_DATE_ASSIGNED_BY_QA ,ISNULL(IS_INSPECTOR_ASSIGNED,0) IS_INSPECTOR_ASSIGNED,REGION_ID
			FROM INSPECTION_REQUESTS
			WHERE STATUS_CODE <> 9 AND CAST(CASE WHEN IS_DATE_ASSIGNED_BY_QA is null THEN   DATE_OF_INSPECTION ELSE QA_ASSIGNED_DOI END AS DATE) > GETDATE() AND
			REGION_ID IN (SELECT value FROM STRING_SPLIT((SELECT REGION_IDS  FROM USER_MASTER WHERE EMP_CODE=@STRFIELD), ','))


			SELECT A.INSPECTION_DATE,U.EMP_NAME,U.EMP_CODE, A.CREATED_DATE FROM [dbo].[INSPECTOR_ASSIGNMENTS] A LEFT JOIN USER_MASTER U on A.FINALIZED_BY=U.ID
		END
	IF(@CMD='QA_DASHBOARD_ONGOING')--2
		BEGIN
			SELECT INSP_ID,POID,
			CAST(CASE WHEN IS_DATE_ASSIGNED_BY_QA is null THEN   DATE_OF_INSPECTION ELSE QA_ASSIGNED_DOI END AS DATE) AS  DOI,
			ISNULL(IS_DATE_ASSIGNED_BY_QA,0) IS_DATE_ASSIGNED_BY_QA ,ISNULL(IS_INSPECTOR_ASSIGNED,0) IS_INSPECTOR_ASSIGNED,REGION_ID
			FROM INSPECTION_REQUESTS 
			WHERE STATUS_CODE NOT IN (7,9,10) AND 
			(
			(QA_ASSIGNED_DOI >= CAST(GETDATE() AS DATE)	AND QA_ASSIGNED_DOI < DATEADD(DAY, 1, CAST(GETDATE() AS DATE))) OR
			(DATE_OF_INSPECTION = CAST(GETDATE() AS DATE)	AND QA_ASSIGNED_DOI IS NULL)
			)
			AND  
			REGION_ID IN (SELECT value FROM STRING_SPLIT((SELECT REGION_IDS  FROM USER_MASTER WHERE EMP_CODE=@STRFIELD), ','))

			SELECT A.INSPECTION_DATE,U.EMP_NAME,U.EMP_CODE, A.CREATED_DATE FROM [dbo].[INSPECTOR_ASSIGNMENTS] A LEFT JOIN USER_MASTER U on A.FINALIZED_BY=U.ID
			
		END
	IF(@CMD='QA_DASHBOARD_PENDING')--3
		BEGIN
			SELECT INSP_ID,POID,
			CAST(CASE WHEN IS_DATE_ASSIGNED_BY_QA is null THEN   DATE_OF_INSPECTION ELSE QA_ASSIGNED_DOI END AS DATE) AS  DOI,
			ISNULL(IS_DATE_ASSIGNED_BY_QA,0) IS_DATE_ASSIGNED_BY_QA ,ISNULL(IS_INSPECTOR_ASSIGNED,0) IS_INSPECTOR_ASSIGNED,REGION_ID
			FROM INSPECTION_REQUESTS 
			WHERE  STATUS_CODE not in (7,9,10) 
			AND 
			CAST(CASE WHEN IS_DATE_ASSIGNED_BY_QA is null THEN   DATE_OF_INSPECTION ELSE QA_ASSIGNED_DOI END AS DATE)  < CAST(GETDATE() AS DATE) 
			AND
			REGION_ID IN (SELECT value FROM STRING_SPLIT((SELECT REGION_IDS  FROM USER_MASTER WHERE EMP_CODE=@STRFIELD), ',')) 

			SELECT A.INSPECTION_DATE,U.EMP_NAME,U.EMP_CODE, A.CREATED_DATE FROM [dbo].[INSPECTOR_ASSIGNMENTS] A LEFT JOIN USER_MASTER U on A.FINALIZED_BY=U.ID
		END
	If(@CMD='QALIST_TO_MAIL')--4
		BEGIN
				DECLARE @Today DATE = CAST(dateadd(DAy,0, GETDATE()) AS DATE);
				SELECT
				A.DATE_OF_INSPECTION,T.INSPECTION_TYPE,A.INSPECTION_NO,(select SAMPLE_SIZE from MASTER_AQL where BATCH_SIZE_MIN<=A.OFFERED_QTY AND BATCH_SIZE_MAX>=A.OFFERED_QTY) as SAMPLE_SIZE ,A.INSPECTOR_EMP_CODE ,U.EMP_NAME ,D.ARTICLE,B.PO_NUMBER,D.ARTICLE_DESC,B.VENDOR_CODE,B.VENDOR_NAME,
				B.TOTAL_QTY,A.OFFERED_QTY,B.APPARELS,B.CATEGORY,R.REGION,C.ADDRESS_LINE1,C.CONTACT_PERSON, C.MOBILE_NUMBERS,C.CITY, C.PINCODE, C.EMAIL_IDS,
				B.BUYER_NAME, B.BUYER_ID,
				A.INSP_ID,ISNULL(B.LINK_PO_NUMBER,'') as LINK_PO_NUMBER, A.POID,
				case when ISNULL(A.IS_DATE_ASSIGNED_BY_QA,0)=1 then A.QA_ASSIGNED_DOI else A.DATE_OF_INSPECTION end as QA_ASSIGNED_DOI,
				A.ADDRESS_ID,ISNULL(A.IS_INSPECTOR_ASSIGNED,0) IS_INSPECTOR_ASSIGNED,
				  ISNULL(A.IS_DATE_ASSIGNED_BY_QA,0) IS_DATE_ASSIGNED_BY_QA,
				A.REGION_ID, B.MC,B.MC_TEXT, B.MRP, B.BRAND_ID, B.BRAND_ID2,B.FIT
				FROM INSPECTION_REQUESTS A
				INNER JOIN POHEADER B ON A.POID =B.POID
				INNER JOIN PODETAIL D on B.POID=D.POID and LINE_ITEM =00100
				INNER JOIN VENDOR_ADDRESS C on A.ADDRESS_ID = C.ADDRESS_ID
				LEFT JOIN USER_MASTER U on A.INSPECTOR_EMP_CODE=U.EMP_CODE
				LEFT JOIN MASTER_INSPECTION_TYPE T on A.INSPECTION_TYPE_ID=T.INSPECTION_TYPE_ID
				LEFT JOIN MASTER_REGION R on A.REGION_ID=R.REGION_ID
				WHERE QA_ASSIGNED_DOI is not null AND  CAST(QA_ASSIGNED_DOI AS DATE)  >= @Today  AND CAST(QA_ASSIGNED_DOI AS DATE) < DATEADD(DAY, 1, @Today);

				 --SELECT EMP_CODE,EMP_MAIL_ID,ROLE_ID FROM USER_MASTER WHERE ROLE_ID in (2,1007,1008,1006,1009);
				 SELECT '000000' as EMP_CODE,EMAIL_ID as EMP_MAIL_ID, 0 as ROLE_ID  from EMAIL_LIST  WHERE IS_ACTIVE=1


		END
END
GO
/****** Object:  StoredProcedure [dbo].[PRO_QPS_GET_FILTERED_PPSREQUTESTS]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[PRO_QPS_GET_FILTERED_PPSREQUTESTS]
    @SearchText NVARCHAR(200) = NULL,
    @FromDate DATE = NULL,
    @ToDate DATE = NULL,
    @PageNumber INT = 0,  -- 0-based (same as MudTable.TableState.Page)
    @PageSize INT = 10    -- number of rows per page
AS
BEGIN
    SET NOCOUNT ON;

    -- Validation: ToDate < FromDate
    IF (@FromDate IS NOT NULL AND @ToDate IS NOT NULL AND @ToDate < @FromDate)
    BEGIN
        RAISERROR('To Date cannot be earlier than From Date.', 16, 1);
        RETURN;
    END;

    ;WITH SearchWords AS
    (
        -- Split search text into words
        SELECT value AS Word
        FROM STRING_SPLIT(LTRIM(RTRIM(ISNULL(@SearchText, ''))), ' ')
        WHERE LTRIM(RTRIM(value)) <> ''
    ),
    Filtered AS
    (
        SELECT r.*
        FROM Requests r
        WHERE
            (
                -- No search text → include all
                @SearchText IS NULL OR LTRIM(RTRIM(@SearchText)) = ''
                
                -- Otherwise: ensure all words exist in Title
                OR NOT EXISTS (
                    SELECT 1
                    FROM SearchWords w
                    WHERE r.Title NOT LIKE '%' + w.Word + '%'
                )
            )
            -- FromDate filter
            AND (@FromDate IS NULL OR CAST(r.Created_At AS DATE) >= @FromDate)
            -- ToDate filter
            AND (@ToDate IS NULL OR CAST(r.Created_At AS DATE) <= @ToDate)
    )
    SELECT 
        f.*,
        COUNT(1) OVER() AS TotalCount  -- return total rows for MudTable
    FROM Filtered f
    ORDER BY f.Created_At DESC
    OFFSET @PageNumber * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END;
GO
/****** Object:  StoredProcedure [dbo].[PRO_SET_FLAGS]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



-- =============================================
-- Author:		Chandra Bhan Singh
-- Create date: 11 Dec 2024
-- Description:	Set Flags
-- =============================================
CREATE PROCEDURE [dbo].[PRO_SET_FLAGS]
	@ID INT,
	@BOOL_FLAG BIT,
	@INT_FLAG INT,
	@STR_FLAG VARCHAR(250),
	@UPDATED_BY INT,
	@CMD VARCHAR(100),
	@ERROR_CODE INT OUTPUT,             -- OUTPUT PARAMETER FOR ERROR CODE
    @ERROR_MESSAGE NVARCHAR(500) OUTPUT -- OUTPUT PARAMETER FOR ERROR MESSAGE 
AS
BEGIN
	SET XACT_ABORT ON;  -- AUTOMATICALLY ROLLBACK ON ERROR
	BEGIN TRY
		BEGIN TRANSACTION
	 -- SET OUTPUT PARAMETERS FOR SUCCESS
		SET @ERROR_CODE = 0;
		SET @ERROR_MESSAGE = 'SUCCESS';
		IF(@CMD='ACTIVATE_DEACTIVATE_MENUMASTER')
		 BEGIN
		   UPDATE MENU_MASTER SET ACTIVE_STATUS=@BOOL_FLAG, UPDATED_ON=GETDATE(),UPDATED_BY=@UPDATED_BY WHERE ID=@ID
		    EXEC PRO_INSERT_LOG_MASTER @ID,'MENU_MASTER',@UPDATED_BY,'UPDATE RECORD STATUS IN MENU_MASTER'
		 END
		 ELSE IF(@CMD='ACTIVATE_DEACTIVATE_ROLEMASTER')
		 BEGIN
		   UPDATE ROLE_MASTER SET ACTIVE_STATUS=@BOOL_FLAG, UPDATED_ON=GETDATE(),UPDATED_BY=@UPDATED_BY WHERE ID=@ID
		    EXEC PRO_INSERT_LOG_MASTER @ID,'ROLE_MASTER',@UPDATED_BY,'UPDATE RECORD STATUS IN ROLE_MASTER'
		 END
		 -- COMMIT TRANSACTION IF EVERYTHING SUCCEEDS
	     COMMIT TRANSACTION;
	END TRY
	BEGIN CATCH
	-- ROLLBACK TRANSACTION IN CASE OF AN ERROR
        ROLLBACK TRANSACTION;
		-- SET ERROR CODE AND ERROR MESSAGE FOR OUTPUT
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
	END CATCH
END

GO
/****** Object:  StoredProcedure [dbo].[PRO_USER_LOGIN]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PRO_USER_LOGIN]
    @ID INT,
    @EMP_CODE VARCHAR(50),
    @EMP_NAME VARCHAR(50),
    @EMP_LOCATION VARCHAR(50),
    @EMP_LOC_CODE VARCHAR(50),
    @EMP_DEPT_NAME VARCHAR(50),
    @EMP_DESIG VARCHAR(50),
    @EMP_CONTACT_NO VARCHAR(50),
    @EMP_MAIL_ID VARCHAR(50),
    @EMP_RPT_MNG VARCHAR(50),
    @IS_RESIGN BIT,
    @EMP_GRADE INT,
    @EMP_GRADE_DESC VARCHAR(50),
    @EMP_STATUS BIT,
    @IP_ADDRESS VARCHAR(50),
    @ROLE_ID INT,
	@INSERTED_UPDATED_BY INT,
    @ERROR_CODE INT OUTPUT,            -- OUTPUT PARAMETER FOR ERROR CODE
    @ERROR_MESSAGE VARCHAR(500) OUTPUT -- OUTPUT PARAMETER FOR ERROR MESSAGE    @ID INT,
AS
BEGIN
BEGIN TRY
        BEGIN TRANSACTION;
		-- SET OUTPUT PARAMETERS FOR SUCCESS
        SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'SUCCESS';

          IF EXISTS(SELECT EMP_CODE FROM USER_MASTER WHERE EMP_CODE=@EMP_CODE) 
		    BEGIN
			  UPDATE USER_MASTER SET EMP_CODE=@EMP_CODE, EMP_NAME=@EMP_NAME, EMP_LOCATION=@EMP_LOCATION, EMP_LOC_CODE=@EMP_LOC_CODE,
			  EMP_DEPT_NAME=@EMP_DEPT_NAME, EMP_DESIG=@EMP_DESIG, EMP_CONTACT_NO=@EMP_CONTACT_NO, EMP_MAIL_ID=@EMP_MAIL_ID, 
			  EMP_RPT_MNG=@EMP_RPT_MNG, IS_RESIGN=@IS_RESIGN, EMP_GRADE=@EMP_GRADE, EMP_GRADE_DESC=@EMP_GRADE_DESC, 
			  EMP_STATUS=@EMP_STATUS, IP_ADDRESS=@IP_ADDRESS,LAST_LOGIN_DATE=CURRENT_LOGIN_DATE,CURRENT_LOGIN_DATE=GETDATE() WHERE EMP_CODE=@EMP_CODE
			  SELECT @ID=ID FROM USER_MASTER WHERE EMP_CODE=@EMP_CODE
		       EXEC PRO_INSERT_LOG_MASTER @ID,'USER_MASTER',@INSERTED_UPDATED_BY,'LOGIN AND UPDATE RECORD IN USER_MASTER'
			   IF NOT EXISTS(SELECT ROLE_ID FROM USER_MASTER WHERE ROLE_ID>0 AND EMP_CODE=@EMP_CODE)
			     BEGIN
				    -- IN CASE OF ROLE NOT DEFINED
				    SET @ERROR_CODE = 1;
                    SET @ERROR_MESSAGE = 'YOU DO NOT HAVE ANY ROLE. PLEASE CONTACT THE ADMINISTRATOR.';
				 END
			END
		  ELSE
		    BEGIN
			-- INSERT NEW USER
			  INSERT INTO USER_MASTER 
			  (EMP_CODE, EMP_NAME, EMP_LOCATION, EMP_LOC_CODE, EMP_DEPT_NAME, EMP_DESIG, EMP_CONTACT_NO, EMP_MAIL_ID, 
			  EMP_RPT_MNG, IS_RESIGN, EMP_GRADE, EMP_GRADE_DESC, EMP_STATUS, IP_ADDRESS, 
			  INSERTED_ON)
			  VALUES 
			  ( @EMP_CODE, @EMP_NAME, @EMP_LOCATION, @EMP_LOC_CODE, @EMP_DEPT_NAME, @EMP_DESIG, @EMP_CONTACT_NO, @EMP_MAIL_ID, 
			  @EMP_RPT_MNG, @IS_RESIGN, @EMP_GRADE, @EMP_GRADE_DESC, @EMP_STATUS, @IP_ADDRESS, 
			  GETDATE());
			  -- GET THE GENERATED IDENTITY VALUE FOR ROLEID
				SET @ID = SCOPE_IDENTITY();
				-- UPDATE INSERTED BY
				UPDATE USER_MASTER SET INSERTED_BY=@ID WHERE ID =@ID
				EXEC PRO_INSERT_LOG_MASTER @ID,'USER_MASTER',@INSERTED_UPDATED_BY,'INSERT RECORD IN USER_MASTER'
			 SET @ERROR_CODE = 1;
             SET @ERROR_MESSAGE = 'YOU DO NOT HAVE ANY ROLE. PLEASE CONTACT THE ADMINISTRATOR.';
			END
			IF NOT EXISTS(SELECT A.ID FROM USER_MASTER A INNER JOIN ROLE_MASTER B ON A.ROLE_ID = B.ID WHERE B.ACTIVE_STATUS=1)
			 BEGIN
			   SET @ERROR_CODE = 1;
               SET @ERROR_MESSAGE = 'YOU DO NOT HAVE ANY ROLE. PLEASE CONTACT THE ADMINISTRATOR.';
			 END
			-- SELECT LOGIN USER DATA
			SELECT A.ID,EMP_CODE,EMP_NAME,EMP_LOCATION,EMP_LOC_CODE,EMP_DEPT_NAME,EMP_DESIG,EMP_CONTACT_NO,EMP_MAIL_ID,EMP_RPT_MNG,IS_RESIGN,EMP_GRADE,EMP_GRADE_DESC,EMP_STATUS,ROLE_ID, REGION_IDS FROM USER_MASTER A INNER JOIN ROLE_MASTER B ON A.ROLE_ID=B.ID WHERE EMP_CODE=@EMP_CODE AND EMP_STATUS=1 AND ACTIVE_STATUS=1
			SELECT MENU,CMS,MEDIA,USER_MANAGEMENT FROM USER_MASTER A INNER JOIN ROLE_MASTER B ON A.ROLE_ID=B.ID WHERE EMP_CODE=@EMP_CODE AND EMP_STATUS=1 AND ACTIVE_STATUS=1
			SELECT C.ID,C.LABEL, C.URL,PARENT_ID,PAGE_TITLE,PAGE_DESCRIPTION,PAGE_KEYWORDS,PERMISSION FROM USER_ROLE_DETAILS A INNER JOIN USER_MASTER B ON A.USER_ID=B.ID INNER JOIN MENU_MASTER C ON A.MENU_ID=C.ID WHERE B.EMP_CODE=@EMP_CODE AND C.ACTIVE_STATUS=1  ORDER BY C.[ORDER]

-- COMMIT TRANSACTION IF EVERYTHING SUCCEEDS
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        -- ROLLBACK TRANSACTION IN CASE OF AN ERROR
        ROLLBACK TRANSACTION;
		-- SET ERROR CODE AND ERROR MESSAGE FOR OUTPUT
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH;
END;

GO
/****** Object:  StoredProcedure [dbo].[PRO_USER_ROLE_MENUS]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author: Dinesh Baghel
-- Create date: 18 Aug 2026
-- Description:	PRO_USER_ROLE_MENU — auth/menu/role, completely unrelated domain to inspections
-- =============================================

CREATE PROCEDURE [dbo].[PRO_USER_ROLE_MENUS]
	@ID INT,
	@STRFIELD VARCHAR(50),
	@CMD VARCHAR(100)
AS
BEGIN
	SET NOCOUNT ON;

	IF(@CMD='GET_ALL_MENU')--1
		BEGIN
			IF(@ID=0)
				BEGIN
					SELECT [ID],[LABEL],[URL],[PARENT_ID],[WEBSITE_VISIBILITY],[ACTIVE_STATUS],[PAGE_TITLE],[PAGE_DESCRIPTION],[PAGE_KEYWORDS],[ORDER] FROM [DBO].[MENU_MASTER] WHERE ISNULL(PARENT_ID,0)=0  ORDER BY [ORDER] ASC, ISNULL(UPDATED_ON,INSERTED_ON) DESC
				END
			ELSE
				BEGIN
					SELECT [ID],[LABEL],[URL],[PARENT_ID],[WEBSITE_VISIBILITY],[ACTIVE_STATUS],[PAGE_TITLE],[PAGE_DESCRIPTION],[PAGE_KEYWORDS],[ORDER] FROM [DBO].[MENU_MASTER] WHERE PARENT_ID = @ID ORDER BY [ORDER] ASC, ISNULL(UPDATED_ON,INSERTED_ON) DESC
				END
			SELECT ID,ROLE_NAME FROM  [DBO].ROLE_MASTER WHERE ACTIVE_STATUS=1
		END
	IF(@CMD='GET_ALL_ROLES')--2
		BEGIN
			SELECT ID,ROLE_NAME, MENU, CMS, MEDIA, USER_MANAGEMENT, ACTIVE_STATUS FROM  [DBO].ROLE_MASTER ORDER BY ID DESC
		END
	IF(@CMD='GET_ALL_USERS')--3
		BEGIN
			SELECT A.*, A.Region_id as RegionId, A.REGION_IDS as RGN,B.ROLE_NAME , A.STAMP_NO as StampNo, A.SIGN AS SignatureBytes 
			FROM  [DBO].USER_MASTER A LEFT JOIN ROLE_MASTER B ON A.ROLE_ID=B.ID --ORDER BY A.UPDATED_ON DESC
		END
	IF(@CMD='GET_BREADCRUMBS')--4
		BEGIN
			WITH  PARENTHIERARCHY AS 
			(
				SELECT ID, LABEL, PARENT_ID
				FROM MENU_MASTER
				WHERE ID = CASE WHEN @ID = 0 THEN (SELECT TOP 1 [PAGE_ID] FROM  [DBO].CONTENTMASTER WHERE ACTIVE_STATUS=1 ORDER BY VIEW_ORDER) ELSE @ID END
				UNION ALL
				SELECT T.ID, T.LABEL, T.PARENT_ID
				FROM MENU_MASTER T
				JOIN PARENTHIERARCHY PH ON T.ID = PH.PARENT_ID
			)
			SELECT 0 AS ID, 'HOME' AS LABEL
			UNION ALL
			SELECT ID, LABEL FROM PARENTHIERARCHY ORDER BY ID ASC;
		END
	IF(@CMD='GET_LOGGEDINUSER_DETAILS_ON_EMP_CODE')--5
		BEGIN
			SELECT A.ID,EMP_CODE,EMP_NAME,EMP_LOCATION,EMP_LOC_CODE,EMP_DEPT_NAME,EMP_DESIG,EMP_CONTACT_NO,EMP_MAIL_ID,EMP_RPT_MNG,IS_RESIGN,EMP_GRADE,EMP_GRADE_DESC,EMP_STATUS,ROLE_ID FROM USER_MASTER A INNER JOIN ROLE_MASTER B ON A.ROLE_ID=B.ID WHERE EMP_CODE=@STRFIELD AND EMP_STATUS=1 AND ACTIVE_STATUS=1
			SELECT MENU,CMS,MEDIA,USER_MANAGEMENT FROM USER_MASTER A INNER JOIN ROLE_MASTER B ON A.ROLE_ID=B.ID WHERE EMP_CODE=@STRFIELD AND EMP_STATUS=1 AND ACTIVE_STATUS=1
			SELECT C.ID,C.LABEL, C.URL,PARENT_ID,PAGE_TITLE,PAGE_DESCRIPTION,PAGE_KEYWORDS,PERMISSION FROM USER_ROLE_DETAILS A INNER JOIN USER_MASTER B ON A.USER_ID=B.ID INNER JOIN MENU_MASTER C ON A.MENU_ID=C.ID WHERE B.EMP_CODE=@STRFIELD AND C.ACTIVE_STATUS=1  ORDER BY C.[ORDER]
		END
	IF(@CMD='GET_MENU_LIST')--6
		BEGIN
			SELECT [ID],ISNULL([PARENT_ID],0) AS PARENT_ID,[LABEL],[URL] FROM [DBO].[MENU_MASTER]  ORDER BY [ORDER] ASC,ISNULL(UPDATED_ON,INSERTED_ON) DESC
		END
	IF(@CMD='GET_MENU_LIST_PUBLIC')--7
		BEGIN
			SELECT [ID],ISNULL([PARENT_ID],0) AS PARENT_ID,[LABEL],[URL] FROM [DBO].[MENU_MASTER] WHERE ACTIVE_STATUS=1 AND WEBSITE_VISIBILITY=1  ORDER BY [ORDER] ASC, ISNULL(UPDATED_ON,INSERTED_ON) DESC
		END
	IF(@CMD='GET_REGION_WISE_INSPECTORS')--8
		BEGIN
			DECLARE @Rgns INT
			SELECT @Rgns= count(1) FROM STRING_SPLIT(@STRFIELD, ',') AS f;
			IF(@Rgns>1)
				BEGIN
					SELECT A.ID,A.EMP_CODE, A.EMP_NAME, A.Region_id as RegionId, A.REGION_IDS as RGN,ROLE_ID  FROM  [DBO].USER_MASTER A WHERE EMP_STATUS=1 AND ROLE_ID in (1006,1007) order by A.EMP_NAME--ROLE_ID desc, REGION_IDS
				END
			ELSE
				BEGIN
					SELECT A.ID,A.EMP_CODE, A.EMP_NAME, A.Region_id as RegionId, A.REGION_IDS as RGN,ROLE_ID   FROM  [DBO].USER_MASTER A WHERE A.EMP_STATUS=1 AND A.REGION_IDS like @STRFIELD  and ROLE_ID in (1006)
					UNION
					SELECT A.ID,A.EMP_CODE, A.EMP_NAME, A.Region_id as RegionId, A.REGION_IDS as RGN,ROLE_ID   FROM  [DBO].USER_MASTER A WHERE A.REGION_IDS like  @STRFIELD  and ROLE_ID in (1007)
					order by A.EMP_NAME--ROLE_ID desc
				END
		END
	IF(@CMD='GET_ROLE_DETAILS_ON_USER_ID')--9 
		BEGIN
			SELECT A.ID AS [MENU_ID],A.[PARENT_ID],A.[LABEL],B.PERMISSION FROM [DBO].[MENU_MASTER] A LEFT JOIN [DBO].[USER_ROLE_DETAILS] B ON A.ID=B.MENU_ID  AND B.USER_ID=@ID
		END
	IF(@CMD='GET_ROLES_LIST')--10
		BEGIN
			SELECT ID,ROLE_NAME FROM  [DBO].ROLE_MASTER WHERE ACTIVE_STATUS=1
		END
	IF(@CMD='GET_USER_DETAILS_ON_USER_CODE')--11
		BEGIN
			SELECT ID,EMP_CODE,EMP_NAME,EMP_LOCATION,EMP_LOC_CODE,EMP_DEPT_NAME,EMP_DESIG,EMP_CONTACT_NO,EMP_MAIL_ID,EMP_RPT_MNG,IS_RESIGN,EMP_GRADE,EMP_GRADE_DESC,EMP_STATUS,ROLE_ID FROM  [DBO].USER_MASTER WHERE EMP_CODE=@STRFIELD
			SELECT [ROLE_ID],[MENU_ID],[PARENT_ID],[LABEL],PERMISSION FROM [DBO].[USER_ROLE_DETAILS] A INNER JOIN [DBO].[MENU_MASTER] B ON A.MENU_ID=B.ID INNER JOIN USER_MASTER C ON A.USER_ID=C.ID  WHERE C.EMP_CODE=@STRFIELD
		END
	IF(@CMD='Get_Vendor_By_Code')
		BEGIN
			SELECT VENDOR_ID,VENDOR_CODE,VENDOR_NAME,GST_NO,PASSWORD,DEFAULT_PASSWORD_CHANGED,IS_ACTIVE,IS_EMAIL_SENT,
		    ISNULL(	CONVERT(varchar(10),LAST_LOGIN_DATE, 103),'') as LAST_LOGIN_DATE,
			ISNULL(	CONVERT(varchar(10),CURRENT_LOGIN_DATE, 103),'') as CURRENT_LOGIN_DATE,isnull(IP_ADDRESS,'') as IP_ADDRESS,
			ISNULL(	CONVERT(varchar(10),CREATED_DATE, 103),'') as CREATED_DATE,
			ISNULL(	CONVERT(varchar(10),MODIFIED_DATE, 103),'') as MODIFIED_DATE,
			CREATED_BY,	isnull(MODIFIED_BY,0) MODIFIED_BY 
			FROM  [DBO].[VENDORS_MASTER] A WHERE VENDOR_CODE=@STRFIELD  


			SELECT ADDRESS_ID, VENDOR_ID,ADDRESS_LINE1,CITY,PINCODE,EMAIL_IDS,MOBILE_NUMBERS,CONTACT_PERSON,REGION_CODE,REGION_DESCRIPTION,IS_DEFAULT,
			ISNULL(	CONVERT(varchar(10),CREATED_DATE, 103),'') as CREATED_DATE,
			ISNULL(	CONVERT(varchar(10),MODIFIED_DATE, 103),'') as MODIFIED_DATE,
			CREATED_BY,	isnull(MODIFIED_BY,0) MODIFIED_BY 
			FROM   [DBO].[VENDOR_ADDRESS] A WHERE VENDOR_ID=(SELECT VENDOR_ID FROM  [DBO].[VENDORS_MASTER] WHERE VENDOR_CODE=@STRFIELD)  ORDER BY A.MODIFIED_DATE DESC
		
		END
	IF(@CMD='Get_IsUserActive')
		BEGIN
			SELECT A.*, A.Region_id as RegionId, A.REGION_IDS as RGN,B.ROLE_NAME , A.STAMP_NO as StampNo, A.SIGN AS SignatureBytes 
			FROM  [DBO].USER_MASTER A LEFT JOIN ROLE_MASTER B ON A.ROLE_ID=B.ID WHERE A.ID=@ID AND EMP_CODE=@STRFIELD AND EMP_STATUS=1 AND IS_RESIGN=0
		END
	
END
GO
/****** Object:  StoredProcedure [dbo].[PRO_USER_SESSION_CLEAR]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- 3. Clear a session (logout / admin force-clear)
-- =============================================
CREATE   PROCEDURE [dbo].[PRO_USER_SESSION_CLEAR]
    @UserType VARCHAR(50),
	@UserCode     VARCHAR(100),
    @UserId   INT
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE dbo.USER_ACTIVE_SESSION
    SET SESSION_TOKEN = NULL,
        UPDATED_AT    = GETDATE()
    WHERE USER_TYPE = @UserType AND USER_ID = @UserId AND USER_CODE = @UserCode;
END
GO
/****** Object:  StoredProcedure [dbo].[PRO_USER_SESSION_VALIDATE]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =============================================
-- 2. Validate a session token
-- =============================================
CREATE   PROCEDURE [dbo].[PRO_USER_SESSION_VALIDATE]
    @UserType     VARCHAR(50),
	@UserCode     VARCHAR(100),
    @UserId       INT,
    @SessionToken CHAR(32)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        CASE
            WHEN SESSION_TOKEN IS NOT NULL AND SESSION_TOKEN = @SessionToken
                THEN CAST(1 AS BIT)
            ELSE CAST(0 AS BIT)
        END AS IS_VALID,
		CASE
            WHEN SESSION_TOKEN IS NOT NULL  THEN SESSION_TOKEN ELSE ''
        END AS TOKEN
    FROM dbo.USER_ACTIVE_SESSION
    WHERE USER_TYPE = @UserType AND USER_ID = @UserId AND USER_CODE = @UserCode;
END
GO
/****** Object:  StoredProcedure [dbo].[PRO_USER_SESSIONS]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- 1. Issue / replace a session token (upsert)
-- =============================================
CREATE   PROCEDURE [dbo].[PRO_USER_SESSIONS]
    @UserType     VARCHAR(50),
	@UserCode     VARCHAR(100),
    @UserId       INT,
    @SessionToken CHAR(32),
    @DeviceInfo   VARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    MERGE dbo.USER_ACTIVE_SESSION WITH (HOLDLOCK) AS target
    USING (SELECT @UserType AS USER_TYPE, @UserId AS USER_ID, @UserCode AS USER_CODE) AS src
        ON target.USER_TYPE = src.USER_TYPE AND target.USER_ID = src.USER_ID AND target.USER_CODE = src.USER_CODE
    WHEN MATCHED THEN
        UPDATE SET SESSION_TOKEN = @SessionToken, DEVICE_INFO   = @DeviceInfo, UPDATED_AT    = GETDATE()
    WHEN NOT MATCHED THEN
        INSERT (USER_TYPE,USER_CODE, USER_ID, SESSION_TOKEN, DEVICE_INFO, UPDATED_AT)
        VALUES (@UserType,@UserCode, @UserId, @SessionToken, @DeviceInfo, GETDATE());
END
GO
/****** Object:  StoredProcedure [dbo].[QPS_PPS_LOG_UPDATE]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Dinesh Kumar
-- Create date: 18 Aug 2025
-- Description:	QPS_PPS_LOG_UPDATE 
-- =============================================
CREATE PROCEDURE [dbo].[QPS_PPS_LOG_UPDATE]
    @REQUEST_ID INT,
    @STATUS_ID INT, --1=New, 2=Accepted, 3=Declined, 4=Passed, 5=Failed
    @VERIFIED_BY VARCHAR(50),
    @COMMENTS VARCHAR(500) = NULL,
	@ATTACHMENTS VARCHAR(MAX) = '',
    @ERROR_CODE INT OUTPUT,
    @ERROR_MESSAGE VARCHAR(500) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @FailedCount INT = 0;
    DECLARE @NewLogId INT;
	DECLARE @USERID INT=0;

    BEGIN TRY
        BEGIN TRANSACTION;

        SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Success';

		SET @ATTACHMENTS = LTRIM(RTRIM(ISNULL(@ATTACHMENTS, '')));
        -- 1️ Validate request exists
        IF NOT EXISTS (SELECT 1 FROM QPS_PPS_REQUEST WHERE REQUEST_ID = @REQUEST_ID)
        BEGIN
            SET @ERROR_CODE = 2001;
            SET @ERROR_MESSAGE = 'Invalid REQUEST_ID';
            ROLLBACK TRANSACTION;
            RETURN;
        END

		 -- 1️.1 Validate record  exists in logs(prevent duplicate entry)
        IF EXISTS (SELECT 1 FROM QPS_PPS_LOGS WHERE REQUEST_ID = @REQUEST_ID and STATUS_ID=@STATUS_ID)
        BEGIN
            SET @ERROR_CODE = 2002;
            SET @ERROR_MESSAGE = 'Record already inserted.';
            ROLLBACK TRANSACTION;
            RETURN;
        END

        -- 2️ Count failed attempts in last 6 months
        SELECT @FailedCount = COUNT(*) FROM QPS_PPS_LOGS WHERE REQUEST_ID = @REQUEST_ID AND STATUS_ID = 5 AND VERIFIED_AT >= DATEADD(MONTH, -6, GETDATE());

        -- 3️⃣ If status is Passed, check duplicate approvals in 6 months
        IF @STATUS_ID = 4
        BEGIN
            IF EXISTS ( SELECT 1  FROM QPS_PPS_LOGS WHERE REQUEST_ID = @REQUEST_ID AND STATUS_ID = 4 AND VERIFIED_AT >= DATEADD(MONTH, -6, GETDATE()))
            BEGIN
                SET @ERROR_CODE = 2002;
                SET @ERROR_MESSAGE = 'Already Passed within last 6 months';
                ROLLBACK TRANSACTION;
                RETURN;
            END
        END

        -- 4️⃣ If Failed count exceeds 3
        IF @STATUS_ID = 5 AND @FailedCount >= 3
        BEGIN
            SET @ERROR_CODE = 2003;
            SET @ERROR_MESSAGE = 'Blocked - PPS Failed 3 times in last 6 months';
            ROLLBACK TRANSACTION;
            RETURN;
        END

        -- 5️⃣ First mark old logs as N (close previous log)
        UPDATE QPS_PPS_LOGS SET LAST_LOG = 'N' WHERE REQUEST_ID = @REQUEST_ID AND LAST_LOG = 'Y';

        -- 6️⃣ Insert new log as Y
        INSERT INTO QPS_PPS_LOGS ( REQUEST_ID, STATUS_ID, LAST_LOG, ATTEMPT_COUNT, VERIFIED_BY, VERIFIED_AT,COMMENTS )
        VALUES ( @REQUEST_ID,@STATUS_ID,'Y', @FailedCount + CASE WHEN @STATUS_ID = 5 THEN 1 ELSE 0 END, @VERIFIED_BY, GETDATE(), @COMMENTS );

		if(@ATTACHMENTS!='')
			 begin
				if(@STATUS_ID=2 or @STATUS_ID=3)
					begin
						UPDATE QPS_PPS_REQUEST SET ATTACHMENTS_STEP2 = @ATTACHMENTS, UPDATED_AT=GETDATE() WHERE REQUEST_ID = @REQUEST_ID
					end
				if(@STATUS_ID=4 or @STATUS_ID=5)
					begin
						UPDATE QPS_PPS_REQUEST SET ATTACHMENTS_STEP3 = @ATTACHMENTS, UPDATED_AT=GETDATE() WHERE REQUEST_ID = @REQUEST_ID
					end
			 end
		

        SET @NewLogId = SCOPE_IDENTITY();

        -- 7️⃣ Custom log entry
		select @USERID= id from USER_MASTER where Emp_Code like @VERIFIED_BY;
        EXEC PRO_INSERT_LOG_MASTER @REQUEST_ID, 'QPS_PPS_LOGS',@USERID ,'Status Updated';

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = 'SQL Error: ' + ERROR_MESSAGE();

        INSERT INTO SystemErrorLog (ErrorCode, ErrorMessage, ErrorProcedure, ErrorLine, ErrorDate)
        VALUES (ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_PROCEDURE(), ERROR_LINE(), GETDATE());
    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[QPS_PPS_REQUEST_INSERT_UPDATE]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Dinesh Kumar
-- Create date: 14 Aug 2025
-- Description:	QPS_PPS_REQUEST CRUD 
-- =============================================
CREATE PROCEDURE [dbo].[QPS_PPS_REQUEST_INSERT_UPDATE]
    @REQUEST_ID INT = 0,
    @BUYER_ID VARCHAR(50),
    @GENERIC_ARTICLE VARCHAR(50),
    @ARTICLE_DESCRIPTION VARCHAR(500),
    @COLOR VARCHAR(50),
    @MC VARCHAR(50),
    @MC_DESCRIPTION VARCHAR(50),
    @DIVISION VARCHAR(50),
    @DIVISION_DESCRIPTION VARCHAR(200),
    @VENDOR_CODE VARCHAR(50),
    @VENDOR_NAME VARCHAR(500),
    @MRP DECIMAL(10, 2),
	@PP_TYPE VARCHAR(50),
	@QTY INT,
	@ATTACHMENTS VARCHAR(MAX) = '',
    @ERROR_CODE INT = 0 OUTPUT,             
    @ERROR_MESSAGE VARCHAR(500) = 'Success' OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @FailedCount INT = 0;
    DECLARE @NewRequestId INT;
	DECLARE @USERID INT=1;

    BEGIN TRY
        -- Default success
        SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Success';

        BEGIN TRANSACTION;

        -- Trim all inputs to avoid data issues
        SET @GENERIC_ARTICLE = LTRIM(RTRIM(ISNULL(@GENERIC_ARTICLE, '')));
        SET @ARTICLE_DESCRIPTION = LTRIM(RTRIM(ISNULL(@ARTICLE_DESCRIPTION, '')));
        SET @COLOR = LTRIM(RTRIM(ISNULL(@COLOR, '')));
        SET @MC = LTRIM(RTRIM(ISNULL(@MC, '')));
        SET @MC_DESCRIPTION = LTRIM(RTRIM(ISNULL(@MC_DESCRIPTION, '')));
        SET @DIVISION = LTRIM(RTRIM(ISNULL(@DIVISION, '')));
        SET @DIVISION_DESCRIPTION = LTRIM(RTRIM(ISNULL(@DIVISION_DESCRIPTION, '')));
        SET @VENDOR_CODE = LTRIM(RTRIM(ISNULL(@VENDOR_CODE, '')));
        SET @VENDOR_NAME = LTRIM(RTRIM(ISNULL(@VENDOR_NAME, '')));
		SET @PP_TYPE = LTRIM(RTRIM(ISNULL(@PP_TYPE, '')));
		SET @ATTACHMENTS = LTRIM(RTRIM(ISNULL(@ATTACHMENTS, '')));

        IF @REQUEST_ID = 0
        BEGIN

			-- Check if there is already an active request for this article
			IF EXISTS (
				SELECT 1
				FROM QPS_PPS_REQUEST r
				JOIN QPS_PPS_LOGS l ON r.REQUEST_ID = l.REQUEST_ID
				WHERE r.GENERIC_ARTICLE = @GENERIC_ARTICLE and PP_TYPE = @PP_TYPE
				  AND l.LAST_LOG = 'Y'
				  AND l.STATUS_ID IN (1,2) -- New/Accepted/Declined (not closed yet)
			)
			BEGIN
				SET @ERROR_CODE = 1004;
				SET @ERROR_MESSAGE = 'Request already exists for this generic article [ '+@GENERIC_ARTICLE+' ] with type [' + @PP_TYPE + '].';
				ROLLBACK TRANSACTION;
				RETURN;
			END
            -- 1️⃣ Check if approved in last 6 months
            IF EXISTS (
                SELECT 1
                FROM QPS_PPS_STATUS
                WHERE GENERIC_ARTICLE = @GENERIC_ARTICLE and PP_TYPE = @PP_TYPE
                  AND STATUS_ID = 4  -- Passed
                  AND CREATED_AT >= DATEADD(MONTH, -6, GETDATE())
            )
            BEGIN
                SET @ERROR_CODE = 1001;
                SET @ERROR_MESSAGE = 'This generic article [ '+@GENERIC_ARTICLE+' ] with type [' + @PP_TYPE + '] was already approved in the last 6 months.';
                ROLLBACK TRANSACTION;
                RETURN;
            END

           
			-- 2️ Count failed attempts in last 6 months
			SELECT @FailedCount =COUNT(*)
			FROM QPS_PPS_REQUEST A (nolock)
			left join QPS_PPS_LOGS B on A.REQUEST_ID=B.REQUEST_ID and B.STATUS_ID=5
			WHERE A.GENERIC_ARTICLE=@GENERIC_ARTICLE and PP_TYPE = @PP_TYPE and STATUS_ID = 5 -- Failed
			AND VERIFIED_AT >= DATEADD(MONTH, -6, GETDATE());


            -- 3️⃣ Apply failed count rule
            IF @FailedCount >= 3
            BEGIN
                SET @ERROR_CODE = 1002;
                SET @ERROR_MESSAGE = 'This request is blocked because it failed 3 times in the last 6 months.';
                ROLLBACK TRANSACTION;
                RETURN;
            END

            -- 4️⃣ Generate new Request ID (prefer SEQUENCE/IDENTITY for safety)
            -- Option 1: Use SEQUENCE (Recommended)
            -- SET @NewRequestId = NEXT VALUE FOR dbo.RequestIdSequence;

            -- Option 2: If no sequence, still use locking hint to avoid race conditions
            SELECT @NewRequestId = ISNULL(MAX(REQUEST_ID), 0) + 1
            FROM QPS_PPS_REQUEST WITH (TABLOCKX);

            -- 5️⃣ Insert into QPS_PPS_REQUEST
            INSERT INTO QPS_PPS_REQUEST
            (
                REQUEST_ID, BUYER_ID, GENERIC_ARTICLE, ARTICLE_DESCRIPTION,
                COLOR, MC, MC_DESCRIPTION, DIVISION, DIVISION_DESCRIPTION,
                VENDOR_CODE, VENDOR_NAME, MRP, PP_TYPE, QTY, ATTACHMENTS, CREATED_AT
            )
            VALUES
            (
                @NewRequestId, @BUYER_ID, @GENERIC_ARTICLE, @ARTICLE_DESCRIPTION,
                @COLOR, @MC, @MC_DESCRIPTION, @DIVISION, @DIVISION_DESCRIPTION,
                @VENDOR_CODE, @VENDOR_NAME, @MRP, @PP_TYPE, @QTY, @ATTACHMENTS, GETDATE()
            );

            -- 6️⃣ Insert into QPS_PPS_LOGS
            INSERT INTO QPS_PPS_LOGS
            (
                REQUEST_ID, STATUS_ID, LAST_LOG, ATTEMPT_COUNT, VERIFIED_BY, VERIFIED_AT,COMMENTS
            )
            VALUES
            (
                @NewRequestId,
                1,  -- STATUS_ID = New
                'Y',
                @FailedCount,
                @BUYER_ID,
                GETDATE(),
				'PPS Created'
            );

			
            -- 7️⃣ Custom log entry
			select @USERID= id from USER_MASTER where Emp_Code like @BUYER_ID;
            EXEC PRO_INSERT_LOG_MASTER @NewRequestId, 'QPS_PPS_REQUEST',@USERID, 'Insert Record In QPS_PPS_REQUEST';
        END
        ELSE
        BEGIN
            -- Updating logic placeholder (if needed)
            -- Example: Update record fields here if @REQUEST_ID != 0
			 SET @ERROR_CODE = 1003;
			 SET @ERROR_MESSAGE = 'Request id is != 0 ';
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = 'SQL Error: ' + ERROR_MESSAGE();
    END CATCH
END;
GO
/****** Object:  StoredProcedure [dbo].[QPS_QUERY_PROC]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Dinesh Kumar
-- Create date: 14 Aug 2025
-- Description:	Query All Entities
-- =============================================
-- QPS_QUERY_PROC 0,'','Get_PPS_All_Request'
CREATE PROCEDURE [dbo].[QPS_QUERY_PROC]
	@Id int=0,
	@StrField varchar(50)='',
	@Cmd varchar(100)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	Declare @FailedCount int;
	SET @StrField = LTRIM(RTRIM(ISNULL(@StrField, '')));
	-- Default success
    DECLARE @ERROR_CODE int = 0;
    DECLARE @ERROR_MESSAGE varchar(500) = 'Success';

	SET NOCOUNT ON;
	If(@Cmd='Get_All_PPS_Users')
		Begin
			select * from [dbo].[USER_MASTER] where ROLE_ID=3
		End
	Else If(@Cmd='Get_All_Active_Roles')
		Begin
			select * from [dbo].[USER_MASTER] where ROLE_ID=2 and EMP_CODE=CONVERT(varchar, @id)
		End
	Else If(@Cmd='Get_User_By_Id')
		Begin
			Select ROLE_ID,ROLE_NAME,DESCRIPTION From  QPS_ROLES where IS_ACTIVE=1 and ROLE_ID=@Id
		End
	Else If(@Cmd='Get_PPS_All_Request')
		Begin
			
			Select A.*,U.Emp_Code+' ~ ' +U.Emp_Name as CREATED_BY,  C.STATUS,
			case when B.STATUS_ID in (2,3,4,5) then  B.VERIFIED_AT else null end as VERIFIED_AT ,
			case when B.STATUS_ID in (2,3,4,5) then  UV.Emp_Code+' ~ '+ UV.Emp_Name else '' end as VERIFIED_BY, 
			B.STATUS_ID, U.Emp_Code, U.Emp_Name from QPS_PPS_REQUEST A 
			Left Join QPS_PPS_LOGS B on A.REQUEST_ID=B.REQUEST_ID and B.LAST_LOG='Y'
			Left join QPS_STATUS C on B.STATUS_ID=C.STATUS_ID
			Left Join USER_MASTER U on A.BUYER_ID=U.Emp_Code 
			Left Join USER_MASTER UV on B.VERIFIED_BY=UV.Emp_Code 
		
		End
	Else If(@Cmd='Get_PPS_Request_Details')
		Begin
			
			Select A.*,U.Emp_Code+' ~ '+U.Emp_Name as CREATED_BY,  C.STATUS,
			case when B.STATUS_ID in (4,5) then  B.VERIFIED_AT else null end as VERIFIED_AT ,
			case when B.STATUS_ID in (4,5) then  UV.Emp_Code+' ~ '+UV.Emp_Name else '' end as VERIFIED_BY, 
			B.STATUS_ID, U.Emp_Code, U.Emp_Name from QPS_PPS_REQUEST A 
			Left Join QPS_PPS_LOGS B on A.REQUEST_ID=B.REQUEST_ID and B.LAST_LOG='Y'
			Left join QPS_STATUS C on B.STATUS_ID=C.STATUS_ID
			Left Join USER_MASTER U on A.BUYER_ID=U.Emp_Code 
			Left Join USER_MASTER UV on B.VERIFIED_BY=UV.Emp_Code 
			where A.REQUEST_ID = @Id
		End
	Else If(@Cmd='Get_Generic_Article_Details')
		Begin
			SELECT 
			r.REQUEST_ID,
			r.GENERIC_ARTICLE,
			r.ARTICLE_DESCRIPTION,
			r.COLOR,
			r.MC,
			r.MC_DESCRIPTION,
			r.DIVISION,
			r.DIVISION_DESCRIPTION,
			r.VENDOR_CODE,
			r.VENDOR_NAME,
			r.MRP,
			r.PP_TYPE,
			-- Row-wise ERROR CODE
			CASE 
				WHEN EXISTS (
					SELECT 1
					FROM QPS_PPS_REQUEST r2
					JOIN QPS_PPS_LOGS l ON r2.REQUEST_ID = l.REQUEST_ID
					WHERE r2.REQUEST_ID = r.REQUEST_ID
					  AND l.LAST_LOG = 'Y'
					  AND l.STATUS_ID IN (1,2)
				) THEN 1004
				WHEN EXISTS (
					SELECT 1
					FROM QPS_PPS_STATUS s
					WHERE s.GENERIC_ARTICLE = r.GENERIC_ARTICLE
					  AND s.STATUS_ID = 4
					  AND s.CREATED_AT >= DATEADD(MONTH, -6, GETDATE())
				) THEN 1001
				WHEN (
					SELECT COUNT(*)
					FROM QPS_PPS_REQUEST a (nolock)
					LEFT JOIN QPS_PPS_LOGS b ON a.REQUEST_ID = b.REQUEST_ID AND b.STATUS_ID = 5
					WHERE a.GENERIC_ARTICLE = r.GENERIC_ARTICLE
					  AND b.STATUS_ID = 5
					  AND b.VERIFIED_AT >= DATEADD(MONTH, -6, GETDATE())
				) >= 3 THEN 1002
				ELSE 0
			END AS ERRORCODE,
			-- Row-wise ERROR MESSAGE
			CASE 
				WHEN EXISTS (
					SELECT 1
					FROM QPS_PPS_REQUEST r2
					JOIN QPS_PPS_LOGS l ON r2.REQUEST_ID = l.REQUEST_ID
					WHERE r2.REQUEST_ID = r.REQUEST_ID
					  AND l.LAST_LOG = 'Y'
					  AND l.STATUS_ID IN (1,2)
				) THEN 'Request already exists for this generic article [' + r.GENERIC_ARTICLE + '] with type [' + r.PP_TYPE + '].'
				WHEN EXISTS (
					SELECT 1
					FROM QPS_PPS_STATUS s
					WHERE s.GENERIC_ARTICLE = r.GENERIC_ARTICLE
					  AND s.STATUS_ID = 4
					  AND s.CREATED_AT >= DATEADD(MONTH, -6, GETDATE())
				) THEN 'This generic article [' + r.GENERIC_ARTICLE + '] with type [' + r.PP_TYPE + '] was already approved in the last 6 months.'
				WHEN (
					SELECT COUNT(*)
					FROM QPS_PPS_REQUEST a
					LEFT JOIN QPS_PPS_LOGS b ON a.REQUEST_ID = b.REQUEST_ID AND b.STATUS_ID = 5
					WHERE a.GENERIC_ARTICLE = r.GENERIC_ARTICLE
					  AND b.STATUS_ID = 5
					  AND b.VERIFIED_AT >= DATEADD(MONTH, -6, GETDATE())
				) >= 3 THEN 'This request is blocked because generic article [' + r.GENERIC_ARTICLE + '] with type [' + r.PP_TYPE + '] failed 3 times in the last 6 months.'
				ELSE 'Success'
			END AS ERRORMESSAGE
		FROM QPS_PPS_REQUEST r
		WHERE r.GENERIC_ARTICLE = @StrField Order by ERRORCODE desc;
			---- Check if there is already an active request for this article
			--IF EXISTS (
			--	SELECT 1
			--	FROM QPS_PPS_REQUEST r
			--	JOIN QPS_PPS_LOGS l ON r.REQUEST_ID = l.REQUEST_ID
			--	WHERE r.GENERIC_ARTICLE = @StrField
			--	  AND l.LAST_LOG = 'Y'
			--	  AND l.STATUS_ID IN (1,2) 
			--)
			--BEGIN
			--	SET @ERROR_CODE = 1004;
			--	SET @ERROR_MESSAGE = 'Request already exists for this generic article [ '+@StrField+' ].';
			--END
   --         -- 1️⃣ Check if approved in last 6 months
   --         IF EXISTS (
   --             SELECT 1
   --             FROM QPS_PPS_STATUS
   --             WHERE GENERIC_ARTICLE = @StrField
   --               AND STATUS_ID = 4  -- Passed
   --               AND CREATED_AT >= DATEADD(MONTH, -6, GETDATE())
   --         )
   --         BEGIN
   --             SET @ERROR_CODE = 1001;
   --             SET @ERROR_MESSAGE = 'This generic article [ '+@StrField+' ] was already approved in the last 6 months.';
   --         END

			----This generic article [ 1120096242 ] was already approved in the last 6 months
           
			---- 2️ Count failed attempts in last 6 months
			--SELECT @FailedCount =COUNT(*)
			--FROM QPS_PPS_REQUEST A (nolock)
			--left join QPS_PPS_LOGS B on A.REQUEST_ID=B.REQUEST_ID and B.STATUS_ID=5
			--WHERE GENERIC_ARTICLE = @StrField and  STATUS_ID = 5 -- Failed
			--  AND VERIFIED_AT >= DATEADD(MONTH, -6, GETDATE());


   --         -- 3️⃣ Apply failed count rule
   --         IF @FailedCount >= 3
   --         BEGIN
   --             SET @ERROR_CODE = 1002;
   --             SET @ERROR_MESSAGE = 'This request is blocked because article failed 3 times in the last 6 months.';
   --         END

   --       -- 4 Return QPS_PPS_REQUEST
          
			--select REQUEST_ID, GENERIC_ARTICLE,ARTICLE_DESCRIPTION,COLOR,MC,MC_DESCRIPTION,DIVISION,DIVISION_DESCRIPTION,VENDOR_CODE,VENDOR_NAME,MRP, @ERROR_CODE as ERRORCODE,@ERROR_MESSAGE as ERRORMESSAGE
			--from QPS_PPS_REQUEST where GENERIC_ARTICLE = @StrField

		End
	Else If(@Cmd='Get_PPS_Request_History_Timeline')
		Begin
			Select B.*,  U.EMP_NAME + ' ~ [ '+U.EMP_CODE+' ] '  as EMP_NAME , U.EMP_DEPT_NAME, C.STATUS from QPS_PPS_REQUEST A 
			Left Join QPS_PPS_LOGS B on A.REQUEST_ID=B.REQUEST_ID 
			Left Join USER_MASTER U on B.VERIFIED_BY=U.Emp_Code
			Left join QPS_STATUS C on B.STATUS_ID=C.STATUS_ID 
			where A.REQUEST_ID=@Id
		End

	 Else If(@Cmd='Get_LoggedinUser_Details_On_Emp_Code')
	   Begin
	        Select a.Id,Emp_Code,Emp_Name,Emp_Location,Emp_Loc_Code,Emp_Dept_Name,Emp_Desig,Emp_Contact_No,Emp_Mail_Id,Emp_Rpt_Mng,Is_Resign,Emp_Grade,Emp_Grade_Desc,Emp_Status,Role_Id From UserMaster a Inner Join RoleMaster b on a.Role_Id=b.Id Where Emp_Code=@StrField And Emp_Status=1 And Active_Status=1
			Select Menu,CMS,Media,User_Management From UserMaster a Inner Join RoleMaster b on a.Role_Id=b.Id Where Emp_Code=@StrField And Emp_Status=1 And Active_Status=1
			Select c.Id,c.Label, c.Url,Parent_Id,Page_Title,Page_Description,Page_Keywords,Permission From UserRoleDetails a Inner Join UserMaster b on a.User_Id=b.Id Inner Join MenuMaster c on a.Menu_Id=c.Id Where b.Emp_Code=@StrField And c.Active_Status=1  Order By c.[order]
	   End
END
