/****** Object:  StoredProcedure [dbo].[QPS_ROLES_INSERT_UPDATE]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Dinesh Kumar
-- Create date: 14 Aug 2025
-- Description:	Roles CRUD 
-- =============================================
CREATE PROCEDURE [dbo].[QPS_ROLES_INSERT_UPDATE]
    @ROLE_ID INT=0,
    @ROLE_NAME VARCHAR(50),
    @DESCRIPTION Varchar(200),
	@IS_ACTIVE bit,
    @ERROR_CODE INT OUTPUT,             -- Output parameter for error code
    @ERROR_MESSAGE VARCHAR(500) OUTPUT -- Output parameter for error message
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;
		-- Set output parameters for success
        SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Success';

        IF @ROLE_ID = 0
			BEGIN
				IF Exists(Select Top 1 ROLE_ID From QPS_ROLES Where ROLE_NAME=@ROLE_NAME)
				 Begin
				   SET @ERROR_CODE = 1;
				   SET @ERROR_MESSAGE = 'This role already exists.';
				   COMMIT TRANSACTION;
				   return;
				 End
				-- Insert new role into RoleMaster
				INSERT INTO QPS_ROLES (ROLE_NAME, DESCRIPTION, CREATED_AT,IS_ACTIVE)
				VALUES (@ROLE_NAME, @DESCRIPTION, GETDATE(),@IS_ACTIVE);

				-- Get the generated identity value for RoleId
				SET @ROLE_ID = SCOPE_IDENTITY();
				Exec PRO_INSERT_LOG_MASTER  @ROLE_ID,'Roles',1,'Insert Record In Roles'
			END
        ELSE
			BEGIN
			  -- Check for duplicate record on update
				IF Exists(Select Top 1 ROLE_ID From QPS_ROLES Where ROLE_NAME=@ROLE_NAME And ROLE_ID!=@ROLE_ID)
				 Begin
				   SET @ERROR_CODE = 1;
				   SET @ERROR_MESSAGE = 'Another role with this name already exists.';
				   COMMIT TRANSACTION;
				   return;
				 End
				-- Update existing role in RoleMaster
				Else
				  Begin
					UPDATE QPS_ROLES
					SET ROLE_NAME = @ROLE_NAME,
						DESCRIPTION = @DESCRIPTION,
						CREATED_AT = GETDATE(),
						IS_ACTIVE=@IS_ACTIVE
					WHERE ROLE_ID = @ROLE_ID;
				  End
			  
				  Exec PRO_INSERT_LOG_MASTER  @ROLE_ID,'Roles',1,'Record Updated'
			END
        -- Commit transaction if everything succeeds
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        -- Rollback transaction in case of an error
        ROLLBACK TRANSACTION;
		-- Set error code and error message for output
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH;
END;
GO
/****** Object:  StoredProcedure [dbo].[SP_ASSIGNED_INSPECTOR]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_ASSIGNED_INSPECTOR]
(
    @USER_ID INT,                        -- created/updated by
	@INSP_ID BIGINT = NULL,
	@OFFERED_QTY DECIMAL(18,3) = NULL,
    @INSPECTOR_EMP_CODE VARCHAR(20) = NULL,
	@ERROR_CODE INT = 0 OUTPUT,             
    @ERROR_MESSAGE VARCHAR(500) = 'Success' OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
	DECLARE @STATUS_CODE int,
	@TOTAL_QTY DECIMAL(18,3),
	@AvailableQty DECIMAL(18,3),
	@POID INT;
		SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Success';
    BEGIN TRY
		
		DECLARE @InspIdStr VARCHAR(20),@RunningNumber VARCHAR(20);
		SET @InspIdStr = CONVERT(VARCHAR(20), @INSP_ID);
		DECLARE @YearMonth CHAR(6) = FORMAT(GETDATE(), 'yyyyMM');
		DECLARE @NextNo INT;

        BEGIN TRANSACTION;

		--SELECT @TOTAL_QTY= TOTAL_QTY, @POID=POID FROM POHEADER WHERE POID = (SELECT POID FROM INSPECTION_REQUESTS WITH (NOLOCK) WHERE INSP_ID = @INSP_ID);
		
		--SELECT @AvailableQty= (@TOTAL_QTY-SUM(OFFERED_QTY)) from INSPECTION_REQUESTS where POID=@POID and INSP_ID != @INSP_ID GROUP BY POID
		--DECLARE  @avlqty VARCHAR(50) = CAST(@AvailableQty as VARCHAR(20));
		--IF(@AvailableQty<@OFFERED_QTY)
		--BEGIN
		--	RAISERROR (
  --              'Offered quantity is morethan available quantity. %s',
  --              16,
  --              1,
  --             @avlqty
  --          );
		--END

		SELECT @STATUS_CODE = case when isnull(IS_INSPECTOR_ASSIGNED,0)=0 then 5 else 6 end   from INSPECTION_REQUESTS WITH (NOLOCK) where INSP_ID=@INSP_ID 
    -----------------------------------------
    -- 1. GET Running Number 
    -----------------------------------------
	if (@STATUS_CODE=5)
		BEGIN
			IF EXISTS (SELECT 1 FROM dbo.DF_NUMBERTRACKER WHERE YEARMONTH = @YearMonth)
				BEGIN
					UPDATE dbo.DF_NUMBERTRACKER	SET LASTNO = LASTNO + 1	WHERE YEARMONTH = @YearMonth;
					SELECT @NextNo = LASTNO	FROM dbo.DF_NUMBERTRACKER WHERE YEARMONTH = @YearMonth;
				END
			ELSE
				BEGIN
					INSERT INTO dbo.DF_NUMBERTRACKER (YEARMONTH, LASTNO) VALUES (@YearMonth, 1);
					SET @NextNo = 1;
				END

		SET @RunningNumber =  @YearMonth + RIGHT('0000' + CAST(@NextNo AS VARCHAR), 4); -- removed @ 6 March 2026 requested by veenu --'DF ' +
		END
    ----------------------------------------
		
	 -- 2. UPDATE QA and Running number in Inspection Request
    -----------------------------------------
		
        IF(@INSPECTOR_EMP_CODE IS NOT NULL)
        BEGIN
			IF (@STATUS_CODE=5)
				BEGIN
					UPDATE INSPECTION_REQUESTS
					SET 
						INSPECTOR_EMP_CODE =  @INSPECTOR_EMP_CODE,
						IS_INSPECTOR_ASSIGNED =1,
						STATUS_CODE=@STATUS_CODE,
						INSPECTION_NO= @RunningNumber,
						LAST_UPDATED_ON = GETDATE(),
						UPDATED_BY = @USER_ID
					WHERE INSP_ID = @INSP_ID;
				END
			ELSE
				BEGIN
					UPDATE INSPECTION_REQUESTS
					SET 
						INSPECTOR_EMP_CODE =  @INSPECTOR_EMP_CODE,
						STATUS_CODE=@STATUS_CODE,
						LAST_UPDATED_ON = GETDATE(),
						UPDATED_BY = @USER_ID
					WHERE INSP_ID = @INSP_ID;
				END
        END
        COMMIT TRANSACTION;
    END TRY

    BEGIN CATCH
		IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE =  ERROR_MESSAGE();
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_ASSIGNED_INSPECTOR_FREEZE]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
