CREATE PROCEDURE [dbo].[SP_ASSIGNED_INSPECTOR_FREEZE]
(
    @USER_ID INT,                        -- created/updated by
	@IS_FREEZE BIT = 0,
	@QA_ASSIGNED_DOI DATETIME = NULL,
    @DETAILS VARCHAR(MAX) = NULL,
	@ERROR_CODE INT = 0 OUTPUT,             
    @ERROR_MESSAGE VARCHAR(500) = 'Success' OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
		SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Success';
    BEGIN TRY
        BEGIN TRANSACTION;
        IF(@QA_ASSIGNED_DOI IS NOT NULL AND @IS_FREEZE=1)
			BEGIN
				BEGIN TRY
					INSERT INTO INSPECTOR_ASSIGNMENTS (INSPECTION_DATE, FINALIZED_BY,DETAIL)
					VALUES 	( @QA_ASSIGNED_DOI, @USER_ID, @DETAILS);
				END TRY
				BEGIN CATCH
					IF ERROR_NUMBER() = 2627  -- Primary Key violation
					BEGIN
						Declare @DOI VARCHAR(MAX) = Convert(varchar,@QA_ASSIGNED_DOI,102);
						RAISERROR (
										'A record for this date ( %s ) already exists. Updates to finalized dates are not permitted.',
										16,
										1,
										@DOI
									);
					END
					ELSE
						THROW;
				END CATCH
			END
        COMMIT TRANSACTION;
    END TRY

    BEGIN CATCH
		IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE =  ERROR_MESSAGE();
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_CALCULATE_AUDIT_SCORE]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


-- ------------------------------------------------------------
-- SP_CALCULATE_AUDIT_SCORE
-- COMPUTES ELEMENT SCORES AND OVERALL AUDIT SCORE % ON SUBMIT
-- ------------------------------------------------------------
CREATE   PROCEDURE [dbo].[SP_CALCULATE_AUDIT_SCORE]
    @AUDIT_ID    INT,
    @UPDATED_BY  NVARCHAR(100) = 'SYSTEM'
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. REMOVE OLD ELEMENT SCORES FOR THIS AUDIT
    DELETE FROM AUDIT_ELEMENT_SCORE WHERE AUDIT_ID = @AUDIT_ID;

    -- 2. COMPUTE AND INSERT FRESH ELEMENT SCORES
    INSERT INTO AUDIT_ELEMENT_SCORE
        (AUDIT_ID, ELEMENT_ID, TOTAL_CHECK_POINTS, TOTAL_SCORE, ELEMENT_AVG_SCORE, FINAL_RATING,
         CREATED_BY, CREATED_ON, UPDATED_BY, UPDATED_ON)
    SELECT
        R.AUDIT_ID,
        CP.ELEMENT_ID,
        COUNT(R.CHECK_POINT_ID) AS TOTAL_CHECK_POINTS,
        SUM(CAST(R.SCORE AS DECIMAL(10,2))) AS TOTAL_SCORE,
        AVG(CAST(R.SCORE AS DECIMAL(10,2))) AS ELEMENT_AVG_SCORE,
        CASE
            WHEN AVG(CAST(R.SCORE AS DECIMAL(10,2))) <= 2.4 THEN 2
            WHEN AVG(CAST(R.SCORE AS DECIMAL(10,2))) <= 4.4 THEN 4
            WHEN AVG(CAST(R.SCORE AS DECIMAL(10,2))) <= 6.4 THEN 6
            WHEN AVG(CAST(R.SCORE AS DECIMAL(10,2))) <= 8.4 THEN 8
            ELSE 10
        END AS FINAL_RATING,
        @UPDATED_BY, GETUTCDATE(), @UPDATED_BY, GETUTCDATE()
    FROM AUDIT_CHECK_POINT_RESPONSE R
    INNER JOIN MASTER_AUDIT_CHECK_POINT CP ON CP.CHECK_POINT_ID = R.CHECK_POINT_ID
    WHERE R.AUDIT_ID  = @AUDIT_ID
      AND R.SCORE    IS NOT NULL
      AND CP.IS_ACTIVE = 1
    GROUP BY R.AUDIT_ID, CP.ELEMENT_ID;

    -- 3. CALCULATE OVERALL WEIGHTED SCORE %
    DECLARE @TOTALELEMENTS  INT;
    DECLARE @WEIGHTEDSCORE  DECIMAL(10,2);

    SELECT
        @TOTALELEMENTS = COUNT(*),
        @WEIGHTEDSCORE = SUM(
            CASE
				WHEN FINAL_RATING = 0 THEN 0
                WHEN FINAL_RATING <= 4 THEN 0.25
                WHEN FINAL_RATING =  6 THEN 0.50
                ELSE 1.0
            END
        )
    FROM AUDIT_ELEMENT_SCORE
    WHERE AUDIT_ID = @AUDIT_ID;

    DECLARE @AUDITSCOREPCT DECIMAL(5,2) = 0;
    IF @TOTALELEMENTS > 0
        SET @AUDITSCOREPCT = (@WEIGHTEDSCORE / @TOTALELEMENTS) * 100;

    -- 4. DETERMINE GRADE
    DECLARE @GRADE_ID INT;
    SELECT @GRADE_ID = GRADE_ID
    FROM   MASTER_AUDIT_GRADE
    WHERE  @AUDITSCOREPCT >= MIN_SCORE
      AND  @AUDITSCOREPCT <= MAX_SCORE
      AND  IS_ACTIVE = 1;

    -- 5. COMPUTE VALIDITY DATE FROM GRADE'S VALIDITY MONTHS
    DECLARE @VALIDITY_TILL DATE;
    SELECT @VALIDITY_TILL = DATEADD(MONTH, VALIDITY_IN_MONTHS, CAST(GETDATE() AS DATE))
    FROM   MASTER_AUDIT_GRADE
    WHERE  GRADE_ID = @GRADE_ID;

    -- 6. UPDATE AUDIT HEADER
    UPDATE AUDIT_REPORT
    SET
        AUDIT_SCORE_PERCENT  = @AUDITSCOREPCT,
        GRADE_ID             = @GRADE_ID,
        VALIDITY_TILL        = @VALIDITY_TILL,
        STATUS_ID            = 3,                -- SUBMITTED
        SUBMITTED_AT         = GETUTCDATE(),
        UPDATED_BY           = @UPDATED_BY,
        UPDATED_ON           = GETUTCDATE()
    WHERE AUDIT_ID = @AUDIT_ID;

    -- 7. RETURN RESULT SET
    SELECT
        @AUDITSCOREPCT      AS AUDITSCORE,
        @GRADE_ID            AS GRADE_ID,
        @VALIDITY_TILL       AS VALIDITY_TILL;
END

GO
/****** Object:  StoredProcedure [dbo].[SP_CHANGE_OFFERED_QTY_BY_INSPECTOR]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_CHANGE_OFFERED_QTY_BY_INSPECTOR]
(
    @USER_ID INT,                        -- created/updated by
	@INSP_ID BIGINT = NULL,
	@OFFERED_QTY DECIMAL(18,3) = NULL,
	@ERROR_CODE INT = 0 OUTPUT,             
    @ERROR_MESSAGE VARCHAR(500) = 'Success' OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
	DECLARE @STATUS_CODE int,
	@TOTAL_QTY DECIMAL(18,3),
	@AvailableQty DECIMAL(18,3),
	@POID INT;
    BEGIN TRY
		SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Success';
		DECLARE @InspIdStr VARCHAR(20);
		SET @InspIdStr = CONVERT(VARCHAR(20), @INSP_ID);
        BEGIN TRANSACTION;

		SELECT @TOTAL_QTY= TOTAL_QTY,@AvailableQty=TOTAL_QTY, @POID=POID FROM POHEADER WHERE POID = (SELECT POID FROM INSPECTION_REQUESTS WITH (NOLOCK) WHERE INSP_ID = @INSP_ID);
		
		SELECT @AvailableQty= (@TOTAL_QTY-SUM(OFFERED_QTY)) from INSPECTION_REQUESTS where POID=@POID and INSP_ID != @INSP_ID GROUP BY POID


		IF(@OFFERED_QTY > CEILING(@AvailableQty * 1.10))--(@AvailableQty<@OFFERED_QTY)
		BEGIN
			RAISERROR (
                'Offered quantity is morethan available quantity.',
                16,
                1,
               @InspIdStr
            );
		END
    -----------------------------------------
    -- 1. UPSERT DOI by QA
    -----------------------------------------
        IF(@OFFERED_QTY >0)
        BEGIN
				UPDATE INSPECTION_REQUESTS
				SET 
					OFFERED_QTY=@OFFERED_QTY,
					LAST_UPDATED_ON = GETDATE(),
					UPDATED_BY = @USER_ID
				WHERE INSP_ID = @INSP_ID;
        END
		
        COMMIT TRANSACTION;
    END TRY

    BEGIN CATCH
		IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE =  ERROR_MESSAGE();
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_DOI_ASSIGNED_BY_QA]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_DOI_ASSIGNED_BY_QA]
(
    @USER_ID INT,                       
	@INSP_ID BIGINT ,
    @QA_ASSIGNED_DOI DATETIME = NULL,
	@OFFERED_QTY DECIMAL(18,3) = NULL,
	@ERROR_CODE INT = 0 OUTPUT,             
    @ERROR_MESSAGE VARCHAR(500) = 'Success' OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
	DECLARE  @STATUS_CODE int;
   

    BEGIN TRY
		SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Success';
		DECLARE @InspIdStr VARCHAR(20);
		SET @InspIdStr = CONVERT(VARCHAR(20), @INSP_ID);
        BEGIN TRANSACTION;
    -----------------------------------------
    -- 1. UPSERT DOI by QA
    -----------------------------------------
		SELECT @STATUS_CODE =
            CASE
                WHEN ISNULL(IS_DATE_ASSIGNED_BY_QA , 0) = 0 THEN 3 ELSE 4
            END
        FROM INSPECTION_REQUESTS WITH (NOLOCK)
        WHERE INSP_ID = @INSP_ID;
		
		
		IF @STATUS_CODE IS NULL
			BEGIN
				RAISERROR (
					'Inspection request not found for INSP_ID = %s.',
					16,
					1,
				   @InspIdStr
				);
			END
		
        IF(@QA_ASSIGNED_DOI IS NOT NULL)
			BEGIN
					UPDATE INSPECTION_REQUESTS
					SET 
						QA_ASSIGNED_DOI =  @QA_ASSIGNED_DOI,
						IS_DATE_ASSIGNED_BY_QA =1,
						OFFERED_QTY=@OFFERED_QTY,
						STATUS_CODE=@STATUS_CODE,
						LAST_UPDATED_ON = GETDATE(),
						UPDATED_BY = @USER_ID
					WHERE INSP_ID = @INSP_ID;
			END

		
        COMMIT TRANSACTION;
    END TRY

    BEGIN CATCH
		IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_EMAIL_LIST_CRUD]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_EMAIL_LIST_CRUD]
(
    @ACTION                 VARCHAR(20),
    @EMAIL_ID               VARCHAR(250) = NULL,
    @NAME                   VARCHAR(50) = NULL,
    @IS_ACTIVE              BIT = NULL,
    @CREATED_BY_EMP_CODE    VARCHAR(50) = NULL,

	 @ERROR_CODE INT = 0 OUTPUT,             
     @ERROR_MESSAGE VARCHAR(500) = 'Success' OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
		IF(@ACTION = 'INSERT' OR @ACTION = 'UPDATE')
			BEGIN
			
				IF (ISNULL(@NAME,'')='' OR ISNULL(@EMAIL_ID,'')='')
					BEGIN
						RAISERROR('EMP NAME / EMAIL ID is null or blank.', 16, 1);
					END
			
				BEGIN TRANSACTION;
					SET @ERROR_CODE = 0;
					SET @ERROR_MESSAGE = 'Saved Successfully';
				
					IF(@ACTION = 'INSERT')
						BEGIN
							  IF EXISTS (SELECT 1 FROM EMAIL_LIST WHERE EMAIL_ID = @EMAIL_ID)
								BEGIN
									RAISERROR('EMAIL ID ALREADY EXISTS.', 16, 1);
								END
							  INSERT INTO EMAIL_LIST(EMAIL_ID,NAME,IS_ACTIVE,CREATED_BY_EMP_CODE,LAST_UPDATED_DATE)
							  VALUES(@EMAIL_ID,@NAME,@IS_ACTIVE,@CREATED_BY_EMP_CODE,GETDATE());
						END
					ELSE IF(@ACTION = 'UPDATE')
						BEGIN
							IF NOT EXISTS (SELECT 1 FROM EMAIL_LIST WHERE EMAIL_ID = @EMAIL_ID)
								BEGIN
									RAISERROR('EMAIL ID NOT FOUND.', 16, 1);
								END
							UPDATE EMAIL_LIST
							SET
							    NAME				= @NAME,
							    IS_ACTIVE			= @IS_ACTIVE,
							    CREATED_BY_EMP_CODE = @CREATED_BY_EMP_CODE,
							    LAST_UPDATED_DATE	= GETDATE()
							WHERE EMAIL_ID = @EMAIL_ID;
						END
					
				COMMIT TRANSACTION;
			END
		ELSE IF(@ACTION = 'GETBYID' )
			BEGIN
				IF (ISNULL(@EMAIL_ID,'')='')
					BEGIN
						RAISERROR('Email Id is null or blank.', 16, 1);
					END
				
				SELECT EMAIL_ID,NAME,IS_ACTIVE,CREATED_BY_EMP_CODE,LAST_UPDATED_DATE
				FROM EMAIL_LIST
				WHERE EMAIL_ID = @EMAIL_ID;
			END
		ELSE IF(@ACTION = 'GETALL')
			BEGIN
				SELECT
                EMAIL_ID,NAME,IS_ACTIVE,CREATED_BY_EMP_CODE,LAST_UPDATED_DATE
				FROM EMAIL_LIST
				ORDER BY NAME;
			END
    END TRY

    BEGIN CATCH
		IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH

END
GO
/****** Object:  StoredProcedure [dbo].[SP_FACTORY_AUDIT_CODE_GENERATE]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


-- ============================================================
-- STORED PROCEDURES
-- ============================================================

-- ------------------------------------------------------------
-- SP_GENERATE_AUDIT_CODE
-- AUTO-GENERATES A UNIQUE AUDIT CODE: VMM-YYYY-NNNNN
-- ------------------------------------------------------------
CREATE   PROCEDURE [dbo].[SP_FACTORY_AUDIT_CODE_GENERATE]
    @AUDIT_CODE VARCHAR(30) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @YEAR   VARCHAR(4) = CAST(YEAR(GETDATE()) AS VARCHAR(4));
    DECLARE @COUNT  INT;
    SELECT  @COUNT = COUNT(*) + 1
    FROM    AUDIT_REPORT
    WHERE   YEAR(CREATED_ON) = YEAR(GETDATE()) AND  IS_DELETED = 0;

    SET @AUDIT_CODE = 'VMM-' + @YEAR + '-' + RIGHT('00000' + CAST(@COUNT AS VARCHAR), 5);
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FACTORY_AUDIT_MASTER_ATTACHMENT_ITEM_GET_ALL]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SP_FACTORY_AUDIT_MASTER_ATTACHMENT_ITEM_GET_ALL]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT *
    FROM MASTER_AUDIT_ATTACHMENT_ITEM
    WHERE IS_ACTIVE = 1
    ORDER BY DISPLAY_ORDER;
