/****** Object:  StoredProcedure [dbo].[SP_FACTORY_AUDIT_MASTER_KEY_ELEMENT_GET_ALL]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_FACTORY_AUDIT_MASTER_KEY_ELEMENT_GET_ALL]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        E.ELEMENT_ID,
        E.ELEMENT_NO,
        E.ELEMENT_NAME,
        E.DISPLAY_ORDER,
        E.IS_ACTIVE,
        E.CREATED_BY,
        E.CREATED_ON,
        E.UPDATED_BY,
        E.UPDATED_ON,

        CP.CHECK_POINT_ID,
        CP.ELEMENT_ID AS CP_ELEMENT_ID,
        CP.CHECK_POINT_NO,
        CP.QUESTION,
        CP.HAVE_DROPDOWN,
        CP.IS_CRITICAL,
        CP.DISPLAY_ORDER AS CP_ORDER,
        CP.IS_ACTIVE AS CP_IS_ACTIVE,
        CP.CREATED_BY AS CP_CB,
        CP.CREATED_ON AS CP_CO,
        CP.UPDATED_BY AS CP_UB,
        CP.UPDATED_ON AS CP_UO

    FROM MASTER_AUDIT_KEY_ELEMENT E
    LEFT JOIN MASTER_AUDIT_CHECK_POINT CP
        ON CP.ELEMENT_ID = E.ELEMENT_ID
        AND CP.IS_ACTIVE = 1

    WHERE E.IS_ACTIVE = 1

    ORDER BY
        E.DISPLAY_ORDER,
        CP.DISPLAY_ORDER;
END
