GO


-- ============================================================
-- SP_FACTORY_AUDIT_REPORT_GET_BY_CODE
-- Returns AUDIT_ID for a given AUDIT_CODE
-- ============================================================
CREATE   PROCEDURE [dbo].[SP_FACTORY_AUDIT_REPORT_GET_BY_CODE]
    @AUDIT_CODE     NVARCHAR(30)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY

        IF NULLIF(LTRIM(RTRIM(@AUDIT_CODE)), '') IS NULL
            THROW 50071, 'AUDIT_CODE is required.', 1;

        SELECT AUDIT_ID
        FROM   AUDIT_REPORT
        WHERE  AUDIT_CODE = @AUDIT_CODE AND  IS_DELETED = 0;

    END TRY
    BEGIN CATCH
        DECLARE @ERROR_MESSAGE  NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ERROR_SEVERITY INT            = ERROR_SEVERITY();
        DECLARE @ERROR_STATE    INT            = ERROR_STATE();
        RAISERROR(@ERROR_MESSAGE, @ERROR_SEVERITY, @ERROR_STATE);
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FACTORY_AUDIT_REPORT_GET_BY_ID]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- ============================================================
-- SP_FACTORY_AUDIT_REPORT_GET_BY_ID
-- Returns full audit header + grade info for aggregate root
-- ============================================================
CREATE   PROCEDURE [dbo].[SP_FACTORY_AUDIT_REPORT_GET_BY_ID]
    @AUDIT_ID   INT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY

        IF @AUDIT_ID <= 0
            THROW 50070, 'AUDIT_ID must be a positive number.', 1;

        -- Header + Grade
        SELECT
            AR.AUDIT_ID,
            AR.AUDIT_CODE,
            AR.STATUS_ID,
            AR.CURRENT_STEP,
            AR.MAX_UNLOCKED_STEP,
            AR.AUDITOR_EMP_CODE,
            AR.AUDIT_DATE,
            AR.AUDIT_REQ_ID,
            AR.FACTORY_OWNER_EMAIL,

			ISNULL(AR.AUDIT_SCORE_PERCENT,0)       AS AUDIT_SCORE_PERCENT,
			AR.GRADE_ID,
			ISNULL(G.GRADE_CODE,'')		 AS GRADE_CODE,
			ISNULL(G.COLOR_HEX,'')       AS GRADECOLOR_HEX,
			G.VALIDATION_PERIOD,
			ISNULL(G.VALIDITY_IN_MONTHS,0) AS VALIDITY_IN_MONTHS,
			AR.VALIDITY_TILL,


			AR.OVER_ALL_COMMENTS  as OVERALLCOMMENTS,
            AR.IS_DELETED,
            AR.CREATED_BY,
            AR.CREATED_ON,
            AR.UPDATED_BY,
            AR.UPDATED_ON,
            AR.SUBMITTED_AT
        FROM  AUDIT_REPORT AR
        LEFT JOIN MASTER_AUDIT_GRADE G ON G.GRADE_ID = AR.GRADE_ID
        WHERE AR.AUDIT_ID   = @AUDIT_ID
          AND AR.IS_DELETED = 0;

        -- Checkpoint → Element map (used for scoring in domain)
        SELECT CHECK_POINT_ID, ELEMENT_ID
        FROM MASTER_AUDIT_CHECK_POINT
        WHERE IS_ACTIVE = 1;

		SELECT RESPONSE_ID,	AUDIT_ID,	CHECK_POINT_ID,	SCORE,	REMARKS,	CREATED_BY,	CREATED_ON,	UPDATED_BY,	UPDATED_ON FROM  [dbo].[AUDIT_CHECK_POINT_RESPONSE] WHERE AUDIT_ID=@AUDIT_ID

		

    END TRY
    BEGIN CATCH
        DECLARE @ERROR_MESSAGE  NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ERROR_SEVERITY INT            = ERROR_SEVERITY();
        DECLARE @ERROR_STATE    INT            = ERROR_STATE();
        RAISERROR(@ERROR_MESSAGE, @ERROR_SEVERITY, @ERROR_STATE);
    END CATCH
END


GO
/****** Object:  StoredProcedure [dbo].[SP_FACTORY_AUDIT_REPORT_GET_DETAIL]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


-- ============================================================
-- SP_FACTORY_AUDIT_REPORT_GET_DETAIL
-- Returns full audit detail — 5 result sets in one call
-- ============================================================
CREATE   PROCEDURE [dbo].[SP_FACTORY_AUDIT_REPORT_GET_DETAIL]
    @AUDIT_ID   INT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY

        IF @AUDIT_ID <= 0
            THROW 50074, 'AUDIT_ID must be a positive number.', 1;

        IF NOT EXISTS (
            SELECT 1 FROM AUDIT_REPORT
            WHERE AUDIT_ID = @AUDIT_ID AND IS_DELETED = 0)
            THROW 50075, 'Audit not found or has been deleted.', 1;

        -- ── Result Set 1: Header (from view) ──────────────
        SELECT
            AUDIT_ID,
            AUDIT_CODE,
            STATUS_ID,
            STATUS_NAME,
            CURRENT_STEP,
            AUDITOR_EMP_CODE,
            AUDITOR_NAME,
            AUDIT_DATE,
            AUDIT_REQ_ID,
            FACTORY_OWNER_EMAIL,
			OVER_ALL_COMMENTS,
            AUDIT_SCORE_PERCENT,
			DESCRIPTION,
            GRADE_ID,
            GRADE_CODE,
            GRADECOLOR_HEX          AS GRADECOLOR_HEX,
            VALIDATION_PERIOD,
            VALIDITY_IN_MONTHS,
            VALIDITY_TILL,
            CREATED_BY,
            CREATED_ON,
            UPDATED_BY,
            UPDATED_ON,
            SUBMITTED_AT
        FROM  VW_AUDITSUMMARY
        WHERE AUDIT_ID = @AUDIT_ID;

        -- ── Result Set 2: Document Responses ──────────────
        SELECT
            DR.RESPONSE_ID,
            DR.ITEM_ID,
            D.SR_NO,
            D.DOCUMENT_NAME,
            D.IS_MANDATORY,
            ISNULL(DR.IS_AVAILABLE, '')  AS IS_AVAILABLE,
            DR.VALIDITY_DATE,
            ISNULL(DR.UNIT_INFO,    '')  AS UNIT_INFO,
            ISNULL(DR.ATTACHMENTS,  '')  AS ATTACHMENTS,
            ISNULL(DR.REMARKS,      '')  AS REMARKS
        FROM  AUDIT_DOCUMENT_RESPONSE DR
        JOIN  MASTER_AUDIT_DOCUMENT_CHECK_LIST_ITEM D
              ON D.ITEM_ID = DR.ITEM_ID
        WHERE DR.AUDIT_ID = @AUDIT_ID
        ORDER BY D.SR_NO;

        -- ── Result Set 3: Checkpoint Responses ────────────
        SELECT
            CR.RESPONSE_ID,
            CR.CHECK_POINT_ID,
            CP.ELEMENT_ID,
            CP.CHECK_POINT_NO,
            CP.QUESTION,
            CP.IS_CRITICAL,
            CR.SCORE,
            ISNULL(CR.REMARKS, '')  AS REMARKS
        FROM  AUDIT_CHECK_POINT_RESPONSE CR
        JOIN  MASTER_AUDIT_CHECK_POINT CP
              ON CP.CHECK_POINT_ID = CR.CHECK_POINT_ID
        WHERE CR.AUDIT_ID = @AUDIT_ID
        ORDER BY CP.ELEMENT_ID, CP.DISPLAY_ORDER;

        -- ── Result Set 4: Element Scores ──────────────────
        SELECT
            ES.SCORE_ID,
            ES.ELEMENT_ID,
            KE.ELEMENT_NO,
            KE.ELEMENT_NAME,
            ES.TOTAL_CHECK_POINTS,
            ES.TOTAL_SCORE,
            ES.ELEMENT_AVG_SCORE,
            ES.FINAL_RATING
        FROM  AUDIT_ELEMENT_SCORE ES
        JOIN  MASTER_AUDIT_KEY_ELEMENT KE
              ON KE.ELEMENT_ID = ES.ELEMENT_ID
        WHERE ES.AUDIT_ID = @AUDIT_ID
        ORDER BY KE.DISPLAY_ORDER;

        -- ── Result Set 5: Attachment Responses ────────────
        SELECT
            AR.ATTACHMENT_ID,
            AR.ITEM_ID,
            AI.SR_NO,
            AI.ATTACHMENT_NAME,
            AI.IS_MANDATORY,
            ISNULL(AR.IS_AVAILABLE, '')  AS IS_AVAILABLE,
            AR.ATTACHMENT,
            ISNULL(AR.REMARKS,      '')  AS REMARKS
        FROM  AUDIT_ATTACHMENT_RESPONSE AR
        JOIN  MASTER_AUDIT_ATTACHMENT_ITEM AI
              ON AI.ITEM_ID = AR.ITEM_ID
        WHERE AR.AUDIT_ID = @AUDIT_ID
        ORDER BY AI.SR_NO;

		 -- ── Result Set 6: Grade Master List ────────────
		SELECT *
        FROM MASTER_AUDIT_GRADE
        WHERE IS_ACTIVE = 1
        ORDER BY GRADE_ID;


    END TRY
    BEGIN CATCH
        DECLARE @ERROR_MESSAGE  NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ERROR_SEVERITY INT            = ERROR_SEVERITY();
        DECLARE @ERROR_STATE    INT            = ERROR_STATE();
        RAISERROR(@ERROR_MESSAGE, @ERROR_SEVERITY, @ERROR_STATE);
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FACTORY_AUDIT_REPORT_GET_PAGED]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


-- ============================================================
-- SP_FACTORY_AUDIT_REPORT_GET_PAGED
-- Returns paged list (count + data) for dashboard
-- ============================================================
CREATE   PROCEDURE [dbo].[SP_FACTORY_AUDIT_REPORT_GET_PAGED]
    @SEARCH_TERM    NVARCHAR(100)   = NULL,
    @STATUS_ID      INT             = NULL,
    @FROM_DATE      DATETIME        = NULL,
    @TO_DATE        DATETIME        = NULL,
    @EMP_CODE       NVARCHAR(30)    = NULL,
    @PAGE           INT             = 1,
    @PAGE_SIZE      INT             = 20
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY

        IF @PAGE <= 0
            THROW 50072, 'PAGE must be greater than 0.', 1;

        IF @PAGE_SIZE <= 0 OR @PAGE_SIZE > 200
            THROW 50073, 'PAGE_SIZE must be between 1 and 200.', 1;

        DECLARE @SKIP   INT = (@PAGE - 1) * @PAGE_SIZE;
        DECLARE @SEARCH NVARCHAR(102) = CASE
            WHEN @SEARCH_TERM IS NOT NULL
            THEN '%' + @SEARCH_TERM + '%'
            ELSE NULL
        END;

        -- Result set 1: Total count
        SELECT COUNT(*) AS TOTAL_COUNT
        FROM   VW_AUDITSUMMARY
        WHERE  (@SEARCH    IS NULL OR AUDIT_CODE LIKE @SEARCH
                           OR CAST(AUDIT_REQ_ID AS NVARCHAR) LIKE @SEARCH)
          AND  (@STATUS_ID IS NULL OR STATUS_ID       = @STATUS_ID)
          AND  (@FROM_DATE IS NULL OR AUDIT_DATE      >= @FROM_DATE)
          AND  (@TO_DATE   IS NULL OR AUDIT_DATE      <= @TO_DATE)
          AND  (@EMP_CODE  IS NULL OR AUDITOR_EMP_CODE = @EMP_CODE);

        -- Result set 2: Paged data
        SELECT
            AUDIT_ID,
            AUDIT_CODE,
            STATUS_ID,
            STATUS_NAME,
            CURRENT_STEP,
            AUDITOR_EMP_CODE,
            AUDITOR_NAME,
            AUDIT_DATE,
            AUDIT_REQ_ID,
            AUDIT_SCORE_PERCENT,
            GRADE_ID,
            GRADE_CODE,
            GRADECOLOR_HEX          AS GRADE_COLOR_HEX,
            VALIDATION_PERIOD,
            VALIDITY_IN_MONTHS,
            VALIDITY_TILL,
            CREATED_BY,
            CREATED_ON,
            UPDATED_BY,
            UPDATED_ON,
            SUBMITTED_AT
        FROM   VW_AUDITSUMMARY
        WHERE  (@SEARCH    IS NULL OR AUDIT_CODE LIKE @SEARCH
                           OR CAST(AUDIT_REQ_ID AS NVARCHAR) LIKE @SEARCH)
          AND  (@STATUS_ID IS NULL OR STATUS_ID       = @STATUS_ID)
          AND  (@FROM_DATE IS NULL OR AUDIT_DATE      >= @FROM_DATE)
          AND  (@TO_DATE   IS NULL OR AUDIT_DATE      <= @TO_DATE)
          AND  (@EMP_CODE  IS NULL OR AUDITOR_EMP_CODE = @EMP_CODE)
        ORDER  BY CREATED_ON DESC
        OFFSET @SKIP ROWS FETCH NEXT @PAGE_SIZE ROWS ONLY;

    END TRY
    BEGIN CATCH
        DECLARE @ERROR_MESSAGE  NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ERROR_SEVERITY INT            = ERROR_SEVERITY();
        DECLARE @ERROR_STATE    INT            = ERROR_STATE();
        RAISERROR(@ERROR_MESSAGE, @ERROR_SEVERITY, @ERROR_STATE);
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FACTORY_AUDIT_REPORT_INSERT]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SP_FACTORY_AUDIT_REPORT_INSERT]
    @AUDIT_CODE             NVARCHAR(30),
    @STATUS_ID              INT,
    @CURRENT_STEP           INT,
    @MAX_UNLOCKED_STEP      INT,
    @AUDITOR_EMP_CODE       NVARCHAR(30),
    @AUDIT_DATE             DATETIME,
    @AUDIT_REQ_ID           BIGINT,
    @FACTORY_OWNER_EMAIL    NVARCHAR(150),
    @CREATED_BY             NVARCHAR(100),
    @NEW_AUDIT_ID           INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -- Validate required fields
        IF NULLIF(LTRIM(RTRIM(@AUDIT_CODE)), '') IS NULL
            THROW 50001, 'AUDIT_CODE is required.', 1;

        IF NULLIF(LTRIM(RTRIM(@AUDITOR_EMP_CODE)), '') IS NULL
            THROW 50002, 'AUDITOR_EMP_CODE is required.', 1;

        IF @AUDIT_DATE IS NULL
            THROW 50003, 'AUDIT_DATE is required.', 1;

        IF NULLIF(LTRIM(RTRIM(@CREATED_BY)), '') IS NULL
            THROW 50004, 'CREATED_BY is required.', 1;

        IF @AUDIT_REQ_ID <= 0
            THROW 50005, 'AUDIT_REQ_ID must be a positive number.', 1;

        -- Check for duplicate audit code
        IF EXISTS (SELECT 1 FROM AUDIT_REPORT WHERE AUDIT_CODE = @AUDIT_CODE AND IS_DELETED = 0)
            THROW 50006, 'An audit with this AUDIT_CODE already exists.', 1;

        -- Insert
        INSERT INTO AUDIT_REPORT
        (
            AUDIT_CODE,
            STATUS_ID,
            CURRENT_STEP,
            MAX_UNLOCKED_STEP,
            AUDITOR_EMP_CODE,
            AUDIT_DATE,
            AUDIT_REQ_ID,
            FACTORY_OWNER_EMAIL,
            IS_DELETED,
            CREATED_BY,
            CREATED_ON,
            UPDATED_BY,
            UPDATED_ON
        )
        VALUES
        (
            @AUDIT_CODE,
            @STATUS_ID,
            @CURRENT_STEP,
            @MAX_UNLOCKED_STEP,
            @AUDITOR_EMP_CODE,
            @AUDIT_DATE,
            @AUDIT_REQ_ID,
            @FACTORY_OWNER_EMAIL,
            0,
            @CREATED_BY,
            GETUTCDATE(),
            @CREATED_BY,
            GETUTCDATE()
        );

        -- Return the new ID via OUTPUT parameter
        SET @NEW_AUDIT_ID = CAST(SCOPE_IDENTITY() AS INT);

    END TRY
    BEGIN CATCH

        DECLARE @ERROR_MESSAGE  NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ERROR_NUMBER   INT            = ERROR_NUMBER();
        DECLARE @ERROR_SEVERITY INT            = ERROR_SEVERITY();
        DECLARE @ERROR_STATE    INT            = ERROR_STATE();

        -- Re-throw with original error info
        RAISERROR(@ERROR_MESSAGE, @ERROR_SEVERITY, @ERROR_STATE);

    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FACTORY_AUDIT_REPORT_SAVE_ALL]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



-- ============================================================
-- STEP 2: SINGLE MASTER SP — SP_FACTORY_AUDIT_REPORT_SAVE_ALL
-- Accepts all data in one call via TVPs
-- Full transaction — all or nothing
-- ============================================================

CREATE   PROCEDURE [dbo].[SP_FACTORY_AUDIT_REPORT_SAVE_ALL]

    -- ── Header fields ─────────────────────────────────────
    @AUDIT_ID               INT,
    @STATUS_ID              INT,
    @CURRENT_STEP           INT,
    @MAX_UNLOCKED_STEP      INT,
    @AUDITOR_EMP_CODE       NVARCHAR(30),
    @AUDIT_DATE             DATETIME,
    @AUDIT_REQ_ID           BIGINT,
    @FACTORY_OWNER_EMAIL    NVARCHAR(150),
    @AUDIT_SCORE_PERCENT    DECIMAL(5,2)    = NULL,
    @GRADE_ID               INT             = NULL,
    @VALIDITY_TILL          DATE            = NULL,
    @OVER_ALL_COMMENTS      NVARCHAR(2000)  = NULL,
    @IS_DELETED             BIT             = 0,
    @UPDATED_BY             NVARCHAR(100),
    @SUBMITTED_AT           DATETIME2       = NULL,

    -- ── TVP parameters (READONLY is mandatory for TVPs) ───
    @DOCUMENT_RESPONSES     TVP_FACTORY_AUDIT_DOCUMENT_RESPONSE     READONLY,
    @CHECKPOINT_RESPONSES   TVP_FACTORY_AUDIT_CHECKPOINT_RESPONSE   READONLY,
    @ELEMENT_SCORES         TVP_FACTORY_AUDIT_ELEMENT_SCORE         READONLY,
    @ATTACHMENT_RESPONSES   TVP_FACTORY_AUDIT_ATTACHMENT_RESPONSE   READONLY,
    @ACTIVITY_LOGS          TVP_FACTORY_AUDIT_ACTIVITY_LOG          READONLY

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- ══════════════════════════════════════════════════
        -- 1. VALIDATE HEADER
        -- ══════════════════════════════════════════════════

        IF NOT EXISTS (
            SELECT 1 FROM AUDIT_REPORT
            WHERE AUDIT_ID = @AUDIT_ID AND IS_DELETED = 0)
            THROW 50010, 'Audit record not found or has been deleted.', 1;

        IF NULLIF(LTRIM(RTRIM(@AUDITOR_EMP_CODE)), '') IS NULL
            THROW 50011, 'AUDITOR_EMP_CODE is required.', 1;

        IF @AUDIT_DATE IS NULL
            THROW 50012, 'AUDIT_DATE is required.', 1;

        IF NULLIF(LTRIM(RTRIM(@UPDATED_BY)), '') IS NULL
            THROW 50013, 'UPDATED_BY is required.', 1;

        IF @AUDIT_REQ_ID <= 0
            THROW 50014, 'AUDIT_REQ_ID must be a positive number.', 1;

        IF @AUDIT_SCORE_PERCENT IS NOT NULL
            AND (@AUDIT_SCORE_PERCENT < 0 OR @AUDIT_SCORE_PERCENT > 100)
            THROW 50015, 'AUDIT_SCORE_PERCENT must be between 0 and 100.', 1;

        -- ══════════════════════════════════════════════════
        -- 2. VALIDATE TVP DATA
        -- ══════════════════════════════════════════════════

        -- Document: IS_AVAILABLE must be Y/N or NULL
        IF EXISTS (
            SELECT 1 FROM @DOCUMENT_RESPONSES
            WHERE IS_AVAILABLE IS NOT NULL
              AND IS_AVAILABLE NOT IN ('Y', 'N'))
            THROW 50022, 'IS_AVAILABLE must be Y or N.', 1;

        -- Checkpoint: SCORE must be in allowed set
        IF EXISTS (
            SELECT 1 FROM @CHECKPOINT_RESPONSES
            WHERE SCORE IS NOT NULL
              AND SCORE NOT IN (0, 2, 4, 6, 8, 10))
            THROW 50032, 'SCORE must be one of: 0, 2, 4, 6, 8, 10.', 1;

        -- Element: FINAL_RATING must be in allowed set
        IF EXISTS (
            SELECT 1 FROM @ELEMENT_SCORES
            WHERE FINAL_RATING NOT IN (0, 2, 4, 6, 8, 10))
            THROW 50042, 'FINAL_RATING must be one of: 0, 2, 4, 6, 8, 10.', 1;

        -- Activity log: ACTION and PERFORMED_BY required
        IF EXISTS (
            SELECT 1 FROM @ACTIVITY_LOGS
            WHERE NULLIF(LTRIM(RTRIM(ACTION)), '') IS NULL
               OR NULLIF(LTRIM(RTRIM(PERFORMED_BY)), '') IS NULL)
            THROW 50061, 'ACTION and PERFORMED_BY are required in activity logs.', 1;

        -- ══════════════════════════════════════════════════
        -- 3. UPDATE AUDIT HEADER
        -- ══════════════════════════════════════════════════

        UPDATE AUDIT_REPORT SET
            STATUS_ID           = @STATUS_ID,
            CURRENT_STEP        = @CURRENT_STEP,
            MAX_UNLOCKED_STEP   = @MAX_UNLOCKED_STEP,
            AUDITOR_EMP_CODE    = @AUDITOR_EMP_CODE,
            AUDIT_DATE          = @AUDIT_DATE,
            AUDIT_REQ_ID        = @AUDIT_REQ_ID,
            FACTORY_OWNER_EMAIL = @FACTORY_OWNER_EMAIL,
            AUDIT_SCORE_PERCENT = @AUDIT_SCORE_PERCENT,
            GRADE_ID            = @GRADE_ID,
            VALIDITY_TILL       = @VALIDITY_TILL,
            OVER_ALL_COMMENTS   = @OVER_ALL_COMMENTS,
            IS_DELETED          = @IS_DELETED,
            UPDATED_BY          = @UPDATED_BY,
            UPDATED_ON          = GETUTCDATE(),
            SUBMITTED_AT        = @SUBMITTED_AT
        WHERE AUDIT_ID = @AUDIT_ID;

        IF @@ROWCOUNT = 0
            THROW 50016, 'No rows updated. Audit record may not exist.', 1;

        -- ══════════════════════════════════════════════════
        -- 4. UPSERT DOCUMENT RESPONSES
        -- ══════════════════════════════════════════════════

        MERGE AUDIT_DOCUMENT_RESPONSE AS T
        USING (
            SELECT
                @AUDIT_ID   AS AUDIT_ID,
                ITEM_ID,
                IS_AVAILABLE,
                VALIDITY_DATE,
                UNIT_INFO,
                ATTACHMENTS,
                REMARKS
            FROM @DOCUMENT_RESPONSES
        ) AS S
        ON T.AUDIT_ID = S.AUDIT_ID AND T.ITEM_ID = S.ITEM_ID
        WHEN MATCHED THEN
            UPDATE SET
                IS_AVAILABLE  = S.IS_AVAILABLE,
                VALIDITY_DATE = S.VALIDITY_DATE,
                UNIT_INFO     = S.UNIT_INFO,
                ATTACHMENTS   = S.ATTACHMENTS,
                REMARKS       = S.REMARKS,
                UPDATED_BY    = @UPDATED_BY,
                UPDATED_ON    = GETUTCDATE()
        WHEN NOT MATCHED THEN
            INSERT (
                AUDIT_ID, ITEM_ID, IS_AVAILABLE, VALIDITY_DATE,
                UNIT_INFO, ATTACHMENTS, REMARKS,
                CREATED_BY, CREATED_ON, UPDATED_BY, UPDATED_ON)
            VALUES (
                S.AUDIT_ID, S.ITEM_ID, S.IS_AVAILABLE, S.VALIDITY_DATE,
                S.UNIT_INFO, S.ATTACHMENTS, S.REMARKS,
                @UPDATED_BY, GETUTCDATE(), @UPDATED_BY, GETUTCDATE());

        -- ══════════════════════════════════════════════════
        -- 5. UPSERT CHECKPOINT RESPONSES
        -- ══════════════════════════════════════════════════

        MERGE AUDIT_CHECK_POINT_RESPONSE AS T
        USING (
            SELECT
                @AUDIT_ID       AS AUDIT_ID,
                CHECK_POINT_ID,
                SCORE,
                REMARKS
            FROM @CHECKPOINT_RESPONSES
        ) AS S
        ON T.AUDIT_ID = S.AUDIT_ID AND T.CHECK_POINT_ID = S.CHECK_POINT_ID
        WHEN MATCHED THEN
            UPDATE SET
                SCORE      = S.SCORE,
                REMARKS    = S.REMARKS,
                UPDATED_BY = @UPDATED_BY,
                UPDATED_ON = GETUTCDATE()
        WHEN NOT MATCHED THEN
            INSERT (
                AUDIT_ID, CHECK_POINT_ID, SCORE, REMARKS,
                CREATED_BY, CREATED_ON, UPDATED_BY, UPDATED_ON)
            VALUES (
                S.AUDIT_ID, S.CHECK_POINT_ID, S.SCORE, S.REMARKS,
                @UPDATED_BY, GETUTCDATE(), @UPDATED_BY, GETUTCDATE());

        -- ══════════════════════════════════════════════════
        -- 6. REPLACE ELEMENT SCORES (delete + insert)
        -- ══════════════════════════════════════════════════

        -- Delete only elements present in TVP (selective replace)
        DELETE ES
        FROM AUDIT_ELEMENT_SCORE ES
        INNER JOIN @ELEMENT_SCORES TVP
               ON ES.ELEMENT_ID = TVP.ELEMENT_ID
        WHERE ES.AUDIT_ID = @AUDIT_ID;

        -- Insert fresh scores
        INSERT INTO AUDIT_ELEMENT_SCORE (
            AUDIT_ID,
            ELEMENT_ID,
            TOTAL_CHECK_POINTS,
            TOTAL_SCORE,
            ELEMENT_AVG_SCORE,
            FINAL_RATING,
            CREATED_BY,
            CREATED_ON,
            UPDATED_BY,
            UPDATED_ON)
        SELECT
            @AUDIT_ID,
            ELEMENT_ID,
            TOTAL_CHECK_POINTS,
            TOTAL_SCORE,
            ELEMENT_AVG_SCORE,
            FINAL_RATING,
            @UPDATED_BY,
            GETUTCDATE(),
            @UPDATED_BY,
            GETUTCDATE()
        FROM @ELEMENT_SCORES;

        -- ══════════════════════════════════════════════════
        -- 7. UPSERT ATTACHMENT RESPONSES
        -- ══════════════════════════════════════════════════

        MERGE AUDIT_ATTACHMENT_RESPONSE AS T
        USING (
            SELECT
                @AUDIT_ID   AS AUDIT_ID,
                ITEM_ID,
                ATTACHMENT,
                REMARKS
            FROM @ATTACHMENT_RESPONSES
        ) AS S
        ON T.AUDIT_ID = S.AUDIT_ID AND T.ITEM_ID = S.ITEM_ID
        WHEN MATCHED THEN
            UPDATE SET
                ATTACHMENT = S.ATTACHMENT,
                REMARKS    = S.REMARKS,
                UPDATED_BY = @UPDATED_BY,
                UPDATED_ON = GETUTCDATE()
        WHEN NOT MATCHED THEN
            INSERT (
                AUDIT_ID, ITEM_ID, ATTACHMENT, REMARKS,
                CREATED_BY, CREATED_ON, UPDATED_BY, UPDATED_ON)
            VALUES (
                S.AUDIT_ID, S.ITEM_ID, S.ATTACHMENT, S.REMARKS,
                @UPDATED_BY, GETUTCDATE(), @UPDATED_BY, GETUTCDATE());

        -- ══════════════════════════════════════════════════
        -- 8. INSERT ACTIVITY LOGS (append-only)
        -- ══════════════════════════════════════════════════

        INSERT INTO AUDIT_ACTIVITY_LOG (
            AUDIT_ID,
            ACTION,
            STEP_NO,
            PERFORMED_BY,
            PERFORMED_AT,
            NOTES)
        SELECT
            @AUDIT_ID,
            ACTION,
            STEP_NO,
            PERFORMED_BY,
            GETUTCDATE(),
            NOTES
        FROM @ACTIVITY_LOGS;

        -- ══════════════════════════════════════════════════
        -- ALL DONE — COMMIT
        -- ══════════════════════════════════════════════════
        COMMIT TRANSACTION;

    END TRY
    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @ERROR_MESSAGE  NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ERROR_SEVERITY INT            = ERROR_SEVERITY();
        DECLARE @ERROR_STATE    INT            = ERROR_STATE();

        RAISERROR(@ERROR_MESSAGE, @ERROR_SEVERITY, @ERROR_STATE);

    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_FACTORY_AUDIT_REQUEST_GETBYID]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_FACTORY_AUDIT_REQUEST_GETBYID]
    @AUDIT_REQ_ID       BIGINT,
    @INCLUDE_INACTIVE   BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    
	SELECT r.*,(Select TOP 1 AUDIT_ID from audit_Report where AUDIT_REQ_ID=@AUDIT_REQ_ID) AS AUDIT_ID
    FROM   [dbo].[FACTORY_AUDIT_REQUESTS] r
    WHERE  r.[AUDIT_REQ_ID] = @AUDIT_REQ_ID
      AND  (@INCLUDE_INACTIVE = 1 OR r.[IS_ACTIVE] = 1);

    /* Result set 2 – checklist rows */
    SELECT c.*
    FROM   [dbo].[FACTORY_AUDIT_REQUEST_CHECKLIST] c
    WHERE  c.[AUDIT_REQ_ID] = @AUDIT_REQ_ID
    ORDER BY c.[CHECKLIST_MST_ID];
END;


GO
/****** Object:  StoredProcedure [dbo].[SP_FACTORY_AUDIT_REQUEST_GETLIST]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_FACTORY_AUDIT_REQUEST_GETLIST]
    @BUSINESS_HEAD          INT             = NULL,
    @REQ_STATUS             VARCHAR(20)     = NULL,
    @GST_NUMBER             VARCHAR(15)     = NULL,
    @VENDOR_NAME            VARCHAR(250)    = NULL,
    @AUDIT_DATE_FROM        DATE            = NULL,
    @AUDIT_DATE_TO          DATE            = NULL,
    @IS_COMPLETE            BIT             = NULL,
    @PROMOTED_TO_MASTER     BIT             = NULL,
    @REQUESTED_BUYER_CODE   VARCHAR(150)    = NULL,
    @INCLUDE_INACTIVE       BIT             = 0,
    @PAGE_NUMBER            INT             = 1,
    @PAGE_SIZE              INT             = 20
AS
BEGIN
    SET NOCOUNT ON;

    -- -------------------------------------------------------------------------
    -- Normalize: treat empty string ('') the same as NULL for all varchar params
    -- so callers can pass either NULL or '' and both mean "no filter applied"
    -- -------------------------------------------------------------------------
    SET @REQ_STATUS           = NULLIF(LTRIM(RTRIM(@REQ_STATUS)),           '');
    SET @GST_NUMBER           = NULLIF(LTRIM(RTRIM(@GST_NUMBER)),           '');
    SET @VENDOR_NAME          = NULLIF(LTRIM(RTRIM(@VENDOR_NAME)),          '');
    SET @REQUESTED_BUYER_CODE = NULLIF(LTRIM(RTRIM(@REQUESTED_BUYER_CODE)), '');

    -- -------------------------------------------------------------------------
    -- Normalize paging defaults in case caller passes 0 or negative values
    -- -------------------------------------------------------------------------
    SET @PAGE_NUMBER = CASE WHEN ISNULL(@PAGE_NUMBER, 0) < 1 THEN 1    ELSE @PAGE_NUMBER END;
    SET @PAGE_SIZE   = CASE WHEN ISNULL(@PAGE_SIZE,   0) < 1 THEN 20   ELSE @PAGE_SIZE   END;

    DECLARE @Offset INT = (@PAGE_NUMBER - 1) * @PAGE_SIZE;

    SELECT
        r.*, H.HEAD, U.EMP_NAME ,
        COUNT(1) OVER ()                                        AS [TOTAL_RECORDS],
        (
            SELECT COUNT(1)
            FROM   [dbo].[FACTORY_AUDIT_REQUEST_CHECKLIST] c
            WHERE  c.[AUDIT_REQ_ID] = r.[AUDIT_REQ_ID]
        )                                                       AS [CHECKLIST_COUNT]
    FROM [dbo].[FACTORY_AUDIT_REQUESTS] r
	LEFT JOIN [dbo].[MASTER_BUSINESS_HEAD] H on r.BUSINESS_HEAD=H.ID
	LEFT JOIN [dbo].[USER_MASTER] U on r.CREATED_BY=U.ID
    WHERE
        -- Active / inactive filter
        (@INCLUDE_INACTIVE = 1          OR  r.[IS_ACTIVE]            = 1)

        -- Exact match filters
        AND (@BUSINESS_HEAD      IS NULL OR  r.[BUSINESS_HEAD]        = @BUSINESS_HEAD)
        AND (@REQ_STATUS         IS NULL OR  r.[REQ_STATUS]           = @REQ_STATUS)
        AND (@IS_COMPLETE        IS NULL OR  r.[IS_COMPLETE]          = @IS_COMPLETE)
        AND (@PROMOTED_TO_MASTER IS NULL OR  r.[PROMOTED_TO_MASTER]   = @PROMOTED_TO_MASTER)

        -- Partial match filters (safe: NULLIF above ensures param is NULL when blank)
        AND (@GST_NUMBER          IS NULL OR  r.[GST_NUMBER]          LIKE '%' + @GST_NUMBER          + '%')
        AND (@VENDOR_NAME         IS NULL OR  r.[VENDOR_NAME]         LIKE '%' + @VENDOR_NAME         + '%')
        AND (@REQUESTED_BUYER_CODE IS NULL OR r.[REQUESTED_BUYER_CODE] LIKE '%' + @REQUESTED_BUYER_CODE + '%')

        -- Date range filters
        AND (@AUDIT_DATE_FROM    IS NULL OR  r.[AUDIT_DATE]           >= @AUDIT_DATE_FROM)
        AND (@AUDIT_DATE_TO      IS NULL OR  r.[AUDIT_DATE]           <= @AUDIT_DATE_TO)

    ORDER BY r.[CREATED_ON] DESC
    OFFSET  @Offset ROWS
    FETCH NEXT @PAGE_SIZE ROWS ONLY;

END;
GO
/****** Object:  StoredProcedure [dbo].[SP_FACTORY_AUDIT_REQUEST_SAVE]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[SP_FACTORY_AUDIT_REQUEST_SAVE]
(
    /* ── Identity ─────────────────────────────────────────────────────── */
    @AUDIT_REQ_ID           BIGINT          OUTPUT,     -- 0 = INSERT, >0 = UPDATE
    @USER_ID                INT,                        -- created / updated by

    /* ── Header fields ─────────────────────────────────────────────────── */
    @TEMP_VENDOR_CODE       VARCHAR(20)     = NULL,
    @BUSINESS_HEAD          INT,
    @AUDIT_DATE             DATE,
    @GST_NUMBER             VARCHAR(15),
    @VENDOR_NAME            VARCHAR(250),
    @REGISTERED_ADDRESS     VARCHAR(1000),
    @FACTORY_LOCATION       VARCHAR(1000),
    @CONTACT_NAME           VARCHAR(150),
    @CONTACT_NUMBER         VARCHAR(50),
    @CATEGORY               VARCHAR(500),
    @REQUESTED_BUYER_CODE   VARCHAR(150),
    @PRODUCT_CATEGORY       VARCHAR(500),
    @FACTORY_LICENCE_NUMBER VARCHAR(50),
    @FACTORY_AREA_SQFT      DECIMAL(10,3)   = NULL,
    @NUMBER_OF_EMPLOYEES    INT             = NULL,
    @GEN_ATTACHMENT_FIRST   VARCHAR(MAX)    = NULL,
    @GST_API_RAW_RESPONSE   NVARCHAR(MAX)   = NULL,
    @IS_COMPLETE            BIT             = 0,

    /* ── Workflow fields (UPDATE only) ─────────────────────────────────── */
    @REQ_STATUS             VARCHAR(20)     = NULL,     -- pass only to change status
    @REJECTION_REASON       VARCHAR(500)    = NULL,
    @APPROVED_BY            INT             = NULL,

    /* ── Promote to master (UPDATE only) ───────────────────────────────── */
    @PROMOTE_TO_MASTER      BIT             = 0,
    @VENDOR_MASTER_ID       INT             = NULL,

    /* ── Checklist detail rows (TVP) ───────────────────────────────────── */
    @Checklist              [dbo].[TVP_ChecklistUpsert]  READONLY,

    /* ── Output ────────────────────────────────────────────────────────── */
    @RECORD_ID              BIGINT          = 0  OUTPUT,
    @ERROR_CODE             INT             = 0  OUTPUT,
    @ERROR_MESSAGE          VARCHAR(500)    = 'Success' OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    /* ── Working variables ─────────────────────────────────────────────── */
    DECLARE @Now            DATETIME = GETDATE(),
            @CurrentStatus  VARCHAR(20),
            @IsActive       BIT;

    BEGIN TRY

        /* ── Reset outputs ─────────────────────────────────────────────── */
        SET @ERROR_CODE    = 0;
        SET @ERROR_MESSAGE = 'Success';
        SET @RECORD_ID     = 0;


        /* A1. Mandatory header fields */
        IF LTRIM(RTRIM(ISNULL(@GST_NUMBER, ''))) = ''
            BEGIN
                RAISERROR('GST_NUMBER is required.', 16, 1);
                RETURN;
            END

        IF LTRIM(RTRIM(ISNULL(@VENDOR_NAME, ''))) = ''
            BEGIN
                RAISERROR('VENDOR_NAME is required.', 16, 1);
                RETURN;
            END

        /* A2. On UPDATE – verify record exists and is active */
        IF @AUDIT_REQ_ID > 0
            BEGIN
                SELECT  @CurrentStatus = [REQ_STATUS], @IsActive = [IS_ACTIVE] 
				FROM    [dbo].[FACTORY_AUDIT_REQUESTS]
                WHERE   [AUDIT_REQ_ID] = @AUDIT_REQ_ID;

                IF @CurrentStatus IS NULL
                    BEGIN
                        RAISERROR('Record not found. AUDIT_REQ_ID = %I64d.', 16, 1, @AUDIT_REQ_ID);
                        RETURN;
                    END

                IF @IsActive = 0
                    BEGIN
                        RAISERROR('Record is inactive and cannot be modified. AUDIT_REQ_ID = %I64d.', 16, 1, @AUDIT_REQ_ID);
                        RETURN;
                    END

                /* A3. Editing only allowed in DRAFT or REJECTED */
                IF @CurrentStatus NOT IN ('DRAFT', 'REJECTED') AND @REQ_STATUS IS NULL         -- pure field edit (not a workflow action)
                    BEGIN
                        RAISERROR('Record can only be edited in DRAFT or REJECTED status. Current status: %s.',16, 1, @CurrentStatus);
                        RETURN;
                    END
            END

        /* A4. Approve/Reject workflow rules */
        IF @REQ_STATUS = 'APPROVED'
            BEGIN
                IF @CurrentStatus <> 'SUBMITTED'
                    BEGIN
                        RAISERROR('Only SUBMITTED requests can be approved. Current status: %s.',16, 1, @CurrentStatus);
                        RETURN;
                    END

                IF @APPROVED_BY IS NULL
                    BEGIN
                        RAISERROR('APPROVED_BY is required when approving a request.', 16, 1);
                        RETURN;
                    END
            END

        IF @REQ_STATUS = 'REJECTED'
            BEGIN
                IF @CurrentStatus <> 'SUBMITTED'
                    BEGIN
                        RAISERROR('Only SUBMITTED requests can be rejected. Current status: %s.',6, 1, @CurrentStatus);
                        RETURN;
                    END

                IF LTRIM(RTRIM(ISNULL(@REJECTION_REASON, ''))) = ''
                    BEGIN
                        RAISERROR('REJECTION_REASON is required when rejecting a request.', 16, 1);
                        RETURN;
                    END
            END

        /* A5. Promote-to-master rules */
        IF @PROMOTE_TO_MASTER = 1
            BEGIN
                IF @CurrentStatus <> 'APPROVED'
                    BEGIN
                        RAISERROR('Only APPROVED requests can be promoted to master. Current status: %s.',16, 1, @CurrentStatus);
                        RETURN;
                    END

                IF @VENDOR_MASTER_ID IS NULL
                    BEGIN
                        RAISERROR('VENDOR_MASTER_ID is required when promoting to master.', 16, 1);
                        RETURN;
                    END

                IF EXISTS (SELECT 1 FROM [dbo].[FACTORY_AUDIT_REQUESTS]WHERE  [AUDIT_REQ_ID] = @AUDIT_REQ_ID AND [PROMOTED_TO_MASTER] = 1)
                    BEGIN
                        RAISERROR('Record has already been promoted to master.', 16, 1);
                        RETURN;
                    END
            END

        /* ==============================================================
           SECTION B – DML  (inside transaction)
           ============================================================== */

        BEGIN TRANSACTION;

        /* ──────────────────────────────────────────────────────────────
           B1.  INSERT header  (@AUDIT_REQ_ID = 0)
           ────────────────────────────────────────────────────────────── */
        IF @AUDIT_REQ_ID = 0
            BEGIN
				DECLARE @InspIdStr VARCHAR(20), @YearMonth CHAR(6) = FORMAT(GETDATE(), 'yyyyMM'), @NextNo INT;
				IF EXISTS (SELECT 1 FROM dbo.VENDOR_TEMP_CODE_TRACKER WHERE YEARMONTH = @YearMonth)
					BEGIN
						UPDATE dbo.VENDOR_TEMP_CODE_TRACKER	SET LASTNO = LASTNO + 1	WHERE YEARMONTH = @YearMonth;
						SELECT @NextNo = LASTNO	FROM dbo.DF_NUMBERTRACKER WHERE YEARMONTH = @YearMonth;
					END
				ELSE
					BEGIN
						INSERT INTO dbo.VENDOR_TEMP_CODE_TRACKER (YEARMONTH, LASTNO) VALUES (@YearMonth, 1);
						SET @NextNo = 1;
					END

				SET @TEMP_VENDOR_CODE =  'TVC' +@YearMonth + RIGHT('0000' + CAST(@NextNo AS VARCHAR), 4); 

                INSERT INTO [dbo].[FACTORY_AUDIT_REQUESTS]
                (
                    [TEMP_VENDOR_CODE], [BUSINESS_HEAD],   [AUDIT_DATE],
                    [GST_NUMBER],       [VENDOR_NAME],      [REGISTERED_ADDRESS],
                    [FACTORY_LOCATION], [CONTACT_NAME],     [CONTACT_NUMBER],
                    [CATEGORY],         [REQUESTED_BUYER_CODE], [PRODUCT_CATEGORY],
                    [FACTORY_LICENCE_NUMBER], [FACTORY_AREA_SQFT], [NUMBER_OF_EMPLOYEES],
                    [GEN_ATTACHMENT_FIRST],   [GST_API_RAW_RESPONSE],
                    [PROMOTED_TO_MASTER], [REQ_STATUS], [IS_COMPLETE], [IS_ACTIVE],
                    [CREATED_BY], [CREATED_ON]
                )
                VALUES
                (
                    @TEMP_VENDOR_CODE,  @BUSINESS_HEAD,     @AUDIT_DATE,
                    @GST_NUMBER,        @VENDOR_NAME,       @REGISTERED_ADDRESS,
                    @FACTORY_LOCATION,  @CONTACT_NAME,      @CONTACT_NUMBER,
                    @CATEGORY,          @REQUESTED_BUYER_CODE, @PRODUCT_CATEGORY,
                    @FACTORY_LICENCE_NUMBER, @FACTORY_AREA_SQFT, @NUMBER_OF_EMPLOYEES,
                    @GEN_ATTACHMENT_FIRST,   @GST_API_RAW_RESPONSE,
                    0, 'DRAFT', @IS_COMPLETE, 1,
                    @USER_ID, @Now
                );

                SET @AUDIT_REQ_ID = SCOPE_IDENTITY();
            END

        /* ──────────────────────────────────────────────────────────────
           B2.  UPDATE header  (@AUDIT_REQ_ID > 0)
           ────────────────────────────────────────────────────────────── */
        ELSE
            BEGIN
                UPDATE [dbo].[FACTORY_AUDIT_REQUESTS]
                SET
                    [BUSINESS_HEAD]          = ISNULL(@BUSINESS_HEAD,           [BUSINESS_HEAD]),
                    [AUDIT_DATE]             = ISNULL(@AUDIT_DATE,              [AUDIT_DATE]),
                    [GST_NUMBER]             = ISNULL(@GST_NUMBER,              [GST_NUMBER]),
                    [VENDOR_NAME]            = ISNULL(@VENDOR_NAME,             [VENDOR_NAME]),
                    [REGISTERED_ADDRESS]     = ISNULL(@REGISTERED_ADDRESS,      [REGISTERED_ADDRESS]),
                    [FACTORY_LOCATION]       = ISNULL(@FACTORY_LOCATION,        [FACTORY_LOCATION]),
                    [CONTACT_NAME]           = ISNULL(@CONTACT_NAME,            [CONTACT_NAME]),
                    [CONTACT_NUMBER]         = ISNULL(@CONTACT_NUMBER,          [CONTACT_NUMBER]),
                    [CATEGORY]               = ISNULL(@CATEGORY,                [CATEGORY]),
                    [REQUESTED_BUYER_CODE]   = ISNULL(@REQUESTED_BUYER_CODE,    [REQUESTED_BUYER_CODE]),
                    [PRODUCT_CATEGORY]       = ISNULL(@PRODUCT_CATEGORY,        [PRODUCT_CATEGORY]),
                    [FACTORY_LICENCE_NUMBER] = ISNULL(@FACTORY_LICENCE_NUMBER,  [FACTORY_LICENCE_NUMBER]),
                    [FACTORY_AREA_SQFT]      = ISNULL(@FACTORY_AREA_SQFT,       [FACTORY_AREA_SQFT]),
                    [NUMBER_OF_EMPLOYEES]    = ISNULL(@NUMBER_OF_EMPLOYEES,      [NUMBER_OF_EMPLOYEES]),
                    [GEN_ATTACHMENT_FIRST]   = ISNULL(@GEN_ATTACHMENT_FIRST,    [GEN_ATTACHMENT_FIRST]),
                    [GST_API_RAW_RESPONSE]   = ISNULL(@GST_API_RAW_RESPONSE,    [GST_API_RAW_RESPONSE]),
                    [IS_COMPLETE]            = ISNULL(@IS_COMPLETE,             [IS_COMPLETE]),
                    -- Workflow status change
                    [REQ_STATUS]             = ISNULL(@REQ_STATUS,              [REQ_STATUS]),
                    [REJECTION_REASON]       = CASE
                                                   WHEN @REQ_STATUS = 'APPROVED' THEN NULL          -- clear on approval
                                                   WHEN @REQ_STATUS = 'REJECTED' THEN @REJECTION_REASON
                                                   ELSE [REJECTION_REASON]
                                               END,
                    [APPROVED_BY]            = CASE WHEN @REQ_STATUS = 'APPROVED' THEN @APPROVED_BY  ELSE [APPROVED_BY]  END,
                    [APPROVED_ON]            = CASE WHEN @REQ_STATUS = 'APPROVED' THEN @Now           ELSE [APPROVED_ON]  END,
                    -- Promote to master
                    [PROMOTED_TO_MASTER]     = CASE WHEN @PROMOTE_TO_MASTER = 1 THEN 1               ELSE [PROMOTED_TO_MASTER] END,
                    [VENDOR_MASTER_ID]       = CASE WHEN @PROMOTE_TO_MASTER = 1 THEN @VENDOR_MASTER_ID ELSE [VENDOR_MASTER_ID] END,
                    [PROMOTED_BY]            = CASE WHEN @PROMOTE_TO_MASTER = 1 THEN @USER_ID         ELSE [PROMOTED_BY]    END,
                    [PROMOTED_ON]            = CASE WHEN @PROMOTE_TO_MASTER = 1 THEN @Now             ELSE [PROMOTED_ON]    END,
                    -- Audit
                    [UPDATED_BY]             = @USER_ID,
                    [UPDATED_ON]             = @Now
                WHERE [AUDIT_REQ_ID] = @AUDIT_REQ_ID;
            END

        /* ──────────────────────────────────────────────────────────────
           B3.  MERGE checklist detail  (TVP = desired state)
                • TVP row CHECKLIST_ID IS NULL  → INSERT
                • TVP row CHECKLIST_ID > 0      → UPDATE matched DB row
                • DB row not present in TVP     → DELETE
                Skipped entirely when TVP is empty.
           ────────────────────────────────────────────────────────────── */
        IF EXISTS (SELECT 1 FROM @Checklist)
            BEGIN
                MERGE [dbo].[FACTORY_AUDIT_REQUEST_CHECKLIST] AS Target
                USING
                (
                    SELECT
                        [CHECKLIST_ID],
                        [CHECKLIST_MST_ID],
                        [STATUS],
                        [VALIDITY_DATE],
                        [REMARKS],
						[ATTACHMENTS]
                    FROM @Checklist
                ) AS Source
                ON  Target.[CHECKLIST_ID]  = Source.[CHECKLIST_ID]
                AND Target.[AUDIT_REQ_ID]  = @AUDIT_REQ_ID

                /* ── UPDATE existing checklist row ── */
                WHEN MATCHED THEN
                    UPDATE SET
                        [CHECKLIST_MST_ID] = Source.[CHECKLIST_MST_ID],
                        [STATUS]           = Source.[STATUS],
                        [VALIDITY_DATE]    = Source.[VALIDITY_DATE],
                        [REMARKS]          = Source.[REMARKS],
						[ATTACHMENTS]	   = Source.[ATTACHMENTS],
                        [UPDATED_BY]       = @USER_ID,
                        [UPDATED_ON]       = @Now

                /* ── INSERT new checklist row (CHECKLIST_ID IS NULL in TVP) ── */
                WHEN NOT MATCHED BY TARGET THEN
                    INSERT
                    (
                        [AUDIT_REQ_ID], [CHECKLIST_MST_ID], [STATUS],
                        [VALIDITY_DATE], [REMARKS],[ATTACHMENTS],
                        [CREATED_BY],   [CREATED_ON]
                    )
                    VALUES
                    (
                        @AUDIT_REQ_ID,  Source.[CHECKLIST_MST_ID], Source.[STATUS],
                        Source.[VALIDITY_DATE], Source.[REMARKS],Source.[ATTACHMENTS],
                        @USER_ID, @Now
                    )

                /* ── DELETE checklist rows removed by the caller ── */
                WHEN NOT MATCHED BY SOURCE AND Target.[AUDIT_REQ_ID] = @AUDIT_REQ_ID THEN
                    DELETE;
            END

        /* ──────────────────────────────────────────────────────────────
           B4.  Set output and commit
           ────────────────────────────────────────────────────────────── */
        SET @RECORD_ID = @AUDIT_REQ_ID;

        COMMIT TRANSACTION;

    END TRY

    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @ERROR_CODE    = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH

END;
GO
/****** Object:  StoredProcedure [dbo].[SP_GET_INSPECTIONS_BY_IDS]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_GET_INSPECTIONS_BY_IDS]
(
    @INSP_IDS dbo.IdList READONLY
)
AS
BEGIN
	--DECLARE @IdCsv NVARCHAR(MAX), @SDATE DATETIME=GETDATE();
    SET NOCOUNT ON;
	 SELECT A.STATUS_CODE,A.INSP_ID,B.PO_NUMBER, A.POID,A.DATE_OF_INSPECTION,
	-- case when ISNULL(A.IS_DATE_ASSIGNED_BY_QA,0)=1 then A.QA_ASSIGNED_DOI else A.DATE_OF_INSPECTION end as QA_ASSIGNED_DOI,
	 A.QA_ASSIGNED_DOI,
	 A.ADDRESS_ID,A.INSPECTOR_EMP_CODE ,U.EMP_NAME ,ISNULL(A.IS_INSPECTOR_ASSIGNED,0) IS_INSPECTOR_ASSIGNED,
	 A.INSPECTION_NO,B.VENDOR_NAME, B.VENDOR_CODE, B.CATEGORY, B.BUYER_NAME, B.BUYER_ID,ISNULL(A.IS_DATE_ASSIGNED_BY_QA,0) IS_DATE_ASSIGNED_BY_QA,
	 C.ADDRESS_LINE1,C.CITY, C.PINCODE, C.EMAIL_IDS,C.MOBILE_NUMBERS,C.CONTACT_PERSON, A.REGION_ID, A.OFFERED_QTY,
	 CASE WHEN A.STATUS_CODE=7 THEN 1 ELSE 0 END AS IS_CHANGEABLE_BY_ADMIN,A.IS_QC_AT_DC
	 FROM INSPECTION_REQUESTS A
	 INNER JOIN POHEADER B ON A.POID =B.POID
	 INNER JOIN VENDOR_ADDRESS C on A.ADDRESS_ID = C.ADDRESS_ID
	 LEFT JOIN USER_MASTER U on A.INSPECTOR_EMP_CODE=U.EMP_CODE 
     INNER JOIN @INSP_IDS I ON A.INSP_ID = I.RECORD_ID;
	 
	
	 --SELECT @IdCsv = STRING_AGG(CAST(RECORD_ID AS NVARCHAR(20)), ',')
	 --WITHIN GROUP (ORDER BY RECORD_ID)
	 --FROM @INSP_IDS;

	 --INSERT INTO [dbo].[TESTDESHBOARDLIST]([START_TIME],[INSP_IDS],[OUTPUT_TIME],[EXECUTION_TIME_IN_MS])
  --   VALUES (@SDATE,@IdCsv ,GETDATE(),DATEDIFF(MILLISECOND, @SDATE, GETDATE()))


END;
