/****** Object:  StoredProcedure [dbo].[SP_INSERT_VENDOR_EXCEL_DATA]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Dinesh Baghel
-- Create date: 20 Jan 2026
-- Description:	Insert Vendor From Excel
-- =============================================
CREATE PROCEDURE [dbo].[SP_INSERT_VENDOR_EXCEL_DATA]
	@ID int = 0,
    @EXCEL_FILE VARCHAR(150),
	@NO_OF_RECORDS INT,
	@NO_INCORRECT_RECORDS INT,
    @INCORRECT_DETAILS VARCHAR(MAX),
	@VENDOR_DETAILS TVP_Excel_VendorsDtails READONLY, -- TABLE-TYPE PARAMETER 
	@ERRORS TVP_Excel_Errors READONLY, -- TABLE-TYPE PARAMETER 
	@USER_ID INT,
    @ERROR_CODE INT OUTPUT,             -- OUTPUT PARAMETER FOR ERROR CODE
    @ERROR_MESSAGE VARCHAR(500) OUTPUT -- OUTPUT PARAMETER FOR ERROR MESSAGE
AS
BEGIN
	BEGIN TRY
		BEGIN TRANSACTION;
		-- SET OUTPUT PARAMETERS FOR SUCCESS
		SET @ERROR_CODE = 0;
		SET @ERROR_MESSAGE = 'SUCCESS';
		
		INSERT INTO VENDOR_EXCELS (EXCEL_FILE, NO_OF_RECORDS, NO_INCORRECT_RECORDS, INCORRECT_DETAILS,CREATED_BY)
		VALUES ( @EXCEL_FILE, @NO_OF_RECORDS, @NO_INCORRECT_RECORDS, @INCORRECT_DETAILS,@USER_ID);
		
		SET @ID = SCOPE_IDENTITY();
		--TVP_Excel_Errors

		IF EXISTS (SELECT TOP 1 * FROM @ERRORS)
			BEGIN
				INSERT INTO VENDOR_EXCELS_UPLOAD_ERRORS (EXCELID, ROWNUMBER, VENDORCODE, ERRORMESSAGE,CREATED_BY)
				SELECT @ID, ROWNUMBER,VENDORCODE, ERRORMESSAGE, @USER_ID FROM @ERRORS 
			END

		IF EXISTS (SELECT TOP 1 * FROM @VENDOR_DETAILS)
			BEGIN
				MERGE VENODR_EXCEL_DETAILS AS Target
				USING ( SELECT VENDOR_CODE,EMAIL_IDS FROM @VENDOR_DETAILS ) AS Source
				ON Target.VENDOR_CODE = Source.VENDOR_CODE  

				WHEN MATCHED THEN
							UPDATE SET TARGET.EMAIL_IDS = SOURCE.EMAIL_IDS,
									   TARGET.EXCEL_ID = @ID,
									   TARGET.DATE_CREATED = GETDATE(),
									   TARGET.CM_STATUS = NULL,
									   TARGET.CM_USER_ID = NULL,
									   TARGET.CM_DATE = NULL
				WHEN NOT MATCHED BY TARGET THEN
					INSERT 
					(
						VENDOR_CODE, EMAIL_IDS, EXCEL_ID, CREATED_BY
					)
					VALUES
					(
						Source.VENDOR_CODE, Source.EMAIL_IDS, @ID, @USER_ID
					);
			END

		COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH;
END;


GO
/****** Object:  StoredProcedure [dbo].[SP_MASTER_COLOR_CODE_CRUD]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_MASTER_COLOR_CODE_CRUD]
(
    @ACTION            VARCHAR(20),
    @COLOR_CODE_ID     INT = NULL,
    @COLOR_CODE        VARCHAR(50) = NULL,
    @DESCRIPTION       VARCHAR(150) = NULL,
    @ACTIVE            BIT = NULL,
    @ORDER_NO          INT = NULL,

    @ERROR_CODE        INT = 0 OUTPUT,
    @ERROR_MESSAGE     VARCHAR(500) = 'Success' OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        /* =========================================
           INSERT / UPDATE
        ========================================= */
        IF(@ACTION = 'INSERT' OR @ACTION = 'UPDATE')
        BEGIN

            IF(ISNULL(@COLOR_CODE, '') = '')
            BEGIN
                RAISERROR('COLOR CODE is null or blank.', 16, 1);
            END

            BEGIN TRANSACTION;

                SET @ERROR_CODE = 0;
                SET @ERROR_MESSAGE = 'Saved Successfully';

                /* =========================
                   INSERT
                ========================= */
                IF(@ACTION = 'INSERT')
                BEGIN

                    IF EXISTS
                    (
                        SELECT 1
                        FROM MASTER_COLOR_CODE
                        WHERE COLOR_CODE_ID = @COLOR_CODE_ID
                    )
                    BEGIN
                        RAISERROR('COLOR CODE ID ALREADY EXISTS.', 16, 1);
                    END

					DECLARE @ID INT;
					SELECT @ID=MAX(COLOR_CODE_ID)+1 FROM MASTER_COLOR_CODE
					

                    INSERT INTO MASTER_COLOR_CODE
                    (
                        COLOR_CODE_ID,
                        COLOR_CODE,
                        DESCRIPTION,
                        ACTIVE,
                        ORDER_NO
                    )
                    VALUES
                    (
                        @ID,
                        @COLOR_CODE,
                        @DESCRIPTION,
                        @ACTIVE,
                        @ORDER_NO
                    );

                END

                /* =========================
                   UPDATE
                ========================= */
                ELSE IF(@ACTION = 'UPDATE')
                BEGIN

                    IF NOT EXISTS
                    (
                        SELECT 1
                        FROM MASTER_COLOR_CODE
                        WHERE COLOR_CODE_ID = @COLOR_CODE_ID
                    )
                    BEGIN
                        RAISERROR('COLOR CODE ID NOT FOUND.', 16, 1);
                    END

                    UPDATE MASTER_COLOR_CODE
                    SET
                        COLOR_CODE = @COLOR_CODE,
                        DESCRIPTION = @DESCRIPTION,
                        ACTIVE = @ACTIVE,
                        ORDER_NO = @ORDER_NO
                    WHERE COLOR_CODE_ID = @COLOR_CODE_ID;

                END

            COMMIT TRANSACTION;

        END

        /* =========================================
           GET BY ID
        ========================================= */
        ELSE IF(@ACTION = 'GETBYID')
        BEGIN

            IF(ISNULL(@COLOR_CODE_ID, 0) = 0)
            BEGIN
                RAISERROR('COLOR CODE ID is null or blank.', 16, 1);
            END

            SELECT
                COLOR_CODE_ID,
                COLOR_CODE,
                DESCRIPTION,
                ACTIVE,
                ORDER_NO
            FROM MASTER_COLOR_CODE
            WHERE COLOR_CODE_ID = @COLOR_CODE_ID;

        END

        /* =========================================
           GET ALL
        ========================================= */
        ELSE IF(@ACTION = 'GETALL')
        BEGIN

            SELECT
                COLOR_CODE_ID,
                COLOR_CODE,
                DESCRIPTION,
                ACTIVE,
                ORDER_NO
            FROM MASTER_COLOR_CODE
            ORDER BY ORDER_NO, COLOR_CODE;

        END

        /* =========================================
           INVALID ACTION
        ========================================= */
        ELSE
        BEGIN
            RAISERROR('INVALID ACTION.', 16, 1);
        END

    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();

    END CATCH

END
GO
/****** Object:  StoredProcedure [dbo].[SP_MASTER_HIERARCHY_CRUD]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_MASTER_HIERARCHY_CRUD]
(
      @ACTION               VARCHAR(20),

      @EMP_CODE             VARCHAR(50) = NULL,
      @EMP_NAME             VARCHAR(200)= NULL,
      @EMAIL_ID             VARCHAR(200)= NULL,
      @MOBILE_NO            VARCHAR(20) = NULL,
      @ROLE_ID              INT= NULL ,
      @REPORTING_EMP_ID     VARCHAR(50) = NULL,
      @IS_ACTIVE            BIT = 1,

	  @ERROR_CODE INT = 0 OUTPUT,             
      @ERROR_MESSAGE VARCHAR(500) = 'Success' OUTPUT
)
AS
BEGIN

    SET NOCOUNT ON;
	BEGIN TRY

	
		IF(@ACTION = 'INSERT' OR @ACTION = 'UPDATE')
			BEGIN
			
				IF (ISNULL(@EMP_CODE,'')='' OR ISNULL(@EMP_NAME,'')='' OR ISNULL(@EMAIL_ID,'')='')
					BEGIN
						RAISERROR('EMP CODE / EMP NAME / EMAIL ID is null or blank.', 16, 1);
					END
			
				BEGIN TRANSACTION;
					SET @ERROR_CODE = 0;
					SET @ERROR_MESSAGE = 'Saved Successfully';
				
					IF(@ACTION = 'INSERT')
						BEGIN
							INSERT INTO MASTER_HIERARCHY (EMP_CODE,EMP_NAME,EMAIL_ID, MOBILE_NO, ROLE_ID, REPORTING_EMP_ID,IS_ACTIVE )
							VALUES (@EMP_CODE,@EMP_NAME,@EMAIL_ID,@MOBILE_NO,@ROLE_ID,@REPORTING_EMP_ID,@IS_ACTIVE)
						END
					ELSE IF(@ACTION = 'UPDATE')
						BEGIN
							UPDATE MASTER_HIERARCHY
							SET
								EMP_NAME           = @EMP_NAME,
								EMAIL_ID           = @EMAIL_ID,
								MOBILE_NO          = @MOBILE_NO,
								ROLE_ID            = @ROLE_ID, 
								REPORTING_EMP_ID   = CASE WHEN @REPORTING_EMP_ID='' THEN NULL ELSE @REPORTING_EMP_ID  END,
								IS_ACTIVE          = @IS_ACTIVE,
								UPDATED_ON		   = GETDATE()
							WHERE EMP_CODE = @EMP_CODE
						END
					
				COMMIT TRANSACTION;
			END
		ELSE IF(@ACTION = 'GET' OR @ACTION = 'GET_ALONG_WITH_CHILD')
			BEGIN
				IF (ISNULL(@EMP_CODE,'')='')
					BEGIN
						RAISERROR('EMP CODE is null or blank.', 16, 1);
					END
			
				IF(@ACTION = 'GET')
					BEGIN
						SELECT
							E.EMP_CODE,E.EMP_NAME,E.EMAIL_ID,E.MOBILE_NO,E.ROLE_ID,R.ROLE_NAME,E.REPORTING_EMP_ID,RE.EMP_NAME AS REPORTING_MANAGER,E.IS_ACTIVE,E.CREATED_ON
						FROM MASTER_HIERARCHY E
						INNER JOIN [dbo].[ROLE_MASTER] R
							ON E.ROLE_ID = R.ID
						LEFT JOIN MASTER_HIERARCHY RE
							ON E.REPORTING_EMP_ID = RE.EMP_CODE
						WHERE E.EMP_CODE = @EMP_CODE
					END
				ELSE IF(@ACTION='GET_ALONG_WITH_CHILD')
					BEGIN
						;WITH EMP_HIERARCHY AS
						(
							SELECT
								EMP_CODE,EMP_NAME,EMAIL_ID,MOBILE_NO,ROLE_ID,REPORTING_EMP_ID,CAST('' AS VARCHAR(200)) AS REPORTING_MANAGER,IS_ACTIVE,0 AS HIERARCHY_LEVEL
							FROM MASTER_HIERARCHY
							WHERE EMP_CODE = @EMP_CODE
							UNION ALL
							SELECT
								E.EMP_CODE,E.EMP_NAME,E.EMAIL_ID,E.MOBILE_NO,E.ROLE_ID,E.REPORTING_EMP_ID,EH.EMP_NAME ,E.IS_ACTIVE,EH.HIERARCHY_LEVEL + 1 
							FROM MASTER_HIERARCHY E
							INNER JOIN EMP_HIERARCHY EH
								ON E.REPORTING_EMP_ID = EH.EMP_CODE
						)
		
						SELECT
							EH.EMP_CODE,EH.EMP_NAME,EH.EMAIL_ID,EH.MOBILE_NO,EH.ROLE_ID,R.ROLE_NAME,EH.REPORTING_EMP_ID,EH.REPORTING_MANAGER,EH.IS_ACTIVE,EH.HIERARCHY_LEVEL
						FROM EMP_HIERARCHY EH
						INNER JOIN ROLE_MASTER R
							ON EH.ROLE_ID = R.ID
						ORDER BY EH.HIERARCHY_LEVEL, EH.EMP_NAME
					END
			END
		ELSE IF(@ACTION = 'GETALL')
			BEGIN
				SELECT
					E.EMP_CODE,E.EMP_NAME,E.EMAIL_ID,E.MOBILE_NO,E.ROLE_ID,R.ROLE_NAME,E.REPORTING_EMP_ID,RE.EMP_NAME AS REPORTING_MANAGER,E.IS_ACTIVE,E.CREATED_ON
				FROM MASTER_HIERARCHY E
				INNER JOIN ROLE_MASTER R
					ON E.ROLE_ID = R.ID
				LEFT JOIN MASTER_HIERARCHY RE
					ON E.REPORTING_EMP_ID = RE.EMP_CODE
				ORDER BY E.EMP_NAME
			END
    END TRY
    BEGIN CATCH
		IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH
END

GO
/****** Object:  StoredProcedure [dbo].[SP_PO_OFFEREDQTY_UPDATE_DURING_INSPECTION]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


			--EXEC [dbo].[SP_MASTER_HIERARCHY_CRUD]     @ACTION = 'GET_ALONG_WITH_CHILD',     @EMP_CODE = @STRFIELD

CREATE PROCEDURE [dbo].[SP_PO_OFFEREDQTY_UPDATE_DURING_INSPECTION]
(
	@INSP_ID BIGINT ,
    @OFFERED_QTY DECIMAL(18,3) 
)
AS
BEGIN
    SET NOCOUNT ON;
	DECLARE @AvailableQty int, @avlqty Varchar(20), @PO_NUMBER varchar(100),@POID int, @TOTAL_QTY int, @IROFFEREDQTY INT, @QAOFFEREDQTY INT, @AVAILABLE_QTY INT;
	
    BEGIN TRY
        BEGIN TRANSACTION;
		IF(@OFFERED_QTY > 0)
			BEGIN
			SELECT @POID=POID, @PO_NUMBER= PO_NUMBER , @TOTAL_QTY= TOTAL_QTY FROM POHEADER WHERE POID=(SELECT POID FROM INSPECTION_REQUESTS WHERE INSP_ID=@INSP_ID)
			IF (@OFFERED_QTY > CEILING(@TOTAL_QTY * 1.10))
				BEGIN
					RAISERROR (
						'Offered quantity exceeds the allowed 10 percent additional limit of the total quantity.',
						16,
						1,
						 ''
					);
				END
		
			-----------------------------------------
			-- Validation Logic
			-- 1. Fetch all inspection requests for the same PO where inspection is not completed (STATUS_CODE <> 7), excluding the current inspection request.
			-- 2. Fetch only completed inspection requests (STATUS_CODE = 7) where the inspection result is PASS (INSPECTION_RESULT = 1).
			-- 3. Calculate Available Quantity = Total PO Quantity – Sum of Offered Quantities.
			-- 4. Validate that the current Offered Quantity does not exceed 110% of the Available Quantity.
			-----------------------------------------
			-- 1. Fetch all inspection requests for the same PO where inspection is not completed (STATUS_CODE <> 7), excluding the current inspection request.
			SELECT @IROFFEREDQTY= ISNULL(SUM(A.OFFERED_QTY),0) FROM INSPECTION_REQUESTS A 
			INNER JOIN POHEADER C on A.POID=C.POID 
			WHERE C.POID=@POID AND STATUS_CODE NOT IN (7,9,10) AND A.INSP_ID !=@INSP_ID

			-- 2. Fetch only completed inspection requests (STATUS_CODE = 7) where the inspection result is PASS (INSPECTION_RESULT = 1).
			-- 3. Calculate Available Quantity = Total PO Quantity – Sum of Offered Quantities.
			SELECT @AVAILABLE_QTY =
				(
					(CEILING(@TOTAL_QTY * 1.10)) - (@IROFFEREDQTY+ISNULL(SUM(B.OFFERED_QTY),0))
				)
			FROM INSPECTION_REQUESTS A 
			INNER JOIN INSPECTIONS B on A.INSP_ID=B.INSPECTION_ID 
			INNER JOIN POHEADER C on A.POID=C.POID 
			WHERE C.POID=@POID AND STATUS_CODE=7  AND B.INSPECTION_RESULT=1 AND A.INSP_ID !=@INSP_ID
	
			-- 4. Validate that the current Offered Quantity does not exceed 110% of the Available Quantity.
	   
			SET @avlqty= CAST(@AVAILABLE_QTY as VARCHAR(20))
			IF(@AVAILABLE_QTY >0 )
				BEGIN
					IF(@OFFERED_QTY > @AVAILABLE_QTY) -- Check the 10% logic here
						BEGIN
							RAISERROR (
								'Offered quantity exceeds the permitted 10 percent tolerance above the total quantity. Available quantity: %s.',
								16,
								1,
								@avlqty 
							);
						END
				END
			ELSE
				BEGIN
					RAISERROR (
								'Available quantity is insufficient. Current available quantity: %s.',
								16,
								1,
								@avlqty 
							);
				END
	   
			
			INSERT INTO [dbo].[IROFRQTYLOGICCHECK]([PONumber],[IRId],[OfferedQty],[TotalQty],[FirstCheck],[IROfferedQty],[QAOfferedQty],[AvailableQty],[AvgQty],[SecondCheck])
			VALUES (@PO_NUMBER, @INSP_ID, @OFFERED_QTY , @TOTAL_QTY, (IIF(@OFFERED_QTY > CEILING(@TOTAL_QTY * 1.10), 1, 0)) ,@IROFFEREDQTY, @QAOFFEREDQTY, @AVAILABLE_QTY, @avlqty,(IIF(@OFFERED_QTY > CEILING(@AVAILABLE_QTY * 1.10), 1, 0)));

			UPDATE INSPECTION_REQUESTS
			SET 
				OFFERED_QTY = @OFFERED_QTY
			WHERE INSP_ID = @INSP_ID;
				
		END
        COMMIT TRANSACTION;
		
    END TRY

    BEGIN CATCH
		IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_SAVE_INSPECTION]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author: Dinesh Baghel
-- Create date: 18 Dec 2025
-- Description:	INSPECT CURD
-- =============================================
CREATE PROCEDURE [dbo].[SP_SAVE_INSPECTION]
(
    @INSPECT_ID BIGINT = 0,              -- 0 = INSERT, >0 = UPDATE
    @INSPECTION_ID BIGINT,
    @INSPECTOR_CODE VARCHAR(50),
	@OFFERED_QTY INT=0,
	@SHIP_QTY INT=0,
    @GPT_NO VARCHAR(50),
    @GPT_STATUS INT,
    @GPT_APPROVED_BY VARCHAR(150) = NULL,
    @GPT_APPROVED_DATE DATE = NULL,

	@IS_RESET_BY_ADMIN BIT = 0,

    @NO_OF_BAGS_CARTONS_QTY INT,
    @NO_OF_BAGS_CARTONS_UNIT INT,
    @PACKING_STATUS INT = NULL,
    @INLINE_DONE INT,
    @PACKING_LIST INT,

    @PPS_RELEASE_DATE DATE = NULL,
    @PPS_EXPIRY_DATE DATE = NULL,

    @FIBER_CONTENT_ON_PO VARCHAR(250),
    @FIBER_CONTENT_ON_TEST_REPORT VARCHAR(250),
    @FIBER_CONTENT_ON_WC VARCHAR(250),

    @GSM_ON_PO VARCHAR(150),
    @GSM_ON_TEST_REPORT VARCHAR(150),
    @GSM_ON_BULK VARCHAR(150) = NULL,

    @MEASUREMENT_SAMPLE_SIZE INT,
    @MEASUREMENT_ATTACHMENT VARCHAR(150) = NULL,

    @NO_OF_CHECK INT,
    @NO_OF_CHECK_UNIT INT,
    @NO_OF_PREPACK_CHECK INT = NULL,

    @WORKMANSHIP VARCHAR(50) = NULL,
    @INSPECTION_RESULT INT,

    @REMARK_COMMENT VARCHAR(500) = NULL,
    @NOTE VARCHAR(500) = NULL,
    @NAME_OF_FACTORY_REPRESENTATIVE VARCHAR(150),

    @TEST_REPORT_ATTACHMENT VARCHAR(1000) = NULL,  
    @GEN_ATTACHMENT_FIRST VARCHAR(1000) = NULL,
    @GEN_ATTACHMENT_SECOND VARCHAR(150) = NULL,

    @IS_COMPLETE BIT,
    @USER_ID INT,

	@RESEAN_FOR_FAIL INT,
	@COLOR_CODE INT,
	@MFG_DATE DATE = NULL,
	@GPT_COMM_APPROVAL_DATE DATE = NULL,
	@DATE_OF_COMPLETION DATETIME = NULL,
	@SEASON VARCHAR(50) = NULL,
	@AREA_OF_FAIL_GPTR VARCHAR(50) = NULL,
	@GPT_COMM_APPROVED_BY VARCHAR(50) = NULL,
	@IS_EDIT_BY_ADMIN BIT,
	@GPT_ELASTIC_NO varchar(50)	,
    @GPT_ELASTIC_STATUS int,
    @GPT_ELASTIC_APPROVED_BY varchar(150),
    @GPT_ELASTIC_APPROVED_DATE date,
    @CONFORMITY_SIZE varchar(150),
    @CONFORMITY_SIZE_STATUS int,
    @CONFORMITY_PREPACK varchar(150),
    @CONFORMITY_PREPACK_STATUS int,
    @EMBROIDERY_PF int,
    @ACCESSORIES_PF int,
    @BARCODE_PF int,
    @NO_PLASTIC_PF int,
    @BOGO_PF int,
    @THREAD_YN int,
    @BUTTON_YN int,
    @ZIPPER_YN int,
    @INTERLINING_YN int,
    @ELASTIC_YN int,
    @MEASUREMENT_SAMPLE_QTY int,

	@ZIPPER_RPT_NO VARCHAR(500)= NULL,
	@ZIPPER_STATUS INT= NULL,
	@ZIPPER_APPROVED_BY VARCHAR(150)= NULL,
	@ZIPPER_APPROVED_DATE DATE= NULL,
	@FIT VARCHAR(150)= NULL,
	@COMM_APPROVAL_DOC VARCHAR(500)= NULL,
	@DEBIT_AMOUNT DECIMAL(12,2)= NULL,
	@ADMIN_REMARK VARCHAR(250)= NULL,
	@ABORTIVE_REASON_IDS VARCHAR(250)= NULL,
	@OTHER_ABORTIVE_REASON VARCHAR(MAX)=NULL,
	@AMT_TRAVELLING int,
	@SELECTED_BAG_CARTONS_NO VARCHAR(100),

    @DEFECTS DBO.TVP_INSPECTION_DEFECTS READONLY,

    -- OUTPUT PARAMETERS
	@OUT_INSPECT_ID BIGINT=0 OUTPUT,  
	@ERROR_CODE INT OUTPUT,             
    @ERROR_MESSAGE VARCHAR(500)  OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
		
		SET @OUT_INSPECT_ID = @INSPECT_ID;
		SET @ERROR_CODE = 0;
		SET @ERROR_MESSAGE = 'Success';

		        /* ===== REPLACES: from "DECLARE @PONUMBER ..." down to (not including) "BEGIN TRAN;" ===== */
 
        DECLARE @PONUMBER VARCHAR(30), @AQL_ID INT, @DEFECTS_STATUS INT, @AQL2_5_SAMPLE_SIZE INT,
                @DEFECTS_ALLOWED_MAJOR INT = 0, @DEFECTS_ALLOWED_MINOR INT = 0,
                @TOTAL_QTY DECIMAL(18,3), @POID INT, @IsAllreadyComplete BIT,
                @LAST_UPDATE_DATE_BY_ADMIN DATETIME = NULL;
 
        DECLARE @QA_EMP_CODE_IN_REQUEST VARCHAR(20), @EMP_CODE_IN_REPORT VARCHAR(20),
                @INSP_ID BIGINT = @INSPECTION_ID, @ROLEID INT;
 
        DECLARE @IROFFEREDQTY INT = 0, @PASSED_QTY INT = 0, @QAOFFEREDQTY INT, @CIROFFEREDQTY INT,
                @STORED_SHIP_QTY INT = NULL, @QTY_LIMIT INT = 0, @AVAILABLE_QTY INT = 0,
                @DO_QTY_CHECK BIT = 0;
 
        SELECT @ROLEID = ROLE_ID, @EMP_CODE_IN_REPORT = EMP_CODE
        FROM USER_MASTER WHERE ID = @USER_ID;
 
        SELECT @IsAllreadyComplete = IS_COMPLETE,
               @QA_EMP_CODE_IN_REQUEST = INSPECTOR_CODE,
               @STORED_SHIP_QTY = OFFERED_QTY
        FROM INSPECTIONS WHERE INSPECT_ID = @INSPECT_ID;
 
        SELECT @CIROFFEREDQTY = OFFERED_QTY, @POID = POID
        FROM INSPECTION_REQUESTS WHERE INSP_ID = @INSPECTION_ID;
 
        /* Admin reset only re-opens the report, so no data validation is needed (E4, E17) */
        IF (@IS_RESET_BY_ADMIN = 0)
        BEGIN
            IF (@SHIP_QTY < 1 AND @IS_COMPLETE = 1)
            BEGIN
                SET @ERROR_CODE = 50000;
                SET @ERROR_MESSAGE = 'Ship quantity is zero.';
                RETURN;
            END
 
            IF (@INSPECTION_RESULT = 4 AND @AMT_TRAVELLING = 0)
            BEGIN
                SET @ERROR_CODE = 50001;
                SET @ERROR_MESSAGE = 'Please enter the travelling amount.';
                RETURN;
            END
 
            IF (@IS_COMPLETE = 1 AND @ROLEID != 1008 AND @QA_EMP_CODE_IN_REQUEST = @EMP_CODE_IN_REPORT
                AND (@TEST_REPORT_ATTACHMENT IS NULL OR LTRIM(RTRIM(@TEST_REPORT_ATTACHMENT)) = ''))
            BEGIN
                SET @ERROR_CODE = 50002;
                SET @ERROR_MESSAGE = 'Attachment is required.';
                RETURN;
            END
 
            /* ---------- Quantity validation ---------- */
            SELECT @TOTAL_QTY = TOTAL_QTY, @PONUMBER = PO_NUMBER FROM POHEADER WHERE POID = @POID;
            SET @QTY_LIMIT = CEILING(ISNULL(@TOTAL_QTY, 0) * 1.10);
 
            -- Open requests of the same PO (not completed / cancelled / abortive), excluding this one
            SELECT @IROFFEREDQTY = ISNULL(SUM(OFFERED_QTY), 0)
            FROM INSPECTION_REQUESTS
            WHERE POID = @POID AND STATUS_CODE NOT IN (7, 9, 10) AND INSP_ID <> @INSP_ID;
 
            -- Ship quantity already PASSED on completed requests, excluding this one
            SELECT @PASSED_QTY = ISNULL(SUM(B.OFFERED_QTY), 0)
            FROM INSPECTION_REQUESTS A
            INNER JOIN INSPECTIONS B ON A.INSP_ID = B.INSPECTION_ID
            WHERE A.POID = @POID AND A.STATUS_CODE = 7 AND B.INSPECTION_RESULT = 1 AND A.INSP_ID <> @INSP_ID;
 
            SET @AVAILABLE_QTY = @QTY_LIMIT - (@IROFFEREDQTY + @PASSED_QTY);
            SET @QAOFFEREDQTY = @SHIP_QTY;
 
            -- Validate only when quantities are being changed, or on the first submission (E2, E4, E16, E17)
            IF (ISNULL(@STORED_SHIP_QTY, -1) <> @SHIP_QTY
                OR ISNULL(@CIROFFEREDQTY, -1) <> @OFFERED_QTY
                OR (@IS_COMPLETE = 1 AND ISNULL(@IsAllreadyComplete, 0) = 0))
                SET @DO_QTY_CHECK = 1;
 
            IF (@DO_QTY_CHECK = 1 AND (@SHIP_QTY > @AVAILABLE_QTY OR @OFFERED_QTY > @AVAILABLE_QTY))
            BEGIN
                SET @ERROR_CODE = 50001;
                SET @ERROR_MESSAGE =
                    CASE
                        WHEN @AVAILABLE_QTY <= 0 THEN
                            CONCAT('PO ', @PONUMBER, ' quantity is fully consumed. PO qty ', CAST(@TOTAL_QTY AS INT),
                                   ' (+10% = ', @QTY_LIMIT, '), already passed ', @PASSED_QTY,
                                   ', other open requests ', @IROFFEREDQTY, '.')
                        WHEN @SHIP_QTY > @AVAILABLE_QTY THEN
                            CONCAT('Ship quantity (', @SHIP_QTY, ') exceeds the available quantity (', @AVAILABLE_QTY,
                                   ') for PO ', @PONUMBER, '. PO qty ', CAST(@TOTAL_QTY AS INT), ' +10% = ', @QTY_LIMIT,
                                   ', already passed ', @PASSED_QTY, ', other open requests ', @IROFFEREDQTY, '.')
                        ELSE
                            CONCAT('Offered quantity (', @OFFERED_QTY, ') exceeds the available quantity (', @AVAILABLE_QTY,
                                   ') for PO ', @PONUMBER, '. PO qty ', CAST(@TOTAL_QTY AS INT), ' +10% = ', @QTY_LIMIT,
                                   ', already passed ', @PASSED_QTY, ', other open requests ', @IROFFEREDQTY, '.')
                    END;
                RETURN;
            END
 
            IF (@IS_COMPLETE = 1)
            BEGIN
                INSERT INTO [dbo].[IROFRQTYLOGICCHECK]
                    ([PONumber],[IRId],[InspId],[OfferedQty],[TotalQty],[FirstCheck],[IROfferedQty],[QAOfferedQty],[AvailableQty],[SecondCheck])
                VALUES
                    (@PONUMBER, @INSP_ID, @INSPECT_ID, @CIROFFEREDQTY, @TOTAL_QTY,
                     IIF(@SHIP_QTY > CEILING(@TOTAL_QTY * 1.10), 1, 0),
                     @IROFFEREDQTY, @QAOFFEREDQTY, @AVAILABLE_QTY,
                     IIF(@SHIP_QTY > CEILING(@AVAILABLE_QTY * 1.10), 1, 0));
            END
 
            /* ---------- AQL, PPS and defects (unchanged) ---------- */
            SELECT @AQL_ID = AQL_ID, @AQL2_5_SAMPLE_SIZE = SAMPLE_SIZE,
                   @DEFECTS_ALLOWED_MAJOR = AQL_2_5_MAJOR, @DEFECTS_ALLOWED_MINOR = AQL_2_5_MINOR
            FROM [dbo].[MASTER_AQL]
            WHERE @SHIP_QTY BETWEEN BATCH_SIZE_MIN AND BATCH_SIZE_MAX;
 
            IF @PPS_RELEASE_DATE IS NOT NULL AND @PPS_EXPIRY_DATE IS NOT NULL
               AND @PPS_EXPIRY_DATE < DATEADD(DAY, -1, DATEADD(MONTH, 6, @PPS_RELEASE_DATE))
            BEGIN
                SET @ERROR_CODE = 50001;
                SET @ERROR_MESSAGE = 'PPS Expiry Date must be 6 months greater than Release Date';
                RETURN;
            END
 
            IF (SELECT SUM(ISNULL(MAJOR, 0)) FROM @DEFECTS) > @DEFECTS_ALLOWED_MAJOR
               OR (SELECT SUM(ISNULL(MINOR, 0)) FROM @DEFECTS) > @DEFECTS_ALLOWED_MINOR
                SET @DEFECTS_STATUS = 2;
            ELSE
                SET @DEFECTS_STATUS = 1;
 
            IF @INSPECTION_RESULT = 2 AND NOT EXISTS (SELECT 1 FROM @DEFECTS)
            BEGIN
                SET @ERROR_CODE = 50003;
                SET @ERROR_MESSAGE = 'Defects are mandatory when inspection result is FAIL';
                RETURN;
            END
        END
 
        /* ===== END OF REPLACED BLOCK - "BEGIN TRAN;" follows unchanged ===== */



        BEGIN TRAN;

		IF(@IS_RESET_BY_ADMIN=1)
			BEGIN
				UPDATE dbo.INSPECTIONS SET DATE_OF_COMPLETION=NULL,IS_COMPLETE = 0, TEST_REPORT_ATTACHMENT = NULL, LAST_UPDATE_DATE_BY_ADMIN=NULL, GEN_ATTACHMENT_FIRST = NULL, MODIFIED_DATE = GETDATE(),MODIFIED_BY = @USER_ID WHERE INSPECT_ID = @INSPECT_ID;
				UPDATE INSPECTION_REQUESTS	SET STATUS_CODE=8, LAST_UPDATED_ON = GETDATE(), UPDATED_BY = @USER_ID WHERE INSP_ID = @INSPECTION_ID;
			END
		ELSE
			BEGIN

				 /* NEW position: the IR offered quantity is now updated INSIDE the transaction,
                   so it rolls back if any later step fails (N12) */
                IF (@OFFERED_QTY <> @CIROFFEREDQTY)
                BEGIN
                    UPDATE INSPECTION_REQUESTS  SET OFFERED_QTY = @OFFERED_QTY, LAST_UPDATED_ON = GETDATE(), UPDATED_BY = @USER_ID WHERE INSP_ID = @INSPECTION_ID;
                END
				/* =============================
				    INSERT / UPDATE INSPECTION
				 ==============================*/
				IF ISNULL(@INSPECT_ID, 0) = 0
					BEGIN
						INSERT INTO dbo.INSPECTIONS
						(
						    INSPECTION_ID, INSPECTOR_CODE,OFFERED_QTY,AQL_ID, GPT_NO, GPT_STATUS,
						    GPT_APPROVED_BY, GPT_APPROVED_DATE,
						    NO_OF_BAGS_CARTONS_QTY, NO_OF_BAGS_CARTONS_UNIT,
						    PACKING_STATUS, INLINE_DONE, PACKING_LIST,
						    PPS_RELEASE_DATE, PPS_EXPIRY_DATE,
						    FIBER_CONTENT_ON_PO, FIBER_CONTENT_ON_TEST_REPORT, FIBER_CONTENT_ON_WC,
						    GSM_ON_PO, GSM_ON_TEST_REPORT, GSM_ON_BULK,
						    MEASUREMENT_SAMPLE_SIZE, MEASUREMENT_ATTACHMENT,
						    NO_OF_CHECK, NO_OF_CHECK_UNIT, NO_OF_PREPACK_CHECK,
						    WORKMANSHIP, DEFECTS_STATUS, INSPECTION_RESULT,
						    REMARK_COMMENT, NOTE, NAME_OF_FACTORY_REPRESENTATIVE,
						    TEST_REPORT_ATTACHMENT, GEN_ATTACHMENT_FIRST, GEN_ATTACHMENT_SECOND,
						    IS_COMPLETE, CREATED_BY, RESEAN_FOR_FAIL, COLOR_CODE, MFG_DATE, GPT_COMM_APPROVAL_DATE, 
							DATE_OF_COMPLETION, SEASON, AREA_OF_FAIL_GPTR, GPT_COMM_APPROVED_BY, IS_EDIT_BY_ADMIN,
							GPT_ELASTIC_NO,GPT_ELASTIC_STATUS,GPT_ELASTIC_APPROVED_BY,GPT_ELASTIC_APPROVED_DATE,CONFORMITY_SIZE,
							CONFORMITY_SIZE_STATUS,CONFORMITY_PREPACK,CONFORMITY_PREPACK_STATUS,EMBROIDERY_PF,ACCESSORIES_PF,
							BARCODE_PF,NO_PLASTIC_PF,BOGO_PF,THREAD_YN,BUTTON_YN,ZIPPER_YN,INTERLINING_YN,ELASTIC_YN,MEASUREMENT_SAMPLE_QTY,
							ZIPPER_RPT_NO,ZIPPER_STATUS,ZIPPER_APPROVED_BY,	ZIPPER_APPROVED_DATE,FIT,COMM_APPROVAL_DOC,DEBIT_AMOUNT,ADMIN_REMARK,
							ABORTIVE_REASON_IDS,OTHER_ABORTIVE_REASON, AMT_TRAVELLING, SELECTED_BAG_CARTONS_NO
						)
						VALUES
						(
						    @INSPECTION_ID, @INSPECTOR_CODE,@SHIP_QTY,@AQL_ID, @GPT_NO, @GPT_STATUS,
						    @GPT_APPROVED_BY, @GPT_APPROVED_DATE,
						    @NO_OF_BAGS_CARTONS_QTY, @NO_OF_BAGS_CARTONS_UNIT,
						    @PACKING_STATUS, @INLINE_DONE, @PACKING_LIST,
						    @PPS_RELEASE_DATE, @PPS_EXPIRY_DATE,
						    @FIBER_CONTENT_ON_PO, @FIBER_CONTENT_ON_TEST_REPORT, @FIBER_CONTENT_ON_WC,
						    @GSM_ON_PO, @GSM_ON_TEST_REPORT, @GSM_ON_BULK,
						    @MEASUREMENT_SAMPLE_SIZE, @MEASUREMENT_ATTACHMENT,
						    @NO_OF_CHECK, @NO_OF_CHECK_UNIT, @NO_OF_PREPACK_CHECK,
						    @WORKMANSHIP, @DEFECTS_STATUS, @INSPECTION_RESULT,
						    @REMARK_COMMENT, @NOTE, @NAME_OF_FACTORY_REPRESENTATIVE,
						    @TEST_REPORT_ATTACHMENT, @GEN_ATTACHMENT_FIRST, @GEN_ATTACHMENT_SECOND,
						    @IS_COMPLETE, @USER_ID,@RESEAN_FOR_FAIL, @COLOR_CODE, @MFG_DATE, @GPT_COMM_APPROVAL_DATE, 
							@DATE_OF_COMPLETION, @SEASON, @AREA_OF_FAIL_GPTR, @GPT_COMM_APPROVED_BY, @IS_EDIT_BY_ADMIN,
							@GPT_ELASTIC_NO,@GPT_ELASTIC_STATUS,@GPT_ELASTIC_APPROVED_BY,@GPT_ELASTIC_APPROVED_DATE,@CONFORMITY_SIZE,
							@CONFORMITY_SIZE_STATUS,@CONFORMITY_PREPACK,@CONFORMITY_PREPACK_STATUS,@EMBROIDERY_PF,@ACCESSORIES_PF,
							@BARCODE_PF,@NO_PLASTIC_PF,@BOGO_PF,@THREAD_YN,@BUTTON_YN,@ZIPPER_YN,@INTERLINING_YN,@ELASTIC_YN,@MEASUREMENT_SAMPLE_QTY,
							@ZIPPER_RPT_NO,@ZIPPER_STATUS,@ZIPPER_APPROVED_BY,@ZIPPER_APPROVED_DATE,@FIT,@COMM_APPROVAL_DOC,@DEBIT_AMOUNT,@ADMIN_REMARK,
							@ABORTIVE_REASON_IDS,@OTHER_ABORTIVE_REASON, @AMT_TRAVELLING,@SELECTED_BAG_CARTONS_NO
						);
						
						SET @OUT_INSPECT_ID = SCOPE_IDENTITY();
					END
				-- =======================
				-- UPDATE
				-- =======================
				ELSE
					BEGIN

					   -- Is this an admin/supervisor editing someone else's (a child's) record?
					   IF((@ROLEID=1008 OR @ROLEID=1007) AND (@QA_EMP_CODE_IN_REQUEST != @EMP_CODE_IN_REPORT))
					        BEGIN
					            SET @IS_EDIT_BY_ADMIN = 1;
								SET @LAST_UPDATE_DATE_BY_ADMIN = GETDATE();
					        END
					   ELSE
					        BEGIN
					            SET @IS_EDIT_BY_ADMIN = 0
					        END
					   
					   IF (@IsAllreadyComplete = 0)
					      OR (@IsAllreadyComplete = 1 AND @ROLEID = 1008)
					      OR (@IsAllreadyComplete = 1 AND @ROLEID = 1007 AND @QA_EMP_CODE_IN_REQUEST != @EMP_CODE_IN_REPORT)
					        BEGIN
					   
					            IF (@IsAllreadyComplete = 0)
					                BEGIN
					                    INSERT INTO TESTAUTOSAVE (USERID, INSPECITON_ID, IS_COMPLETE, DATEOFCOMPLETION, TESTVALUES)
					                    VALUES (@USER_ID,@INSPECT_ID, @IS_COMPLETE, @DATE_OF_COMPLETION, 'F-:'+@TEST_REPORT_ATTACHMENT+' :-|-: S-:'+@GEN_ATTACHMENT_FIRST);
					                END
					   
					            UPDATE dbo.INSPECTIONS
					            SET
					                AQL_ID=@AQL_ID,
					                OFFERED_QTY= @SHIP_QTY,
					                GPT_NO=@GPT_NO,
					                GPT_STATUS = @GPT_STATUS,
					                GPT_APPROVED_BY = @GPT_APPROVED_BY,
					                GPT_APPROVED_DATE = @GPT_APPROVED_DATE,
					                NO_OF_BAGS_CARTONS_QTY=@NO_OF_BAGS_CARTONS_QTY,
					                NO_OF_BAGS_CARTONS_UNIT=@NO_OF_BAGS_CARTONS_UNIT,
					                PACKING_STATUS = @PACKING_STATUS,
					                INLINE_DONE = @INLINE_DONE,
					                PACKING_LIST = @PACKING_LIST,
					                PPS_RELEASE_DATE = @PPS_RELEASE_DATE,
					                PPS_EXPIRY_DATE = @PPS_EXPIRY_DATE,
					                FIBER_CONTENT_ON_PO=@FIBER_CONTENT_ON_PO,
					                FIBER_CONTENT_ON_TEST_REPORT=@FIBER_CONTENT_ON_TEST_REPORT,
					                FIBER_CONTENT_ON_WC=@FIBER_CONTENT_ON_WC,
					                GSM_ON_PO=@GSM_ON_PO,
					                GSM_ON_TEST_REPORT=@GSM_ON_TEST_REPORT,
					                GSM_ON_BULK=@GSM_ON_BULK,
					                MEASUREMENT_SAMPLE_SIZE=@MEASUREMENT_SAMPLE_SIZE,
					                MEASUREMENT_ATTACHMENT=@MEASUREMENT_ATTACHMENT,
					                NO_OF_CHECK=@NO_OF_CHECK,
					                NO_OF_CHECK_UNIT=@NO_OF_CHECK_UNIT,
					                NO_OF_PREPACK_CHECK=@NO_OF_PREPACK_CHECK,
					                WORKMANSHIP=@WORKMANSHIP,
					                DEFECTS_STATUS = @DEFECTS_STATUS,
					                INSPECTION_RESULT = @INSPECTION_RESULT,
					                REMARK_COMMENT = @REMARK_COMMENT,
					                NOTE = @NOTE,
					                NAME_OF_FACTORY_REPRESENTATIVE=@NAME_OF_FACTORY_REPRESENTATIVE,
					                TEST_REPORT_ATTACHMENT=@TEST_REPORT_ATTACHMENT,
					                GEN_ATTACHMENT_FIRST=@GEN_ATTACHMENT_FIRST,
					                GEN_ATTACHMENT_SECOND=@GEN_ATTACHMENT_SECOND,
					                IS_COMPLETE = @IS_COMPLETE,
					                MODIFIED_BY = @USER_ID,
					                MODIFIED_DATE = GETDATE(),
					                RESEAN_FOR_FAIL=@RESEAN_FOR_FAIL,
					                COLOR_CODE=@COLOR_CODE,
					                MFG_DATE=@MFG_DATE,
					                GPT_COMM_APPROVAL_DATE=@GPT_COMM_APPROVAL_DATE,
					                DATE_OF_COMPLETION=@DATE_OF_COMPLETION,
					                SEASON=@SEASON,
					                AREA_OF_FAIL_GPTR=@AREA_OF_FAIL_GPTR,
					                GPT_COMM_APPROVED_BY=@GPT_COMM_APPROVED_BY,
					                IS_EDIT_BY_ADMIN=@IS_EDIT_BY_ADMIN,
									LAST_UPDATE_DATE_BY_ADMIN=@LAST_UPDATE_DATE_BY_ADMIN,
					   
					                GPT_ELASTIC_NO=@GPT_ELASTIC_NO,
					                GPT_ELASTIC_STATUS=@GPT_ELASTIC_STATUS,
					                GPT_ELASTIC_APPROVED_BY=@GPT_ELASTIC_APPROVED_BY,
					                GPT_ELASTIC_APPROVED_DATE=@GPT_ELASTIC_APPROVED_DATE,
					                CONFORMITY_SIZE=@CONFORMITY_SIZE,
					                CONFORMITY_SIZE_STATUS=@CONFORMITY_SIZE_STATUS,
					                CONFORMITY_PREPACK=@CONFORMITY_PREPACK,
					                CONFORMITY_PREPACK_STATUS=@CONFORMITY_PREPACK_STATUS,
					                EMBROIDERY_PF=@EMBROIDERY_PF,
					                ACCESSORIES_PF=@ACCESSORIES_PF,
					                BARCODE_PF=@BARCODE_PF,
					                NO_PLASTIC_PF=@NO_PLASTIC_PF,
					                BOGO_PF=@BOGO_PF,
					                THREAD_YN=@THREAD_YN,
					                BUTTON_YN=@BUTTON_YN,
					                ZIPPER_YN=@ZIPPER_YN,
					                INTERLINING_YN=@INTERLINING_YN,
					                ELASTIC_YN=@ELASTIC_YN,
					                MEASUREMENT_SAMPLE_QTY=@MEASUREMENT_SAMPLE_QTY,
					   
					                ZIPPER_RPT_NO=@ZIPPER_RPT_NO,
					                ZIPPER_STATUS=@ZIPPER_STATUS,
					                ZIPPER_APPROVED_BY=@ZIPPER_APPROVED_BY,
					                ZIPPER_APPROVED_DATE=@ZIPPER_APPROVED_DATE,
					                FIT=@FIT,
					                COMM_APPROVAL_DOC=@COMM_APPROVAL_DOC,
					                DEBIT_AMOUNT=@DEBIT_AMOUNT,
					                ADMIN_REMARK=@ADMIN_REMARK,
					                ABORTIVE_REASON_IDS=@ABORTIVE_REASON_IDS,
					                OTHER_ABORTIVE_REASON=@OTHER_ABORTIVE_REASON,
					                AMT_TRAVELLING=@AMT_TRAVELLING,
					                SELECTED_BAG_CARTONS_NO=@SELECTED_BAG_CARTONS_NO
					            WHERE INSPECT_ID = @INSPECT_ID;
					   
					            SET @OUT_INSPECT_ID = @INSPECT_ID;
					        END
					   ELSE
					        BEGIN
					            -- No permission: record is complete and caller is neither
					            -- 1008 admin nor a 1007 supervisor editing a child's record.
					            IF @@TRANCOUNT > 0
					                ROLLBACK TRAN;
					   
					            SET @ERROR_CODE = 50004;
					            SET @ERROR_MESSAGE = 'Inspection is already complete. Only Admin (1008) or a Supervisor (1007) editing a child inspector''s record can modify it.';
					            RETURN;
					        END
					END

				 /* =============================
				    MERGE DEFECTS
				 ==============================*/
				 MERGE dbo.INSPECTION_DEFECTS AS T
				 USING @DEFECTS AS S
				 ON T.DEFECTS_ID = S.DEFECTS_ID  AND T.INSPECTION_ID = @INSPECTION_ID
				 
				 WHEN MATCHED THEN
				     UPDATE SET
				         T.DEFECTS = S.DEFECTS,
				         T.DIMENSION = S.DIMENSION,
				         T.MAJOR = S.MAJOR,
				         T.MINOR = S.MINOR,
				         T.MODIFIED_BY = @USER_ID,
				         T.MODIFIED_DATE = GETDATE()
				 
				 WHEN NOT MATCHED BY TARGET THEN
				     INSERT
				     (
				         INSPECTION_ID, DEFECTS, DIMENSION,
				         MAJOR, MINOR, CREATED_BY, CREATED_DATE
				     )
				     VALUES
				     (
				         @INSPECTION_ID, S.DEFECTS, S.DIMENSION,
				         S.MAJOR, S.MINOR, @USER_ID, GETDATE()
				     )
				 
				 WHEN NOT MATCHED BY SOURCE  AND T.INSPECTION_ID = @INSPECTION_ID
				 THEN DELETE;
				 
				 IF( @IS_COMPLETE =1)
				 BEGIN
				 	IF( @INSPECTION_RESULT=4)
				 		BEGIN
				 			UPDATE INSPECTION_REQUESTS	SET STATUS_CODE=10, LAST_UPDATED_ON = GETDATE(), UPDATED_BY = @USER_ID WHERE INSP_ID = @INSPECTION_ID;
				 		END
				 	ELSE
				 		BEGIN
				 			UPDATE INSPECTION_REQUESTS	SET STATUS_CODE=7, LAST_UPDATED_ON = GETDATE(), UPDATED_BY = @USER_ID WHERE INSP_ID = @INSPECTION_ID;
				 		END
				 END
			END
        COMMIT TRAN;

        SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Inspection saved successfully';
    END TRY
    BEGIN CATCH
	IF @@TRANCOUNT>0
        ROLLBACK TRAN;

        SET @ERROR_CODE = 1;
        SET @ERROR_MESSAGE = ERROR_MESSAGE();

    END CATCH
END



SET QUOTED_IDENTIFIER ON
GO
/****** Object:  StoredProcedure [dbo].[SP_SAVE_PO]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_SAVE_PO]
(
    @POID INT OUTPUT,                    -- if 0 -> INSERT, else UPDATE
    @PO_NUMBER VARCHAR(30),
    @VENDOR_CODE VARCHAR(30),
    @VENDOR_NAME VARCHAR(100),
    @FABRIC VARCHAR(255),
    @COLOR VARCHAR(100),
    @TOTAL_QTY DECIMAL(18,3),
	@APPARELS VARCHAR(50)= NULL,
	@CATEGORY VARCHAR(50)= NULL,
	@BUYER_NAME VARCHAR(50)= NULL,
	@MC VARCHAR(50)= NULL,
	@MC_TEXT VARCHAR(250)= NULL,
	@MRP DECIMAL(18,3)=NULL,
	@BUYER_ID VARCHAR(20)= NULL,
	@BRAND_ID VARCHAR(250)= NULL,
	@BRAND_ID2 VARCHAR(250)= NULL,
	@FIT VARCHAR(250)= NULL,
    @USER_ID INT,                        -- created/updated by
    @IS_CANCELLED BIT = 0,  
    -- Inspection Request (optional)
	@INSP_ID BIGINT = NULL,
    @INSPECTION_DATE DATETIME = NULL,
    @OFFERED_QTY DECIMAL(18,3) = NULL,
    @ADDRESS_ID INT = NULL,
	@REGION_ID INT= NULL,

	@INSPECTION_TYPE_ID INT= NULL,
	
	@IS_QC_AT_DC BIT = 0,
    -- TABLE TYPE
    @DETAILS TVP_PODETAIL READONLY,
	@RECORD_ID INT OUTPUT,  
	@ERROR_CODE INT = 0 OUTPUT,             
    @ERROR_MESSAGE VARCHAR(500) = 'Success' OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
	DECLARE @AvailableQty int,
	@avlqty Varchar(20),
    @Now DATETIME,
    @MinAllowedDT DATETIME,
	@InitialTarget DATETIME,
    @SundayCount INT;
	
    BEGIN TRY
		SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Success';
		SET @RECORD_ID = 0;
        BEGIN TRANSACTION;

		IF(@IS_CANCELLED=1)
		BEGIN
			UPDATE INSPECTION_REQUESTS						
			SET 							
				LAST_UPDATED_ON = GETDATE(),
				UPDATED_BY = @USER_ID,
				STATUS_CODE= case when @IS_CANCELLED = 1 then 9 else 2 end
			WHERE INSP_ID = @INSP_ID;
			SET @RECORD_ID = @INSP_ID;
		END
		ELSE
		BEGIN

		-- FIX 1: NULL means "new". Treat NULL as 0 so every "= 0" and "!= @INSP_ID" check below works
		-- (with NULL, "!=" is never true, so the quantity sums ignored every row and the checks were skipped).
		SET @INSP_ID = ISNULL(@INSP_ID, 0);
		SET @POID    = ISNULL(@POID, 0);

		-- CHANGE 1: existing PO -> validate against the quantity stored in QPS (last SAP sync),
		-- never the value sent by the screen (E5, N10).
		IF (@POID > 0)
		BEGIN
			SELECT @TOTAL_QTY = TOTAL_QTY FROM POHEADER WHERE POID = @POID;

			-- FIX 4: an unknown POID must not fall back to the screen's quantity.
			IF (@@ROWCOUNT = 0)
			BEGIN
				RAISERROR('PO %s (POID %d) was not found in QPS. Refresh the PO from SAP and try again.', 16, 1, @PO_NUMBER, @POID);
			END
		END

		IF(@INSP_ID=0)
		BEGIN
			IF EXISTS (SELECT 1 FROM INSPECTION_REQUESTS WHERE POID = @POID AND STATUS_CODE NOT IN (7,9,10))
			BEGIN
				-- FIX 2: no RETURN after RAISERROR (severity 16 inside TRY jumps straight to CATCH).
				RAISERROR('Last Inspection request is under process. PO: %s', 16, 1,@PO_NUMBER);
		   
			END
		END
		
		IF(@IS_QC_AT_DC=0)
			BEGIN
				IF(@INSP_ID=0)
					BEGIN
						SET @Now  = GETDATE();
					END
				ELSE
					BEGIN
						SELECT @Now = CREATED_ON FROM INSPECTION_REQUESTS WHERE INSP_ID = @INSP_ID;
					END
					-- Initial 48-hour target
				SET @InitialTarget  = DATEADD(HOUR, 48, @Now);

				-- Count number of Sundays crossed
				SET @SundayCount =
				(
					SELECT COUNT(*)
					FROM
					(
						SELECT TOP (DATEDIFF(DAY, @Now, @InitialTarget) + 1)
								DATEADD(DAY, ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1, CAST(@Now AS DATE)) AS D
						FROM master..spt_values
					) X
					WHERE DATENAME(WEEKDAY, D) = 'Sunday'
				);

				SET @MinAllowedDT = DATEADD(HOUR, 48 + (@SundayCount * 24), @Now);

				DECLARE @InspIdStr VARCHAR(500);
				SET @InspIdStr ='MINIMUM ALLOWD : '+ CONVERT(VARCHAR(50), @MinAllowedDT)+ ',  INSERTED : ' + CONVERT(VARCHAR(50), @INSPECTION_DATE);
				IF @INSPECTION_DATE IS NOT NULL   AND @INSPECTION_DATE < @MinAllowedDT
					BEGIN
						RAISERROR (
							'Please select a Date of Inspection that is at least 48 working hours  later (Sundays excluded).  %s.',
							16,
							1,
							 @InspIdStr
						);
					END
			END
		IF(@IS_QC_AT_DC=1)
			BEGIN
				SET @REGION_ID=1;-- All QC AT DC Request will go to Ram Prakash Soni Ji.
			END
		-----------------------------------------
		-- 1. INSERT or UPDATE POHEADER
		-----------------------------------------

		 -- Change here to apply 10% exceed logic 
	  
			IF (@OFFERED_QTY > CEILING(@TOTAL_QTY * 1.10)) --(@TOTAL_QTY<@OFFERED_QTY)
				BEGIN
					RAISERROR (
						'Offered quantity exceeds the allowed 10 percent additional limit of the total quantity.',
						16,
						1,
						 ''
					);
				END
		
			IF(@POID = 0)
			BEGIN
			   IF EXISTS (SELECT 1 FROM POHEADER WHERE PO_NUMBER = @PO_NUMBER)
                 BEGIN
                     -- FIX 2: no RETURN after RAISERROR.
                     RAISERROR('PO_NUMBER %s already exists.', 16, 1, @PO_NUMBER);
							
                 END
				INSERT INTO POHEADER
				(
					PO_NUMBER, VENDOR_CODE, VENDOR_NAME, FABRIC, COLOR,TOTAL_QTY, APPARELS,CATEGORY,BUYER_NAME,BUYER_ID,MC,MC_TEXT,MRP,BRAND_ID,BRAND_ID2,FIT, CREATED_ON, CREATED_BY
				)
				VALUES
				(
					@PO_NUMBER, @VENDOR_CODE, @VENDOR_NAME, @FABRIC, @COLOR, @TOTAL_QTY, @APPARELS, @CATEGORY, @BUYER_NAME, @BUYER_ID,@MC,@MC_TEXT,@MRP, @BRAND_ID,@BRAND_ID2,@FIT,GETDATE(), @USER_ID
				);

				SET @POID = SCOPE_IDENTITY();

					-----------------------------------------
					-- 2. UPSERT PODETAIL using MERGE
					-----------------------------------------
					MERGE PODETAIL AS Target
					USING (
						SELECT 
							PO_DETAILS_ID,
							LINE_ITEM, ARTICLE, ARTICLE_DESC, 
							PREPACK_QTY, PURCHASE_TOT_QTY,
							PREPACK_QTY_EACHES, EACHES,MRP,ATTYP,
							CREATED_BY, UPDATED_BY
						FROM @DETAILS
					) AS Source
					ON Target.PO_DETAILS_ID = Source.PO_DETAILS_ID  AND Target.POID = @POID

					WHEN MATCHED THEN 
						UPDATE SET
							LINE_ITEM = Source.LINE_ITEM,
							ARTICLE = Source.ARTICLE,
							ARTICLE_DESC = Source.ARTICLE_DESC,
							PREPACK_QTY = Source.PREPACK_QTY,
							PURCHASE_TOT_QTY = Source.PURCHASE_TOT_QTY,
							PREPACK_QTY_EACHES = Source.PREPACK_QTY_EACHES,
							EACHES = Source.EACHES,
							MRP = Source.MRP,
							ATTYP = Source.ATTYP,
							LAST_UPDATED_ON = GETDATE(),
							UPDATED_BY = Source.UPDATED_BY

					WHEN NOT MATCHED BY TARGET THEN
						INSERT 
						(
							POID, LINE_ITEM, ARTICLE, ARTICLE_DESC,
							PREPACK_QTY, PURCHASE_TOT_QTY, 
							PREPACK_QTY_EACHES, EACHES,MRP,ATTYP,
							CREATED_ON, CREATED_BY
						)
						VALUES
						(
							@POID, Source.LINE_ITEM, Source.ARTICLE, Source.ARTICLE_DESC,
							Source.PREPACK_QTY, Source.PURCHASE_TOT_QTY,
							Source.PREPACK_QTY_EACHES, Source.EACHES,Source.MRP,Source.ATTYP,
							GETDATE(), Source.CREATED_BY
						)

					WHEN NOT MATCHED BY SOURCE AND Target.POID = @POID THEN
						DELETE;     -- remove deleted rows
				-----------------------------------------

			END
			-----------------------------------------
			--Offered quantity exceeds the allowed 10% additional limit of the total quantity.
			-- 3. UPSERT INSPECTION REQUEST
			-- Validation Logic
			-- 1. Fetch all inspection requests for the same PO where inspection is not completed (STATUS_CODE <> 7), excluding the current inspection request.
			-- 2. Fetch only completed inspection requests (STATUS_CODE = 7) where the inspection result is PASS (INSPECTION_RESULT = 1).
			-- 3. Calculate Available Quantity = Total PO Quantity – Sum of Offered Quantities.
			-- 4. Validate that the current Offered Quantity does not exceed 110% of the Available Quantity.
			-----------------------------------------
			-- FIX 3: same type as the quantities (DECIMAL(18,3)), so 10.5 is no longer cut to 10.
			DECLARE @IROFFEREDQTY DECIMAL(18,3), @QAOFFEREDQTY DECIMAL(18,3), @AVAILABLE_QTY DECIMAL(18,3)
			-- 1. Fetch all inspection requests for the same PO where inspection is not completed (STATUS_CODE <> 7), excluding the current inspection request.
			SELECT @IROFFEREDQTY= ISNULL(SUM(A.OFFERED_QTY),0) FROM INSPECTION_REQUESTS A 
			LEFT JOIN POHEADER C on A.POID=C.POID 
			WHERE C.POID=@POID AND STATUS_CODE NOT IN (7,9,10) AND A.INSP_ID !=@INSP_ID

			-- 2. Fetch only completed inspection requests (STATUS_CODE = 7) where the inspection result is PASS (INSPECTION_RESULT = 1).
			-- 3. Calculate Available Quantity = Total PO Quantity – Sum of Offered Quantities.
			SELECT @AVAILABLE_QTY =
				(
				(CEILING(@TOTAL_QTY * 1.10)) - (@IROFFEREDQTY+ISNULL(SUM(B.OFFERED_QTY),0))
				)
			FROM INSPECTION_REQUESTS A 
			LEFT JOIN INSPECTIONS B on A.INSP_ID=B.INSPECTION_ID 
			LEFT JOIN POHEADER C on A.POID=C.POID 
			WHERE C.POID=@POID AND STATUS_CODE=7  AND B.INSPECTION_RESULT=1 AND A.INSP_ID !=@INSP_ID
	
			-- 4. Validate that the current Offered Quantity does not exceed 110% of the Available Quantity.
	   
			-- FIX 3: show 120 or 10.5, not 120.000 or 10.500.
			SET @avlqty = FORMAT(@AVAILABLE_QTY, '0.###')
			IF(@AVAILABLE_QTY >0 )
				BEGIN
					IF(@OFFERED_QTY > @AVAILABLE_QTY) -- Check the 10% logic here
						BEGIN
							RAISERROR (
								'Offered quantity exceeds the permitted 10 percent tolerance above the total quantity. Available quantity: %s.',
								16,
								1,
								@avlqty 
							);
						END
				END
			ELSE
				BEGIN
					-- CHANGE 2 (E3): no confusing negative "available" figure.
					SET @avlqty = FORMAT(IIF(@AVAILABLE_QTY < 0, 0, ISNULL(@AVAILABLE_QTY, 0)), '0.###');
					RAISERROR (
						'PO %s quantity is fully consumed (available quantity: %s). No further inspection request can be raised.',
						16,
						1,
						@PO_NUMBER,
						@avlqty
					);
				END
	   
	   
			INSERT INTO [dbo].[IROFRQTYLOGICCHECK]([PONumber],[IRId],[OfferedQty],[TotalQty],[FirstCheck],[IROfferedQty],[QAOfferedQty],[AvailableQty],[AvgQty],[SecondCheck])
			VALUES (@PO_NUMBER, @INSP_ID, @OFFERED_QTY , @TOTAL_QTY, (IIF(@OFFERED_QTY > CEILING(@TOTAL_QTY * 1.10), 1, 0)) ,@IROFFEREDQTY, @QAOFFEREDQTY, @AVAILABLE_QTY, @avlqty,(IIF(@OFFERED_QTY > CEILING(@AVAILABLE_QTY * 1.10), 1, 0)));

			IF(@INSPECTION_DATE IS NOT NULL AND @OFFERED_QTY > 0 AND @ADDRESS_ID IS NOT NULL)
				BEGIN
					IF(@INSP_ID = 0)
						BEGIN
							INSERT INTO INSPECTION_REQUESTS
							(
								POID, OFFERED_QTY, DATE_OF_INSPECTION, ADDRESS_ID, REGION_ID,STATUS_CODE, 
								INSPECTION_TYPE_ID, IS_QC_AT_DC, CREATED_ON, CREATED_BY, LAST_UPDATED_ON, UPDATED_BY
							)
							VALUES
							(
								@POID, @OFFERED_QTY, @INSPECTION_DATE, @ADDRESS_ID, @REGION_ID,1, 
								@INSPECTION_TYPE_ID, @IS_QC_AT_DC, GETDATE(), @USER_ID, GETDATE(), @USER_ID
							);
							SET @RECORD_ID = SCOPE_IDENTITY();
						END
					ELSE
						BEGIN
							UPDATE INSPECTION_REQUESTS
							SET 
								OFFERED_QTY = @OFFERED_QTY,
								DATE_OF_INSPECTION = @INSPECTION_DATE,
								ADDRESS_ID = @ADDRESS_ID,
								REGION_ID = @REGION_ID,
								INSPECTION_TYPE_ID = @INSPECTION_TYPE_ID, 
								IS_QC_AT_DC=@IS_QC_AT_DC,
								LAST_UPDATED_ON = GETDATE(),
								UPDATED_BY = @USER_ID,
								STATUS_CODE= case when @IS_CANCELLED = 1 then 9 else 2 end
							WHERE INSP_ID = @INSP_ID;
							SET @RECORD_ID = @INSP_ID;
						END
			END
			ELSE
				BEGIN
					RAISERROR (
						'Date of Inspection & Offered Qty and Address field is required.',
						16,
						1,
						 ''
					);
				END
		END
        COMMIT TRANSACTION;
		
    END TRY

    BEGIN CATCH
		IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_SEARCH_INSPECTIONS]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_SEARCH_INSPECTIONS]
(
    @CMD            VARCHAR(100),
    @STRFIELD       VARCHAR(50),
    @RequestType    VARCHAR(20)    = 'VIEW',
	@SubType    VARCHAR(20)    = 'ALL',
	@IS_QC_AT_DC BIT = 0,
    @VendorIds      VARCHAR(MAX)   = NULL,
    @BuyerIds       VARCHAR(MAX)   = NULL,
    @CategoryIds    VARCHAR(MAX)   = NULL,
    @ProductIds     VARCHAR(MAX)   = NULL,
    @InspectorIds   VARCHAR(MAX)   = NULL,
    @Mrp            DECIMAL(10,2)  = NULL,
    @PONumber       VARCHAR(20)    = NULL,
    @InspectionNumber VARCHAR(20)  = NULL,
    @FromDate       DATE           = NULL,
    @ToDate         DATE           = NULL,
    @PageNumber     INT            = 1,
    @PageSize       INT            = 20,
    @TotalCount     INT OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
	DECLARE @ROLEID INT;
	DECLARE @IdCsv NVARCHAR(MAX), @SDATE DATETIME=GETDATE();
	SELECT @ROLEID=ROLE_ID FROM USER_MASTER WHERE EMP_CODE = @STRFIELD;

	INSERT INTO TestCases_SP_SEARCH_INSPECTIONS (TestDescription, CMD, STRFIELD, RequestType, SubType, VendorIds, BuyerIds, CategoryIds, ProductIds, InspectorIds, Mrp, PONumber, InspectionNumber, FromDate, ToDate,IsQcAtDc)
	VALUES ('Test Cases', @CMD, @STRFIELD, @RequestType, @SubType, @VendorIds, @BuyerIds, @CategoryIds, @ProductIds, @InspectorIds, @Mrp, @PONumber, @InspectionNumber, @FromDate, @ToDate,@IS_QC_AT_DC)
   
	IF (@CMD IN ('GET_ALL_RECEIVED_PENDING_ONGOING_INSPECTIONS', 'GET_BUYER_WISE_ALL_RECEIVED_PENDING_ONGOING_INSPECTIONS', 'GET_VENDOR_WISE_ALL_RECEIVED_PENDING_ONGOING_INSPECTIONS','GET_QA_WISE_INSPECTIONS_ALL_RECEIVED_PENDING_ONGOING_INSPECTIONS'))
    BEGIN
		
		IF OBJECT_ID('tempdb..#REGION_SCOPE_LIST')  IS NOT NULL DROP TABLE #REGION_SCOPE_LIST;
		IF OBJECT_ID('tempdb..#EMP_LIST')      IS NOT NULL DROP TABLE #EMP_LIST;
		IF OBJECT_ID('tempdb..#IR_LIST')                IS NOT NULL DROP TABLE #IR_LIST;
		IF OBJECT_ID('tempdb..#POD_LIST')               IS NOT NULL DROP TABLE #POD_LIST;
		IF OBJECT_ID('tempdb..#IRF_LIST')			   IS NOT NULL DROP TABLE #IRF_LIST;

		CREATE TABLE #IRF_LIST (POID INT,INSP_ID INT,DATE_OF_INSPECTION DATETIME,CREATED_ON DATETIME);
		CREATE UNIQUE CLUSTERED INDEX IX_IRF_INSP  ON #IRF_LIST (INSP_ID);
		CREATE NONCLUSTERED INDEX IX_IRF_POID      ON #IRF_LIST (POID);
		CREATE NONCLUSTERED INDEX IX_IRF_DATEOFINS ON #IRF_LIST (DATE_OF_INSPECTION);
		CREATE NONCLUSTERED INDEX IX_IRF_CREATED_ON ON #IRF_LIST (CREATED_ON);

		CREATE TABLE #REGION_SCOPE_LIST (REGION_ID INT);
		CREATE TABLE #EMP_LIST(EMP_CODE VARCHAR(50), EMP_NAME VARCHAR(100), EMAIL_ID VARCHAR(100), MOBILE_NO VARCHAR(100),ROLE_ID INT, ROLE_NAME VARCHAR(100), REPORTING_EMP_ID VARCHAR(100), REPORTING_MANAGER VARCHAR(50),IS_ACTIVE BIT, HIERARCHY_LEVEL INT);

        IF (@CMD = 'GET_ALL_RECEIVED_PENDING_ONGOING_INSPECTIONS' AND @RoleId = 1007)
			BEGIN
			    INSERT INTO #REGION_SCOPE_LIST (REGION_ID)
			    SELECT TRY_CAST(VALUE AS INT)
			    FROM STRING_SPLIT((SELECT REGION_IDS FROM USER_MASTER WHERE EMP_CODE = @STRFIELD), ',');
			END
		IF (@CMD = 'GET_BUYER_WISE_ALL_RECEIVED_PENDING_ONGOING_INSPECTIONS')
			BEGIN
			    INSERT INTO #EMP_LIST
			    EXEC [dbo].[SP_MASTER_HIERARCHY_CRUD] @ACTION = 'GET_ALONG_WITH_CHILD', @EMP_CODE = @STRFIELD;
			END
        ----------------------------------------------------------------
        -- MATERIALIZE IR ONCE 
        ----------------------------------------------------------------
        SELECT A.POID,A.INSP_ID, A.QA_ASSIGNED_DOI,A.CREATED_ON
        INTO #IR_LIST
        FROM INSPECTION_REQUESTS A
        INNER JOIN POHEADER B ON A.POID = B.POID
		WHERE A.STATUS_CODE NOT IN (7,9,10) 
			AND 
			(
					(@IS_QC_AT_DC = 1 AND ISNULL(A.IS_QC_AT_DC, 0) = 1)
					OR ISNULL(@IS_QC_AT_DC, 0) = 0
			)
            AND
            (
                   (@CMD = 'GET_ALL_RECEIVED_PENDING_ONGOING_INSPECTIONS'
						AND (
								ISNULL(@RoleId, 0) <> 1007
								OR EXISTS (SELECT 1 FROM #REGION_SCOPE_LIST R WHERE R.REGION_ID = A.REGION_ID)
							)
						)
				OR (@CMD = 'GET_QA_WISE_INSPECTIONS_ALL_RECEIVED_PENDING_ONGOING_INSPECTIONS'
                    AND A.INSPECTOR_EMP_CODE = @STRFIELD)
                OR (@CMD = 'GET_BUYER_WISE_ALL_RECEIVED_PENDING_ONGOING_INSPECTIONS'
                        AND EXISTS (SELECT 1 FROM #EMP_LIST E WHERE B.BUYER_ID LIKE '%'+E.EMP_CODE))
                OR (@CMD = 'GET_VENDOR_WISE_ALL_RECEIVED_PENDING_ONGOING_INSPECTIONS'
                        AND B.VENDOR_CODE = @STRFIELD)
            )
            AND (@VendorIds        IS NULL OR B.VENDOR_CODE        IN (SELECT value FROM STRING_SPLIT(@VendorIds,',')))
            AND (@BuyerIds         IS NULL OR B.BUYER_ID           IN (SELECT value FROM STRING_SPLIT(@BuyerIds,',')))
            AND (@CategoryIds      IS NULL OR B.CATEGORY           IN (SELECT value FROM STRING_SPLIT(@CategoryIds,',')))
            AND (@ProductIds       IS NULL OR B.MC                 IN (SELECT value FROM STRING_SPLIT(@ProductIds,',')))
            AND (@InspectorIds     IS NULL OR A.INSPECTOR_EMP_CODE IN (SELECT value FROM STRING_SPLIT(@InspectorIds,',')))
            AND (@Mrp              IS NULL OR B.MRP BETWEEN @Mrp-10 AND @Mrp+10)
            AND (@PONumber         IS NULL OR B.PO_NUMBER LIKE '%'+@PONumber OR B.LINK_PO_NUMBER LIKE '%'+@PONumber)
            AND (@InspectionNumber IS NULL OR A.INSPECTION_NO LIKE '%'+@InspectionNumber)
			AND
			(
				(@SubType = 'ALL'
				AND (@FromDate         IS NULL OR A.DATE_OF_INSPECTION >= @FromDate)
				AND (@ToDate           IS NULL OR A.DATE_OF_INSPECTION <  DATEADD(DAY, 1, @ToDate))
				)
                OR (@SubType = 'RECEIVED' AND CAST(CASE WHEN A.IS_DATE_ASSIGNED_BY_QA is null THEN   A.DATE_OF_INSPECTION ELSE A.QA_ASSIGNED_DOI END AS DATE)  > CAST(GETDATE() AS DATE))
				OR (@SubType = 'PENDING'  
				AND (@FromDate         IS NULL OR CAST(CASE WHEN A.IS_DATE_ASSIGNED_BY_QA is null THEN   A.DATE_OF_INSPECTION ELSE A.QA_ASSIGNED_DOI END AS DATE) >= @FromDate)
				AND CAST(CASE WHEN A.IS_DATE_ASSIGNED_BY_QA is null THEN   A.DATE_OF_INSPECTION ELSE A.QA_ASSIGNED_DOI END AS DATE)  < CAST(GETDATE() AS DATE)
				)
				OR (@SubType = 'ONGOING'  AND CAST(CASE WHEN A.IS_DATE_ASSIGNED_BY_QA is null THEN   A.DATE_OF_INSPECTION ELSE A.QA_ASSIGNED_DOI END AS DATE)  >= CAST(GETDATE() AS DATE)
										  AND CAST(CASE WHEN A.IS_DATE_ASSIGNED_BY_QA is null THEN   A.DATE_OF_INSPECTION ELSE A.QA_ASSIGNED_DOI END AS DATE)  < DATEADD(DAY, 1, CAST(GETDATE() AS DATE)))
			);


			CREATE NONCLUSTERED INDEX IX_IR_LIST_DATEOFINSPECTION ON #IR_LIST (QA_ASSIGNED_DOI);
			CREATE NONCLUSTERED INDEX IX_IR_LIST_CREATED_ON ON #IR_LIST (CREATED_ON);

			SELECT @TotalCount = COUNT(1) FROM #IR_LIST;

			 IF (@RequestType = 'REPORT')
			   INSERT INTO #IRF_LIST (POID,INSP_ID,DATE_OF_INSPECTION,CREATED_ON) 
			   SELECT POID,INSP_ID, QA_ASSIGNED_DOI, CREATED_ON FROM #IR_LIST ORDER BY QA_ASSIGNED_DOI DESC;

			IF (@RequestType = 'VIEW')
			    INSERT INTO #IRF_LIST (POID,INSP_ID,DATE_OF_INSPECTION,CREATED_ON)  
				SELECT POID,INSP_ID, QA_ASSIGNED_DOI, CREATED_ON
			    FROM #IR_LIST
			    ORDER BY CREATED_ON DESC
			    OFFSET (@PageNumber - 1) * @PageSize ROWS
			    FETCH NEXT @PageSize ROWS ONLY;

			----------------------------------------------------------------
			-- POD 
			----------------------------------------------------------------
			SELECT P.POID, STRING_AGG(ARTICLE + '~' + CAST(MRP AS VARCHAR(50)) + '/-', ' | ') WITHIN GROUP (ORDER BY ARTICLE) AS ARTICLE_NO
			INTO #POD_LIST
			FROM PODETAIL P
			WHERE EXISTS (SELECT 1 FROM #IRF_LIST IR WHERE IR.POID = P.POID)
			AND TRY_CAST(LINE_ITEM AS DECIMAL(18,2)) % 100 = 0
			GROUP BY P.POID; 
			----------------------------------------------------------------
			-- MAIN QUERY 
			----------------------------------------------------------------
			SELECT
			CASE
                WHEN ISNULL(B.BUYER_NAME,'') <> '' AND ISNULL(B.BUYER_ID,'') <> ''
                THEN B.BUYER_NAME + ' [ ' + B.BUYER_ID + ' ]'
                ELSE '-'
            END AS BUYER_NAME,
            B.PO_NUMBER,
            CONCAT
            (
                B.PO_NUMBER,
                CASE WHEN ISNULL(B.LINK_PO_NUMBER,'') <> '' THEN ' ~ ' + B.LINK_PO_NUMBER ELSE '' END
            ) AS PO_NUMBER_WITH_LINK_PO_NUMBER,
            B.LINK_PO_NUMBER,
			B.VENDOR_NAME + ' [ ' + B.VENDOR_CODE + ' ]' AS VENDOR,
            B.MC_TEXT AS DESCRIPTION,
            B.MRP,
            CASE
                WHEN ISNULL(B.BRAND_ID2,'') <> '' AND ISNULL(B.BRAND_ID,'') <> ''
                THEN B.BRAND_ID2 + ' [ ' + B.BRAND_ID + ' ]'
                ELSE '-'
            END AS BRAND_LABEL,
            B.COLOR,
            B.FIT,
            B.CATEGORY,
            CAST(B.TOTAL_QTY AS FLOAT) AS PO_QTY,
            B.APPARELS AS APPS_NON_APPS,
            B.FABRIC,
            B.MC,
            A.INSP_ID,
            A.POID,
            CONVERT(VARCHAR(11), A.DATE_OF_INSPECTION, 106) AS INSPECTION_DATE,
            IT.INSPECTION_TYPE AS TYPE_OF_INSPECTION,
            ISNULL(A.INSPECTION_NO,'NA') AS INSPECTION_REPORT_NO,
			CASE WHEN @CMD = 'GET_VENDOR_WISE_ALL_RECEIVED_PENDING_ONGOING_INSPECTIONS' THEN '----' ELSE
				 CASE
					WHEN ISNULL(A.INSPECTOR_EMP_CODE,'') <> '' AND ISNULL(INSP.EMP_NAME,'') <> ''
					THEN INSP.EMP_NAME + ' [ ' + A.INSPECTOR_EMP_CODE + ' ]'
					ELSE '-'
				 END 
			END AS INSPECTOR,
            ISNULL(PD.ARTICLE_NO,'---') AS ARTICLE_NO,
            CAST(A.OFFERED_QTY AS FLOAT) AS OFFERED_QTY,
            RM.REGION AS LOCATION,
            E.ADDRESS_LINE1 + ', ' + E.CITY + ', ' + E.REGION_DESCRIPTION + ', ' + E.PINCODE AS ADDRESS,
            E.CONTACT_PERSON AS CONTACT_NAME,
            E.MOBILE_NUMBERS AS CONTACT_NUMBER,
            CONVERT(VARCHAR(11), A.DATE_OF_INSPECTION, 106) AS DATE_OF_INSPECTION,
            A.ADDRESS_ID,
            A.CREATED_ON,
            A.LAST_UPDATED_ON,
            A.REGION_ID,
            CONVERT(VARCHAR(11), A.QA_ASSIGNED_DOI, 106) AS QA_ASSIGNED_DOI,
            A.INSPECTION_TYPE_ID,
            A.IS_DATE_ASSIGNED_BY_QA,
            A.IS_INSPECTOR_ASSIGNED,
            ISNULL(S.INSP_STATUS,'Created') AS INSP_REQ_STATUS,
            A.STATUS_CODE,
			A.DATE_OF_INSPECTION  AS DoI_Vendor ,
			A.QA_ASSIGNED_DOI AS DoI_For_QA,
			A.INSPECTOR_EMP_CODE,
			A.IS_QC_AT_DC
        FROM #IRF_LIST IR
		INNER JOIN INSPECTION_REQUESTS A ON IR.INSP_ID=A.INSP_ID
        INNER JOIN POHEADER B ON IR.POID = B.POID
        INNER JOIN MASTER_REGION RM ON A.REGION_ID = RM.REGION_ID
        INNER JOIN DBO.INSPECTION_REQUEST_STATUS S ON A.STATUS_CODE = S.INSP_STATUS_ID
        LEFT JOIN VENDOR_ADDRESS E ON A.ADDRESS_ID = E.ADDRESS_ID
        LEFT JOIN #POD_LIST PD ON A.POID = PD.POID
        LEFT JOIN USER_MASTER INSP ON A.INSPECTOR_EMP_CODE = INSP.EMP_CODE
        LEFT JOIN MASTER_INSPECTION_TYPE IT ON A.INSPECTION_TYPE_ID = IT.INSPECTION_TYPE_ID;

		--INSERT INTO [dbo].[TESTDESHBOARDLIST]([START_TIME],[INSP_IDS],[OUTPUT_TIME],[EXECUTION_TIME_IN_MS])
		--VALUES (@SDATE,@RequestType+' : LIST | Rows : '+ CAST(@TotalCount as VARCHAR) ,GETDATE(),DATEDIFF(MILLISECOND, @SDATE, GETDATE()))
		
		--Select * from TESTDESHBOARDLIST

    END
   

   IF (@CMD IN ('GET_REPORT_INSPECTIONS', 'GET_REPORT_INSPECTIONS_INSPECTOR_WISE', 'GET_REPORT_INSPECTIONS_BUYER_WISE', 'GET_REPORT_INSPECTIONS_VENDOR_WISE', 'GET_INSPECTOR_WISE_FAILED_INSPECTIONS_REPORT'))
    BEGIN
		IF OBJECT_ID('tempdb..#REGION_SCOPE_RPT')  IS NOT NULL DROP TABLE #REGION_SCOPE_RPT;
		IF OBJECT_ID('tempdb..#EMP_LIST_RPT')      IS NOT NULL DROP TABLE #EMP_LIST_RPT;
		IF OBJECT_ID('tempdb..#IR')                IS NOT NULL DROP TABLE #IR;
		IF OBJECT_ID('tempdb..#POD')               IS NOT NULL DROP TABLE #POD;
		IF OBJECT_ID('tempdb..#DEFECTS')           IS NOT NULL DROP TABLE #DEFECTS;
		IF OBJECT_ID('tempdb..#ABORTIVE')          IS NOT NULL DROP TABLE #ABORTIVE;
		IF OBJECT_ID('tempdb..#IRF')			   IS NOT NULL DROP TABLE #IRF;

		CREATE TABLE #IRF (POID INT,INSP_ID INT,INSPECT_ID INT,DATE_OF_COMPLETION DATETIME);
		CREATE UNIQUE CLUSTERED INDEX IX_IRF_INSP  ON #IRF (INSP_ID);
		CREATE NONCLUSTERED INDEX IX_IRF_POID      ON #IRF (POID);
		CREATE NONCLUSTERED INDEX IX_IRF_ISPECT_ID ON #IRF (INSPECT_ID);
		CREATE NONCLUSTERED INDEX IX_IRF_DATEOFCOMPLETION ON #IRF (DATE_OF_COMPLETION);

		CREATE TABLE #REGION_SCOPE_RPT (REGION_ID INT);
		CREATE TABLE #EMP_LIST_RPT
		(
		    EMP_CODE VARCHAR(50), EMP_NAME VARCHAR(100), EMAIL_ID VARCHAR(100), MOBILE_NO VARCHAR(100),
		    ROLE_ID INT, ROLE_NAME VARCHAR(100), REPORTING_EMP_ID VARCHAR(100), REPORTING_MANAGER VARCHAR(50),
		    IS_ACTIVE BIT, HIERARCHY_LEVEL INT
		);

        IF (@CMD = 'GET_REPORT_INSPECTIONS' AND @RoleId = 1007)
			BEGIN
			    INSERT INTO #REGION_SCOPE_RPT (REGION_ID)
			    SELECT TRY_CAST(VALUE AS INT)
			    FROM STRING_SPLIT((SELECT REGION_IDS FROM USER_MASTER WHERE EMP_CODE = @STRFIELD), ',');
			END
		Else IF (@CMD = 'GET_INSPECTOR_WISE_FAILED_INSPECTIONS_REPORT' AND @RoleId = 1006)
			BEGIN
			    INSERT INTO #REGION_SCOPE_RPT (REGION_ID)
			    SELECT TRY_CAST(VALUE AS INT)
			    FROM STRING_SPLIT((SELECT REGION_IDS FROM USER_MASTER WHERE EMP_CODE = @STRFIELD), ',');
			END
		IF (@CMD = 'GET_REPORT_INSPECTIONS_BUYER_WISE')
			BEGIN
			    INSERT INTO #EMP_LIST_RPT
			    EXEC [dbo].[SP_MASTER_HIERARCHY_CRUD] @ACTION = 'GET_ALONG_WITH_CHILD', @EMP_CODE = @STRFIELD;
			END
        ----------------------------------------------------------------
        -- MATERIALIZE IR ONCE 
        ----------------------------------------------------------------
        SELECT A.POID,A.INSP_ID, I.INSPECT_ID,I.DATE_OF_COMPLETION
        INTO #IR
        FROM INSPECTION_REQUESTS A
        INNER JOIN POHEADER B ON A.POID = B.POID
		INNER join INSPECTIONS I ON I.INSPECTION_ID=A.INSP_ID
        WHERE A.STATUS_CODE IN (7,10) AND I.IS_COMPLETE=1
        AND
        (
               (@CMD = 'GET_REPORT_INSPECTIONS'
                    AND ( ISNULL(@RoleId, 0) <> 1007 OR EXISTS (SELECT 1 FROM #REGION_SCOPE_RPT R WHERE R.REGION_ID = A.REGION_ID) ))
            OR (@CMD = 'GET_REPORT_INSPECTIONS_INSPECTOR_WISE'
                    AND A.INSPECTOR_EMP_CODE = @STRFIELD)
            OR (@CMD = 'GET_REPORT_INSPECTIONS_BUYER_WISE'
                    AND EXISTS (SELECT 1 FROM #EMP_LIST_RPT E WHERE B.BUYER_ID LIKE '%'+E.EMP_CODE))
            OR (@CMD = 'GET_REPORT_INSPECTIONS_VENDOR_WISE'
                    AND B.VENDOR_CODE = @STRFIELD)
            OR (@CMD = 'GET_INSPECTOR_WISE_FAILED_INSPECTIONS_REPORT' 
					AND EXISTS (SELECT 1 FROM #REGION_SCOPE_RPT R WHERE R.REGION_ID = A.REGION_ID) AND A.STATUS_CODE = 7 AND I.INSPECTION_RESULT = 2)
        )
        AND (@VendorIds        IS NULL OR B.VENDOR_CODE        IN (SELECT value FROM STRING_SPLIT(@VendorIds,',')))
        AND (@BuyerIds         IS NULL OR B.BUYER_ID           IN (SELECT value FROM STRING_SPLIT(@BuyerIds,',')))
        AND (@CategoryIds      IS NULL OR B.CATEGORY           IN (SELECT value FROM STRING_SPLIT(@CategoryIds,',')))
        AND (@ProductIds       IS NULL OR B.MC                 IN (SELECT value FROM STRING_SPLIT(@ProductIds,',')))
        AND (@InspectorIds     IS NULL OR A.INSPECTOR_EMP_CODE IN (SELECT value FROM STRING_SPLIT(@InspectorIds,',')))
        AND (@Mrp              IS NULL OR B.MRP BETWEEN @Mrp-10 AND @Mrp+10)
        AND (@PONumber         IS NULL OR B.PO_NUMBER LIKE '%'+@PONumber OR B.LINK_PO_NUMBER LIKE '%'+@PONumber)
        AND (@InspectionNumber IS NULL OR A.INSPECTION_NO LIKE '%'+@InspectionNumber)
        AND (@FromDate         IS NULL OR I.DATE_OF_COMPLETION >= @FromDate)
        AND (@ToDate           IS NULL OR I.DATE_OF_COMPLETION <  DATEADD(DAY, 1, @ToDate));
       
	    CREATE NONCLUSTERED INDEX IX_IR_DATEOFCOMPLETION ON #IR (DATE_OF_COMPLETION);

	    SELECT @TotalCount = COUNT(1) FROM #IR;

		 IF (@RequestType = 'REPORT')
           INSERT INTO #IRF (POID,INSP_ID,INSPECT_ID,DATE_OF_COMPLETION) 
		   SELECT POID,INSP_ID, INSPECT_ID,DATE_OF_COMPLETION FROM #IR ORDER BY DATE_OF_COMPLETION DESC;

        IF (@RequestType = 'VIEW')
            INSERT INTO #IRF (POID,INSP_ID,INSPECT_ID,DATE_OF_COMPLETION) 
			SELECT POID,INSP_ID, INSPECT_ID,DATE_OF_COMPLETION
            FROM #IR
            ORDER BY DATE_OF_COMPLETION DESC
            OFFSET (@PageNumber - 1) * @PageSize ROWS
            FETCH NEXT @PageSize ROWS ONLY;


        ----------------------------------------------------------------
        -- POD 
        ----------------------------------------------------------------
		SELECT P.POID, STRING_AGG(ARTICLE + '~' + CAST(MRP AS VARCHAR(50)) + '/-', ' | ') WITHIN GROUP (ORDER BY ARTICLE) AS ARTICLE_NO
		INTO #POD
		FROM PODETAIL P
		WHERE EXISTS (SELECT 1 FROM #IRF IR WHERE IR.POID = P.POID)
		AND TRY_CAST(LINE_ITEM AS DECIMAL(18,2)) % 100 = 0
		GROUP BY P.POID;
		
		----------------------------------------------------------------
        -- DEFECTS
        ----------------------------------------------------------------
        SELECT
            INSPECTION_ID,
            STRING_AGG
            (
                DEFECTS + ' [MJ=' +
                CAST(MAJOR AS VARCHAR(10)) +
                ', MN=' +
                CAST(MINOR AS VARCHAR(10)) + ']',
                ', '
            ) AS DEFECT_DETAILS,
            SUM(ISNULL(MAJOR,0)) AS TOTAL_MAJOR,
            SUM(ISNULL(MINOR,0)) AS TOTAL_MINOR
        INTO #DEFECTS
        FROM INSPECTION_DEFECTS D
        INNER JOIN (SELECT INSP_ID FROM #IRF) IRL ON IRL.INSP_ID = D.INSPECTION_ID
        GROUP BY INSPECTION_ID;

		
		----------------------------------------------------------------
        -- ABORTIVE 
        ----------------------------------------------------------------
        SELECT I.INSPECT_ID, STRING_AGG(MAR.REASON, ', ') AS ABORTIVE_REASON
        INTO #ABORTIVE
        FROM INSPECTIONS I
        CROSS APPLY STRING_SPLIT(I.ABORTIVE_REASON_IDS, ',') SS
        INNER JOIN MASTER_ABORTIVE_REASON MAR
            ON TRY_CAST(SS.VALUE AS INT) = MAR.AR_ID
        WHERE I.INSPECT_ID IN (SELECT INSPECT_ID FROM #IRF)
        GROUP BY I.INSPECT_ID;

		
        ----------------------------------------------------------------
        -- Final projection — INSPECTIONS join keeps your new conditional  234MS
        -- INSPECTION_RESULT = 2 filter for the failed-inspections branch
        ----------------------------------------------------------------
        SELECT
            A.INSP_ID,
            A.POID,
            CONVERT(VARCHAR(11), A.DATE_OF_INSPECTION, 106) AS INSPECTION_DATE,
            IT.INSPECTION_TYPE AS TYPE_OF_INSPECTION,
            ISNULL(A.INSPECTION_NO,'NA') AS INSPECTION_REPORT_NO,
            CASE
                WHEN ISNULL(A.INSPECTOR_EMP_CODE,'') <> '' AND ISNULL(INSP.EMP_NAME,'') <> ''
                THEN INSP.EMP_NAME + ' [ ' + A.INSPECTOR_EMP_CODE + ' ]'
                ELSE '-'
            END AS INSPECTOR,

            CASE
                WHEN ISNULL(B.BUYER_NAME,'') <> '' AND ISNULL(B.BUYER_ID,'') <> ''
                THEN B.BUYER_NAME + ' [ ' + B.BUYER_ID + ' ]'
                ELSE '-'
            END AS BUYER_NAME,
            B.PO_NUMBER,
            CONCAT
            (
                B.PO_NUMBER,
                CASE WHEN ISNULL(B.LINK_PO_NUMBER,'') <> '' THEN ' ~ ' + B.LINK_PO_NUMBER ELSE '' END
            ) AS PO_NUMBER_WITH_LINK_PO_NUMBER,
            B.LINK_PO_NUMBER,

            
            ISNULL(PD.ARTICLE_NO,'---') AS ARTICLE_NO,
            
            B.VENDOR_NAME + ' [ ' + B.VENDOR_CODE + ' ]' AS VENDOR,
			B.MC_TEXT AS DESCRIPTION,
 
            CASE
                WHEN ISNULL(B.BRAND_ID2,'') <> '' AND ISNULL(B.BRAND_ID,'') <> ''
                THEN B.BRAND_ID2 + ' [ ' + B.BRAND_ID + ' ]'
                ELSE '-'
            END AS BRAND_LABEL,
            B.MRP,
            B.COLOR,
            B.FIT,
            B.MC,
            B.FABRIC,
            B.CATEGORY,
            CAST(B.TOTAL_QTY AS FLOAT) AS PO_QTY,
            CAST(A.OFFERED_QTY AS FLOAT) AS OFFERED_QTY,
            B.APPARELS AS APPS_NON_APPS,
            RM.REGION AS LOCATION,
            E.ADDRESS_LINE1 + ', ' + E.CITY + ', ' + E.REGION_DESCRIPTION + ', ' + E.PINCODE AS ADDRESS,
            E.CONTACT_PERSON AS CONTACT_NAME,
            E.MOBILE_NUMBERS AS CONTACT_NUMBER,
            CONVERT(VARCHAR(11), A.DATE_OF_INSPECTION, 106) AS DATE_OF_INSPECTION,
            P.PASSFAIL AS INSP_RESULT,
            FORMAT(I.DATE_OF_COMPLETION, 'dd MMM, yyyy hh:mm:ss tt') AS DATE_OF_COMPLETION,

            CAST(I.OFFERED_QTY AS FLOAT) AS SHIP_QTY,
            MAQL.SAMPLE_SIZE,
            ISNULL(MFR.FAIL_REASON,'') AS FAIL_REASON,
            ISNULL(AB.ABORTIVE_REASON,'')
            +
            CASE
                WHEN EXISTS
                (
                    SELECT 1
                    FROM STRING_SPLIT(I.ABORTIVE_REASON_IDS, ',')
                    WHERE TRY_CAST(VALUE AS INT) = 8
                )
                THEN ' : ' + ISNULL(I.OTHER_ABORTIVE_REASON,'')
                ELSE ''
            END AS ABORTIVE_REASON,

            DF.DEFECT_DETAILS AS DEFECTS,
            DF.TOTAL_MAJOR AS MAJOR,
            DF.TOTAL_MINOR AS MINOR,
            MAQL.AQL_2_5_MAJOR AS ALLOWED,

            CASE
                WHEN
                    ISNULL(DF.TOTAL_MAJOR,0) > ISNULL(MAQL.AQL_2_5_MAJOR,0)
                    OR
                    ISNULL(DF.TOTAL_MINOR,0) > ISNULL(MAQL.AQL_2_5_MAJOR,0)
                THEN 'FAIL'
                ELSE 'PASS'
            END AS STATUS,

            I.REMARK_COMMENT AS REMARKS_DETAILS,
            I.NOTE,
            I.FIBER_CONTENT_ON_TEST_REPORT,
            I.FIBER_CONTENT_ON_WC AS FIBER_CONTENT_ON_LABEL,
            I.FIBER_CONTENT_ON_PO,
            I.GSM_ON_PO,
            I.GSM_ON_TEST_REPORT,
            I.GSM_ON_BULK,

            CASE
                WHEN I.NO_OF_BAGS_CARTONS_QTY > 0
                THEN CAST(I.NO_OF_BAGS_CARTONS_QTY AS VARCHAR)
                     + ' ' + ISNULL(UNOB.UNIT,'')
                ELSE ''
            END AS NO_OF_BAGS_CARTON,

            I.SELECTED_BAG_CARTONS_NO AS SELECTED_BAGS_CARTON_NO,

            CASE
                WHEN I.NO_OF_CHECK > 0
                THEN CAST(I.NO_OF_CHECK AS VARCHAR)
                     + ' ' + ISNULL(UCOB.UNIT,'')
                ELSE ''
            END AS NO_OF_CHECK_CARTON_BAG,

            I.NO_OF_PREPACK_CHECK AS NO_OF_CHECK_PRE_PACK,
            I.MEASUREMENT_SAMPLE_QTY AS MESUREMENT_SAMPLE_SIZE,

            CASE
                WHEN I.MEASUREMENT_SAMPLE_SIZE > 0
                THEN MPF.PASSFAIL
                ELSE ''
            END AS MEASUREMENT_PASS_FAIL,

            CASE WHEN I.PACKING_STATUS > 0 THEN PSYN.YESNO ELSE '' END AS PACKING_STATUS,
            CASE WHEN I.PACKING_LIST > 0 THEN PLYN.YESNO ELSE '' END AS PACKING_LIST,
            CASE WHEN I.INLINE_DONE > 0 THEN IDYN.YESNO ELSE '' END AS INLINE_DONE,

            CONVERT(VARCHAR(11), I.PPS_RELEASE_DATE, 106) AS PPS_RELEASE_DATE,
            CONVERT(VARCHAR(11), I.PPS_EXPIRY_DATE, 106) AS PPS_EXPIRY_DATE,
            CONVERT(VARCHAR(11), I.MFG_DATE, 106) AS MFG_DATE,

            I.SEASON,
            CC.COLOR_CODE,
            I.GPT_NO AS GPT_REPORT_NO,

            CASE WHEN I.GPT_STATUS > 0 THEN GSPF.PASSFAIL ELSE '' END AS TEST_REPORT_STATUS,
            I.AREA_OF_FAIL_GPTR AS AREA_OF_FAILURE_IN_GPT_TEST,
            I.GPT_APPROVED_DATE AS APPROVED_DATE,
            I.GPT_APPROVED_BY AS APPROVED_BY_IF_GPT_FAILS,
            I.GPT_ELASTIC_NO,

            CASE WHEN I.GPT_ELASTIC_STATUS > 0 THEN ESPF.PASSFAIL ELSE '' END AS ELASTIC_TEST_REPORT_STATUS,
            I.GPT_ELASTIC_APPROVED_DATE,
            I.GPT_ELASTIC_APPROVED_BY,
            I.ZIPPER_RPT_NO AS ZIPPER_REPORT_NO,

            CASE WHEN I.ZIPPER_STATUS > 0 THEN ZSPF.PASSFAIL ELSE '' END AS ZIPPER_REPORT_STATUS,
            I.ZIPPER_APPROVED_DATE,
            I.ZIPPER_APPROVED_BY AS IF_FAIL_ZIPPER_APPROVED_BY,

            I.CONFORMITY_SIZE +
            CASE
                WHEN I.CONFORMITY_SIZE_STATUS > 0
                THEN ' : ' + SSPF.PASSFAIL
                ELSE ''
            END AS SIZE,

            CASE WHEN I.EMBROIDERY_PF > 0 THEN EMPF.PASSFAIL ELSE '' END AS EMBRIODERY_PRINT_SHOULD_BE_AS_PER_PPS,
            CASE WHEN I.ACCESSORIES_PF > 0 THEN ACPF.PASSFAIL ELSE '' END AS ACCESSORIES_SHOULD_BE_AS_PER_PPS,
            CASE WHEN I.BARCODE_PF > 0 THEN BAPF.PASSFAIL ELSE '' END AS BARCODE_COMPLIANCES,
            CASE WHEN I.NO_PLASTIC_PF > 0 THEN NPPF.PASSFAIL ELSE '' END AS NO_PLASTIC_TAG_KIMBLE_TAG,
            CASE WHEN I.BOGO_PF > 0 THEN BOPF.PASSFAIL ELSE '' END AS BOGO_DISCOUNT_TAG,

            I.CONFORMITY_PREPACK +
            CASE
                WHEN I.CONFORMITY_PREPACK_STATUS > 0
                THEN ' : ' + PPRYN.YESNO
                ELSE ''
            END AS PRE_PACK_RATIO,

            CASE WHEN I.THREAD_YN > 0 THEN THYN.YESNO ELSE '' END AS THREAD_FROM_NOMINATED_Y_N,
            CASE WHEN I.BUTTON_YN > 0 THEN BUYN.YESNO ELSE '' END AS BUTTON_FROM_NOMINATED_Y_N,
            CASE WHEN I.ZIPPER_YN > 0 THEN ZIYN.YESNO ELSE '' END AS ZIPPER_FROM_NOMINATED_Y_N,
            CASE WHEN I.INTERLINING_YN > 0 THEN INYN.YESNO ELSE '' END AS INTERLINING_FROM_NOMINATED_VENDOR_Y_N,
            CASE WHEN I.ELASTIC_YN > 0 THEN ELYN.YESNO ELSE '' END AS ELASTIC_FROM_NOMINATED_Y_N,

            CONVERT(VARCHAR(11), I.GPT_COMM_APPROVAL_DATE,106) AS FI_COMM_APPR_DATE,
            I.GPT_COMM_APPROVED_BY AS FI_COMM_APPROVED_BY,
            I.COMM_APPROVAL_DOC AS COMM_APPROVAL_DOCUMENTS,
            I.DEBIT_AMOUNT,
            I.AMT_TRAVELLING AS AMOUNT_OF_TRAVELLING_AND_OTHER_EXPENCES,
            I.ADMIN_REMARK,

            I.INSPECT_ID,
            I.INSPECTION_RESULT,
            A.INSPECTOR_EMP_CODE,
            A.ADDRESS_ID,
            A.CREATED_ON,
            A.LAST_UPDATED_ON,
            A.REGION_ID,
            CONVERT(VARCHAR(11), A.QA_ASSIGNED_DOI, 106) AS QA_ASSIGNED_DOI,
            A.INSPECTION_TYPE_ID,
            A.IS_DATE_ASSIGNED_BY_QA,
            A.IS_INSPECTOR_ASSIGNED,
            ISNULL(S.INSP_STATUS,'Created') AS INSP_REQ_STATUS,
            A.STATUS_CODE
        
        FROM #IRF IR
			INNER JOIN INSPECTION_REQUESTS A 
				ON IR.INSP_ID=A.INSP_ID
			INNER JOIN POHEADER B 
				ON IR.POID=B.POID
            INNER JOIN INSPECTIONS I
                ON IR.INSPECT_ID=I.INSPECT_ID
            INNER JOIN MASTER_PASSFAIL P
                ON I.INSPECTION_RESULT = P.PASSFAIL_ID
            LEFT JOIN MASTER_REGION RM
                ON A.REGION_ID = RM.REGION_ID
            LEFT JOIN DBO.INSPECTION_REQUEST_STATUS S
                ON A.STATUS_CODE = S.INSP_STATUS_ID
            LEFT JOIN VENDOR_ADDRESS E
                ON A.ADDRESS_ID = E.ADDRESS_ID
            INNER JOIN #POD PD
                ON IR.POID = PD.POID
            LEFT JOIN USER_MASTER INSP
                ON A.INSPECTOR_EMP_CODE = INSP.EMP_CODE
            LEFT JOIN MASTER_INSPECTION_TYPE IT
                ON A.INSPECTION_TYPE_ID = IT.INSPECTION_TYPE_ID
            LEFT JOIN #DEFECTS DF
                ON A.INSP_ID = DF.INSPECTION_ID
            LEFT JOIN #ABORTIVE AB
                ON IR.INSPECT_ID = AB.INSPECT_ID
            LEFT JOIN MASTER_FAIL_REASON MFR
                ON I.RESEAN_FOR_FAIL = MFR.FAIL_REASON_ID
            LEFT JOIN MASTER_COLOR_CODE CC
                ON I.COLOR_CODE = CC.COLOR_CODE_ID
            LEFT JOIN MASTER_UNIT UNOB
                ON I.NO_OF_BAGS_CARTONS_UNIT = UNOB.UNIT_ID
            LEFT JOIN MASTER_UNIT UCOB
                ON I.NO_OF_CHECK_UNIT = UCOB.UNIT_ID
            LEFT JOIN MASTER_PASSFAIL MPF
                ON I.MEASUREMENT_SAMPLE_SIZE = MPF.PASSFAIL_ID
            LEFT JOIN MASTER_YESNO PSYN
                ON I.PACKING_STATUS = PSYN.YESNO_ID
            LEFT JOIN MASTER_YESNO PLYN
                ON I.PACKING_LIST = PLYN.YESNO_ID
            LEFT JOIN MASTER_YESNO IDYN
                ON I.INLINE_DONE = IDYN.YESNO_ID
            LEFT JOIN MASTER_PASSFAIL GSPF
                ON I.GPT_STATUS = GSPF.PASSFAIL_ID
            LEFT JOIN MASTER_PASSFAIL ESPF
                ON I.GPT_ELASTIC_STATUS = ESPF.PASSFAIL_ID
            LEFT JOIN MASTER_PASSFAIL ZSPF
                ON I.ZIPPER_STATUS = ZSPF.PASSFAIL_ID
            LEFT JOIN MASTER_PASSFAIL SSPF
                ON I.CONFORMITY_SIZE_STATUS = SSPF.PASSFAIL_ID
            LEFT JOIN MASTER_PASSFAIL EMPF
                ON I.EMBROIDERY_PF = EMPF.PASSFAIL_ID
            LEFT JOIN MASTER_PASSFAIL ACPF
                ON I.ACCESSORIES_PF = ACPF.PASSFAIL_ID
            LEFT JOIN MASTER_PASSFAIL BAPF
                ON I.BARCODE_PF = BAPF.PASSFAIL_ID
            LEFT JOIN MASTER_PASSFAIL NPPF
                ON I.NO_PLASTIC_PF = NPPF.PASSFAIL_ID
            LEFT JOIN MASTER_PASSFAIL BOPF
                ON I.BOGO_PF = BOPF.PASSFAIL_ID
            LEFT JOIN MASTER_YESNO PPRYN
                ON I.CONFORMITY_PREPACK_STATUS = PPRYN.YESNO_ID
            LEFT JOIN MASTER_YESNO THYN
                ON I.THREAD_YN = THYN.YESNO_ID
            LEFT JOIN MASTER_YESNO BUYN
                ON I.BUTTON_YN = BUYN.YESNO_ID
            LEFT JOIN MASTER_YESNO ZIYN
                ON I.ZIPPER_YN = ZIYN.YESNO_ID
            LEFT JOIN MASTER_YESNO INYN
                ON I.INTERLINING_YN = INYN.YESNO_ID
            LEFT JOIN MASTER_YESNO ELYN
                ON I.ELASTIC_YN = ELYN.YESNO_ID
            LEFT JOIN MASTER_AQL MAQL
                ON I.OFFERED_QTY BETWEEN MAQL.BATCH_SIZE_MIN AND MAQL.BATCH_SIZE_MAX;

		
		INSERT INTO [dbo].[TESTDESHBOARDLIST]([START_TIME],[INSP_IDS],[OUTPUT_TIME],[EXECUTION_TIME_IN_MS])
		VALUES (@SDATE,@RequestType+' : REPORT | Rows : '+ CAST(@TotalCount as VARCHAR) ,GETDATE(),DATEDIFF(MILLISECOND, @SDATE, GETDATE()))
		
		--Select * from TESTDESHBOARDLIST
    END
	

	IF (@CMD IN ('GET_ALL_CANCEL_INSPECTIONS', 'GET_BUYER_WISE_CANCEL_INSPECTIONS', 'GET_VENDOR_WISE_CANCEL_INSPECTIONS'))
    BEGIN
		IF OBJECT_ID('tempdb..#REGION_SCOPE_LIST_CANCEL')  IS NOT NULL DROP TABLE #REGION_SCOPE_LIST_CANCEL;
		IF OBJECT_ID('tempdb..#EMP_LIST_CANCEL')      IS NOT NULL DROP TABLE #EMP_LIST_CANCEL;
		IF OBJECT_ID('tempdb..#IRF_LIST_CANCEL')			   IS NOT NULL DROP TABLE #IRF_LIST_CANCEL;
		IF OBJECT_ID('tempdb..#IR_LIST_CANCEL')                IS NOT NULL DROP TABLE #IR_LIST_CANCEL;
		IF OBJECT_ID('tempdb..#POD_LIST_CANCEL')               IS NOT NULL DROP TABLE #POD_LIST_CANCEL;
		

		CREATE TABLE #IRF_LIST_CANCEL (POID INT,INSP_ID INT,DATE_OF_INSPECTION DATETIME,CREATED_ON DATETIME);
		CREATE UNIQUE CLUSTERED INDEX IX_IRF_INSP_CANCEL  ON #IRF_LIST_CANCEL (INSP_ID);
		CREATE NONCLUSTERED INDEX IX_IRF_POID_CANCEL      ON #IRF_LIST_CANCEL (POID);
		CREATE NONCLUSTERED INDEX IX_IRF_DATEOFINS_CANCEL ON #IRF_LIST_CANCEL (DATE_OF_INSPECTION);
		CREATE NONCLUSTERED INDEX IX_IRF_CREATED_ON_CANCEL ON #IRF_LIST_CANCEL (CREATED_ON);

		CREATE TABLE #REGION_SCOPE_LIST_CANCEL (REGION_ID INT);
		CREATE TABLE #EMP_LIST_CANCEL(EMP_CODE VARCHAR(50), EMP_NAME VARCHAR(100), EMAIL_ID VARCHAR(100), MOBILE_NO VARCHAR(100),ROLE_ID INT, ROLE_NAME VARCHAR(100), REPORTING_EMP_ID VARCHAR(100), REPORTING_MANAGER VARCHAR(50),IS_ACTIVE BIT, HIERARCHY_LEVEL INT);

        IF (@CMD = 'GET_ALL_CANCEL_INSPECTIONS' AND @RoleId = 1007)
			BEGIN
			    INSERT INTO #REGION_SCOPE_LIST_CANCEL (REGION_ID)
			    SELECT TRY_CAST(VALUE AS INT)
			    FROM STRING_SPLIT((SELECT REGION_IDS FROM USER_MASTER WHERE EMP_CODE = @STRFIELD), ',');
			END
		IF (@CMD = 'GET_BUYER_WISE_CANCEL_INSPECTIONS')
			BEGIN
			    INSERT INTO #EMP_LIST_CANCEL
			    EXEC [dbo].[SP_MASTER_HIERARCHY_CRUD] @ACTION = 'GET_ALONG_WITH_CHILD', @EMP_CODE = @STRFIELD;
			END
        ----------------------------------------------------------------
        -- MATERIALIZE IR ONCE 
        ----------------------------------------------------------------
        SELECT A.POID,A.INSP_ID, A.QA_ASSIGNED_DOI,A.CREATED_ON
        INTO #IR_LIST_CANCEL
        FROM INSPECTION_REQUESTS A
        INNER JOIN POHEADER B ON A.POID = B.POID
		WHERE A.STATUS_CODE = 9
            AND
            (
                   (@CMD = 'GET_ALL_CANCEL_INSPECTIONS'
						AND (
								ISNULL(@RoleId, 0) <> 1007
								OR EXISTS (SELECT 1 FROM #REGION_SCOPE_LIST_CANCEL R WHERE R.REGION_ID = A.REGION_ID)
							)
						)
                OR (@CMD = 'GET_BUYER_WISE_CANCEL_INSPECTIONS'
                        AND EXISTS (SELECT 1 FROM #EMP_LIST_CANCEL E WHERE B.BUYER_ID LIKE '%'+E.EMP_CODE))
                OR (@CMD = 'GET_VENDOR_WISE_CANCEL_INSPECTIONS'
                        AND B.VENDOR_CODE = @STRFIELD)
            )
            AND (@VendorIds        IS NULL OR B.VENDOR_CODE        IN (SELECT value FROM STRING_SPLIT(@VendorIds,',')))
            AND (@BuyerIds         IS NULL OR B.BUYER_ID           IN (SELECT value FROM STRING_SPLIT(@BuyerIds,',')))
            AND (@CategoryIds      IS NULL OR B.CATEGORY           IN (SELECT value FROM STRING_SPLIT(@CategoryIds,',')))
            AND (@ProductIds       IS NULL OR B.MC                 IN (SELECT value FROM STRING_SPLIT(@ProductIds,',')))
            AND (@InspectorIds     IS NULL OR A.INSPECTOR_EMP_CODE IN (SELECT value FROM STRING_SPLIT(@InspectorIds,',')))
            AND (@Mrp              IS NULL OR B.MRP BETWEEN @Mrp-10 AND @Mrp+10)
            AND (@PONumber         IS NULL OR B.PO_NUMBER LIKE '%'+@PONumber OR B.LINK_PO_NUMBER LIKE '%'+@PONumber)
            AND (@InspectionNumber IS NULL OR A.INSPECTION_NO LIKE '%'+@InspectionNumber)
			AND (@FromDate         IS NULL OR A.DATE_OF_INSPECTION >= @FromDate)
            AND (@ToDate           IS NULL OR A.DATE_OF_INSPECTION <  DATEADD(DAY, 1, @ToDate));


			CREATE NONCLUSTERED INDEX IX_IR_LIST_DATEOFINSPECTION_CANCEL ON #IR_LIST_CANCEL (QA_ASSIGNED_DOI);
			CREATE NONCLUSTERED INDEX IX_IR_LIST_CREATED_ON_CANCEL ON #IR_LIST_CANCEL (CREATED_ON);

			SELECT @TotalCount = COUNT(1) FROM #IR_LIST_CANCEL;

			 IF (@RequestType = 'REPORT')
			   INSERT INTO #IRF_LIST_CANCEL (POID,INSP_ID,DATE_OF_INSPECTION,CREATED_ON) 
			   SELECT POID,INSP_ID, QA_ASSIGNED_DOI, CREATED_ON FROM #IR_LIST_CANCEL ORDER BY QA_ASSIGNED_DOI DESC;

			IF (@RequestType = 'VIEW')
			    INSERT INTO #IRF_LIST_CANCEL (POID,INSP_ID,DATE_OF_INSPECTION,CREATED_ON)  
				SELECT POID,INSP_ID, QA_ASSIGNED_DOI, CREATED_ON
			    FROM #IR_LIST_CANCEL
			    ORDER BY CREATED_ON DESC
			    OFFSET (@PageNumber - 1) * @PageSize ROWS
			    FETCH NEXT @PageSize ROWS ONLY;

			----------------------------------------------------------------
			-- POD 
			----------------------------------------------------------------
			SELECT P.POID, STRING_AGG(ARTICLE + '~' + CAST(MRP AS VARCHAR(50)) + '/-', ' | ') WITHIN GROUP (ORDER BY ARTICLE) AS ARTICLE_NO
			INTO #POD_LIST_CANCEL
			FROM PODETAIL P
			WHERE EXISTS (SELECT 1 FROM #IRF_LIST_CANCEL IR WHERE IR.POID = P.POID)
			AND TRY_CAST(LINE_ITEM AS DECIMAL(18,2)) % 100 = 0
			GROUP BY P.POID; 
			----------------------------------------------------------------
			-- MAIN QUERY 
			----------------------------------------------------------------
			SELECT
			CASE
                WHEN ISNULL(B.BUYER_NAME,'') <> '' AND ISNULL(B.BUYER_ID,'') <> ''
                THEN B.BUYER_NAME + ' [ ' + B.BUYER_ID + ' ]'
                ELSE '-'
            END AS BUYER_NAME,
            B.PO_NUMBER,
            CONCAT
            (
                B.PO_NUMBER,
                CASE WHEN ISNULL(B.LINK_PO_NUMBER,'') <> '' THEN ' ~ ' + B.LINK_PO_NUMBER ELSE '' END
            ) AS PO_NUMBER_WITH_LINK_PO_NUMBER,
            B.LINK_PO_NUMBER,
			B.VENDOR_NAME + ' [ ' + B.VENDOR_CODE + ' ]' AS VENDOR,
            B.MC_TEXT AS DESCRIPTION,
            B.MRP,
            CASE
                WHEN ISNULL(B.BRAND_ID2,'') <> '' AND ISNULL(B.BRAND_ID,'') <> ''
                THEN B.BRAND_ID2 + ' [ ' + B.BRAND_ID + ' ]'
                ELSE '-'
            END AS BRAND_LABEL,
            B.COLOR,
            B.FIT,
            B.CATEGORY,
            CAST(B.TOTAL_QTY AS FLOAT) AS PO_QTY,
            B.APPARELS AS APPS_NON_APPS,
            B.FABRIC,
            B.MC,
            A.INSP_ID,
            A.POID,
            CONVERT(VARCHAR(11), A.DATE_OF_INSPECTION, 106) AS INSPECTION_DATE,
            IT.INSPECTION_TYPE AS TYPE_OF_INSPECTION,
            ISNULL(A.INSPECTION_NO,'NA') AS INSPECTION_REPORT_NO,
			CASE WHEN @CMD = 'GET_VENDOR_WISE_ALL_RECEIVED_PENDING_ONGOING_INSPECTIONS' THEN '----' ELSE
				 CASE
					WHEN ISNULL(A.INSPECTOR_EMP_CODE,'') <> '' AND ISNULL(INSP.EMP_NAME,'') <> ''
					THEN INSP.EMP_NAME + ' [ ' + A.INSPECTOR_EMP_CODE + ' ]'
					ELSE '-'
				 END 
			END AS INSPECTOR,
            ISNULL(PD.ARTICLE_NO,'---') AS ARTICLE_NO,
            CAST(A.OFFERED_QTY AS FLOAT) AS OFFERED_QTY,
            RM.REGION AS LOCATION,
            E.ADDRESS_LINE1 + ', ' + E.CITY + ', ' + E.REGION_DESCRIPTION + ', ' + E.PINCODE AS ADDRESS,
            E.CONTACT_PERSON AS CONTACT_NAME,
            E.MOBILE_NUMBERS AS CONTACT_NUMBER,
            CONVERT(VARCHAR(11), A.DATE_OF_INSPECTION, 106) AS DATE_OF_INSPECTION,
            A.ADDRESS_ID,
            A.CREATED_ON,
            A.LAST_UPDATED_ON,
            A.REGION_ID,
            CONVERT(VARCHAR(11), A.QA_ASSIGNED_DOI, 106) AS QA_ASSIGNED_DOI,
            A.INSPECTION_TYPE_ID,
            A.IS_DATE_ASSIGNED_BY_QA,
            A.IS_INSPECTOR_ASSIGNED,
            ISNULL(S.INSP_STATUS,'Created') AS INSP_REQ_STATUS,
            A.STATUS_CODE,
			A.DATE_OF_INSPECTION  AS DoI_Vendor ,
			A.QA_ASSIGNED_DOI AS DoI_For_QA,
			A.INSPECTOR_EMP_CODE
        FROM #IRF_LIST_CANCEL IR
		INNER JOIN INSPECTION_REQUESTS A ON IR.INSP_ID=A.INSP_ID
        INNER JOIN POHEADER B ON IR.POID = B.POID
        INNER JOIN MASTER_REGION RM ON A.REGION_ID = RM.REGION_ID
        INNER JOIN DBO.INSPECTION_REQUEST_STATUS S ON A.STATUS_CODE = S.INSP_STATUS_ID
        LEFT JOIN VENDOR_ADDRESS E ON A.ADDRESS_ID = E.ADDRESS_ID
        LEFT JOIN #POD_LIST_CANCEL PD ON A.POID = PD.POID
        LEFT JOIN USER_MASTER INSP ON A.INSPECTOR_EMP_CODE = INSP.EMP_CODE
        LEFT JOIN MASTER_INSPECTION_TYPE IT ON A.INSPECTION_TYPE_ID = IT.INSPECTION_TYPE_ID;

		--INSERT INTO [dbo].[TESTDESHBOARDLIST]([START_TIME],[INSP_IDS],[OUTPUT_TIME],[EXECUTION_TIME_IN_MS])
		--VALUES (@SDATE,@RequestType+' : CANCEL | Rows : '+ CAST(@TotalCount as VARCHAR) ,GETDATE(),DATEDIFF(MILLISECOND, @SDATE, GETDATE()))
		
		--Select * from TESTDESHBOARDLIST
    END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_UPDATE_CM_STATUS]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		Dinesh Baghel
-- Create date: 20 Jan 2026
-- Description:	Insert Vendor From Excel
-- =============================================
CREATE PROCEDURE [dbo].[SP_UPDATE_CM_STATUS]
	@USER_ID INT,
	@VENDOR_DETAILS TVP_Excel_CM_VendorsDtails READONLY,  
    @ERROR_CODE INT OUTPUT,             -- OUTPUT PARAMETER FOR ERROR CODE
    @ERROR_MESSAGE VARCHAR(500) OUTPUT -- OUTPUT PARAMETER FOR ERROR MESSAGE
AS
BEGIN
	BEGIN TRY
	
		-- SET OUTPUT PARAMETERS FOR SUCCESS
		SET @ERROR_CODE = 0;
		SET @ERROR_MESSAGE = 'SUCCESS';
		IF EXISTS (SELECT TOP 1 * FROM @VENDOR_DETAILS)
			BEGIN
				BEGIN TRANSACTION;
				MERGE VENODR_EXCEL_DETAILS AS TARGET
				USING ( SELECT VENDOR_CODE,	CM_STATUS FROM @VENDOR_DETAILS ) AS SOURCE
				ON TRIM(TARGET.VENDOR_CODE) = TRIM(SOURCE.VENDOR_CODE)

				WHEN MATCHED THEN
							UPDATE SET TARGET.CM_STATUS = SOURCE.CM_STATUS,
									   TARGET.CM_DATE = GETDATE(),
									   TARGET.CM_USER_ID =@USER_ID;
				COMMIT TRANSACTION;
			END

		
    END TRY
    BEGIN CATCH
       IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH;
END;


GO
/****** Object:  StoredProcedure [dbo].[SP_UPDATE_LINK_PO]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_UPDATE_LINK_PO]
(
    @INSPID INT,                   
    @LINK_PO_NUMBER VARCHAR(30),
    @USER_ID INT,                     
	@ERROR_CODE INT = 0 OUTPUT,             
    @ERROR_MESSAGE VARCHAR(500) = 'Success' OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
		SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Success';
		DECLARE @POID INT
        BEGIN TRANSACTION;

		

        IF EXISTS (SELECT TOP 1 * FROM INSPECTION_REQUESTS WHERE INSP_ID=@INSPID)
			BEGIN
				SELECT @POID=POID FROM INSPECTION_REQUESTS WITH (NOLOCK) WHERE INSP_ID=@INSPID
				UPDATE POHEADER SET LINK_PO_NUMBER = @LINK_PO_NUMBER, UPDATED_BY=@USER_ID, LAST_UPDATED_ON=GETDATE() WHERE POID=@POID
			END
        ELSE
			BEGIN
				RAISERROR (
					'PO not found.',
					16,
					1,
					 ''
				);
			END
	
        COMMIT TRANSACTION;
		
    END TRY

    BEGIN CATCH
		IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[SP_UPDATE_POHEADER]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_UPDATE_POHEADER]
(
    @POID INT OUTPUT,
    @PO_NUMBER VARCHAR(30),
    @FABRIC VARCHAR(255),
    @COLOR VARCHAR(100),
    @TOTAL_QTY DECIMAL(18,3),
    @APPARELS VARCHAR(50) = NULL,
    @CATEGORY VARCHAR(50) = NULL,
    @MC VARCHAR(50) = NULL,
    @MC_TEXT VARCHAR(250) = NULL,
    @MRP DECIMAL(18,3) = NULL,
    @BUYER_ID VARCHAR(20) = NULL,
    @BRAND_ID VARCHAR(250) = NULL,
    @BRAND_ID2 VARCHAR(250) = NULL,
    @FIT VARCHAR(250) = NULL,
    @VENDOR_NAME VARCHAR(100) = NULL,              -- NEW (E13)
    @BUYER_NAME VARCHAR(50) = NULL,                -- NEW (E13)
    @USER_ID INT,
    @RECORD_ID INT OUTPUT,
    @ERROR_CODE INT = 0 OUTPUT,
    @ERROR_MESSAGE VARCHAR(500) = 'Success' OUTPUT,
    @WARNING_MESSAGE VARCHAR(500) = NULL OUTPUT    -- NEW (quantity impact warning)
)
AS
BEGIN
    SET NOCOUNT ON;
 
    DECLARE @DB_PO_NUMBER VARCHAR(30), @OLD_TOTAL_QTY DECIMAL(18,3),
            @NORM_DB_PO VARCHAR(30), @NORM_SAP_PO VARCHAR(30),
            @NEW_LIMIT INT = 0, @OPEN_IR_QTY INT = 0, @PASSED_QTY INT = 0, @COMMITTED_QTY INT = 0,
            @LOG_OLD_VALUE VARCHAR(MAX), @LOG_NEW_VALUE VARCHAR(MAX);
 
    BEGIN TRY
        SET @ERROR_CODE = 0;
        SET @ERROR_MESSAGE = 'Success';
        SET @WARNING_MESSAGE = NULL;
        SET @RECORD_ID = 0;
 
        /* 1. The PO must already exist in QPS (N6) */
        IF (ISNULL(@POID, 0) <= 0)
            RAISERROR('PO %s cannot be synchronized because it is not saved in QPS (POID is missing).', 16, 1, @PO_NUMBER);
 
        SELECT @DB_PO_NUMBER = PO_NUMBER, @OLD_TOTAL_QTY = TOTAL_QTY
        FROM POHEADER WHERE POID = @POID;
 
        IF (@DB_PO_NUMBER IS NULL)
            RAISERROR('PO %s was not found in QPS for POID %d.', 16, 1, @PO_NUMBER, @POID);
 
        /* 2. SAP PO number must match the QPS PO number, ignoring spaces and leading zeros (N5) */
        SET @NORM_DB_PO  = LTRIM(RTRIM(@DB_PO_NUMBER));
        SET @NORM_SAP_PO = LTRIM(RTRIM(@PO_NUMBER));
        SET @NORM_DB_PO  = SUBSTRING(@NORM_DB_PO,  PATINDEX('%[^0]%', @NORM_DB_PO  + '.'), 30);
        SET @NORM_SAP_PO = SUBSTRING(@NORM_SAP_PO, PATINDEX('%[^0]%', @NORM_SAP_PO + '.'), 30);
 
        IF (@NORM_DB_PO <> @NORM_SAP_PO)
            RAISERROR('SAP returned PO %s, which does not match QPS PO %s. Sync stopped.', 16, 1, @PO_NUMBER, @DB_PO_NUMBER);
 
        /* 3. Never overwrite with a zero or negative quantity (N2) */
        IF (ISNULL(@TOTAL_QTY, 0) <= 0)
            RAISERROR('SAP returned zero quantity for PO %s. Sync stopped and the existing details are retained.', 16, 1, @PO_NUMBER);
 
        /* 4. Quantity impact check - the sync is applied, but a warning is returned (E2, E3, E16, E17) */
        SELECT @OPEN_IR_QTY = ISNULL(SUM(OFFERED_QTY), 0)
        FROM INSPECTION_REQUESTS
        WHERE POID = @POID AND STATUS_CODE NOT IN (7, 9, 10);
 
        SELECT @PASSED_QTY = ISNULL(SUM(B.OFFERED_QTY), 0)
        FROM INSPECTION_REQUESTS A
        INNER JOIN INSPECTIONS B ON A.INSP_ID = B.INSPECTION_ID
        WHERE A.POID = @POID AND A.STATUS_CODE = 7 AND B.INSPECTION_RESULT = 1;
 
        SET @COMMITTED_QTY = @OPEN_IR_QTY + @PASSED_QTY;
        SET @NEW_LIMIT = CEILING(@TOTAL_QTY * 1.10);
 
        IF (@NEW_LIMIT < @COMMITTED_QTY)
            SET @WARNING_MESSAGE = CONCAT('WARNING: PO quantity changed in SAP from ', CAST(@OLD_TOTAL_QTY AS INT),
                ' to ', CAST(@TOTAL_QTY AS INT), '. Allowed quantity (110%) is ', @NEW_LIMIT, ' but ', @COMMITTED_QTY,
                ' is already offered or passed (open ', @OPEN_IR_QTY, ', passed ', @PASSED_QTY,
                '). Open requests must be reduced by ', @COMMITTED_QTY - @NEW_LIMIT, '.');
 
        /* 5. Audit values (same format as before, plus the new fields) */
        SELECT @LOG_OLD_VALUE =
              'PO_NUMBER = ' + ISNULL(CAST(PO_NUMBER AS VARCHAR(MAX)), '')
            + ', FABRIC = ' + ISNULL(CAST(FABRIC AS VARCHAR(MAX)), '')
            + ', COLOR = ' + ISNULL(CAST(COLOR AS VARCHAR(MAX)), '')
            + ', TOTAL_QTY = ' + ISNULL(CAST(TOTAL_QTY AS VARCHAR(MAX)), '')
            + ', APPARELS = ' + ISNULL(CAST(APPARELS AS VARCHAR(MAX)), '')
            + ', CATEGORY = ' + ISNULL(CAST(CATEGORY AS VARCHAR(MAX)), '')
            + ', MC = ' + ISNULL(CAST(MC AS VARCHAR(MAX)), '')
            + ', BUYER_ID = ' + ISNULL(CAST(BUYER_ID AS VARCHAR(MAX)), '')
            + ', MC_TEXT = ' + ISNULL(CAST(MC_TEXT AS VARCHAR(MAX)), '')
            + ', MRP = ' + ISNULL(CAST(MRP AS VARCHAR(MAX)), '')
            + ', BRAND_ID = ' + ISNULL(CAST(BRAND_ID AS VARCHAR(MAX)), '')
            + ', BRAND_ID2 = ' + ISNULL(CAST(BRAND_ID2 AS VARCHAR(MAX)), '')
            + ', FIT = ' + ISNULL(CAST(FIT AS VARCHAR(MAX)), '')
            + ', VENDOR_NAME = ' + ISNULL(CAST(VENDOR_NAME AS VARCHAR(MAX)), '')
            + ', BUYER_NAME = ' + ISNULL(CAST(BUYER_NAME AS VARCHAR(MAX)), '')
            + ', UPDATED_BY = ' + ISNULL(CAST((CASE WHEN ISNULL(UPDATED_BY, 0) = 0 THEN CREATED_BY ELSE UPDATED_BY END) AS VARCHAR(MAX)), '')
            + ', LAST_UPDATED_ON = ' + ISNULL(CONVERT(VARCHAR(19), LAST_UPDATED_ON, 120), '')
        FROM POHEADER WHERE POID = @POID;
 
        SET @LOG_NEW_VALUE =
              'PO_NUMBER = ' + ISNULL(CAST(@PO_NUMBER AS VARCHAR(MAX)), '')
            + ', FABRIC = ' + ISNULL(CAST(@FABRIC AS VARCHAR(MAX)), '')
            + ', COLOR = ' + ISNULL(CAST(@COLOR AS VARCHAR(MAX)), '')
            + ', TOTAL_QTY = ' + ISNULL(CAST(@TOTAL_QTY AS VARCHAR(MAX)), '')
            + ', APPARELS = ' + ISNULL(CAST(@APPARELS AS VARCHAR(MAX)), '')
            + ', CATEGORY = ' + ISNULL(CAST(@CATEGORY AS VARCHAR(MAX)), '')
            + ', MC = ' + ISNULL(CAST(@MC AS VARCHAR(MAX)), '')
            + ', BUYER_ID = ' + ISNULL(CAST(@BUYER_ID AS VARCHAR(MAX)), '')
            + ', MC_TEXT = ' + ISNULL(CAST(@MC_TEXT AS VARCHAR(MAX)), '')
            + ', MRP = ' + ISNULL(CAST(@MRP AS VARCHAR(MAX)), '')
            + ', BRAND_ID = ' + ISNULL(CAST(@BRAND_ID AS VARCHAR(MAX)), '')
            + ', BRAND_ID2 = ' + ISNULL(CAST(@BRAND_ID2 AS VARCHAR(MAX)), '')
            + ', FIT = ' + ISNULL(CAST(@FIT AS VARCHAR(MAX)), '')
            + ', VENDOR_NAME = ' + ISNULL(CAST(@VENDOR_NAME AS VARCHAR(MAX)), '')
            + ', BUYER_NAME = ' + ISNULL(CAST(@BUYER_NAME AS VARCHAR(MAX)), '')
            + ', UPDATED_BY = ' + ISNULL(CAST(@USER_ID AS VARCHAR(MAX)), '')
            + ', LAST_UPDATED_ON = ' + CONVERT(VARCHAR(19), GETDATE(), 120)
            + ISNULL(', ' + @WARNING_MESSAGE, '');
 
        /* 6. Apply the update */
        BEGIN TRANSACTION;
 
        UPDATE POHEADER SET
            FABRIC          = @FABRIC,
            COLOR           = @COLOR,
            TOTAL_QTY       = @TOTAL_QTY,
            APPARELS        = @APPARELS,
            CATEGORY        = @CATEGORY,
            MC              = @MC,
            BUYER_ID        = @BUYER_ID,
            MC_TEXT         = @MC_TEXT,
            MRP             = @MRP,
            BRAND_ID        = @BRAND_ID,
            BRAND_ID2       = @BRAND_ID2,
            FIT             = @FIT,
            VENDOR_NAME     = ISNULL(NULLIF(LTRIM(RTRIM(@VENDOR_NAME)), ''), VENDOR_NAME),
            BUYER_NAME      = ISNULL(NULLIF(LTRIM(RTRIM(@BUYER_NAME)), ''), BUYER_NAME),
            UPDATED_BY      = @USER_ID,
            LAST_UPDATED_ON = GETDATE()
        WHERE POID = @POID;
 
        IF (@@ROWCOUNT = 0)
            RAISERROR('PO %s was not updated. Please retry.', 16, 1, @PO_NUMBER);
 
        INSERT INTO [dbo].[SPTRACE]([SP_OLDVALUES], [SP_NEWVALUES]) VALUES (@LOG_OLD_VALUE, @LOG_NEW_VALUE);
 
        SET @RECORD_ID = @POID;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
 
        SET @ERROR_CODE = ERROR_NUMBER();
        SET @ERROR_MESSAGE = ERROR_MESSAGE();
        SET @WARNING_MESSAGE = NULL;
    END CATCH
END

GO
/****** Object:  StoredProcedure [dbo].[usp_Inspection_Search]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[usp_Inspection_Search]
(
	@CMD VARCHAR(100),
	@STRFIELD VARCHAR(50),
    @VendorIds      dbo.IdListType READONLY,
    @BuyerIds       dbo.IdListType READONLY,
    @CategoryIds    dbo.IdListType READONLY,
    @ProductIds     dbo.IdListType READONLY,
    @InspectorIds   dbo.IdListType READONLY,
    @Mrp            NVARCHAR(50)  = NULL,
    @FromDate       DATE          = NULL,
    @ToDate         DATE          = NULL,
    @PageNumber     INT           = 1,
    @PageSize       INT           = 20,
    @TotalCount     INT OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;
	IF(@CMD='GET_OVER_ALL_INSPECTION_REPORT')
		BEGIN
			SELECT A.INSP_ID, A.POID,B.PO_NUMBER,
			ISNULL(B.LINK_PO_NUMBER,'') as LINK_PO_NUMBER,B.VENDOR_CODE,B.VENDOR_NAME,B.FABRIC,B.COLOR,B.TOTAL_QTY , A.OFFERED_QTY,A.DATE_OF_INSPECTION,
			E.ADDRESS_LINE1 + E.CITY + E.REGION_DESCRIPTION+ E.PINCODE as LOCATION, A.ADDRESS_ID,
			A.CREATED_ON, C.VENDOR_NAME as CREATED_BY, D.VENDOR_NAME as UPDATED_BY, A.LAST_UPDATED_ON
			,A.REGION_ID,A.QA_ASSIGNED_DOI,
			A.INSPECTION_TYPE_ID,B.APPARELS,A.INSPECTION_NO,B.CATEGORY,B.BUYER_NAME,B.BUYER_ID,
			CONVERT(int, A.INSPECTOR_EMP_CODE) as INSPECTOR_EMP_CODE, ISNULL( INSP.EMP_NAME ,'') as INSPECTOR ,  ISNULL(A.INSPECTION_NO,'NA') INSPECTION_NO ,A.IS_DATE_ASSIGNED_BY_QA, A.IS_INSPECTOR_ASSIGNED,
			ISNULL(S.INSP_STATUS,'Created') as INSP_REQ_STATUS, A.STATUS_CODE, case when A.STATUS_CODE=7 then P.PASSFAIL else ''end as INSP_RESULT,B.MC,B.MC_TEXT, B.MRP, B.BRAND_ID, B.BRAND_ID2,
			ZIPPER_RPT_NO,ZIPPER_STATUS,ZIPPER_APPROVED_BY,ZIPPER_APPROVED_DATE,I.FIT,COMM_APPROVAL_DOC,DEBIT_AMOUNT,ADMIN_REMARK,
			I.DATE_OF_COMPLETION,I.ABORTIVE_REASON_IDS,I.OTHER_ABORTIVE_REASON ,I.AMT_TRAVELLING ,I.SELECTED_BAG_CARTONS_NO 
			INTO #Filtered
			FROM [dbo].[INSPECTION_REQUESTS] A 
			left join DBO.POHEADER B on A.POID=B.POID
			left join [dbo].[VENDORS_MASTER] C on A.CREATED_BY=C.VENDOR_ID
			left join [dbo].[VENDORS_MASTER] D on A.UPDATED_BY=D.VENDOR_ID
			left join DBO.VENDOR_ADDRESS E on A.ADDRESS_ID=E.ADDRESS_ID
			left join DBO.INSPECTION_REQUEST_STATUS S on A.STATUS_CODE=S.INSP_STATUS_ID 
			left join INSPECTIONS I on A.INSP_ID=I.INSPECTION_ID
			left join MASTER_PASSFAIL P on I.INSPECTION_RESULT=P.PASSFAIL_ID
			left join USER_MASTER INSP on A.INSPECTOR_EMP_CODE=INSP.EMP_CODE
			WHERE A.STATUS_CODE not in (7,9,10) 
			AND  A.REGION_ID IN (SELECT value FROM STRING_SPLIT((SELECT REGION_IDS  FROM USER_MASTER WHERE EMP_CODE=@STRFIELD), ','))
			AND (NOT EXISTS (SELECT 1 FROM @VendorIds)    OR B.VENDOR_CODE    IN (SELECT Id FROM @VendorIds))
            AND (NOT EXISTS (SELECT 1 FROM @BuyerIds)     OR B.BUYER_ID     IN (SELECT Id FROM @BuyerIds))
            AND (NOT EXISTS (SELECT 1 FROM @CategoryIds)  OR B.CATEGORY  IN (SELECT Id FROM @CategoryIds))
            AND (NOT EXISTS (SELECT 1 FROM @ProductIds)   OR B.MC   IN (SELECT Id FROM @ProductIds))
            AND (NOT EXISTS (SELECT 1 FROM @InspectorIds) OR A.INSPECTOR_EMP_CODE IN (SELECT Id FROM @InspectorIds))
            AND (@Mrp IS NULL OR B.MRP = @Mrp)
            AND (@FromDate IS NULL OR A.DATE_OF_INSPECTION >= @FromDate)
            AND (@ToDate   IS NULL OR A.DATE_OF_INSPECTION <  DATEADD(DAY, 1, @ToDate))

			SELECT @TotalCount = COUNT(*) FROM #Filtered;

			SELECT *
			FROM #Filtered
			ORDER BY DATE_OF_INSPECTION DESC
			OFFSET (@PageNumber - 1) * @PageSize ROWS
			FETCH NEXT @PageSize ROWS ONLY;

			DROP TABLE #Filtered;
		END

END
GO
/****** Object:  Trigger [dbo].[TRG_INSPECTION_AUDIT_JSON]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [dbo].[TRG_INSPECTION_AUDIT_JSON]
ON [dbo].[INSPECTION_REQUESTS]
FOR UPDATE, INSERT, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    -------------------------------------------------------------------
    -- INSERT
    -------------------------------------------------------------------
    INSERT INTO INSPECTION_AUDIT_JSON (POID, CHANGE_HISTORY)
    SELECT 
        i.POID,
        (
            SELECT
                i.INSP_ID AS insp_id,
                'INSERT' AS action,
                i.CREATED_BY AS changed_by,
                GETDATE() AS changed_on,
				 (
                    SELECT 
                        v.column_name,
                        v.old_value,
                        v.new_value
                    FROM
                    (
                        VALUES
                            ('OFFERED_QTY', NULL, CAST(i.OFFERED_QTY AS NVARCHAR(100))),
                            ('DATE_OF_INSPECTION', NULL, CONVERT(NVARCHAR(30), i.DATE_OF_INSPECTION, 120)),
                            ('ADDRESS_ID', NULL, CAST(i.ADDRESS_ID AS NVARCHAR(100))),
							('CREATED_ON', NULL, CONVERT(NVARCHAR(30), i.CREATED_ON, 120)),
                            ('CREATED_BY', NULL, CAST(i.CREATED_BY AS NVARCHAR(100))),
                            ('LAST_UPDATED_ON', NULL, CONVERT(NVARCHAR(30), i.LAST_UPDATED_ON, 120)),
                            ('UPDATED_BY', NULL, CAST(i.UPDATED_BY AS NVARCHAR(100))),
							('REGION_ID', NULL, CAST(i.REGION_ID AS NVARCHAR(100))),
							('STATUS_CODE', NULL, CAST(i.STATUS_CODE AS NVARCHAR(100))),
							('INSPECTION_TYPE_ID', NULL, CAST(i.INSPECTION_TYPE_ID AS NVARCHAR(100)))
						
							
                    ) AS v(column_name, old_value, new_value)
                    WHERE v.old_value IS NULL AND v.new_value IS NOT NULL
                       OR v.old_value IS NOT NULL AND v.new_value IS NULL
                       OR v.old_value <> v.new_value
                    FOR JSON PATH
                ) AS changes
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        )
    FROM inserted i
    WHERE NOT EXISTS (SELECT 1 FROM deleted);

    -------------------------------------------------------------------
    -- DELETE
    -------------------------------------------------------------------
    INSERT INTO INSPECTION_AUDIT_JSON (POID, CHANGE_HISTORY)
    SELECT 
        d.POID,
        (
            SELECT
                d.INSP_ID AS insp_id,
                'DELETE' AS action,
                d.UPDATED_BY AS changed_by,
                GETDATE() AS changed_on,
                --(
                --    SELECT 
                --        'DELETED' AS status
                --    FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
                --) AS details,
				 (
                    SELECT 
                        v.column_name,
                        v.old_value,
                        v.new_value
                    FROM
                    (
                        VALUES
                            ('OFFERED_QTY', CAST(d.OFFERED_QTY AS NVARCHAR(100)), NULL),
                            ('DATE_OF_INSPECTION', CONVERT(NVARCHAR(30), d.DATE_OF_INSPECTION, 120), NULL),
                            ('ADDRESS_ID', CAST(d.ADDRESS_ID AS NVARCHAR(100)), NULL),
							('CREATED_ON', CONVERT(NVARCHAR(30), d.CREATED_ON, 120), NULL),
                            ('CREATED_BY', CAST(d.CREATED_BY AS NVARCHAR(100)), NULL),
                            ('LAST_UPDATED_ON', CONVERT(NVARCHAR(30), d.LAST_UPDATED_ON, 120), NULL),
                            ('UPDATED_BY', CAST(d.UPDATED_BY AS NVARCHAR(100)), NULL),
							('REGION_ID', CAST(d.REGION_ID AS NVARCHAR(100)), NULL),
							('QA_ASSIGNED_DOI', CONVERT(NVARCHAR(30), d.QA_ASSIGNED_DOI, 120), NULL),
							('INSPECTOR_EMP_CODE', CAST(d.INSPECTOR_EMP_CODE AS NVARCHAR(100)), NULL),
							('IS_DATE_ASSIGNED_BY_QA', CAST(d.IS_DATE_ASSIGNED_BY_QA AS NVARCHAR(100)), NULL),
							('IS_INSPECTOR_ASSIGNED', CAST(d.IS_INSPECTOR_ASSIGNED AS NVARCHAR(100)), NULL),
							('STATUS_CODE', CAST(d.STATUS_CODE AS NVARCHAR(100)), NULL),
							('INSPECTION_TYPE_ID', CAST(d.INSPECTION_TYPE_ID AS NVARCHAR(100)), NULL)
							
                    ) AS v(column_name, old_value, new_value)
                    WHERE v.old_value IS NULL AND v.new_value IS NOT NULL
                       OR v.old_value IS NOT NULL AND v.new_value IS NULL
                       OR v.old_value <> v.new_value
                    FOR JSON PATH
                ) AS changes
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        )
    FROM deleted d
    WHERE NOT EXISTS (SELECT 1 FROM inserted);

    -------------------------------------------------------------------
    -- UPDATE (diff of changed columns only)
    -------------------------------------------------------------------
    INSERT INTO INSPECTION_AUDIT_JSON (POID, CHANGE_HISTORY)
    SELECT 
        i.POID,
        (
            SELECT
                i.INSP_ID AS insp_id,
                'UPDATE' AS action,
                i.UPDATED_BY AS changed_by,
                GETDATE() AS changed_on,
                (
                    SELECT 
                        v.column_name,
                        v.old_value,
                        v.new_value
                    FROM
                    (
                        VALUES
                            ('OFFERED_QTY', CAST(d.OFFERED_QTY AS NVARCHAR(100)), CAST(i.OFFERED_QTY AS NVARCHAR(100))),
                            ('DATE_OF_INSPECTION', CONVERT(NVARCHAR(30), d.DATE_OF_INSPECTION, 120), CONVERT(NVARCHAR(30), i.DATE_OF_INSPECTION, 120)),
                            ('ADDRESS_ID', CAST(d.ADDRESS_ID AS NVARCHAR(100)), CAST(i.ADDRESS_ID AS NVARCHAR(100))),
                            ('LAST_UPDATED_ON', CONVERT(NVARCHAR(30), d.LAST_UPDATED_ON, 120), CONVERT(NVARCHAR(30), i.LAST_UPDATED_ON, 120)),
                            ('UPDATED_BY', CAST(d.UPDATED_BY AS NVARCHAR(100)), CAST(i.UPDATED_BY AS NVARCHAR(100))),
							('REGION_ID', CAST(d.REGION_ID AS NVARCHAR(100)), CAST(i.REGION_ID AS NVARCHAR(100))),
							('QA_ASSIGNED_DOI', CONVERT(NVARCHAR(30), d.QA_ASSIGNED_DOI, 120), CONVERT(NVARCHAR(30), i.QA_ASSIGNED_DOI, 120)),
							('INSPECTOR_EMP_CODE', CAST(d.INSPECTOR_EMP_CODE AS NVARCHAR(100)), CAST(i.INSPECTOR_EMP_CODE AS NVARCHAR(100))),
							('IS_DATE_ASSIGNED_BY_QA', CAST(d.IS_DATE_ASSIGNED_BY_QA AS NVARCHAR(100)),  CAST(i.IS_DATE_ASSIGNED_BY_QA AS NVARCHAR(100))),
							('IS_INSPECTOR_ASSIGNED', CAST(d.IS_INSPECTOR_ASSIGNED AS NVARCHAR(100)), CAST(i.IS_INSPECTOR_ASSIGNED AS NVARCHAR(100))),
							('STATUS_CODE', CAST(d.STATUS_CODE AS NVARCHAR(100)),CAST(i.STATUS_CODE AS NVARCHAR(100))),
							('INSPECTION_TYPE_ID', CAST(d.INSPECTION_TYPE_ID AS NVARCHAR(100)),CAST(i.INSPECTION_TYPE_ID AS NVARCHAR(100)))
						
                    ) AS v(column_name, old_value, new_value)
                    WHERE v.old_value IS NULL AND v.new_value IS NOT NULL
                       OR v.old_value IS NOT NULL AND v.new_value IS NULL
                       OR v.old_value <> v.new_value
                    FOR JSON PATH
                ) AS changes
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        )
    FROM inserted i
    INNER JOIN deleted d ON i.INSP_ID = d.INSP_ID;
END;


