							('FIT', NULL, i.FIT ),
							('COMM_APPROVAL_DOC', NULL,i.COMM_APPROVAL_DOC ),
							('DEBIT_AMOUNT', NULL, CAST(i.DEBIT_AMOUNT AS NVARCHAR(13)) ),
							('ADMIN_REMARK', NULL, i.ADMIN_REMARK )
							
							
                    ) AS v(column_name, old_value, new_value)
                    WHERE v.old_value IS NULL AND v.new_value IS NOT NULL
                       OR v.old_value IS NOT NULL AND v.new_value IS NULL
                       OR ISNULL(v.old_value,'') <> ISNULL(v.new_value,'')
                    FOR JSON PATH
                ) AS CHANGES
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        )
    FROM inserted i
    WHERE NOT EXISTS (SELECT 1 FROM deleted) ;


    -------------------------------------------------------------------
