							('INLINE_DONE', CAST(i.INLINE_DONE AS NVARCHAR(100)), NULL),
                            ('PACKING_LIST', CAST(i.PACKING_LIST AS NVARCHAR(100)), NULL),
                            ('PPS_RELEASE_DATE', CONVERT(NVARCHAR(30), i.PPS_RELEASE_DATE, 120), NULL),
							('PPS_EXPIRY_DATE', CONVERT(NVARCHAR(30), i.PPS_EXPIRY_DATE, 120), NULL),
							('FIBER_CONTENT_ON_PO',i.FIBER_CONTENT_ON_PO , NULL),
							('FIBER_CONTENT_ON_TEST_REPORT', i.FIBER_CONTENT_ON_TEST_REPORT, NULL),
							('FIBER_CONTENT_ON_WC', i.FIBER_CONTENT_ON_WC, NULL),
							('GSM_ON_PO', i.GSM_ON_PO, NULL),
							('GSM_ON_TEST_REPORT',i.GSM_ON_TEST_REPORT, NULL ),
							('GSM_ON_BULK',i.GSM_ON_BULK, NULL ),
							('MEASUREMENT_SAMPLE_SIZE', CAST(i.MEASUREMENT_SAMPLE_SIZE AS NVARCHAR(100)), NULL),
							('MEASUREMENT_ATTACHMENT',i.MEASUREMENT_ATTACHMENT, NULL ),
