							('GPT_ELASTIC_APPROVED_DATE', CONVERT(NVARCHAR(30),i.GPT_ELASTIC_APPROVED_DATE, 120) , NULL),
							('CONFORMITY_SIZE',i.CONFORMITY_SIZE, NULL ),
							('CONFORMITY_SIZE_STATUS', CAST(i.CONFORMITY_SIZE_STATUS AS NVARCHAR(2)), NULL ),
							('CONFORMITY_PREPACK', i.CONFORMITY_PREPACK, NULL ),
							('CONFORMITY_PREPACK_STATUS',CAST(i.CONFORMITY_PREPACK_STATUS AS NVARCHAR(2)), NULL ),
							('EMBROIDERY_PF', CAST(i.EMBROIDERY_PF  AS NVARCHAR(2)), NULL ),
							('ACCESSORIES_PF', CAST(i.ACCESSORIES_PF AS NVARCHAR(2)), NULL ),
							('BARCODE_PF',CAST(i.BARCODE_PF AS NVARCHAR(2)), NULL ),
							('NO_PLASTIC_PF',CAST(i.NO_PLASTIC_PF AS NVARCHAR(2)) , NULL),
							('BOGO_PF', CAST(i.BOGO_PF AS NVARCHAR(2)), NULL ),
							('THREAD_YN',CAST(i.THREAD_YN AS NVARCHAR(2)) , NULL),
							('BUTTON_YN', CAST(i.BUTTON_YN AS NVARCHAR(2)), NULL ),
