							('MEASUREMENT_SAMPLE_QTY', CAST(i.MEASUREMENT_SAMPLE_QTY AS NVARCHAR(10)) , NULL),

							('ZIPPER_RPT_NO',i.ZIPPER_RPT_NO, NULL ),
							('ZIPPER_STATUS', CAST(i.ZIPPER_STATUS AS NVARCHAR(2)), NULL ),
							('ZIPPER_APPROVED_BY',i.ZIPPER_APPROVED_BY, NULL ),
							('ZIPPER_APPROVED_DATE', CONVERT(NVARCHAR(30), i.ZIPPER_APPROVED_DATE, 120), NULL ),
							('FIT', i.FIT, NULL ),
							('COMM_APPROVAL_DOC',i.COMM_APPROVAL_DOC, NULL ),
