                    ) AS v(column_name, old_value, new_value)
                    WHERE v.old_value IS NULL AND v.new_value IS NOT NULL
                       OR v.old_value IS NOT NULL AND v.new_value IS NULL
                       OR ISNULL(v.old_value,'') <> ISNULL(v.new_value,'')
                    FOR JSON PATH
                ) AS CHANGES
            FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
        )
    FROM deleted i
    WHERE NOT EXISTS (SELECT 1 FROM inserted);

    -------------------------------------------------------------------
    -- UPDATE (diff of changed columns only)
    -------------------------------------------------------------------

	/* 
	LOGIC:
	1. If Auto Save (IS_COMPLETE = 0)
	   -> Update existing latest audit row for same inspection.
	2. If Final Submit (IS_COMPLETE = 1)
	   -> Insert new audit trail row.
	*/
	DECLARE @CHANGE_DATA TABLE
	(
	    INSPECT_ID INT,
	    IS_COMPLETE BIT,
	    CHANGE_HISTORY NVARCHAR(MAX)
	);
	
	INSERT INTO @CHANGE_DATA
	(
	    INSPECT_ID,
	    IS_COMPLETE,
	    CHANGE_HISTORY
	)
	SELECT 
		i.INSPECT_ID AS INSPECT_ID,
		ISNULL(i.IS_COMPLETE,0) AS IS_COMPLETE,
		(
			SELECT
				i.INSPECT_ID AS INSPECTION_ID,
				CASE 
					WHEN ISNULL(i.IS_COMPLETE,0) = 1 THEN 'FINAL_SUBMIT'
					ELSE 'AUTO_SAVE'
				END AS ACTION,
				i.MODIFIED_BY AS ACTION_BY,
				GETDATE() AS ACTION_ON,
				(
					SELECT 
						v.column_name,
						v.old_value,
						v.new_value
					FROM
					(
						VALUES
						('INSPECTION_ID', CAST(d.INSPECTION_ID AS NVARCHAR(100)), CAST(i.INSPECTION_ID AS NVARCHAR(100))),
                        ('INSPECTOR_CODE', d.INSPECTOR_CODE, i.INSPECTOR_CODE),
                        ('OFFERED_QTY', CAST(d.OFFERED_QTY AS NVARCHAR(100)), CAST(i.OFFERED_QTY AS NVARCHAR(100))),
						('GPT_NO', d.GPT_NO, i.GPT_NO),
                        ('GPT_STATUS', CAST(d.GPT_STATUS AS NVARCHAR(100)), CAST(i.GPT_STATUS AS NVARCHAR(100))),
                        ('GPT_APPROVED_BY', d.GPT_APPROVED_BY, i.GPT_APPROVED_BY),
						('GPT_APPROVED_DATE', CONVERT(NVARCHAR(30), d.GPT_APPROVED_DATE, 120), CONVERT(NVARCHAR(30), i.GPT_APPROVED_DATE, 120)),
                        ('NO_OF_BAGS_CARTONS_QTY', CAST(d.NO_OF_BAGS_CARTONS_QTY AS NVARCHAR(100)), CAST(i.NO_OF_BAGS_CARTONS_QTY AS NVARCHAR(100))),
						('NO_OF_BAGS_CARTONS_UNIT', CAST(d.NO_OF_BAGS_CARTONS_UNIT AS NVARCHAR(100)), CAST(i.NO_OF_BAGS_CARTONS_UNIT AS NVARCHAR(100))),
						('PACKING_STATUS', CAST(d.PACKING_STATUS AS NVARCHAR(100)), CAST(i.PACKING_STATUS AS NVARCHAR(100))),
						('INLINE_DONE', CAST(d.INLINE_DONE AS NVARCHAR(100)), CAST(i.INLINE_DONE AS NVARCHAR(100))),
                        ('PACKING_LIST', CAST(d.PACKING_LIST AS NVARCHAR(100)), CAST(i.PACKING_LIST AS NVARCHAR(100))),
                        ('PPS_RELEASE_DATE', CONVERT(NVARCHAR(30), d.PPS_RELEASE_DATE, 120), CONVERT(NVARCHAR(30), i.PPS_RELEASE_DATE, 120)),
						('PPS_EXPIRY_DATE', CONVERT(NVARCHAR(30), d.PPS_EXPIRY_DATE, 120), CONVERT(NVARCHAR(30), i.PPS_EXPIRY_DATE, 120)),
						('FIBER_CONTENT_ON_PO', d.FIBER_CONTENT_ON_PO,i.FIBER_CONTENT_ON_PO ),
						('FIBER_CONTENT_ON_TEST_REPORT', d.FIBER_CONTENT_ON_TEST_REPORT, i.FIBER_CONTENT_ON_TEST_REPORT),
						('FIBER_CONTENT_ON_WC', d.FIBER_CONTENT_ON_WC, i.FIBER_CONTENT_ON_WC),
						('GSM_ON_PO', d.GSM_ON_PO, i.GSM_ON_PO),
						('GSM_ON_TEST_REPORT', d.GSM_ON_TEST_REPORT,i.GSM_ON_TEST_REPORT ),
						('GSM_ON_BULK', d.GSM_ON_BULK ,i.GSM_ON_BULK ),
						('MEASUREMENT_SAMPLE_SIZE', CAST(d.MEASUREMENT_SAMPLE_SIZE AS NVARCHAR(100)), CAST(i.MEASUREMENT_SAMPLE_SIZE AS NVARCHAR(100))),
						('MEASUREMENT_ATTACHMENT', d.MEASUREMENT_ATTACHMENT ,i.MEASUREMENT_ATTACHMENT ),
						('NO_OF_CHECK', CAST(d.NO_OF_CHECK AS NVARCHAR(100)), CAST(i.NO_OF_CHECK AS NVARCHAR(100))),
						('NO_OF_CHECK_UNIT', CAST(d.NO_OF_CHECK_UNIT AS NVARCHAR(100)), CAST(i.NO_OF_CHECK_UNIT AS NVARCHAR(100))),
						('NO_OF_PREPACK_CHECK', CAST(d.NO_OF_PREPACK_CHECK AS NVARCHAR(100)), CAST(i.NO_OF_PREPACK_CHECK AS NVARCHAR(100))),
						('WORKMANSHIP', d.MEASUREMENT_ATTACHMENT,i.MEASUREMENT_ATTACHMENT ),
						('AQL_ID', CAST(d.AQL_ID AS NVARCHAR(100)), CAST(i.AQL_ID AS NVARCHAR(100))),
						('DEFECTS_STATUS', CAST(d.DEFECTS_STATUS AS NVARCHAR(100)), CAST(i.DEFECTS_STATUS AS NVARCHAR(100))),
						('INSPECTION_RESULT', CAST(d.INSPECTION_RESULT AS NVARCHAR(100)), CAST(i.INSPECTION_RESULT AS NVARCHAR(100))),
						('REMARK_COMMENT', d.REMARK_COMMENT,i.REMARK_COMMENT ),
						('NOTE', d.NOTE,i.NOTE ),
						('NAME_OF_FACTORY_REPRESENTATIVE', d.NAME_OF_FACTORY_REPRESENTATIVE,i.NAME_OF_FACTORY_REPRESENTATIVE ),
						('TEST_REPORT_ATTACHMENT', d.TEST_REPORT_ATTACHMENT,i.TEST_REPORT_ATTACHMENT ),
						('GEN_ATTACHMENT_FIRST', d.GEN_ATTACHMENT_FIRST,i.GEN_ATTACHMENT_FIRST ),
						('GEN_ATTACHMENT_SECOND', d.GEN_ATTACHMENT_SECOND,i.GEN_ATTACHMENT_SECOND ),
						('IS_COMPLETE', CAST(d.IS_COMPLETE AS NVARCHAR(100)), CAST(i.IS_COMPLETE AS NVARCHAR(100))),
						('CREATED_BY', CAST(d.CREATED_BY AS NVARCHAR(100)), CAST(i.CREATED_BY AS NVARCHAR(100))),
						('CREATED_DATE', CONVERT(NVARCHAR(30), d.CREATED_DATE, 120), CONVERT(NVARCHAR(30), i.CREATED_DATE, 120)),
						('MODIFIED_BY', CAST(d.MODIFIED_BY AS NVARCHAR(100)), CAST(i.MODIFIED_BY AS NVARCHAR(100))),
						('MODIFIED_DATE', CONVERT(NVARCHAR(30), d.MODIFIED_DATE, 120), CONVERT(NVARCHAR(30), i.MODIFIED_DATE, 120)),
						('RESEAN_FOR_FAIL',  CAST(d.RESEAN_FOR_FAIL AS NVARCHAR(100)), CAST(i.RESEAN_FOR_FAIL AS NVARCHAR(100))),
						('MFG_DATE', CONVERT(NVARCHAR(30), d.MFG_DATE, 120), CONVERT(NVARCHAR(30), i.MFG_DATE, 120)),
						('SEASON', d.SEASON,i.SEASON ),
                        ('COLOR_CODE', CAST(d.COLOR_CODE AS NVARCHAR(100)), CAST(i.COLOR_CODE AS NVARCHAR(100))),
						('AREA_OF_FAIL_GPTR', d.AREA_OF_FAIL_GPTR,i.AREA_OF_FAIL_GPTR),
                        ('GPT_COMM_APPROVAL_DATE', CONVERT(NVARCHAR(30), d.GPT_COMM_APPROVAL_DATE, 120), CONVERT(NVARCHAR(30), i.GPT_COMM_APPROVAL_DATE, 120)),
                        ('GPT_COMM_APPROVED_BY', d.GPT_COMM_APPROVED_BY,i.GPT_COMM_APPROVED_BY),
						('DATE_OF_COMPLETION', CONVERT(NVARCHAR(30), d.DATE_OF_COMPLETION, 120), CONVERT(NVARCHAR(30), i.DATE_OF_COMPLETION, 120)),
						('IS_EDIT_BY_ADMIN',  CAST(d.IS_EDIT_BY_ADMIN AS NVARCHAR(100)), CAST(i.IS_EDIT_BY_ADMIN AS NVARCHAR(100))),

						('GPT_ELASTIC_NO', d.GPT_ELASTIC_NO, i.GPT_ELASTIC_NO  ),
						('GPT_ELASTIC_STATUS', CAST(d.GPT_ELASTIC_STATUS AS NVARCHAR(2)),CAST(i.GPT_ELASTIC_STATUS AS NVARCHAR(2)) ),
						('GPT_ELASTIC_APPROVED_BY', d.GPT_ELASTIC_APPROVED_BY, i.GPT_ELASTIC_APPROVED_BY ),
						('GPT_ELASTIC_APPROVED_DATE', CONVERT(NVARCHAR(30),d.GPT_ELASTIC_APPROVED_DATE, 120), CONVERT(NVARCHAR(30),i.GPT_ELASTIC_APPROVED_DATE, 120) ),
						('CONFORMITY_SIZE', d.CONFORMITY_SIZE,i.CONFORMITY_SIZE ),
						('CONFORMITY_SIZE_STATUS', CAST(d.CONFORMITY_SIZE_STATUS AS NVARCHAR(2)), CAST(i.CONFORMITY_SIZE_STATUS AS NVARCHAR(2)) ),
						('CONFORMITY_PREPACK', d.CONFORMITY_PREPACK, i.CONFORMITY_PREPACK ),
						('CONFORMITY_PREPACK_STATUS', CAST(d.CONFORMITY_PREPACK_STATUS AS NVARCHAR(2)),CAST(i.CONFORMITY_PREPACK_STATUS AS NVARCHAR(2)) ),
						('EMBROIDERY_PF', CAST(d.EMBROIDERY_PF  AS NVARCHAR(2)), CAST(i.EMBROIDERY_PF  AS NVARCHAR(2)) ),
						('ACCESSORIES_PF', CAST(d.ACCESSORIES_PF AS NVARCHAR(2)), CAST(i.ACCESSORIES_PF AS NVARCHAR(2)) ),
						('BARCODE_PF', CAST(d.BARCODE_PF AS NVARCHAR(2)),CAST(i.BARCODE_PF AS NVARCHAR(2)) ),
						('NO_PLASTIC_PF', CAST(d.NO_PLASTIC_PF AS NVARCHAR(2)),CAST(i.NO_PLASTIC_PF AS NVARCHAR(2)) ),
						('BOGO_PF', CAST(d.BOGO_PF AS NVARCHAR(2)), CAST(i.BOGO_PF AS NVARCHAR(2)) ),
						('THREAD_YN', CAST(d.THREAD_YN AS NVARCHAR(2)),CAST(i.THREAD_YN AS NVARCHAR(2)) ),
						('BUTTON_YN', CAST(d.BUTTON_YN AS NVARCHAR(2)), CAST(i.BUTTON_YN AS NVARCHAR(2)) ),
						('ZIPPER_YN', CAST(d.ZIPPER_YN  AS NVARCHAR(2)), CAST(i.ZIPPER_YN  AS NVARCHAR(2)) ),
						('INTERLINING_YN', CAST(d.INTERLINING_YN AS NVARCHAR(2)),CAST(i.INTERLINING_YN AS NVARCHAR(2)) ),
						('ELASTIC_YN', CAST(d.ELASTIC_YN AS NVARCHAR(2)), CAST(i.ELASTIC_YN AS NVARCHAR(2)) ),
						('MEASUREMENT_SAMPLE_QTY', CAST(d.MEASUREMENT_SAMPLE_QTY AS NVARCHAR(10)), CAST(i.MEASUREMENT_SAMPLE_QTY AS NVARCHAR(10)) ),

						('ZIPPER_RPT_NO', d.ZIPPER_RPT_NO,i.ZIPPER_RPT_NO ),
						('ZIPPER_STATUS', CAST(d.ZIPPER_STATUS AS NVARCHAR(2)), CAST(i.ZIPPER_STATUS AS NVARCHAR(2)) ),
						('ZIPPER_APPROVED_BY', d.ZIPPER_APPROVED_BY,i.ZIPPER_APPROVED_BY ),
						('ZIPPER_APPROVED_DATE',  CONVERT(NVARCHAR(30), d.ZIPPER_APPROVED_DATE, 120), CONVERT(NVARCHAR(30), i.ZIPPER_APPROVED_DATE, 120) ),
						('FIT', d.FIT, i.FIT ),
						('COMM_APPROVAL_DOC', d.COMM_APPROVAL_DOC,i.COMM_APPROVAL_DOC ),
						('DEBIT_AMOUNT', CAST(d.DEBIT_AMOUNT AS NVARCHAR(13)), CAST(i.DEBIT_AMOUNT AS NVARCHAR(13)) ),
						('ADMIN_REMARK', d.ADMIN_REMARK, i.ADMIN_REMARK )
					) AS v(column_name, old_value, new_value)
					WHERE 
						(v.old_value IS NULL AND v.new_value IS NOT NULL)
						OR (v.old_value IS NOT NULL AND v.new_value IS NULL)
						OR ISNULL(v.old_value,'') <> ISNULL(v.new_value,'')
					FOR JSON PATH
				) AS CHANGES
			FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
		) AS CHANGE_HISTORY
	FROM inserted i
	INNER JOIN deleted d 
			ON i.INSPECT_ID = d.INSPECT_ID
	

	-------------------------------------------------------
	-- AUTO SAVE -> UPDATE EXISTING AUDIT ROW
	-------------------------------------------------------
	UPDATE AT
	SET 
		AT.CHANGE_HISTORY = CD.CHANGE_HISTORY,
		AT.LOGGED_ON = GETDATE()
	FROM INSPECTION_AUDIT_TRAIL AT
	INNER JOIN @CHANGE_DATA CD
		ON AT.INSPECTION_ID = CD.INSPECT_ID
	WHERE CD.IS_COMPLETE = 0
	AND AT.AUDIT_ID =
	(
		SELECT TOP 1 AUDIT_ID
		FROM INSPECTION_AUDIT_TRAIL
		WHERE INSPECTION_ID = CD.INSPECT_ID
		ORDER BY AUDIT_ID ASC
	);
	
	-------------------------------------------------------
	-- FINAL SUBMIT -> INSERT NEW AUDIT ROW
	-------------------------------------------------------
	INSERT INTO INSPECTION_AUDIT_TRAIL
	(
		INSPECTION_ID,
		CHANGE_HISTORY
	)
	SELECT
		CD.INSPECT_ID,
		CD.CHANGE_HISTORY
	FROM @CHANGE_DATA CD
	WHERE CD.IS_COMPLETE = 1;

	END TRY
    BEGIN CATCH

        -------------------------------------------------------------------
        -- IMPORTANT:
        -- DO NOT THROW ERROR
        -- OTHERWISE MAIN TRANSACTION WILL ROLLBACK
        -------------------------------------------------------------------

        BEGIN TRY

            INSERT INTO TRG_ERROR_LOG
            (
                ERROR_MESSAGE,
                ERROR_LINE,
                ERROR_PROCEDURE,
                CREATED_ON
            )
            VALUES
            (
                ERROR_MESSAGE(),
                ERROR_LINE(),
                ERROR_PROCEDURE(),
                GETDATE()
            );

        END TRY
        BEGIN CATCH
            -- swallow logging errors also
        END CATCH;

    END CATCH;
   
END;
GO
ALTER TABLE [dbo].[INSPECTIONS] ENABLE TRIGGER [TRG_INSPECTION_AUDIT_TRAIL]
GO
/****** Object:  Trigger [dbo].[TRG_USER_MASTER_REGION_HISTORY]    Script Date: 23-11-2026 14:30:58 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [dbo].[TRG_USER_MASTER_REGION_HISTORY]
ON [dbo].[USER_MASTER]
AFTER UPDATE
AS
BEGIN

    SET NOCOUNT ON;

    INSERT INTO [dbo].[USER_MASTER_AUDIT_HISTORY]
    (
        EMP_CODE,OLD_REGION_IDS,NEW_REGION_IDS,CHANGED_BY,CHANGED_ON
    )
    SELECT
        D.EMP_CODE,D.REGION_IDS,I.REGION_IDS,I.UPDATED_BY,GETDATE()
    FROM INSERTED I
    INNER JOIN DELETED D
        ON I.EMP_CODE = D.EMP_CODE
    WHERE
        ISNULL(D.REGION_IDS, '') <> ISNULL(I.REGION_IDS, '');

END
GO
ALTER TABLE [dbo].[USER_MASTER] ENABLE TRIGGER [TRG_USER_MASTER_REGION_HISTORY]
GO
